INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12104', 'WGST-1413', 'Intro: Feminist Methodologies', 'This course provides an interdisciplinary introduction to various feminist methods of social, cultural, and political analysis. Students will examine concepts such as intersectionality to examine how gender, sexuality, race, and ability interlock in practices of discrimination. Topics may include gender and sexual violence, imperialism, colonialism, prisons and policing, sports, media, AI, masculinity, reproductive justice, disability justice, and practices of resistance.', 'WGST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12105', 'WGST-2193', 'Women in Science', 'This course will explore issues affecting women in science and attempt to answer the questions: Why so few? How can we effect change? Through an examination of research on topics such as implicit bias, stereotyping, and messaging in popular culture, the barriers to women entering scientific fields and ways to challenge and overcome them will be explored. Prerequisite(s): Second-year standing or higher. Antirequisite(s): Credit can be obtained for only one of PSYC 2193 or WGST 2193.', 'WGST', 3, 0, 2, '[{"codes":["1","Year","of","University","Study","(completed","at","least","25","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12106', 'WGST-2403', 'Gender and Sexuality 1', '??This course focuses on the social norms, institutions, and structures that reproduce oppressive gender and sexual relationships at the intimate, everyday, legal, national, and transnational levels. Topics may include feminist approaches to masculinity and femininity, sex positivity, gender-based violence, consent, and sex education, with attention to how race, class, age, and/or ability influence how people experience gender and sexual hierarchies.?  Antirequisite(s): Credit can be obtained for only one of WGST 2403 or SOCI 2403.', 'WGST', 3, 0, 2, '[{"codes":["3h","1000-level","SOCI","or","WGST","1413,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12107', 'WGST-2906', 'W&G in Today''s World', 'This interdisciplinary course analyzes the nature, status, image and changing roles of women and men in the world today, placing gender at the forefront of analysis from a cross-cultural perspective, with comparisons to Canada. May be taken for major or minor credit in Canadian Studies and Sociology. Prerequisite(s): Second-year standing.', 'WGST', 6, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12108', 'WGST-2913', 'Global Women''s Movements', 'The course focuses on women''s movements around the globe, with an emphasis on the Global South. Using historical and contemporary case studies, students examine what leads women to mobilize, the resources helping or hindering them, the conditions of women''s lives sparking action for social change, and the impact of their activism. Topics may include peace, religion, violence, health, and labour.', 'WGST', 3, 0, 2, '[{"codes":["2nd-year","standing","(>24h","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12109', 'WGST-3023', 'Fem. Theories & Methodologies', 'The course examines the historical evolution of feminism through the analysis of theoretical texts and methodologies such as Indigenous feminisms, Black, Marxist, transgender, abolitionist, and transnational studies. Topics vary but may include heteropatriarchy; gender and sexual normativity; materialist and intersectional analysis of factors of discrimination and oppression such as race, class, and able-bodiedness; white supremacy, colonialism, and capitalism.  May be offered for major credit in English, Politics, and Sociology.', 'WGST', 3, 0, 3, '[{"codes":["WGST-1413","and","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12110', 'WGST-3123', 'Feminism and Popular Culture', '??This course examines how gender is constructed, represented, and contested in popular culture. Engaging feminist and cultural studies theories, students will examine constructs of masculinity, femininity, and nonbinarism in various types of popular culture. Students will examine how gender representation and contestation intersect with factors such as race, class, age, sexuality, and ability.?', 'WGST', 3, 0, 3, '[{"codes":["WGST-1413","and","second-year","standing,","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12111', 'WGST-3403', 'Gender and Sexuality 2', '??This advanced course focuses on the intersections of sex, gender, and power. Students will study the structural forces of patriarchy, capitalism, and colonialism that uphold unequal gendered and heteronormative relations as well as diverse forms of collective resistance that imagine and enact progressive sexual and feminist citizenship.? Antirequisite(s): Credit can be obtained for only one of WGST 3403 or SOCI 3403.', 'WGST', 3, 0, 3, '[{"codes":["WGST-2403","or","SOCI","2403,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12112', 'WGST-3503', 'Gender Through the Ages', '??Students will read major writings that contributed to the construction of gender from classical texts to modern treatises. Archives may include myths, epics, journals, religious texts, medical treatises, law codes, criminal trials, conduct literature, or popular romances. Students will consider how historical cultures developed normative masculinities and femininities, and how they used gender constructs to persecute gender identity and expressions.? May be offered for major credit in English, history, and sociology.', 'WGST', 3, 0, 3, '[{"codes":["WGST-1413","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12113', 'WGST-3703', 'Spec Top: Women''s /Gend Stud', 'An in-depth study of a selected topic in the area designed to enable students to take advantage of the particular expertise of visiting or current faculty. May include topics such as domestic violence, women in film, women and food, or women in science. Prerequisite(s): WGST 1413 or permission of the instructor.', 'WGST', 3, 0, 3, '[{"codes":["WGST","-1413","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12114', 'WGST-3803', 'Queer and Trans Studies', '??Drawing on queer and trans theories, students will examine the social, cultural, and political dimensions of sexual and gender diversity as well as intersectional lines of discrimination and oppression characterizing heteropatriarchy. Topics of interdisciplinary analysis may include the social construction of sexual and gender identities; homophobia, transphobia, and heterosexism; 2SLGBTQIA+ activism, education, and advocacy; theory as practice; and cultural production.?  Antirequisite(s): Credit can be obtained for only one of WGST 3803 or SOCI 3803.', 'WGST', 3, 0, 3, '[{"codes":["3h","1000-level","SOCI","or","WGST","1413,","and","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12115', 'WGST-4903', 'Directed Individual Readings', 'Designed to deepen the student''s understanding of particular topics in Women''s and Gender Studies. Intended primarily for qualified fourth year and honours students. Prerequisite(s): Permission of WGST program coordinator.', 'WGST', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12116', 'WGST-4913', 'Women of the African Diaspora', 'A conceptual and thematic exploration of the ways in which race, gender, sexuality and socio-economic status have influenced the experiences of African-descended women. Focus is on individual and group experiences of women of the African Diaspora in the Americas and beyond. How have societies shaped and been shaped by the African Diaspora? What impact(s) has the African Diaspora had globally?', 'WGST', 3, 0, 4, '[{"codes":["WGST","1413","and","WGST","3023,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12117', 'WGST-4923', 'Contemporary Feminist Issues', 'This capstone course is an in-depth examination of contemporary issues and debates within Women''s and Gender Studies. Reflecting on feminist theories, methodologies, politics, and activism, the course will focus on a variety of topics, themes, and contemporary issues. Students will pursue advanced scholarship through a skills-focused major project that may involve workshops, peer-review, or collaboration.', 'WGST', 3, 0, 4, '[{"codes":["WGST-1413","and","WGST-3023,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
