INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13218', 'BIBL-BKEE', 'Bible Knowledge Exam', '', 'BIBL', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13238', 'BIOL-4183', 'Becoming Human', 'Becoming Human is a course on human development. Topics include embryonic and fetal development, and focus on current topics such as infertility, epigenetics, stem cells, placental development and microchimerism. This is a flipped course where students do the preparation before class, and class time is focussed on discussion and other activities. There is no lab. Prerequisite(s): BIOL 3153.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-3153"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13239', 'CHEM-4993', 'Honours Research Methods', 'Introduction to research methods. Taught as a directed readings course by a research supervisor, the course will emphasize critical evaluation of per-reviewed chemistry literature and communication of chemistry research in oral and written form. Course is graded as Pass/Fail.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-407T"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13240', 'CLAS-3693', 'Special Topics', 'Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13241', 'CLAS-3813', 'Ancient Greece & Rome in Film', 'This course examines 20th-21st century cinematic representations of the ancient Graeco-Roman Mediterranean. Films are viewed weekly, and ancient texts and assigned readings offer an opportunity to reflect on how our modern visions of the ancient world attempt to represent the realities of the past while simultaneously shedding light on our contemporary society, politics, gender roles, and popular culture. (3h lab)', 'CLAS', 3, 0, 3, '[{"codes":["CLAS-3810L"],"textExtension":"- Must be taken at the same time as this course."},{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13242', 'CREL-3363', 'Special Topics', 'Prerequisite(s): 30h or permission of the instructor.', 'CREL', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13243', 'EDUC-42P3', 'Teaching Computer Science 1', 'This course introduces current methods for teaching computer science through the core competencies and multiple learning pathways emerging in secondary education. Drawing on relevant documents and current research, pre-service teachers explore the expanding cross-curricular relevance of computer science in a modern education system and the pedagogical approaches to promote computational thinking as a foundation for inquiry and innovation.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13244', 'EDUC-42R3', 'Teaching Computer Science 2', 'This course explores computer science curriculum connections through engaging instructional and assessment strategies in the secondary classroom. Focusing on current research and practices, pre-service teachers will have the opportunity to apply computer science education principles in the design and implementation of innovative and inquiry-based classroom experiences with real-world applications. Prerequisite(s): EDUC 42P3', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13245', 'EDUC-42T3', 'Classroom Management', 'This course explores the development and maintenance of a safe, creative, ethical and inclusive learning centered environment which promotes engagement. Pre-service teachers will consider class participation, the critical role of the teacher in responding to students, researching theories, policies, programs and approaches and examining current literature, case studies and school experiences as they learn how theory and practice are interwoven.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13247', 'ENVS-5043', 'Advanced Topic Envs 2', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Environmental Contamination; Lacustrine Environmental Science; Coastal Environmental Science; Environmental Science Policy; Environmental Change; Environmental Monitoring, Assessment, Remediation and Restoration; Ecosystems Health; Applied Biodiversity; Legal Issues; Environmental Impact Assessment; Borders, Scale and Environment.', 'ENVS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13248', 'HIST-1043', 'The Mid. East in World History', 'The term Middle East was invented to identify a region and a culture. The course follows the development of that culture by examining the centrality of the "Middle East" in global cultural and economic exchanges that have led to the region''s prominent role in global politics, including political Islam, migration and migrants, and the resulting debates on Islamization and secularization. No prerequisite.', 'HIST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13249', 'KINE-3153', 'Development of Sport Expertise', 'This course provides an in-depth examination of the psychological and social factors underpinning the development of sport expertise. Drawing upon peer-reviewed research and real-life examples, students will develop a holistic understanding of athlete development, from an individual''s first initiation into organized sport in childhood to elite and/or professional levels of competition. Prerequisite(s): BKIN/BKIH Students Only, KINE 2433, third-year standing or higher.', 'KINE', 3, 0, 3, '[{"codes":["BKIN/BKIH","Students","Only,","KINE","2433,","third-year","standing","or","higher."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13250', 'KINE-4203', 'Exercise Sci Clinical Practicu', 'This course provides students an opportunity to apply course material in clinical settings. Students will be expected to work in diverse situations weekly to develop skills around laboratory fitness testing, developing exercise programs and directing personal training opportunities primarily for those with chronic conditions. Students will also complete self-directed study toward preparation of theoretical and practical clinical competencies. Prerequisite(s): BKIN/BKIH (ES&T Option) Students Only, and KINE 4193.', 'KINE', 3, 0, 4, '[{"codes":["BKIN/BKIH","(ES&T","Option)","Students","Only,","and","KINE","4193."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13253', 'PHYS-2123', 'Classical Mechanics', 'Vector calculus is employed in Newtonian mechanics. Attractive for students wishing to experience the power of mathematics as a tool in describing easily-visualizable phenomena. Problems such as oscillations, motion under a central force, the two-body problem and motion in a rotating coordinate system are analyzed. Corequisite(s): MATH 2753 or MATH 2013. Antirequisite(s): Credit can be obtained for only one of PHYS 2123 or PHYS 2113.', 'PHYS', 3, 0, 2, '[{"codes":["PHYS-1023","or","equivalent,","and","MATH-2723","or","MATH-2023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-2753","or","MATH-2013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13254', 'POLS-1503', 'Intro to Indigenous Politics', 'This interactive course introduces students to Indigenous political perspectives on relationships with the land, nationhood, sovereignty, and legal traditions vis-a-vis Mi''kma''ki, the Canadian state, and the world. Students will learn how Indigenous peoples have been challenging colonialism through struggles for self-determination, recognition, self-government, land claims, and economic selfsufficiency. Identity, power, and the principles of Indigenous Knowledge forms are foundational.', 'POLS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13255', 'SOCI-3643', 'Sociology of Disability', 'This course introduces students to the field of disability studies. Students will examine the medical and social models of disability and the impact they have on disabled people. Students will apply a critical lens to understand the lived experiences of disability throughout the life course.', 'SOCI', 3, 0, 3, '[{"codes":["3h","of","1000-level","SOCI","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13256', 'THEO-3153', 'Theology of Love', 'What is love? Why is it considered the most essential human value for so many? How is it connected to such fundamental facets of the human condition as family, sex, religion, justice, forgiveness, etc.? This course will engage the topic of love as it is related to perennial dimensions of our human experience, and how our humanity can be understood through divine love. This course will set out to define love in its various forms, chart its history from ancient ideas (such as the Epic of Gilgamesh, the Bible, Plato, Aristotle, and Augustine) to modern ones (such as C. S. Lewis and Thomas Jay Oord), and will set out to explore modern contributors to the practice of love (such as Martin Luther King Jr, Desmond Tutu, Mother Teresa).', 'THEO', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13271', 'EDUC-4993', 'Develop. Psyc for Teachers', 'Human development is a process of change that extends across the lifespan. Examining development from a psychosocial and ecological perspective, pre-service teachers will develop an understanding of the interaction of individual student competencies with the demands and resources of their environments. This course will examine the integration of both stage and ecological theories for a comprehensive understanding of student development.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13288', 'IDST-0000', 'Covid 19 Prep and Education', '', 'IDST', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13289', 'BIOL-5253', 'Applied Statistical Modeling', 'The application of statistical models to real-world ecological, environmental or other data. Core topics include data collection, visualization and wrangling, leading to general linear models, general additive models, and mixed effects models. Focus is on practical and applied modeling including model selection, fit, validation, and visualization. The use of R and model output interpretation is emphasized.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13290', 'IDST-0010', 'New Student Orientation 2021', '', 'IDST', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13291', 'PHYS-2423', 'Modern Physics', 'Covers topics such as special relativity, de Broglie waves, particle diffraction, wave particle duality, indeterminacy, and the correspondence principle. Schrodinger''s equation is introduced and solved for simple physical systems with applications to atoms and molecules. Good preparation for advanced courses requiring quantum physics or teaching high school. Antirequisite(s): Credit can be obtained for only one of PHYS 2423 or PHYS 2413.', 'PHYS', 3, 0, 2, '[{"codes":["PHYS-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13294', 'ENVS-5013', 'Research Methods Enviro Sci', 'Exploration of the history and philosophy of science, expectations of students and supervisors, practical approaches to research in Environmental Science, publishing, and critical review. Students complete a research proposal, research grant application, and/or manuscript from current or past research. Students meet weekly to explore topics, and review and critique the work of others. Proposals and applications are presented and defended. Antirequisite(s): Credit can be obtained for only one of ENVS 5013 or BIOL 5013.', 'ENVS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13295', 'ENVS-5033', 'Advanced Topic Envs 1', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Environmental Contamination; Lacustrine Environmental Science; Coastal Environmental Science; Environmental Science Policy; Environmental Change; Environmental Monitoring, Assessment, Remediation and Restoration; Ecosystems Health; Applied Biodiversity; Legal Issues; Environmental Impact Assessment; Borders, Scale and Environment.', 'ENVS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13297', 'ENVS-5053', 'Advanced Topic Envs 3', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Environmental Contamination; Lacustrine Environmental Science; Coastal Environmental Science; Environmental Science Policy; Environmental Change; Environmental Monitoring, Assessment, Remediation and Restoration; Ecosystems Health; Applied Biodiversity; Legal Issues; Environmental Impact Assessment; Borders, Scale and Environment.', 'ENVS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13326', 'EDUC-4963', 'Music Education: Seco 2', 'This advanced course provides an overview of learning theories pertinent to music education. Students will learn about pedagogical strategies for the teaching of music literacy that will lead to a teaching model to empower musicianship and engagement in music. Students will become familiar with Nova Scotia music curricula content and outcomes. Prerequisite(s): EDUC 4663.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4663"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13327', 'EDUC-5343', 'Counselling for Social Justice', 'Students are supported in exploring theories of social justice, equity, and cultural responsiveness in counselling. Students will be provided with opportunities for self-reflection on their social positioning and biases and how this impacts their approach to counselling. A priority of this course is to bring forward first voice of groups marginalized by traditional counselling practices and raise student''s consciousness.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13328', 'EDUC-5353', 'Crisis and Trauma Counselling', 'This course is aimed at providing students with a theoretical and practical understanding of trauma and basic accepted practices of supporting individuals from a trauma-informed approach. This course also takes up the research, theory, and practical interventions in supporting individuals experiencing situational or transitional crises. Topics of this course are approached through an ecological perspective and crisis and trauma are explored through consideration of interactions to environmental, developmental, and cultural factors.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13329', 'GEOL-5900', 'Graduate Seminar 1', 'Review of current research topics and problems in the Geological Sciences. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOM 5900.', 'GEOL', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13330', 'GEOM-5900', 'Applied Geomatics Seminar 1', 'Review of current research topics and problems in Applied Geomatics or the Geological Sciences. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOL 5900 and BIOL 5013/5023.', 'GEOM', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13332', 'THEO-7153', 'Theology of Love', 'What is love? Why is it considered the most essential human value for so many? How is it connected to such fundamental facets of the human condition as family, sex, religion, justice, forgiveness, etc.? This course will engage the topic of love as it is related to perennial dimensions of our human experience, and how our humanity can be understood through divine love. This course will set out to define love in its various forms, chart its history from ancient ideas (such as the Epic of Gilgamesh, the Bible, Plato, Aristotle, and Augustine) to modern ones (such as C. S. Lewis and Thomas Jay Oord), and will set out to explore modern contributors to the practice of love (such as Martin Luther King Jr, Desmond Tutu, Mother Teresa).', 'THEO', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13334', 'CHEM-4303', 'Advanced Main Group Chemistry', 'Topics of current interest in main group chemistry are discussed. Emphasis will be on developing research areas in the scientific literature. Prerequisite(s): CHEM 3303 or CHEM 3313, with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3303","or","CHEM-3313","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13335', 'CLAS-2733', 'Arch of Daily Life in Anct Med', 'A study of the physical remains of the ancient Mediterranean world and how archaeologists use this evidence to recreate socio-cultural history in the region. Specific topics include the structure of the home, gender roles, and domestic spaces; food and drink; trade and the economy; religious practice and festivals; public spaces and markets; laws and legal procedures; and sport and entertainment. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13336', 'CLAS-2823', 'Race & Ethnicity Anct Med', 'Students explore ancient views of race, ethnicity, and the ''other'' (foreigners, ''barbarians'', enslaved people) through an examination of art, literature, and archaeological remains. By analyzing primary sources and material culture, we engage with evidence for ancient perspectives on ethnicity, investigate current scholarship on ancient perceptions of identity, and connect the study of classical antiquity to modern notions of race. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[{"codes":["30h","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13337', 'CLAS-3663', 'Temp, Sanc, & Scrd Anct Greece', 'An examination of the archaeological and literary evidence for ancient Greek religion, cult, and ritual practices. Attention is given to religious practice and space in both private and public spheres, the development of Greek sanctuaries and the worship of the Olympian Gods, festivals, temples, processions, and sacred calendars in ancient Greece. Prerequisite(s): Third-year standing or permission of the instructor.', 'CLAS', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13338', 'EDUC-42U3', 'Classroom Management', 'The primary objective of this course is to develop a broad understanding of environmental justice and equity issues as they relate to education. The goal is to support students in developing their own informed pedagogical understandings on these complex and multifaceted issues. The geographic scope of environmental justice issues will extend from the local, to Pan Canadian and Global environmental justice struggles. Coursework will encourage expression of independent, fact-informed and well-argued opinions, and ideas concerning the development of curricula that encourages problem solving and critical thinking.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13339', 'ENGL-4223', 'Special Topics 2', '', 'ENGL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13340', 'HIST-3853', 'Great Dep & Fight Agst Fascism', 'The Great Depression represented the greatest challenge the US faced in the 20th century. This was both a domestic and an international crisis, one which produced progressive as well as reactionary movements for social and political change. Using an international lens, this course will explore the American response to the crisis of economic collapse and the rise of right-wing extremism. Prerequisite(s): Second-year standing or permission of the instructor.', 'HIST', 3, 0, 3, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13341', 'SOCI-4223', 'Seminar Sociology Global Hlth', 'This course examines the local and transnational relations governing health and health care in global south settings. We investigate the relative role of international groups, nations, and local health care providers in shaping how health care is received (and not received). Topics include: political violence and care in conflict settings; poverty, structural violence, and neoliberalism; and diverging ideas about bodies and healing.', 'SOCI', 3, 0, 4, '[{"codes":["3h","1000-level","SOCI","and","third-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13343', 'ECON-2883', 'Contemporary Economic Issues', 'A collaborative seminar introducing modern research ideas and methods in economics. Several distinct topics will be covered by different instructors, drawing from faculty research interests and current economic issues, primarily in microeconomics.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013,","ECON-1023,","and","ECON-2613"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13345', 'ECON-3533', 'Economics and Personal Finance', 'This course focuses on the economic environment in which personal financial decisions are made. It exposes students  to  modern  economic  literature and  a  broad  range  of  topics  within  life-cycle,  financial,  family,  housing, and computational economics. A substantive writing component forms part of the course.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013,","ECON-1023","and","ECON","2613","required","and","MATH-1613","or","MATH-1013."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13346', 'THEA-4613', 'Digital Theatre', 'A survey of the historical development of media-rich performances and consideration of the theoretical, aesthetic, and practical implications for theatrical storytelling.', 'THEA', 3, 0, 4, '[{"codes":["THEA","2883,","2893","and","at","least","one","of","3883,","3893,","4833,","4843,","and/or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13347', 'GREE-2023', 'Intermediate Greek II', 'Completion of the study of advanced aspects of Greek grammar and syntax begun in Intermediate Greek I', 'GREE', 3, 0, 2, '[{"codes":["GREE-2013","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13348', 'HIST-2653', 'Law & Life in Medieval England', 'Legal systems develop and change over time. They shape and are shaped by society. Using surviving documents (charters, writs, statutes, contracts, court rolls, wills, law codes), students explore both the evolution of the English legal system, from Germanic customs to early Common Law, and the experiences of those living under the law from the 5th to the 15th centuries.', 'HIST', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13349', 'LATI-2023', 'Intermediate Latin 2', 'Readings in Latin prose and poetry; continued study of Latin grammar.', 'LATI', 3, 0, 2, '[{"codes":["LATI-2013","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13350', 'GREE-2013', 'Intermediate Greek I', 'The study of classical Greek, continuing with the reading approach of Elementary Greek I and II. After a period of review, students begin the study of advanced aspects of grammar and syntax.', 'GREE', 3, 0, 2, '[{"codes":["GREE-1113","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13353', 'CLAS-3810L', 'CLAS-3813 Laboratory', '', 'CLAS', 0, 1, 3, '[{"codes":["CLAS-3813"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13354', 'LATI-2013', 'Intermediate Latin 1', 'Readings in Latin prose and poetry; continued study of Latin grammar.', 'LATI', 3, 0, 2, '[{"codes":["LATI-1113","with","minimum,","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13355', 'APSC-3553', 'Project Mgmt & Leadership', 'This course will introduce concepts and techniques of project management, change management, and leadership for use in professional settings, and provide students with the opportunity to use learned knowledge in practical applications from industry experts. Multiple modules will help students develop skills and build capacity for management and leadership with a focus on maintaining commitment to professional and environmental integrity.', 'APSC', 3, 0, 3, '[{"codes":["Four","or","more","second-year","courses","in","the","Faculty","of","Pure","and","Applied","Science","or","with","permission","of","the","School."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13356', 'BIOL-2173', 'Research Skills in Biology', 'Introduction to laboratory or field research skills in biology with hands-on experience assisting in a research project. Skills may include trouble-shooting procedures, field work, data entry, processing samples, maintaining cultures, etc. The research must be supervised by a member of the department (6h/ week).', 'BIOL', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13358', 'NUTR-4313', 'Applied Sports Nutrition 1', 'A practical course that applies cumulative knowledge in nutrition to the varsity athletic setting, with supervision and support. Focus will be on supporting athletes to manage the interaction between the training program and food choices including meals, pre, during and post training nutrition strategies, and analysis of dietary intake of the athletes in the context of athletic performance.', 'NUTR', 3, 0, 4, '[{"codes":["NUTR","3533,","NUTR","3933,","and","permission","of","Instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13359', 'NUTR-4323', 'Applied Sports Nutrition 2', 'This practical course combines research projects that incorporate knowledge and critical discourse in sport nutrition to the varsity athletic setting with supervision and support. Building on knowledge gained in Applied Sports Nutrition 1, students will be engaged in hands-on research projects that will contribute to their knowledge and application in the field of sport nutrition.', 'NUTR', 3, 0, 4, '[{"codes":["NUTR","4313,","and","permission","of","Instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13360', 'KINE-3063', 'AT Practicum 1', 'This course will enhance skills in emergency injury assessment, emergency injury management, general medical conditions, orthopedic taping, splinting, and wound management. Field scenarios and evidence-informed practice will be a focus. Students will also complete designated blocks of supervised field and clinical experiences, with approved field and clinical agencies.', 'KINE', 3, 0, 3, '[{"codes":["BKIN/BKIH","(AT","Option)","Students","only","and","KINE-1333"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-3060L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13361', 'KINE-3073', 'AT Practicum 2', 'This course will continue to enhance skills in emergency injury assessment, emergency injury management, general medical conditions, nutrition, adapted physical activity, orthopedic taping, splinting, and wound management. Field scenarios and evidence-informed practice will be a focus. Students will also complete designated blocks of supervised field and clinical experiences, with approved field and clinical agencies.(1.5h lab). Prerequisite(s): BKIN/BKIH (AT Option) students only.', 'KINE', 3, 0, 3, '[{"codes":["BKIN/BKIH","(AT","Option)","Students","only,","KINE-1333,","KINE-3063"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-3070L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13362', 'KINE-4500', 'AT Practicum 3', 'For students accepted to the Bachelor of Kinesiology (Athletic Therapy Option), this is the third designated block of supervised field and clinical experiences, with approved field and clinical agencies. Students will continue to develop their portfolio of a defined list of competencies as set by the Canadian Athletic Therapists Association.  Prerequisite(s): BKIN/BKIH (AT Option) students only.', 'KINE', 0, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13363', 'KINE-4600', 'AT Practicum 4', 'For students accepted to the Bachelor of Kinesiology (Athletic Therapy Option), this is the fourth designated block of supervised field and clinical experiences, with approved field and clinical agencies. Students will continue to develop their portfolio of a defined list of competencies as set by the Canadian Athletic Therapists Association.  Prerequisite(s): BKIN/BKIH (AT Option) students only.', 'KINE', 0, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13364', 'KINE-2993', 'Personal Health', 'This course will provide students with an overview of Personal Health. Broadly, we will examine what it means to be healthy within various domains (i.e., exercise, sleep, etc.) and how they tie together to create overall wellness. We will also explore how we can measure health and some special considerations (i.e., athletics, across the lifespan, etc.). This course cannot be counted as credit toward the BKIN degree. Prerequisite(s): Non-KINE majors only, second-year standing.', 'KINE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13365', 'KINE-3173', 'Sport and Law', 'This course will explore various aspects of law in the sport context. Students will be introduced to the many legal issues they may face as professional, or volunteer, teachers, coaches, managers, board members or administrators.  Prerequisite(s): BKIN/BKIH Students only.', 'KINE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13366', 'KINE-3183', 'Developing Leadership', 'An investigation into transformational leadership practice and how to make an impact within our own community. This course explores the different components of great leadership and will give the students an opportunity to assess their own leadership. Students will create a leadership improvement plan and develop an innovative Leadership Project to make a positive impact on themselves and society.  Prerequisite(s): BKIN/BKIH Students only.', 'KINE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13367', 'KINE-3193', 'Para-Sport', 'Para Sports is an introduction into the world of Paralympic Sports. Student will learn about the Paralympic History and Movement. Students will explore different Para Sports. The students will learn about the differences in Physiology, Biomechanics and the Psychology of the Paralympic Athletes. Students will also learn about performance testing for Para Athletes such as Exercise-Testing, Strength-Testing and Nutritional-Assessments.  Prerequisite(s): BKIN/BKIH Students only.', 'KINE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13368', 'KINE-3383', 'AESTH SPORT & DANCE', 'Philosophical inquiry into the aesthetics of movement in sport and dance. Topics to be discussed include the contextual nature of movement aesthetics, the problem of subjectivity in judging movement quality, and debates about possible intersections between the domains of sport and art.  Prerequisite(s): BKIN/BKIH students with second-year standing or higher.', 'KINE', 3, 0, 3, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13370', 'MATH-1253', 'Statistics 1', 'Descriptive statistics and exploratory data analysis, including correlation and the least squares regression line; basic probability including random variables and normal distribution; sampling distributions; introduction to estimation, confidence intervals and hypothesis testing; one-way analysis of variance. Prerequisite(s): Mathematics 11 and 12, or Precalculus 11 and 12, or MATH 1003. Antirequisite(s): MATH 1213, MATH 2233, ECON 2613. Students who have completed Math 2213 may not subsequently receive credit for this course.', 'MATH', 3, 0, 1, '[{"codes":["MATH-1250L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13371', 'BIOL-407T', 'Honours Thesis 1', 'This course requires a student, with mentorship from a supervisor, to complete a research-based project, obtain and analyze data, and present their research in a thesis format. Prerequisite(s): permission of thesis  supervisor and department.', 'BIOL', 3, 0, 4, '[{"codes":["Take","BIOL-408T","and","Permission","of","thesis","supervisor","and","department."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13372', 'KINE-3453', 'Pos Youth Dev Sport & Phys Act', 'This course will explore psychosocial research on positive youth development in sport and physical activity contexts. Through the review of theoretical and empirical literature, students will develop an in-depth understanding of how organized sport and physical activity can be used as a vehicle to facilitate the development of life skills and positive psychosocial outcomes. Prerequisites: BKIN/BKIH students only, KINE 2433 and third-year standing or higher.', 'KINE', 3, 0, 3, '[{"codes":["BKIN/BKIH","students","only,","KINE","2433","and","third-year","standing","or","higher."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13373', 'MUSI-1823', 'Practising Music', 'An exploration of different practice concepts, designed to improve one''s own practice habits and ultimately performance. Concepts are approached theoretically with research-based readings and resources, and applied practically through independent and collaborative learning on students'' principal or secondary instruments.', 'MUSI', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13374', 'BIOL-408T', 'Honours Thesis 2', 'This course requires a student, with mentorship from a supervisor, to complete a research-based project, obtain and analyze data, and present their research in a thesis format. Prerequisite: BIOL 407T Prerequisite(s): Permission of thesis supervisor and department. Corequisite(s): BIOL-407T.', 'BIOL', 3, 0, 4, '[{"codes":["Prerequisite(s):","Permission","of","thesis","supervisor","and","department.","Corequisite(s):","BIOL-407T."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13375', 'CHEM-407T', 'Honours Thesis 1', 'This course requires participation in original chemical research/education projects involving 72 hours of research activity such as laboratory experiments or fieldwork as well as presentation of research results and written thesis. Prereuisite(s): Permission of thesis supervisor and department, and 30h of chemistry courses. Corequisite(s): CHEM 4993 and CHEM 408T. Antirequisite(s): Credit can be obtained for only one of CHEM 407T/408T or CHEM 4916.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-4993","and","CHEM-408T"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["Permission","of","thesis","supervisor","and","department,","and","30h","of","","chemistry","courses."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13376', 'CHEM-408T', 'Honours Thesis 2', 'This course requires participation in original chemical research/education projects involving 72 hours of research activity such as laboratory experiments or fieldwork, presentation of research results, a written thesis, and an oral defense.  Prerequisite(s): Permission of thesis supervisor and department, and 30h of chemistry courses. Prequisite(s): CHEM 407T. Antirequisite(s): Credit can be obtained for only one of CHEM 407T/408T or CHEM 4916.', 'CHEM', 3, 0, 4, '[{"codes":["Take","CHEM-407T"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13378', 'BUSI-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out a research study or applied research project under the guidance of an approved supervisor and submit a thesis in accordance with the Program Guidelines of the student''s degree discipline and in a format approved by the Honours Committee of Senate.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3483","and","BUSI-3993,","or","equivalent;","Registration","in","honours","program"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13379', 'BUSI-408T', 'Honours Thesis 2', 'This course requires the student to propose and carry out a research study or applied research project under the guidance of an approved supervisor and submit a thesis in accordance with the Program Guidelines of the student''s degree discipline and in a format approved by the Honours Committee of Senate.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-407T,","BUSI-3483","and","BUSI-3993,","or","equivalent;","registration","in","honours","program"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13381', 'CLAS-407T', 'Honours Thesis 1', 'Prerequisite(s): Students must have permission of Thesis Supervisor and Department to do a Classics Thesis.', 'CLAS', 3, 0, 4, '[]');
