INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13383', 'CODE-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out a research study under the supervision of an approved supervisor and submit a thesis in accordance with the Department Honours Program Guidelines and in a format approved by the Honours Committee of Senate.', 'CODE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13384', 'CODE-408T', 'Honours Thesis 2', 'This course requires the student to propose and carry out a research study under the supervision of an approved supervisor and submit a thesis in accordance with the Department Honours Program Guidelines and in a format approved by the Honours Committee of Senate.', 'CODE', 3, 0, 4, '[]');
