INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13387', 'ECON-407T', 'Honours Thesis 1', 'The first half of the honours experience during which students undertake a mentored research investigation or project. 407T and 408T are required of and only available to thesis-option honours students. Students wishing to engage in honours research should consult the department during their third year.', 'ECON', 3, 0, 4, '[]');
