INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13392', 'ENVS-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out an original study and submit and defend a thesis. As a component of an  interdisciplinary degree, the thesis should reflect an interdisciplinary approach to the issue under study. Prior to registering in 407T, students should normally have completed a thesis proposal and successfully established their ability to complete interdisciplinary work. Prerequisite(s): Completion of the first three years (90h) of the BScH ENVS program; minimum CGPA of 3.00.', 'ENVS', 3, 0, 4, '[{"codes":["4th-year","standing","(85h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13393', 'ENVS-408T', 'Honours Thesis 2', 'This course requires the student to propose and carry out an original study and submit and defend a thesis. As a component of an interdisciplinary degree, the thesis should reflect an interdisciplinary approach to the issue under study. Prior to registering in 408T, students should normally have completed a thesis proposal and successfully established their ability to complete interdisciplinary work. Prerequisite(s): Completion of the first three years (90h) of the BScH ENVS program; minimum CGPA of 3.00.', 'ENVS', 3, 0, 4, '[{"codes":["4th-year","standing","(85h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13395', 'ESST-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out a research study under the supervision of an approved supervisor and submit a thesis in accordance with the Program Guidelines of the student''s degree discipline and in a format approved by the Honours Committee of Senate.', 'ESST', 3, 0, 4, '[]');
