INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13407', 'KINE-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out a research study under the supervision of a KINE faculty member and submit  a thesis in accordance with the KINE format and University Honours Committee regulations. Both the proposal and the thesis must be successfully defended before the thesis supervisor and the KINE Honours Committee of Senate.  Prerequisite(s): BKIH Students Only.', 'KINE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13408', 'KINE-408T', 'Honours Thesis 2', 'This course requires the student to propose and carry out a research study under the supervision of a KINE faculty member and submit  a thesis in accordance with the KINE format and University Honours Committee regulations. Both the proposal and the thesis must be successfully defended before the thesis supervisor and the KINE Honours Committee of Senate.  Prerequisite(s): BKIH Students Only.', 'KINE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13409', 'MATH-407T', 'Honours Thesis 1', 'An honours thesis in mathematics or statistics to be completed in conjunction with the honours student''s supervisor. The course requirements include an oral report and a written thesis. Prerequisite(s): permission of thesis supervisor and department.', 'MATH', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13410', 'MATH-408T', 'Honours Thesis 2', 'An honours thesis in mathematics or statistics to be completed in conjunction with the honours student''s supervisor. The course requirements include an oral report and a written thesis. Prerequisite(s): permission of thesis supervisor and department.', 'MATH', 3, 0, 4, '[]');
