INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13624', 'KINE-599Y', 'Graduate Thesis', 'This course requires the student to propose and carry out a research study under the supervision of a KINE faculty member. Students construct, submit, and defend a written thesis document in accordance with the KINE format and Graduate Studies regulations.', 'KINE', 15, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13627', 'LEDR-2113', 'Theo & Prac of Racial Justice', '', 'LEDR', 3, 0, 2, '[{"codes":["Take","9","credit","hours","from;","BIBL-2013","or","BIBL-3013","or","BIBL-3023","or","THEO-3013","or","THEO-3023"],"textExtension":"- Must be completed prior to taking this course."}]');
