INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13972', 'PAST-403A', 'Mentored Ministry 3', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 402a', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-402a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13973', 'PAST-404A', 'Mentored Ministry 4', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 403a', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-403a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13974', 'LEDR-501A', 'Leadership Labs 1', 'Digital Literacies is a hands-on lab for discerning and using digital spaces in ministry. Students evaluate platforms and hybrid practices for communication, worship support, pastoral care, and formation, attending to opportunities and risks. The course cultivates theological judgment and ethics for emerging technologies (including AI) through discussion, guided exercises, feedback, and revision. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13975', 'LEDR-501B', 'Leadership Labs 1', 'Digital Literacies is a hands-on lab for discerning and using digital spaces in ministry. Students evaluate platforms and hybrid practices for communication, worship support, pastoral care, and formation, attending to opportunities and risks. The course cultivates theological judgment and ethics for emerging technologies (including AI) through discussion, guided exercises, feedback, and revision. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13976', 'LEDR-502A', 'Leadership Labs 2', 'Adaptive Leadership is a practice-focused lab for leading through changing times. Students learn to name adaptive challenges, test small responses, and adjust leadership approaches through feedback-informed cycles. Attention is given to courageous, hope-shaped leadership and to cultivating innovation as an ongoing discipline so students can guide communities through real transitions. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13977', 'LEDR-502B', 'Leadership Labs 2', 'Adaptive Leadership is a practice-focused lab for leading through changing times. Students learn to name adaptive challenges, test small responses, and adjust leadership approaches through feedback-informed cycles. Attention is given to courageous, hope-shaped leadership and to cultivating innovation as an ongoing discipline so students can guide communities through real transitions. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13978', 'HIST-2843', 'Ancient Rome: Culture/Society', 'An introduction to the central aspects of the experience of living in ancient Rome with an emphasis on the first century BCE to the second century CE. Topics include class and status, slavery, gender and sexuality, religion, health, public entertainment, and the reception of ancient Rome in our modern world. Antirequisite(s): Credit can be obtained for only one of HIST 2843 or CLAS 2843.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6613', 'APSC-1070L', 'APSC 1073 Laboratory', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1073"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6614', 'APSC-1073', 'Introduction to Engineering', 'This course provides students with basic engineering skills and knowledge that will be used through their professional life. The primary topic is technical communications (report writing, referencing sources, unit analyses, data acquisition & interpretation, effective presentations). The history and disciplines of engineering, code of ethics, and engineers'' responsibility for safety in the workplace and environmental awareness are also covered. (1h tutorial).', 'APSC', 3, 0, 1, '[{"codes":["APSC-1070L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6615', 'APSC-1110L', 'APSC 1113 Laboratory', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6616', 'APSC-1113', 'Statics', 'This is a first course in engineering mechanics, focusing on the analysis of various simple static structures. Topics include force and position vectors, dot and cross products, directed force vectors, equivalent force and moment systems, particle and rigid body equilibrium, two and three force elements, trusses, frames, machines, friction, centroids and moments of inertia. Students complete a major design project for part of their grade. (3h lab). Prerequisite(s) or Corequisite(s): MATH 1013, PHYS 1013.', 'APSC', 3, 0, 1, '[{"codes":["MATH-1013","and","PHYS-1013",""],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["APSC-1110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6622', 'APSC-1220L', 'APSC 1223 Tutorial', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1223"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6623', 'APSC-1223', 'Design 1 (CAD)', 'An introduction to the engineering design process focusing on the role of graphics in design. Students are instructed in the use of modern CAD software for the production of mechanical drawings and learn standards for same. Free hand sketching, 3-D visualization techniques and report writing are also covered. Students complete a major design project and submit a set of drawings with a written report to obtain a significant portion of their grade. (3h lab).', 'APSC', 3, 0, 1, '[{"codes":["APSC-1220L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6624', 'APSC-1410L', 'APSC 1413 Tutorial', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6625', 'APSC-1413', 'Comp Programming for APSC 1', 'This course covers the fundamental programming principles of flow control, modularity and structured programming. The student will implement significant programs in the "C" programming language to solve a variety of engineering problems. (3h lab).  Prerequisite(s) or Corequisite(s): MATH 1013.', 'APSC', 3, 0, 1, '[{"codes":["MATH-1013"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["APSC-1410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6632', 'APSC-2110L', 'APSC 2113 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6633', 'APSC-2113', 'Thermo-Fluids I', 'This course introduces the sciences of Thermodynamics and Fluid Mechanics in an integrated manner. It covers the basic properties of fluids and gasses, the ideal gas equation of state, simple compressible substances, fluid statics, work and heat interactions, the first and second laws of thermodynamics, enthalphy, entropy and specific heat, steady and unsteady flow, Carnot, Rankine and refrigeration cycles. (3h lab). Prerequisite(s): APSC 1113, MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6634', 'APSC-2120L', 'APSC 2123 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6635', 'APSC-2123', 'Thermo-Fluids 2', 'Fluid flow definitions and material properties. Fluid statics, forces on submerged surfaces, buoyancy and stability. Continuity, Euler, energy and momentum equations with engineering applications. Dimensional analysis, similitude, theory of physical models. Reynolds number, laminar vs turbulent flows, friction factor and simple piping systems. Lift and drag of submerged objects. (3h lab). Prerequisite(s): APSC 2113.', 'APSC', 3, 0, 2, '[{"codes":["APSC-2113"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6636', 'APSC-2130L', 'ASPC 2133 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2133","-","Must","be","taken","at","the","same","time","as","this","course"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6637', 'APSC-2133', 'Strength of Materials', 'Elastic deformation and failure analysis for common engineering elements. Material properties, stress strain testing and diagrams. Axial, torsion, transverse and bending loads. Stress transformations and principal stresses. Statically indeterminate problems. Design of struts, pins, shafts, pressure vessels, beams and columns. (3h lab). Prerequisite(s): APSC 1113, MATH 1023. Antirequisite(s): Credit can be obtained for only one of APSC 2133 or APSC 1133.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2130L","-","Must","be","taken","at","the","same","time","as","this","course"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6638', 'APSC-2210L', 'APSC 2213 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2213"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6639', 'APSC-2213', 'Electric Circuits 1', 'Introductory circuit analysis. Kirchoff''s laws, node and mesh analysis, terminal behaviour and circuit equivalence including Thévenin and Norton circuits. Controlled sources and energy storage elements, steady state and transient response of first order networks. Steady state AC power, phasor diagrams, power and power factor are introduced. (3h lab). Prerequisite(s): MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6640', 'APSC-2220L', 'APSC 2223 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2223"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6641', 'APSC-2223', 'Digital Systems', 'Digital logic, digital systems, machine level representation of data, principles of assembly level machine organization, principles of CPU design. Cross-coded as Comp 2203. (1.5h lab).', 'APSC', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6642', 'APSC-2323', 'Surveying', 'Chain, level, transit, EDM; Differential, contour, profile, vertical curves, grade stakes, slope stakes; triangulations, traversing, horizontal curves, coordinates; areas and volumes. Two weeks of field work required. Prerequisite(s): Permission of School of Engineering.', 'APSC', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6643', 'APSC-2410L', 'APSC 2413 Tutorial', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6644', 'APSC-2413', 'Engineering Economics', 'Topics of theoretical and applied economics of interest and use to engineers and professionals in related fields. Topics include market equilibria, interest rate determination, present and future values, investment criteria, budgeting and replacement analysis, depreciation, taxation, inflation, sensitivity and risk analysis, and multi-staged and multi-attribute decision making. (3h lab). Prerequisite(s): MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6646', 'APSC-2520L', 'APSC 2523 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2523"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6647', 'APSC-2523', 'Electric Circuits 2', 'Advanced circuit analysis dealing primarily with AC systems. The concepts of sinusoidal excitation, phasors and complex impedance are fully developed. Mutual inductance and magnetically coupled coils are used to describe transformer behaviour and performance. Power calculations for single and balanced three phase systems are covered, introducing the concepts of real and reactive power. Unbalanced networks, grounding and harmonics are also examined. (3h lab). Prerequisite(s): APSC 2213.', 'APSC', 3, 0, 2, '[{"codes":["APSC-2213"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2520L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6648', 'APSC-2610L', 'APSC 2613 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2613"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6649', 'APSC-2613', 'Comp Programming for APSC 2', 'Computer programming in the C++ language. Topics discussed include object oriented versus procedural programming, objects, stacks, queues, linked lists, trees, various sorting and searching algorithms. Students may apply the theory to develop programs for hardware control, graphics or the numerical solution of various engineering problems. (3h lab). Prerequisite(s): APSC 1413.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1413"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2610L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6651', 'APSC-2680L', 'APSC 2683 Tutorial', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2683"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6652', 'APSC-2683', 'Design 2', 'This course provides a project-based exercise in the engineering design process. Students work in teams and as individuals on defined projects which utilize knowledge gained from their previous engineering courses. The projects encompass conceptual design, detailed analysis, engineering drawings, physical model fabrication, experimentation, testing and report writing. (3h lab). Prerequisite(s): APSC 1223', 'APSC', 3, 0, 2, '[{"codes":["APSC-1223"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2680L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6653', 'APSC-2710L', 'APSC 2713 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2713"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6654', 'APSC-2713', 'Dynamics', 'The kinematics and kinetics of particles and rigid bodies. Rectangular, tangential/normal and cylindrical coordinates in translating reference frames. Application of Newton''s laws, energy method, and impulse and momentum method. Simple mechanisms with emphasis on linkages. (3h lab). Prerequisite(s): APSC 1113, MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2710L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6658', 'APSC-2810L', 'APSC 2813 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2813"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6659', 'APSC-2813', 'Engineering and the Biosphere', 'The course explores the effect of engineered systems and structures on the biosphere. Topics include cell structure and function, microbiology and toxicology, nutrient cycles, communities and ecology as these relate to engineering projects. The application of technology and design to minimize the impact of human activities on living systems is also considered. Laboratory sessions will consist of field-trips to local sites. NOTE: APSC 2813 is not considered an equivalent to any course offered through the Biology department. (3h lab). Prerequisite(s): CHEM 1023 or permission of the instructor.', 'APSC', 3, 0, 2, '[{"codes":["CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2810L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6661', 'APSC-2920L', 'APSC 2923 Laboratory', '', 'APSC', 0, 1, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6662', 'APSC-2923', 'Intro to Industrial Eng', 'This course introduces operations research models. The focus is on formulating, building and solving optimization models, primarily using Microsoft Excel. Topics to be covered include linear programming, assignment models, transportation and network models, project management, decision analysis and risk, queueing models, nonlinear optimization and case studies from other engineering disciplines. Prerequisite(s): MATH 1023; APSC 1413 or COMP 1113.', 'APSC', 3, 0, 2, '[{"codes":["#","MATH-1023","#","APSC-1413","or","COMP-1113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6663', 'APSC-3210L', 'APSC 3213 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3213"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6664', 'APSC-3213', 'Industrial Chemistry', 'An introduction to selected chemical industries, with particular emphasis on the Canadian scene. Examination of basic chemical industries and the relationship between chemistry of the process, engineering design, and equipment requirement is performed. (1h lab). Prerequisite(s): MATH 1023 and CHEM 1023.', 'APSC', 3, 0, 3, '[{"codes":["MATH-1023","CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6665', 'APSC-3310L', 'APSC 3313 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3313"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6666', 'APSC-3313', 'Fundamentals of Process Eng', 'This course seeks to develop the student''s ability to perform mass and energy balances on reactive and non-reactive processes. Topics include the fundamental properties of multiphase systems, phase equilibrium, vapour pressure, phase rule, Roault''s and Henry''s laws and colligative properties. Emphasis is placed on developing problem solving skills. (3h lab). Prerequisite(s): CHEM 1023 or CHEM 1123, MATH 1023.', 'APSC', 3, 0, 3, '[{"codes":["#","MATH-1023","#","CHEM-1023","or","CHEM-1123"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3310L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6667', 'APSC-3410L', 'APSC 3413 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6668', 'APSC-3413', 'Intro Environmental Eng', 'Overview of environmental engineering terms and definitions. Air and water quality, impact of domestic, agricultural and industrial operations on the environment. Review of pertinent legislation, measurement techniques and common control methods. Construction practices and their effects on the environment. (3h lab). Prerequisite(s): CHEM 1023, MATH 1023.', 'APSC', 3, 0, 3, '[{"codes":["MATH-1023","CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6671', 'APSC-3683', 'Special Topics Project', 'Guided study/project work in a particular area of applied science, carried out under the direction of a faculty member in the School of Engineering. Such work may involve the design, development, implementation and documentation of a significant engineering device or research to better understand an engineering problem. A written report must be submitted and/or a public presentation made upon completion of the work to receive a grade. Prerequisite(s): Third-year standing and permission of the School of Engineering.', 'APSC', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6672', 'ARAM-7013', 'Biblical Aramaic', 'This course will introduce students to the grammar, syntax, and vocabulary of the Aramaic of the Old Testament. Building off the basics of Hebrew grammar, students will learn the basic grammar and vocabulary of Biblical Aramaic. As part of this course, students will translate portions of the Aramaic sections of Daniel and Ezra. Prerequisite: HEBR 5023', 'ARAM', 3, 0, 7, '[{"codes":["HEBR-5023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6673', 'ARAM-7913', 'Directed Study in Aramaic 1', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6674', 'ARAM-7923', 'Directed Study in Aramaic 2', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6675', 'ARAM-7933', 'Directed Study in Aramaic 3', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6676', 'ARAM-7943', 'Directed Study in Aramaic 4', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6677', 'ARAM-7953', 'Directed Study in Aramaic 5', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6678', 'ARAM-7963', 'Directed Study in Aramaic 6', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6681', 'ART-1813', 'Hist of Art: Prehistory-1400', 'Art from prehistoric times to Giotto is considered in relation to its cultural and historical context. Cross-coded as HIST 1813. Antirequisite(s): Credit can be obtained for only one of ART 1813 or HIST 1813.', 'ART', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6682', 'ART-1823', 'Hist of Art: 1400 to Present', 'Art from the time of Giotto to the present is considered in relation to its cultural and historical context. Antirequisite(s): Credit can be obtained for only one of ART 1823 or HIST 1823.', 'ART', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6685', 'ART-2013', 'Drawing 1', 'Studio art course for beginners and those with more advanced technical skills. Students maintain a sketchbook and learn techniques like contour, value studies, textural inquiry and perspective. Realism and abstraction are explored. Limited to 14 students.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6687', 'ART-2023', 'Drawing 2', 'This course develops concepts and skills introduced in ART 2013, although ART 2013 is not a prerequisite. Students will learn more complex and imaginative drawing techniques working in realism and abstraction. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 16   participants', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6688', 'ART-2033', 'Digital Imaging 1', 'An introduction to the computer as an art-making tool. Students will learn to create, develop, manipulate and enhance digital images with several applications using their laptop computer as a mobile studio.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6689', 'ART-2043', 'Digital Imaging 2', 'The ethics, aesthetics, and theory of digital image making will be addressed. Through assignments and experimentation, the student will create, acquire, manipulate and output of digital images with several applications using the laptop computer as a mobile studio. Prerequisite(s): ART 2033.', 'ART', 3, 0, 2, '[{"codes":["ART-2033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6690', 'ART-2053', 'Art and the Environment 1', 'This course addresses environmental issues through art, with a focus on the landscape model. It provides students with both "hands on" and academic assistance to allow them to undertake visual studies of local urban and rural landscapes, with the possibility of wilderness study. This course utilizes representational drawing and painting, working with drawing materials with an introduction to watercolour.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6691', 'ART-2063', 'Art and the Environment 2', 'This course addresses environmental issues through art, with a focus on the landscape model. It allows students to undertake visual studies of local landscapes. Students will develop their own imagery employing both realism and abstraction of their work. This course explores the production of images using acrylic on both paper and canvas surfaces.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6692', 'ART-2073', 'Contemporary Art', 'An examination of western art from 1945 to the present. Topics include the development of abstract expressionism, minimalism and post-minimalism, conceptualism, and pluralism in both two-dimensional and three-dimensional media.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6693', 'ART-2083', 'Canadian Art 1', 'The history of the visual arts in Canada from the sixteenth century to the early twentieth century with special emphasis on painting and sculpture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6694', 'ART-2093', 'Canadian Art 2', 'The history of the visual arts in Canada from the early twentieth century to the present with special emphasis on painting and sculpture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6701', 'ART-2313', 'American Art', 'Major developments in American art from the colonial period to the present. Major emphasis will be placed on specific artistic groups, major artists, pivotal artistic events, and themes specific to American culture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6703', 'ART-2413', 'Art of the Nineteenth Century', 'Major developments in European art from the time of the French Revolution to the end of the century. Emphasis is placed on movements such as neo-classicism, romanticism, impressionism, and post-impressionism.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6704', 'ART-2423', 'Art of the 20th C. 1900-1945', 'Major developments in western art from 1900-1945. Major movements such as expressionism, cubism, Surrealism, and Dadaism will be emphasized.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6706', 'ART-2623', 'Art 17th & 18th C.', 'Selected work from these centuries is studied in relationship to its cultural, political, and economic context. Emphasis will be placed on such major figures as Rembrandt, Velazquez, Caravaggio, Watteau, and others.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6707', 'ART-2813', 'Art of the Indian Subcontinent', 'A general survey of the architecture, sculpture, and painting with particular emphasis on the development of the Hindu temple and of the Buddha image.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6712', 'ART-3013', 'Painting: Wtrcolour, Pen, Ink', 'A studio art course in which students will learn pen and ink, as well as complex watercolour techniques, and work to create realistic, multi-technical paintings on paper. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 14 students.', 'ART', 3, 0, 3, '[{"codes":["ART-2013","or","ART-2023","or","permission","of","instructor",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6714', 'ART-3023', 'Painting 2: Acrylic', 'Students will learn acrylic painting techniques, including colour mixing, scales, and brush work, and will   produce a professional-style large-format painting on gallery canvas suitable for exhibition. Realism and abstraction are explored. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 14 students.', 'ART', 3, 0, 3, '[{"codes":["ART","2013","or","ART","2023","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6715', 'ART-3033', 'Art and Identity 1', 'In this course, art will be employed as both a tool and potentially a catalyst in our search for the meaning of identity. This will be accomplished through a visual exploration of memory on a personal and cultural level. Prerequisite(s): ART 2013 or permission of the instructor.', 'ART', 3, 0, 3, '[{"codes":["ART-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6716', 'ART-3043', 'Art and Identity 2', 'In this course, art will be employed as both a tool and potentially a catalyst in our search for the meaning of identity. This will be accomplished through a visual exploration of memory on a personal and cultural level. Prerequisite(s): ART 2013 or permission of the instructor.', 'ART', 3, 0, 3, '[{"codes":["ART-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6724', 'ART-3313', 'Special Topics in Hist of Art', 'This course examines selected topics in the history of western and non-western art not included in the established curriculum. May be repeated for credit with change of topic.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6725', 'ART-3323', 'Art Critcl Theo & Methds', 'A study of various scholarly approaches to the history of art, as well as theories which inform these approaches. Prerequisite(s): 6h ART and permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6728', 'ART-3513', 'Woman and Art', 'An examination of women in art, as subjects and as artists, from the middle ages to the present. Emphasis is placed on their contribution to the history of western art as producers of major paintings, sculptures, and craft objects.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6730', 'ART-3613', 'Art Ind. Study Studio 1', 'Individual study of problems in studio art, for highly motivated students, developed with and directed by a supervising professor. Prerequisite(s): Permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6731', 'ART-3623', 'Art Ind. Study Studio 2', 'Individual study of problems in studio art, for highly motivated students, developed with and directed by a supervising professor. Prerequisite(s): Permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6732', 'ART-3713', 'Art Directed Readings 1', 'This course consists of supervised readings and research projects in a specific area of the history of art to be chosen in consultation with a faculty member to culminate in the preparation of a major research paper using technical and critical literature in the history of art. Prerequisite(s): 12h ART (history) and permission of the instructor.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6733', 'ART-3723', 'Art Directed Readings 2', 'This course consists of supervised readings and research projects in a specific area of the history of art to be chosen in consultation with a faculty member to culminate in the preparation of a major research paper using technical and critical literature in the history of art. Prerequisite(s): 12h ART (history) and permission of the instructor.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6741', 'BIBL-3063', 'Interpreting the Bible', 'This course on how to interpret the Christian Scriptures examines and integrates practical and theoretical perspectives on the Biblical writings. Students will learn how to read, interpret, and apply the Bible. Among the various subjects discussed are: Bible translations, text and context, literary genres, and the influence of our own cultural context on interpretation.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6742', 'BIBL-2023', 'Survey of the Bible', 'This course lays the foundation for advanced study of the Bible by helping students acquire knowledge of the basic contents and narrative of the Bible.', 'BIBL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6743', 'BIBL-3013', 'Intro to the Old Testament 1', 'An examination of Genesis through Nehemiah. This course will survey these texts within the historical, political, and religious contexts of the Ancient Near East, and will introduce the student to the academic, literary, and theological study of this section of the Bible.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6744', 'BIBL-3023', 'Intro to the Old Testament 2', 'An examination of Esther through Malachi. This course will survey these texts within the historical, political, and religious contexts of the Ancient Near East, and will introduce the student to the academic, literary, and theological study of this section of the Bible. Prerequisite(s): BIBL-2053; BIBL-3013 recommended.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6745', 'BIBL-3033', 'Intro to the New Testament 1', 'An examination of the New Testament gospels. This course will survey these texts within their 1st century historical, political, and religious contexts, and will introduce the student to the academic, literary, and theological study of this section of the Bible.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6746', 'BIBL-3043', 'Intro to the New Testament 2', 'An examination of Acts to Revelation. This course will survey these texts within their Greco-Roman contexts, and will introduce the student to the academic, literary, and theological study of these sections of the Bible. Prerequisite(s): BIBL 2053; BIBL 3033 recommended.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-3033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6747', 'BIBL-3053', 'Israel Study Tour', 'A study tour in Israel and the Palestinian Territories (and surrounding areas as possible) designed to introduce the geography of the land and to shed light on events of the Old and New Testaments and the intertestamental period. Some consideration will also be given to the role that Christians and the Church have played in the land in ancient and modern times.', 'BIBL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6748', 'BIBL-3143', 'Death,Burial&Resurrec Jesus', 'The death, burial and resurrection of Jesus is central to historic Christian belief. This course will consider how the historicity of these events can be established confidently, despite criticisms and objections. Through a close reading of the evidence in the four Gospels and other portions of the New Testament, and examination of other historical and archeological evidence, the historicity of these events will be explored.', 'BIBL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6750', 'BIBL-5013', 'Survey of the Bible', 'This course lays the foundation for advanced study of the Bible by helping students acquire knowledge of the basic contents and narrative of the Bible. This course is required of students who have not passed the Bible Knowledge Entrance Test. Normally, this course is taken prior to, or concurrent with, BIBL 5023 or BIBL 5033.', 'BIBL', 3, 0, 5, '[{"codes":["BIBL-5023","or","BIBL-5033"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6751', 'BIBL-5023', 'Interpreting the Old Testament', 'The Old Testament contains most of the Christian Bible. This course will introduce the student to the different sections and genres of literature in the Old Testament, to interpretative methods appropriate to them, and to theological principles. The course will also survey aspects of the historical and cultural context of the Old Testament. This course assumes knowledge of the contents of the Old Testament, and is the foundation for advanced studies.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6752', 'BIBL-5033', 'Interpreting the New Testament', 'This course will introduce the student to the different sections and genres of literature in the New Testament, to interpretative methods appropriate to them, and to theological principles. The course will also survey the world of Jesus and the early Christian Church. This course assumes knowledge of the contents of the New Testament, and is the foundation for advanced studies.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6753', 'BIBL-5043', 'Death,Burial&Resurrec Jesus', 'The death, burial and resurrection of Jesus is central to historic Christian belief. This course will consider how the historicity of these events can be established confidently, despite criticisms and objections. Through a close reading of the evidence in the four Gospels and other portions of the New Testament, and examination of other historical and archeological evidence, the historicity of these events will be explored.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6754', 'BIBL-5503', 'Hebrew Scripture Foundations', 'A general introduction to the historical, sociological, and theological context in which the Hebrew Scriptures came into existence, this course will provide the student with an understanding of the major emphases of the texts. In addition, the student will be introduced to themes of community life and praxis in the Hebrew Scriptures that find parallels in historical Indigenous worldviews of creation and Creator. The course will use community understandings, models and paradigms as a basis for comparison. This course is normally taught by an Indigenous instructor. This course is normally available only to students enrolled in the MA-INCD program.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6755', 'BIBL-5513', 'New Testament Foundations', 'A general introduction to the historical, sociological, and theological context in which the New Testament Scriptures came into existence, this course will familiarize students with the content and structure, distinctive theology, and introductory matters of the New Testament. In addition, the student will be introduced to the nature of the early Christian community, its transitions and changes from a strictly Hebraic construct as found within the Jewish community, and projections made for its future development. This course is normally taught by an Indigenous instructor. This course is normally available only to students enrolled in the MA-INCD program.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6757', 'BIBL-6013', 'Genesis', 'In this course students will study the book of Genesis by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Genesis and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6758', 'BIBL-6023', 'Deuteronomistic History', 'In this course students will study selected texts from Joshua, Judges, 1 and 2 Samuel, and 1 and 2 Kings by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in these books and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6759', 'BIBL-6033', '1 & 2 Chron & Ezra-Nehemiah', 'In this course students will study the books of 1 and 2 Chronicles and Ezra-Nehemiah by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in 1 and 2 Chronicles, Ezra-Nehemiah, and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6760', 'BIBL-6043', 'Daniel', 'In this course students will study the book of Daniel by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and apocalyptic world-view will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Daniel and other apocalyptic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6761', 'BIBL-6053', 'Amos and Isaiah', 'In this course students will study the books of Amos and Isaiah by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and social justice issues will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Amos, Isaiah, and other prophetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6762', 'BIBL-6063', 'Psalms', 'In this course students will study the book of Psalms by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and poetic technique will also be receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Psalms and other poetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6763', 'BIBL-6113', 'The Gospel of Matthew', 'In this course students will study Matthew''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and Matthew''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Matthew and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6764', 'BIBL-6123', 'Luke-Acts', 'Luke-Acts is a two-part work that describes the life and ministry of Jesus and moves seamlessly to the life and ministry of the church, with the early church''s ministry modelled upon the ministry of Jesus. This course will examine the narrative and theological unity of Luke-Acts, focusing particularly on the mission of the early church. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6765', 'BIBL-6133', 'The Gospel of John', 'In this course students will study the John''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and John''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in John and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6766', 'BIBL-6143', 'Romans and Galatians', 'In this course students will study the Epistles of Romans and Galatians by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study of the apostle Paul''s major epistles to the churches in Galatia and in Rome, the epistles'' contribution to the Christian teaching regarding righteousness and justification before God will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Romans, Galatians and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6767', 'BIBL-6153', 'Hebrews and James', 'In this course students will study the Epistle to the Hebrews and James by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study of Hebrews and James, these letters'' contribution to the Christian understanding of Jesus Christ''s saving work will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Hebrews and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6768', 'BIBL-6163', 'Philippians, Colos, Eph, Phil', 'In this course students will study Paul''s Prison Epistles by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study these epistles, these letter''s contribution to Christology and a life of integrity in the face of adversity will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in the Prison Epistles and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6771', 'BIBL-6503', 'Community Models in Scripture', 'This course is a theological and exegetical exploration of how the Scriptures speak about community, how they present and promote particular values and praxis of community, and what examples of community appear in both testaments. This understanding is critical to a community development program focused through the lens of a biblically-informed worldview. Finally, the course will seek to enable understanding of the nature of community in the early church and its implications, if any, on our thinking about the holistic development of community within the Kingdom of God.', 'BIBL', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6780', 'BIBL-7113', 'Dead Sea Scrolls', 'This course introduces students to the Dead Sea Scrolls and their contribution to our understanding of the world of Jesus and the early Church. The course surveys the Scrolls and related literature of the intertestamental and New Testament periods, including a survey of the history of these periods and the debate surrounding the origin of the Scrolls. The course engages in the study of a number of texts and themes that shed light on Jesus, the Gospels, and Paul. Prerequisite: BIBL 5023, 5033.', 'BIBL', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6781', 'BIBL-7123', 'Life and Teaching of Jesus', 'This course offers an introduction to the life of Jesus, with emphasis on religious and historical context. Sources-canonical and noncanonical-will be critically assessed, criteria for determining authenticity will be reviewed, and the history of critical study of the life of Jesus will be surveyed. Prerequisite: BIBL 5033.', 'BIBL', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6782', 'BIBL-7133', 'Israel Study Tour', 'A study tour in Israel and the Palestinian Territories (and surrounding areas as possible) designed to introduce the geography of the land and to shed light on events of the Old and New Testaments and the intertestamental period. Some consideration will also be given to the role that Christians and the Church have played in the land in ancient and modern times.', 'BIBL', 3, 0, 7, '[]');
