INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6816', 'BIBL-7733', 'MA Guided Read: 2nd Temple 1', 'A guided reading course surveying significant scholarship in the field of Second Temple Judaism.', 'BIBL', 3, 0, 7, '[]');
