INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7502', 'CLAS-2833', 'Ancient Greece Culture/Society', 'An introduction to the central aspects of the experience of living in ancient Greece. Topics include legal institutions, gender and sexuality, domestic life, warfare, economic activities, religion and ritual, slavery, commerce, health, athletic competition, philosophy, and the reception of ancient Greece in our modern world. Emphasis will be placed on Athens and Sparta, from the Archaic through the Hellenistic periods. Antirequisite(s): Credit can be obtained for only one of CLAS 2833 or HIST 2833.', 'CLAS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7503', 'CLAS-2843', 'Ancient Rome Culture/Society', 'An introduction to the central aspects of the experience of living in ancient Rome with an emphasis on the first century BCE to the second century CE. Topics include class and status, slavery, gender and sexuality, religion, health, public entertainment, and the reception of ancient Rome in our modern world. Antirequisite(s): Credit can be obtained for only one of CLAS 2843 or HIST 2843.', 'CLAS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7505', 'CLAS-1803', 'Introduction to Archaeology', 'A hands-on introduction to the discipline of archaeology, with a geographic focus on the Mediterranean, North Africa, Europe, and Western Asia. Students will gain firsthand experience in archaeological practice, remote sensing, ceramic analysis, excavation, survey, site and artifact recording, osteoarchaeology, 3D scanning/printing, and petrography. Special emphasis is placed on archaeological theory, ethics, and the role of archaeology in popular media. Restricted to students with first or second year standing, or with permission of the instructor.', 'CLAS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7506', 'CLAS-2013', 'Greek Art and Archaeology', 'An introduction to the art and archaeology of ancient Greece from the Aegean Bronze Age to the Hellenistic period. Attention is given to art historical and archaeological approaches to ancient Greek visual and material culture in public and private contexts both within Greece and the wider Mediterranean world.', 'CLAS', 3, 0, 2, '[{"codes":["Minimum","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7507', 'CLAS-2023', 'Roman Art and Archaeology', 'An introduction to Roman art and architecture from the founding of Rome to the reign of Constantine. Attention is given to art historical and archaeological approaches to Roman visual and material culture in public and private contexts with an emphasis on the city of Rome and Italy.', 'CLAS', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7512', 'CLAS-2233', 'Scientific Terminology', 'The Greek and Latin origins of the technical vocabulary of modern science. For biology and pre-med students, but of obvious interest to students of all sciences. An examination of the Greek and Latin root words in scientific terminology and their combination and modification in English. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7516', 'CLAS-2273', 'Gods of Greek & Roman Myth', 'A study of the gods of the mythology of the ancient Greeks and Romans as they appear in art and literature. This will include representations in the eighth century BCE epic poets of the Greek world through to the syncretism of these gods under Roman authors and artists and attention. The course also considers contemporary representations of classical myth.', 'CLAS', 3, 0, 2, '[{"codes":["Minimum","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7517', 'CLAS-2283', 'Heroes in Greek & Roman Myth', 'The hero and heroine in Greek and Roman literature and art, from the influence of Near Eastern myths on epic cycles of eighth century Greece to the refashioning of the hero and heroine in Roman myth. This course emphasizes contemporary approaches to heroic myths within their ancient social context and their universal inspiration in storytelling.', 'CLAS', 3, 0, 2, '[{"codes":["Minimum","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7518', 'CLAS-2293', 'Cult of Grapes in Anct Greece', 'From the cultivation of the grape to the cult of Dionysus, god of wine, this course shall study the economic, religious, social and cultural impact of wine on ancient Greece, with a special focus on classical Athens. No prerequisite.', 'CLAS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7527', 'CLAS-2553', 'Archaeology of Ancient Egypt', 'Egypt from the Predynastic period to the Roman era. A survey of the historical development of ancient Egypt from the perspective of archaeology and art history, including cultural and political relations with neighbouring cultures of the ancient world.', 'CLAS', 3, 0, 2, '[{"codes":["Minimum","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7529', 'CLAS-2583', 'Greece, Rome in Pop Culture', 'Classical culture in contemporary art, literature, and the popular culture of advertising, comics, film, music, graphic novels, sport and video games. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7531', 'CLAS-2663', 'Class Greece: State & Society', 'A study of the social, economic and political institutions of classical Greece (450-350 BCE). Special attention will be paid to political constitutions, influence of gender on the roles of men and women in Greek society, institutionalization of pederasty, household management, status of women and children, and practice of slavery. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7532', 'CLAS-3653', 'Roman History: Republic/Empire', 'A seminar on Rome''s political, military and institutional history with an emphasis on the evolving nature of state and society in the Late Republic and Early Empire through the study of literary, epigraphic and archaeological evidence.', 'CLAS', 3, 0, 3, '[{"codes":["Minimum","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7533', 'CLAS-2693', 'Special Topics', 'Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 2, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7534', 'CLAS-3113', 'Roman Law and Society', 'A seminar course on Roman law from the earliest legal texts to their codification under the emperor Justinian. Topics include the development of private and criminal law; treatises of the Roman jurists; the role of law in shaping social, political, and economic life of the Roman world; and the influence on later western legal systems. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7535', 'CLAS-3123', 'Gend/Sex Mediterranean World', 'A study of the social and cultural dimensions of gender and sexuality in the ancient Mediterranean world with a focus on the cultures of the ancient Greeks and Romans. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7536', 'CLAS-3133', 'Nature in Ancient Greece', 'A study of various aspects of engagement with nature in ancient Greek culture and society: economic engagement with the natural environment; civic engagement with nature in rural and urban settings; spiritual engagement with nature in art, myth and religion; intellectual engagement with nature in literature and philosophy. Familiarity with ancient Greece is not a prerequisite. Prerequisite(s): 30h of university courses, or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7540', 'CLAS-3333', 'Greek Historians & Histrigrphy', 'A study of the origin and development of historiography in ancient Greece involving the intensive study of the major classical historians in translation. May be offered for major credit in history. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7542', 'CLAS-3423', 'Greek and Roman Novel', 'The prose romance and novel of the later Greek and Roman world in the context of the social, intellectual, and cultural life of this era. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7544', 'CLAS-3453', 'Fieldwork Class Archaeology', 'A seminar in archaeology and field methods offered in the summer, typically off campus. This course involves a 30-day study period in the Mediterranean focusing on classical archaeology. Due to funding and supervision this will be offered with limited enrolment. Prerequisite(s): 3h from CLAS 1503, CLAS 1803, CLAS 2013, CLAS 2023, or equivalent.', 'CLAS', 3, 0, 3, '[{"codes":["CLAS-1503","or","CLAS-2013","or","CLAS-2023","or","CLAS-2503","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7546', 'CLAS-3673', 'Ritual, Mystery & Temple', 'An examination of the archaeological and literary evidence for the religions of Rome. Attention is given to private and public religious activities and their roles in supporting the state. As religion is an aspect of daily life in which women and slaves had significant roles, gender and status are important components of the subject. May be taken for Women''s and Gender Studies credit. Prerequisite(s): 30h of university courses or permission of the instructor.', 'CLAS', 3, 0, 3, '[{"codes":["Completed","30h","of","university","credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7596', 'CODE-1010L', 'CODE 1013 Laboratory', '', 'CODE', 0, 1, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7597', 'CODE-1013', 'Leadership in Community Devel', 'A theoretical and experiential investigation of leadership and group dynamics for professional and voluntary settings. Emphasis is given to the application of theory for effective leadership of groups and organizations within a community development context. Prerequisites: Restricted to first-year CODE students. Antirequisite(s): Credit can be obtained for only one of CODE 1013 or ESST 2003.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7598', 'CODE-1023', 'Enviro & Sustainable Society', 'This introductory course explores the connectedness of individual, local, regional and international responsibility to address global issues such as climate change, poverty, consumerism, and natural resource utilization through social, political, and environmental action. It examines their uneven impact on diverse socioeconomic and cultural communities as well as the potential of collective initiatives for a more just and sustainable world. This course also reviews encouraging innovations and achievements by individuals, organizations, communities and governments in shifting to a more sustainable and just society. Restricted CODE students and ESST students, or by permission of the Department.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7599', 'CODE-1030L', 'CODE 1033 Laboratory', '', 'CODE', 0, 1, 1, '[{"codes":["CODE-1033"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7600', 'CODE-1033', 'Community Development', 'An exploration of the characteristics of healthy communities and models of community building as a means to enhance quality of life for individuals and groups. The course takes a systems approach in providing an overview of the principles and strategies for the assessment and development of community wellness, drawing on examples from geographic communities and communities of interest. (1.5h lab). Open only to Community Development majors, or with permission of the Department.', 'CODE', 3, 0, 1, '[{"codes":["CODE-1030L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7601', 'CODE-1043', 'Communication in Community', 'This introductory course develops foundational communication skills for success in academic, professional, and community contexts. Students explore the communication process, information literacy, academic and professional writing, oral presentation, and the ethical use of digital and AI-enabled tools. Emphasis is placed on working collaboratively, building confidence, strengthening credibility, and applying adaptable strategies to communicate effectively with diverse audiences. Restricted to BCD students only. Antirequisite(s): Credit can be obtained for only one of CODE 1043 or COMM 1013, or COMM 1213.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7603', 'CODE-1523', 'Outdoor Recreation', 'This course examines outdoor recreation management through community contexts. Emphasis is placed on how outdoor recreation supports well-being, inclusion, and connection to place, while exploring leadership, risk management, group dynamics, and decision-making. Students consider management challenges related to access, equity, sustainability, and community-based outdoor  recreation experiences. Open to non-majors.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7604', 'CODE-1533', 'Sustainable Tourism', 'Sustainable tourism provides a framework for examining tourism. Topics include tourist behaviour, tourism planning, socio-cultural, marketing, and the role of tourism organizations. Case studies will emphasize both theoretical and applied dimensions of sustainable tourism. Open to non-majors.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7605', 'CODE-1543', 'Sport & Physical Activity', 'This course encourages students to think critically about the nature of sport and physical activity in relation to leisure. Particular attention is placed on how sport and physical activity have become both the products of and producers of dominant contemporary cultures. Open to non-majors.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7606', 'CODE-1963', 'Intro: Topics Community Devel', 'This course takes advantage of particular expertise of permanent or visiting faculty to provide introductory exposure to theory and practice concerning a contemporary issue such as entrepreneurship, advocacy or fields. This course focuses on a professional competency such as entrepreneurship, advocacy or reconciliation that can be further cultivated throughout a student''s degree program.', 'CODE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7608', 'CODE-2023', 'Commnty Develop Rsrch Meth.', 'The role of research within community development. Issues related to the development of research questions, and the collection, interpretation and application of research data are examined. Prerequisite(s): Second-year standing in BCD. Antirequisite(s): Credit can be obtained for only one of CODE 2023 or ESST 3003.', 'CODE', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7609', 'CODE-2033', 'Sustainable Community Devel', 'This course explores the various dimensions of community capital (e.g., natural, environmental, economic, and socio-cultural capital) and how these can be managed for sustainable community. Tools and concepts for conceiving, planning, and managing sustainable community will be examined from a transdisciplinary perspective drawing on readings, case studies, and field experiences.  Prerequisites: Second-year standing in BCD and ESST or permission of the Department.', 'CODE', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7610', 'CODE-2513', 'Concepts of Leisure', 'This course will examine individual and group leisure behaviour, and the many roles of leisure in society. An emphasis will be placed on the social construction of leisure within Canadian society. Prerequisites: Second-year standing in BCD and ESST or permission of the Department.', 'CODE', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7611', 'CODE-285A', 'Community Development Practice', 'This applied half-credit (1.5h) course focusses on developing professional skills and applying them in community development settings. It builds on core theory and concepts, and helps students appreciate and experience the challenges in applying them in organizational and community settings. The course topic and content will vary based on student interests, community opportunities, and faculty experience.', 'CODE', 1.5, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7612', 'CODE-3013', 'Community Design & Wellness', 'A key challenge for all communities is to manage their infrastructure to enhance community wellness while ensuring long-term social, economic, and environmental sustainability. This course examines the influence of a community''s infrastructure- defined as the interacting system of physical structures, services, institutions, and policies that impact a community''s overall physical, emotional, spiritual, and economic health and wellness. Prerequisite(s): Third-year standing in BCD, ESST, or KINE, or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","in","BCD,","ESST,","or","KINE,","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7613', 'CODE-3023', 'Community Program Design', 'The course examines the community and recreation programming process from organizational culture, through program development, to implementation and evaluation. Case studies as well as intensive small group work to design and lead a significant community program are used to facilitate program design understanding and skills. Prerequisite(s): Third-year standing in BCD or permission of the Department.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7615', 'CODE-3513', 'History & Phil of Leisure', 'A historical and philosophical overview of the roots of leisure, the conditions in society that have affected leisure, and the societal and institutional responses to those conditions through recreation management and community development. Prerequisite(s): Third-year standing in BCD or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7616', 'CODE-3523', 'Parks/Open Space Res Dev', 'A seminar which explores issues and management topics related to human use of parks and open space. Seminars will address a variety of ethical and technical topics including environmental impact assessment, sustainable development and system policy. Prerequisite(s): Third-year standing in the BCD or BA ESST, or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7617', 'CODE-3543', 'Natural Resource/Enviro Mgmt', 'The exploration of theory and issues in natural resource and environmental management with emphasis on rural community development issues, ecosystem management, outdoor recreation and nature-based tourism. The theoretical focus will be on policy decision making. Case studies will be drawn from forestry, agriculture and land-use planning fields as well as natural resource recreation and tourism, and parks and protected areas management. Prerequisites: open to non-majors, third-year standing or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7618', 'CODE-3553', 'Leisure Educ Princ. & Proces.', 'This course will focus on understanding the sources of leisure education in society today, principles that underlie leisure education, and approaches used to educate various segments of the population about leisure. Various models, assessment tools, and intervention strategies of leisure education are introduced and discussed. Content will include the design, delivery, and evaluation of various types of leisure education initiatives. Prerequisite(s): Third year BCD standing or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7619', 'CODE-3560L', 'CODE 3563 Laboratory', '', 'CODE', 0, 1, 3, '[{"codes":["CODE-3563"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7620', 'CODE-3563', 'Environmental Education', 'Environmental education is critical to shifting toward a more sustainable society. This seminar, emphasizing experiential and community learning, provides an overview in leisure, educational, community and work settings. Emphasis is on philosophy, concepts and techniques required to create powerful interactive programs. Prerequisite(s): CODE 1023, ENVS 1013 or permission of the Department, open to non-majors (2.5h lab).', 'CODE', 3, 0, 3, '[{"codes":["CODE-1023","and","ENVS-1013","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CODE-3560L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7621', 'CODE-3573', 'Festival & Special Event Mgmt', 'A systematic approach to the planning, development, marketing and staging of major community events and festivals as tourist attractions, catalysts for development, and image builders for attractions, communities and destinations areas. Particular attention will be given to the needs of performers, participants and local residents as they relate to the fields of event tourism and festival and event management. Prerequisite(s): Enrolment in BCD/BKIN.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7622', 'CODE-3583', 'Diversity, Equity&Social Just', 'This course will examine the challenges, rewards and best practices of how communities embrace diversity, while creating a culture of equity and inclusivity. Using problem-based learning and critical reflection students will explore diversity and inclusion topics of interest that relate to community engagement. Prerequisites: Third-year standing in BCD or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7623', 'CODE-3593', 'Ecotourism & Nature Based Trsm', 'An examination of ecotourism''s and nature tourism''s impacts on host communities, natural resources, visitors, and community infrastructure as well as its influence on broader environmental, social/cultural, and economic sustainability processes. Illustrative case studies will be drawn from a broad range of Canadian and international examples (open to non-majors). Prerequisite(s): Third-year standing or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7624', 'CODE-3603', 'Sust. Food Systems/Comm Dev', 'This course uses an experiential approach to understanding sustainable food systems theory and practice. Students will explore the current and historical context, and applications of sustainability, citizenship, sovereignty, security, and policy in food and food systems. Through hands on activities and field trips, students will learn foundational food skills and broaden their capacity as growers, eaters, and food citizens. Prerequisite(s): Third-year standing in BCD or ESST or permission of the Department.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7625', 'CODE-2613', 'Facilitation', 'This course explores theories and practices of group development and facilitation in community and interpersonal group contexts. It introduces a range of facilitation concepts and strategies to develop cohesiveness and trust, maximize equitable and participatory processes, welcome and listen to diverse viewpoints, and transform conflict into creative cooperation. Concepts will be applied, with an emphasis on experiential learning. Prerequisites: BCD students who have completed 30 credits or more, or permission of the Department.', 'CODE', 3, 0, 2, '[{"codes":["BCD","students","who","have","completed","30","credits","or","more,","or","permission","of","the","instructor."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7626', 'CODE-2623', 'International Community Dev', 'This course situates community development within the broader global context and draws connections between relevant historical, social, economic, political, and environmental perspectives. Students will explore the individual and collective implications of responsible global citizenship and community development practice. Prerequisites: BCD students who have completed 30h or more, or permission of the Department.', 'CODE', 3, 0, 2, '[{"codes":["BCD","students","who","have","completed","30","credits","or","more,","or","permission","of","the","instructor."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7627', 'CODE-3963', 'Special Topics:Community Dev.', 'In-depth study of a selected current topic in the field. This course is designed to enable students to take advantage of a particular expertise of visiting or permanent faculty and will be offered from time to time as circumstances dictate. Prerequisite(s): Permission of the Department.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7628', 'CODE-3973', 'Explorations in Comm Dev Educ', 'An exploration of professional development opportunities outside the traditional university course structure that are not normally found in professional institutes, workshops and mini-courses. Evidence of credit hour course equivalency, relevance to the student''s specific program of study, and suitable academic standards must be provided prior to participation. A written report, with possible additional academic assignments, is required. Prerequisite(s): Permission of the Department.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7629', 'CODE-3983', 'Exploration:Adv Enviro Advo', 'This course integrates personal, physical and intellectual development through environmental advocacy, wilderness travel, and community engagement. Situated in an area of cultural interest, physical challenge, and environmental concern; this "journey" provides a unique and challenging learning setting utilizing teaching resources from both Acadia University and Outward Bound Canada. Normally offered in the spring and/or summer sessions.', 'CODE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7630', 'CODE-4010L', 'CODE 4013 Laboratory', '', 'CODE', 0, 1, 4, '[{"codes":["CODE-4013"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7631', 'CODE-4013', 'Strategic Planning Comm Dev', 'An exploration of the conceptual and procedural theory regarding planning and public policy in community development. Emphasis will be placed on organizational, community, and governmental decision-making processes. The laboratory focuses on planning applications. (1.5h lab) Prerequisite(s): successful completion of all CODE Core courses in the 1000, 2000, and 3000 levels, or permission of the Department.', 'CODE', 3, 0, 4, '[{"codes":["CODE-1013,","CODE-1023,","CODE-1033,","CODE-1043,","CODE-2023,","CODE-2033,","CODE-3013","and","CODE-3023","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CODE-4010L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7632', 'CODE-4033', 'Senior Seminar in Code', 'This capstone course provides opportunities to critically reflect on community development issues. Local, regional, national and international examples of social change, advocacy, and sustaianability are explored through the application of community development concepts and tools  Prerequisite(s): Successful completion of all CODE Core courses in the 1000, 2000, and 3000 levels, or permission of the Department.', 'CODE', 3, 0, 4, '[{"codes":["CODE-1013,","CODE-1023,","CODE-1033,","CODE-1043,","CODE-2023,","CODE-2033,","CODE-3013","and","CODE-3023","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7633', 'CODE-4059', 'Community & Pro Engagement', 'This team-taught course provides opportunities for final year students to apply their accumulated knowledge and expertise in professional community development experiences. Students normally complete a three- week community development project (locally or internationally) and a six-week professional placement or with departmental permission complete a nine-week professional placement that integrates an advanced community development research project. Prerequisites: Successful completion of all CODE Core courses in the 1000, 2000, and 3000 levels, or permission of the Department.', 'CODE', 9, 0, 4, '[{"codes":["CODE-1013,","CODE-1023,","CODE-1033,","CODE-1043,","CODE-2023,","CODE-2033,","CODE-3013","and","CODE-3023","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7636', 'CODE-4963', 'Directed Study', 'This course is a supervised study of current knowledge in a selected topic. A major paper or project is produced in conjunction with a faculty advisor. The study will be carried out in accordance with the procedures of the program. Prerequisite(s): Permission of the instructor.', 'CODE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7637', 'CODE-4973', 'Independent Study', 'A substantial research project chosen in consultation with the faculty advisor to reflect student interest and the application of community development theory. The project seeks to draw an original conclusion based on information derived from research. The study will be carried out in accordance with the procedures of the program. Prerequisite(s): Permission of the instructor.', 'CODE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7640', 'CODE-5033', 'Community Development Seminar', 'The seminar comprises an investigation of the relationships among the concepts, issues and problems associated with community development. It is a theory-based approach to the process of identifying and critically examining the conditions which influence community development in contemporary society. Seminars consist of discussions relative to student presentations and prescribed readings.', 'CODE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7641', 'CODE-5056', 'Community Devel Practicum', 'This course is designed to integrate practical experience with applied research in a community development or allied field setting, or an in-depth exposure to post-secondary teaching in community development. The nature of the placement is determined by the student''s interest in consultation with, and with the approval of, the graduate student''s program supervisor.', 'CODE', 6, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7642', 'CODE-5073', 'Research Methods', 'This course examines the application of research techniques and methodologies to community development. The topics include discussion of current community development and evaluation, methodologies and analyses and research design.', 'CODE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7643', 'CODE-5513', 'Applied Community Development', 'Review and analysis of selected topics in community development. Specific topics, format and content of course are negotiated on an individual or small group basis with members of the faculty.', 'CODE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7644', 'CODE-5553', 'Community Development Theory', 'Review and analysis of selected topics in community development theory. Specific topics, format and content of course are negotiated on an individual or small group basis with members of the faculty.', 'CODE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7645', 'CODE-5960', 'Graduate Thesis', 'Every candidate must prepare an approved thesis based on original work under the direction of a supervisor appointed by the school.', 'CODE', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7646', 'COMM-1013', 'Communication for Kinesiology', 'This course will help kinesiology majors master effective written and oral communication skills to succeed in the field. Students will be given practically oriented theory plus various writing assignments and public speaking challenges. To address the interdisciplinary nature of the field and related issues in communication ethics, a contextual approach to formal (scholarly and professional) communication will be emphasized. Prerequisite(s): BKIN and BScN students only. Antirequisite(s): Credit can be obtained for only one of COMM 1013 or COMM 1213.', 'COMM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7647', 'COMM-1213', 'Professional Communication', 'This introductory level course focuses on foundational communication concepts to help students thrive in professional environments with emphasis placed upon the development of skills necessary for effective communication in the workplace. As such, topics include understanding the communication process, nonverbal communication, working together, the fundamentals of writing and speaking for professional purposes, and cultivating credibility.? Prerequisite(s): Open to Business and Computer Science students only, or with instructor permission. Antirequisite(s): Credit can be obtained for only one of COMM 1213, COMM 1013, or CODE 1043.', 'COMM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7648', 'COMM-1223', 'Public Speaking and Presenting', 'This course is designed to help students become more comfortable, confident, and proficient in speaking circumstances and in delivering presentations or speeches. To assist students in the development of the skills necessary for effective and engaging oral communication, public speaking/public communication concepts, techniques, and strategies are identified, discussed, and practiced. Stage-fright/anxiety management is also addressed.', 'COMM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7653', 'COMP-1110L', 'COMP 1113 Laboratory', '', 'COMP', 0, 1, 1, '[{"codes":["COMP-1113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7654', 'COMP-1113', 'Computer Programming 1', 'Introduction to the field of computer science and computer programming. Topics include fundamental programming constructs, algorithms, and problem-solving. Lecture and lab. No programming experience required. Prerequisite(s): Mathematics 12 (or equivalent) or Precalculus 12 (or equivalent) or 3h of Mathematics. Antirequisite(s): Credit can be obtained for only one of COMP 1113 or COMP 1893.', 'COMP', 3, 0, 1, '[{"codes":["COMP-1110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7655', 'COMP-1120L', 'COMP 1123 Laboratory', '', 'COMP', 0, 1, 1, '[{"codes":["COMP-1123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7656', 'COMP-1123', 'Computer Programming 2', 'Topics include object-oriented programming, declarations and types, fundamental techniques in graphics, event-driven programming, subclasses and inheritance in object-oriented programming, recursion, and file processing. Lecture and lab. Prerequisite(s): COMP 1113 with a minimum grade of C-.', 'COMP', 3, 0, 1, '[{"codes":["COMP-1113","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["COMP-1120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7670', 'COMP-1813', 'Computer Concepts & App', 'Introduction to computer concepts and hands-on experience with basic applications. Topics include how to create effective web pages, powerful presentations, dynamic spreadsheets, efficient word processing, and simple database applications. No prior computer knowledge assumed. Students pursuing a degree, major, second major, or honours in Computer Science may not take COMP 1813, and can not use it for credit towards graduation requirements.', 'COMP', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7678', 'COMP-1893', 'Multimedia Based Intro: Prog', 'An introduction to programming by writing computer programs to manipulate images and other media. No prior computer knowledge assumed. Antirequisite(s): Credit can be obtained for only one of COMP 1113 or COMP 1893.', 'COMP', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7684', 'COMP-2100L', 'COMP 2103 Laboratory', '', 'COMP', 0, 1, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7685', 'COMP-2103', 'Computer Programming 3', 'Topics include fundamental programming concepts, algorithms and problem solving, fundamental data structures, recursion, the imperative programming paradigm, structured design, compiled and scripting languages, program correctness, robustness, and portability, interfacing with operating system. Lecture and lab. Prerequisite(s): COMP 1123 with a minimum grade of C-.', 'COMP', 3, 0, 2, '[{"codes":["COMP-1123","or","COMP-1233","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Take","COMP-2100L;"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7686', 'COMP-2113', 'Data Structures and Algorithms', 'Topics include introduction to abstract data specification, implementation and testing, introduction to algorithms and their analysis. Prerequisite(s): COMP 1123 and either (MATH 1323 or MATH 1333), each with a minimum grade of C-.', 'COMP', 3, 0, 2, '[{"codes":["COMP-1123","or","COMP-1233","with","minimum","grade","C-","required","and","either","MATH-1323","or","MATH-1333","with","minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7690', 'COMP-2200L', 'COMP 2203 Laboratory', '', 'COMP', 0, 1, 2, '[{"codes":["COMP-2203"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7691', 'COMP-2203', 'Comp Architect./Organization 1', 'Topics include digital logic and digital systems, machine level representation of data, assembly level organization and architecture. (1.5h lab). Prerequisite(s): 6h of mathematics cross-coded as APSC 2223.', 'COMP', 3, 0, 2, '[{"codes":["6-hours","from","MATH"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["COMP-2200L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7692', 'COMP-2213', 'Comp Architect./Organization 2', 'Topics include memory system organization and architecture, interfaces and communication, functional organization, multiprocessing and alternative architectures, performance enhancements. Prerequisite(s): COMP 2203 plus 6 additional hours of computer science, each with a minimum grade of C-.', 'COMP', 3, 0, 2, '[{"codes":["COMP-2203","with","minimum","grace","C-","plus","6-hours","from","COMP","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7707', 'COMP-2663', 'Software Engineering 1', 'Topics include software requirements and specifications, methods and tools for object-oriented analysis and design, introduction to software validation, introduction to design patterns and frameworks, programming with components, using APIs, software tools and environments, software processes (introduction), software evolution (introduction), software project management. Prerequisite(s): COMP 1123 with a minimum grade of C-.', 'COMP', 3, 0, 2, '[{"codes":["COMP-1123","or","COMP-1233","with","minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7714', 'COMP-2853', 'Handling Data Concpts/Apps', 'This course provides hands-on experience in managing research data from when it is collected to the final report. Includes data collection, storage, data manipulation, data analysis, generating charts and graphs, effective methods of presenting information in both reports and presentations. Prerequisite(s): 3h COMP or equivalent word processing and spreadsheet experience.', 'COMP', 3, 0, 2, '[{"codes":["3-hours","from","COMP","department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7715', 'COMP-2863', 'How Websites Work', 'Topics include an introduction to Web fundamentals, and programming techniques for Web site development. Prerequisite(s): 3h COMP or permission of school. Students pursuing a degree, major, second major, or honours in Computer Science may not take COMP 2863, and can not use it for credit towards graduation requirements.', 'COMP', 3, 0, 2, '[{"codes":["3-hours","from","COMP","department","or","permission","of","School"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7716', 'COMP-2873', 'Build Web-Based Application', 'Development of dynamic Web applications using database technology. Topics include an introduction to Web development frameworks, and building Web sites which access data stored in a database backend. Prerequisite(s): COMP 2853 and COMP 2863.', 'COMP', 3, 0, 2, '[{"codes":["COMP-2853","and","COMP-2863"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7718', 'COMP-2903', 'Computers and Society', 'Topics include the technical, economic, legal, political, social, ethical, and professional issues related to the widespread use of computers. Prerequisite(s): 3h COMP with a minimum grade of C-.', 'COMP', 3, 0, 2, '[{"codes":["TAKE","3","HOURS;","FROM","DEPARTMENT","COMP;","MIN","GRADE","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7720', 'COMP-2923', 'Special Topics', 'Prerequisite(s): Permission of school.', 'COMP', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7724', 'COMP-3123', 'Security', 'Topics include cryptography, security issues and, network and data level security. Prerequisite(s): COMP 2113, MATH 1223 or MATH 2223 or MATH 2233, and MATH 1413, each with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of COMP 3123 or COMP 2523.', 'COMP', 3, 0, 3, '[{"codes":["Take","COMP","2113,","with","a","minimum","grade","of","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH","2233","or","1253","or","MATH","2213/2223,","with","a","minimum","grade","of","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-1413","or","MATH-1313,","with","minimum","grade","C-,P","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7732', 'COMP-3343', 'Data Comm & Comp Networks', 'Topics include theory and applications of data communications systems; language of data, coding for communications, transmission media, error control, channels, modems, communications system design, terminal selection and cost analysis. Prerequisite(s): COMP 2213 and MATH 2223 or MATH 2233 with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2213","with","minimum","grade","C-required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-2233","or","MATH-1253","or","MATH-2213","and","MATH-2223;","","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7733', 'COMP-3403', 'Analysis of Algorithms', 'Brief review of computer representation and manipulation of mathematical structures. Introduction to models of computations, basic programming techniques for efficiency (recursion, balancing back-tracking, etc.), complexity theory, estimation and measurement of efficiency of algorithms, and proving algorithms optimal. Prerequisite(s): COMP 2113, MATH 1023, MATH 1413, (MATH 1323 or MATH 1333), each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Take","MATH-1023,","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Take","MATH-1413","or","MATH-1313,","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-1323","or","MATH-1333,","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7734', 'COMP-3413', 'Automata/Formal Lang/Comput', 'Automata theory, formal languages, computability and complexity, including the Chomsky hierarchy for languages, decision problems for languages, theoretical computability, non-computable functions and related problems. Prerequisite(s): COMP 2113, MATH 1413, MATH 1323, each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113","with","minimum","grade","C-","required","MATH-1413","or","MATH-1313","with","minimum","grade","C-","required","MATH-1323","or","MATH-1333","with","minimum","GRADE","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7738', 'COMP-3500L', 'COMP 3503 Laboratory', '', 'COMP', 0, 1, 3, '[{"codes":["COMP-3503"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7739', 'COMP-3503', 'Data Analytics', 'Methods and technologies surrounding the capture of organizational data; the preparation and modelling of that data to identify patterns, make predictions, or inform decision making. Topics include: the data analytics process, data warehousing, data engineering, data visualization, data mining and machine learning. (1h lab). Prerequisite(s): COMP 2113, COMP 2103, MATH 1223 or MATH 2223 or MATH 2233, and MATH 1413 or MATH 1313, each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113","COMP-2103","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["COMP-3500L"],"textExtension":"- Must be taken at the same time as this course."},{"codes":["Take","MATH-2233","or","MATH-1253","or","MATH-2213","and","MATH-2223;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-1413","or","MATH-1313","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7740', 'COMP-3513', 'Systems Analysis and Design', 'Introduction to the tools and techniques of information systems analysis and design and the project management process. The analysis and specification of systems requirements will be covered, as well as the design of system data, input, output and processes. A typical business case study project will constitute a major portion of the course. Prerequisite(s): COMP 1113, COMP 1893 or COMP 2863 with a minimum grade of C-, or permission of the School of Computer Science.', 'COMP', 3, 0, 3, '[{"codes":["COMP-1113,","COMP-1233,","COMP-1893","or","COMP-2863","with","minimum","grade","C-","required","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7744', 'COMP-3553', 'Computer Graphics', 'Selected higher-level concepts in computer graphics, such as display devices, display files and data structures for graphics, interactive and dynamic display techniques, three-dimensional graphics, shaded and colour graphics. Graphics language standardization, and device-independent software.', 'COMP', 3, 0, 3, '[{"codes":["COMP","2113","and","MATH","1013,","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-1413","or","MATH-1313,","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-1323","or","MATH-1333,","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7745', 'COMP-3583', 'Human Computer Interaction', 'Examines the human factors associated with information technology and seeks to provide students with knowledge of the variables likely to influence the perceived usability, and hence the acceptability, of any information technology. This course introduces a series of techniques for developing and evaluating usable software, with a focus on both mobile and traditional computing hardware. Prerequisite(s): COMP 2113.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7746', 'COMP-3610L', 'COMP 3613 Laboratory', '', 'COMP', 0, 1, 3, '[{"codes":["COMP-3613"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7747', 'COMP-3613', 'Artificial Intelligence 1', 'Topics include an introduction to artificial intelligence, solving problems with search, knowledge and reasoning, uncertain knowledge and reasoning, supervised and unsupervised machine learning, artificial neural networks and reinforcement learning. (1.5h Lab). Prerequisite(s): COMP 2113, MATH 1413, MATH 1323, MATH 2233 or MATH 2213/MATH 2223, each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113,","MATH-1413","or","MATH-1313,","MATH-1323","or","MATH-1333,","each","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["COMP-3610L"],"textExtension":"- Must be taken at the same time as this course."},{"codes":["MATH-2233","or","MATH-1253","or","MATH-2213","and","MATH-2223","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7749', 'COMP-3663', 'Software Engineering 2', 'Topics include software evolution, project management, standards and practices of requirements analysis, design, implementation and testing, configuration and change management, quality assurance, resource and cost estimation, risk management, professional and ethical responsibilities, team application of SE methodology to the development of a software product. Prerequisite(s): COMP 2663 with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2663","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7750', 'COMP-3703', 'Translators', 'Basic components and techniques of translators for programming languages; preprocessors, compilers, interpreters, assemblers. Prerequisite(s): COMP 2103, COMP 2113, MATH 1413, (MATH 1323 or MATH 1333), each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2103,","COMP-2113,","MATH-1413","or","MATH-1313","and","MATH-1323","or","MATH-1333","with","minimum","grade","C-required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7751', 'COMP-3713', 'Operating Systems', 'Major operating systems principles, and the interrelationships between the operating system and the architecture of computer systems. Topics from memory and process management, and concurrent computation in operating systems. Prerequisite(s): COMP 2103, COMP 2113, and COMP 2213 each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2103,","COMP-2113,","and","COMP-2213","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7753', 'COMP-3753', 'Database Management Systems', 'The analysis, design, operation and maintenance of large information systems, especially those using database techniques, on-line processing, and networking. The most common models for database management systems with commercial examples. Prerequisite(s): COMP 2113, MATH 1413, (MATH 1323 or MATH 1333), each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2113,","MATH-1413","or","MATH-1313","and","MATH-1323","or","MATH-1333","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7755', 'COMP-3773', 'Adv Obj Oriented App Dev C++', 'Advanced topics in object-oriented programming, analysis, and design using C++. Compile and run time binding, reflective and polymorphic programming, compile and run time type parametrization. Standard template library. Design patterns and frameworks in C++. Prerequisite(s): COMP 2103, COMP 2113, and COMP 2663, each with a minimum grade of C-.', 'COMP', 3, 0, 3, '[{"codes":["COMP-2103,","COMP-2113,","and","COMP-2663","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7760', 'COMP-3923', 'Special Topics', 'Prerequisite(s): Permission of School of Computer Science.', 'COMP', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7763', 'COMP-4223', 'Advanced Computer Architecture', 'New generation architectures and technologies, foundations of parallel computation, software for advanced architecture, parallel architectures. Prerequisite(s): COMP 3703, COMP 3713.', 'COMP', 3, 0, 4, '[{"codes":["COMP-3703","and","COMP-3713"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7764', 'COMP-4343', 'Comp Net & Distributed Systems', 'Design and implementation of computer networks and related systems, communications protocols and distributed systems. Prerequisite(s): COMP 3343, COMP 3713, MATH 1413, MATH 1323, each with a minimum grade of C-.', 'COMP', 3, 0, 4, '[{"codes":["COMP-3343","COMP-3713","and","MATH-1413","or","MATH-1313","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7766', 'COMP-4443', 'Topics: Comp & Network Sec', 'This course will cover selected topics such as: authentication applications, data integrity and privacy, anonymity, security infrastructures and intrusion prevention, network attacks, and wireless Networks and Security. Prerequisite(s): COMP 3123 and COMP 4343, each with a minimum grade of C-. Corequisite or prerequisite: MATH 4333 or permission of the School of Computer Science.', 'COMP', 3, 0, 4, '[{"codes":["COMP-2523","and","COMP-4343","with","minimum","grade","C-","required","or","department","permission"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["MATH-4333"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7770', 'COMP-4523', 'Environmental Informatics', 'This course consists of intensive examination of selected topics in computer science and information technology for environmental science. Prerequisite(s): Permission of the School of Computer Science.', 'COMP', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7771', 'COMP-4553', 'Game Development', 'The game development life cycle, game design and programming, graphics engines and game engines, game tools. Prerequisite(s): COMP 3553 and 3773, each with a minimum grade of C-.', 'COMP', 3, 0, 4, '[{"codes":["COMP-3553","and","COMP-3773","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7772', 'COMP-4583', 'Mobile/Ubiquitous Computing', 'This course covers the technologies used in mobile and ubiquitous computing and how to apply this knowledge to real-world applications. This course will provide specific skills needed for designing, developing and deploying mobile applications. Prerequisite(s): COMP 3343, COMP 2513, COMP 3713, each with a minimum grade of C-.', 'COMP', 3, 0, 4, '[{"codes":["COMP-3343,","COMP-3033","and","COMP-3713","all","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7774', 'COMP-4613', 'Artificial Intelligence 2', 'Special topics in artificial intelligence. Prerequisite(s): COMP 3613 with a minimum grade of C-, and permission of the School of Computer Science.', 'COMP', 3, 0, 4, '[{"codes":["COMP-3613","with","minimum","grade","C-","required","and","either","MATH-2223","or","MATH-2233","(or","MATH-1253)","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7783', 'COMP-4923', 'Special Topics', '2026/27 - COMP 4923 FA01 Special Topics Internet of Things Programming    This course will investigate the Internet of Things (IoT) as a network of objects or "things" embedded with electronics, software and sensors connected on networks enabling them to collect or exchange information. Students will also learn to program and enable devices to collect or exchange information. This course is cross-listed with COMP 5163. 
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7785', 'COMP-4983', 'Capstone Project', 'Experience in the design, development, implementation and documentation of a significant computer software or hardware system; or a thorough literature review and analysis of an aspect of computer science. Students in the BACS degree must complete an applied project in their area of defined option, second major, or minor. A final project report and a presentation to the School are required. Prerequisite(s): 12h computer science at the 3000 or 4000 level, each with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of COMP 4983 or COMP 4996.', 'COMP', 3, 0, 4, '[{"codes":["12-hours","from","COMP","department","from","level","3000","or","4000","with","minimum","grade","C-","required","on","each"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7787', 'COMP-5013', 'Top.: Theor. Comp Science 1', 'These courses consist of intensive examination of selected specific advanced topics in theoretical computer science. Since the specific topic or research problem that receives special treatment will differ from year-to-year, students are advised to consult with the School prior to registration.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7790', 'COMP-5113', 'Applications in Comp Sci 1', 'These courses consist of intensive examination of selected specific advanced topics in applications of computer science. Since the specific topic or research problem that receives special treatment will differ from year-to-year, students are advised to consult with the School prior to registration.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7793', 'COMP-5213', 'Systems in Computer Science 1', 'These courses consist of intensive examination of selected specific advanced topics in systems in computer science. Since the specific topic or research problem that receives special treatment will differ from year-to-year, students are advised to consult with the School prior to registration.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7797', 'COMP-5403', 'Advanced Algorithm Analysis', 'This advanced algorithm analysis course covers a selection of the following topics: review of asymptotic notion, The FFT (polynomials  over final fields and/or complex numbers), lower bound analysis, union-find algorithms and their analysis, Strassen''s algorithm, Number theoretic algorithm, and NP completeness.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7798', 'COMP-5413', 'Adv Formal Lang & Comp Complex', 'This course will cover the following topics: The Unsolvability of halting problems, decidable and semi-decidable languages, unrestricted grammars, the Chomsky hierarchy and beyond, computable functions, introduction to the analysis of complexity, time and space complexity classes.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7799', 'COMP-5503', 'Simulation and Modelling', 'This course provides a comprehensive introduction to digital twins, focusing on the technologies, tools, and techniques (Python, MATLAB) for creating representation models for AR/VR interfaces. Topics include IoT, data science, and modelling methods, with a project-based approach through lectures and labs. Students will work in teams on practical, challenging project, enhancing problem-solving skills.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7809', 'COMP-5913', 'Readings in Computer Science', 'The student is assigned to a faculty member for regular meetings to discuss readings in a selected area. Papers and research projects are expected. Prerequisite(s): permission from the Graduate Coordinator.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7810', 'COMP-5923', 'Research in Computer Science', 'This course provides an introduction to research methods in computer science.', 'COMP', 3, 0, 5, '[{"codes":["Take","COMP-5950","OR","COMP-5960"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7811', 'COMP-5960', 'Thesis', '', 'COMP', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7815', 'COOP-1902', 'Co-operative Education 1', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Antirequisite(s): COOP 3706 and COOP 3806.', 'COOP', 2, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7816', 'COOP-2900', 'Co-operative Education 2', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisite(s): COOP 1900 (Passing grade).', 'COOP', 0, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7817', 'COOP-2902', 'Co-operative Education 2', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisite(s): COOP 1902 (Passing grade). Antirequisite(s): COOP 3706 and COOP 3806.', 'COOP', 2, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7818', 'COOP-3700', 'CoOp Internship (12 Month)', '', 'COOP', 0, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7820', 'COOP-3706', 'Co-op Internship (12-Month)', 'Students will engage in degree-relevant, hands-on learning for 12 consecutive months with one employer offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and one formal report and one presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Antirequisite(s): COOP 1902, COOP 2902, and COOP 3902, and COOP 3806.', 'COOP', 6, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7823', 'COOP-3806', 'Co-op Internship (16-Month)', 'Students will engage in degree-relevant, hands-on learning for 16 consecutive months with one employer offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and one formal report and one presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Antirequisite(s): COOP 1902, COOP 2902, and COOP 3902, and COOP 3706.', 'COOP', 6, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7825', 'COOP-3902', 'Co-operative Education 3', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisites: COOP 1902, COOP 2902 (Passing grade). Antirequisite(s): COOP 3706 and COOP 3806.', 'COOP', 2, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7826', 'COOP-3903', 'Co-operative Education 3', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisites: COOP 2900 (Passing grade).', 'COOP', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7827', 'COOP-4900', 'Co-operative Education 4', 'Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisite(s): COOP 3902 (Passing grade).', 'COOP', 0, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7828', 'COOP-5910', 'Co-operative Education 1', 'This is the first (second) four-month term in which the student is employed in a discipline related position. Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours per term offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisite(s): permission from the Masters supervisor and Graduate Coordinator.', 'COOP', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7829', 'COOP-5920', 'Co-operative Education 2', 'This is the first (second) four-month term in which the student is employed in a discipline related position. Students will engage in degree-relevant, hands-on learning for a minimum of 420 hours per term offering opportunities for application of classroom-based theory, reflection, collaboration with subject matter experts, as well as feedback on performance and a formal report or presentation. Provides in depth exposure to varied professional environments, learning of specialized knowledge/techniques/equipment, and first-hand insight into potential career paths. Prerequisite(s): permission from the Masters supervisor and Graduate Coordinator.', 'COOP', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7830', 'CREL-1206', 'World Religions', 'The history, beliefs, practices and contemporary relevance of the Hindu, Buddhist, Confucian, Taoist, Zoroastrian, Judaic, Muslim and Christian faiths. After outlining methods of understanding different ways of being religious the course examines the components of larger streams of tradition and compares and contrasts their respective beliefs and practices.', 'CREL', 6, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7833', 'CREL-2206', 'Intro to Biblical Studies', 'The origins, early history and documents of Judaism and Christianity. The religious, social and cultural significance of the scriptures will be stressed, and the techniques of historical and literary criticism will be introduced.', 'CREL', 6, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7834', 'CREL-2213', 'Intro to Biblical Studies 1', 'The origins, early history and documents of Judaism and Christianity. The religious, social and cultural significance of the scriptures will be stressed, and the techniques of historical and literary criticism will be introduced.', 'CREL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7835', 'CREL-2223', 'Intro to Biblical Studies 2', 'The origins, early history and documents of Judaism and Christianity. The religious, social and cultural significance of the scriptures will be stressed, and the techniques of historical and literary criticism will be introduced.', 'CREL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7838', 'CREL-2413', 'Ecology and Religion', 'This course reviews the relationship between religion and the environment from two perspectives. It first traces how traditional religions (Eastern, Western, Aboriginal) define things. Second, it provides an overview of contemporary ecological spirituality in Western society, including ecoactivism, ecofeminism, deep ecology, and animal rights.', 'CREL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7839', 'CREL-2443', 'Health, Illness and Religion', 'An examination of the different ways health and illness are related to religion. Ideas of sickness and techniques of healing will be studied in a variety of traditional and modern contexts. We will explore how differing religious and medical systems sustain a variety of understandings of the human person, culture/society relationships, and cosmological views. Prerequisite(s): One-year university.', 'CREL', 3, 0, 2, '[{"codes":["1","Year","of","University","Study","(completed","at","least","25","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7841', 'CREL-2533', 'Cults New Religious Mvmt', 'An examination of practices and self-understandings of New Religious Movements (NRMs, i.e. Scientology, Neo-paganism (Wicca), Satanism, Falun Gong, Branch Davidians) in North America. Topics include the social scientific study of NRMs; historical roots and teachings; issues of popularity and interpretation; and special consideration of gender in the emergence and form of NRMs.', 'CREL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7842', 'CREL-2553', 'Goddesses and Women of Power', 'An examination of goddesses, female religious powers and women manifesting divine power in a variety of cultures: Indigenous, eastern and western. Consideration will be paid to the intertwined emergence of feminist scholarship on religion and feminist spirituality. Prerequisite(s): One-year university.', 'CREL', 3, 0, 2, '[{"codes":["1","Year","of","University","Study","(completed","at","least","25","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7843', 'CREL-3123', 'Writing Life: Worldviews/Exp.', 'Students will conduct field-based research documenting life stories and engage in an on-the-ground introduction to interviewing and analysis of worldviews and experience. Students will learn culturally appropriate protocols involved in ethnographic research, including life history and feminist methodologies, approaches to interviewing and participant-observation. These skills and methodologies apply to similar work in other disciplines.', 'CREL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7846', 'CREL-3693', 'Fieldwork in Ritual Studies', 'Examination of theoretical and methodological issues arising in the interdisciplinary and feminist approach to the study of ritual. Special attention is given to the study of lived ritual practice and to ritual as a conceptual lens for cultural analysis. Students conduct fieldwork, learning culturally appropriate methodologies for participant-observation, description and analysis.', 'CREL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7852', 'DISP-2023', 'Introductory Praxis', 'This course will introduce students to reflective practice (praxis). Students will be expected to commit to volunteer positions in church or community settings in consultation with the instructor. Students will be encouraged to become ''reflective practitioners'' by contemplating their volunteer experiences in reflection papers and in structured debriefing sessions with the instructor.', 'DISP', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7853', 'DISP-3013', 'Transformational Discipleship', 'This course explores discipleship as participation in the mission of God rather than mere program delivery or information transfer. Grounded in a biblical theology of discipleship and attentive to contemporary cultural realities, the course examines how people learn and change across generations, cultures, and digital contexts. Students will evaluate congregational discipleship strategies and design lessons that foster spiritual maturity, vocational integration, and reproducible disciple-making. The course culminates in a theological and practical vision for lifelong discipleship that forms resilient, mission-shaped leaders.', 'DISP', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7854', 'DISP-3023', 'Junior Praxis', 'In this course students will develop reflective practice (praxis) by volunteering consistently in a specific church or community ministry setting, chosen in consultation with the instructor. Students will develop abilities as ''reflective practitioners'' through reflection papers and structured debriefing sessions with the instructor.', 'DISP', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7855', 'DISP-3036', 'Mission Praxis', 'Through preparation and through guided participation in an intensive international short-term mission trip, students experience cross-cultural mission and engage in reflective practices during and after the mission experience. Prerequisite: EVAN 3073.', 'DISP', 6, 0, 3, '[{"codes":["EVAN-3073"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7856', 'DISP-4013', 'Faith Development Small Groups', 'Explores the place of small groups within the wider ministry of the church in church in nurturing Christian spiritual growth - both in the individual and in the community of faith. Provides a practical knowledge of small-group ministry with its benefits and challenges and of various models, approaches and leadership training. Recommended prior study: DISP 3013', 'DISP', 3, 0, 4, '[{"codes":["DISP-3013"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7857', 'DISP-4023', 'Senior Praxis', 'In this course students will develop critical reflective practice (praxis) by volunteering consistently in a specific church or community ministry setting, chosen in consultation with the instructor. Students will be expected to integrate knowledge and skills as ''reflective practitioners'' through regular journaling and structured debriefing sessions with the instructor.', 'DISP', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7858', 'DISP-4213', 'Special Topics in Discipleship', 'Specialized courses in Discipleship offered from time to time.', 'DISP', 3, 0, 4, '[]');
