INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7900', 'DMIN-8113', 'Research & Writing', 'This course is an introduction to the range of skills and attributes associated with academic research and writing. Participants will be introduced to the skills of advanced academic writing, general and specific research methodologies and methods such as the use of library resources, quantitative and qualitative research approaches, how to identify a research question, how to carry out a critical literature review, how to prepare a research proposal, and the type of personal qualities and attributes which will be required for a sustained period of study at an advanced level.', 'DMIN', 3, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7901', 'DMIN-8123', 'Ministry Mentoring&Reflection', 'Participants establish an interactive learning relationship with a trained ministry mentor, who becomes a senior friend, mentor, advisor, objective evaluator, and advocate. Selection of a mentor is made by DMin staff in consultation with the participant and will be dependent on location, denominational affiliation, and other relevant factors.', 'DMIN', 3, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7902', 'DMIN-8133', 'Candidacy Evaluation', 'Admission to DMin candidacy status (thus permitting the student to engage in thesis research and writing) is dependent upon a successful evaluation of the participant''s growth and integration of thought, practice, and scholarship. To achieve candidacy, students will submit two pieces of work: a paper detailing how the program contributed to the understanding and development of their theology of the practice of ministry; and a full thesis proposal with literature review. Oral evaluation will be conducted through an interview, either in person or via electronic communication, normally involving the potential supervisor, a member of the Doctor of Ministry team, and one other faculty member.', 'DMIN', 3, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7903', 'DMIN-8213', 'Adv Biblical Studies Min Prac', 'These courses provide an opportunity for students to engage in biblical studies at an advanced level with a view toward the application of their studies to their ministry. For a list of upcoming courses, please consult the ADC website.', 'DMIN', 3, 0, 8, '[]');
