INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7950', 'DMIN-8616', 'Thesis-Project 1', 'Under the direction of a thesis supervisor, appointed by the Director in consultation with the candidate, the doctoral candidate will design, implement, and report on a major research project.', 'DMIN', 6, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7951', 'DMIN-8626', 'Thesis-Project 2', 'Under the direction of a thesis supervisor, appointed by the Director in consultation with the candidate, the doctoral candidate will design, implement, and report on a major research project.', 'DMIN', 6, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7957', 'DMIN-8960', 'Continuance', 'This course is designated for approved DMin students who extend their studies beyond the fourth year of registration. This course maintains the continuing status of the student within the Doctor of Ministry program and within the university system.', 'DMIN', 0, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7997', 'ECON-1013', 'Microeconomic Principles', 'An introduction to the following questions: How do markets work? When do markets successfully allocate resources? What causes markets to fail and what can be done about it? How do firms make production decisions? What results from firms having market power?', 'ECON', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7998', 'ECON-1023', 'Macroeconomic Principles', 'An introduction to the modern macroeconomic system. The measurement of incomes, jobs, and prices. An introduction to economic growth. The monetary system, the basics of banking, and interest rates. Exchange rate determination and related policy. Basic business cycle models and their implications for monetary and fiscal policy.', 'ECON', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8005', 'ECON-2113', 'Intermed. Microecon Thry 1', 'This course develops a theory of the market economy from the perspective of consumers and producers. Topics include utility maximization, income and substitution effects, profit maximization, firm cost structures, competition structures, and taxation. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8008', 'ECON-2213', 'Inter Macroeconomic Theory1', 'Theories of economic growth including consideration of labour, capital, and technology. The empirics of economic growth. Neoclassical and New Keynesian business cycle models, their implications for fiscal and monetary policy, and the zero lower bound. The course focuses on rigorous model-building based on an understanding of how data disciplines economic models, and introduces students to numerical simulation.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8010', 'ECON-2413', 'Engineering Economics', 'Topics of theoretical and applied economics of interest and use to engineers and professionals in related fields. Topics include market equilibria, interest rate determination, present and future values, investment criteria, budgeting and replacement analysis, depreciation, taxation, inflation, sensitivity and risk analyses, and multi-staged and multi-attribute decision making. Cross-coded as APSC 2413. Prerequisite(s): MATH 1023, ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 2, '[{"codes":["MATH-1023,","ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8012', 'ECON-2613', 'Empirical Analy in Econ & Busi', 'This course aims to provide an introduction to empirical analysis in Economics and Business making extensive use of Microsoft Excel. Topics include both descriptive and inferential statistics, culminating in hypothesis testing and an introduction to regression analysis. Antirequisite(s): Credit can be obtained for only one of ECON 2613 or MATH 1253; Students who have completed MATH 2213 may not subsequently receive credit for ECON 2613.', 'ECON', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8013', 'ECON-2623', 'Introduction to Econometrics', 'The objective of this course is to provide an introduction to econometric theory and illustrate practical implications of regression analysis in Economics and Business. The first half of the course provides an introduction to the classical linear regression model (CLRM). The second part of the course is concerned with identification and treatment of violations to the assumptions of the CLRM. Prerequisite(s): ECON 2613. Antirequisite(s): Credit can be obtained for only one of MATH 3233 or ECON 2623.', 'ECON', 3, 0, 2, '[{"codes":["ECON-2613"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8014', 'ECON-2713', 'Environmental Economics', 'An introductory analysis of pollution and the use of natural resources based on microeconomic tools, particularly the study of market failures with environmental consequences. This framework leads to evaluation of various government policies to address diverse problems related to the environment and the changing climate.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8015', 'ECON-2813', 'Macro Economic Policy Issues', 'We investigate two questions: (1) Can and should policy increase economic growth? (2) Can and should policy decrease the variation in economic activity? Throughout, we will consider a variety of policy tools, and how the answer to one of the above questions influences answers to the other. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8016', 'ECON-2823', 'Micro Economic Policy Issues', 'Canada''s economy, like that of any other G8 country, is characterized by considerable government intervention. Using standard tools from microeconomic theory, this course examines the wisdom, and folly, of government policy. Topics include price and quantity controls, competition policy, public good provision, taxation and redistribution, and environmental protection. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8021', 'ECON-3113', 'Intermediate Micro Econ Thry 2', 'This course extends the analysis in Intermediate Microeconomic Theory 1 to various market structures and imperfect competition. Topics include monopoly and price discrimination, oligopoly, introduction to game theory, externality and public goods. Prerequisite(s): ECON 2113 and MATH 1613 or MATH 1013 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-2113","with","minimum","grade","C-","required","and","either","MATH-1613","or","MATH-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8022', 'ECON-3123', 'Intermed. Macroecon Thry 2', 'Microfoundations of business cycle elements including consumption, investment, employment, life-cycles, equilibrium, and the Lucas Critique. Extension of business cycle models to the open economy and applications to fiscal and monetary policy. Macro-finance models incorporating banking, investment, and financial frictions,  and macroprudential regulation.', 'ECON', 3, 0, 3, '[{"codes":["ECON-2113","and","ECON-2213","with","minimum","grade","C-","required","and","either","MATH-1613","or","MATH-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8023', 'ECON-3133', 'Economics of Financial Markets', 'The economic characteristics, function and performance of financial markets. Topics include the efficiency of financial markets, futures and options markets, pricing of financial assets, definition and measurement of risk, portfolio analysis, interest rate and yield curve analysis. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8024', 'ECON-3143', 'Fin Institutions & Policy', 'Deals with economic characteristics, functions and performance of financial institutions nationally and internationally. Topics include commercial and central banking in Canada, foreign banking systems and international monetary policy and exchange rate regimes. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8025', 'ECON-3203', 'Economic History of Canada', 'A consideration of significant economic events and circumstances since before Confederation that have shaped the Canadian economy. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8028', 'ECON-3313', 'Labour Economics', 'This course aims to make an introduction to modern labour economics. The main focus will be an analysis of the key aspects of labour supply and demand behavior, with an emphasis on major policy questions such as the impact of public policy on work incentives and retirement. The acquired tools are applied to topics such as wage determination, human capital, returns to education and immigration. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8031', 'ECON-3413', 'Public Finance', 'A study of public finance or the various types of taxes and government expenditures and their impacts on the Canadian economy, such as the effects of prices, production, and the distribution of income. Prerequisite(s): ECON 1013/1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8033', 'ECON-3433', 'Cost-Benefit Analysis', 'The techniques and application of cost-benefit analysis to public policy and project evaluation. Topics include the welfare foundations of cost-benefit analysis, investment decision rules, the choice of a social discount rate, risk and uncertainty, shadow pricing of inputs and outputs, public sector pricing and assessment of the value of intangibles such as time, noise and life. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8036', 'ECON-3513', 'Economics of Transportation', 'This course applies concepts from microeconomics (including utility theory, supply and demand, pricing, public goods, and market failures) to the study of urban transportation issues. Examples of topics covered include traffic congestion, cost-benefit analysis and investment evaluation, and the regulation of transportation systems.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8037', 'ECON-3523', 'Industrial Organization 1', 'An introduction to industrial organization and Canadian industrial policy. Topics such as the determinants and measurement of industry structure lead to a review and development of the theories of monopoly and oligopoly. Canadian public policy (e.g. competition policy) is examined in this context. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8039', 'ECON-3613', 'Mathematical Economics', 'This course is concerned with the application of mathematical tools to economic theory. Incoming students are expected to be familiar with univariate calculus. Tools such as multivariate calculus, matrix algebra and linear programming are brought to bear on macroeconomic models and a variety of unconstrained and constrained microeconomic optimization problems. Prerequisite(s): ECON 1013/ECON 1023, MATH 1613 or MATH 1013, each with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013,","ECON-1023","and","either","MATH-1613","or","MATH-1013","all","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8040', 'ECON-3623', 'Mathematical Economics 2', 'This course is a continuation of ECON 3613. Additional mathematical techniques are applied to microeconomic theory in greater depth, including the treatment of time and uncertainty. Partial equilibrium analysis, and dynamic macroeconomic analysis is treated. Prerequisite(s): ECON 3613.', 'ECON', 3, 0, 3, '[{"codes":["ECON-3613"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8041', 'ECON-3633', 'Financial Econometrics', 'The objective of this course is to provide an introduction to the econometrics used in empirical finance. Topics will cover modern statistical and econometric techniques necessary for both professional and academic quantitative research in finance. Particular emphasis will be placed on measuring risk of holding and trading financial assets, models for risk management, estimation and inference using computer-based applications. Prerequisite(s): ECON 2623 and ECON 3133.', 'ECON', 3, 0, 3, '[{"codes":["ECON-2623","ECON-3133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8044', 'ECON-3733', 'Econ of Recreation & Sport', 'This course examines the role of economics in the consumption and provision of recreation and sport in today''s society. Topics include demand estimation and forecasting, assessing the benefits and costs of recreation and sport events/facilities, pricing issues, and the role of government in the recreation and sport industries. Prerequisite(s): ECON 1013 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8045', 'ECON-3743', 'Economics of Tourism', 'A theoretical and empirical analysis of the tourism industry as it applies to consumers and providers at the community/regional/national and international levels. Topics include cost structures in the tourism industries and related pricing issues, demand analysis and market segmentation, economic and social impacts of tourism, the role of multinationals and government in the tourism industry. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8047', 'ECON-3823', 'Urban Economics', 'This course provides an introduction to urban economics. This class will use established economic tools/analysis to explain why cities exist, how /where they develop, and what forces underlie the distribution of economic activity. Also examined will be the determinants of land prices/rents, market failures related with land use and relevant public policy. The course will also look at urban issues such as congestion, poverty, and crime. These issues, as they relate to Canadian cities, will be the primary focus of this class. Prerequisite(s): Econ 1013. Interested students should contact the instructor.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8048', 'ECON-3833', 'Economics and Entrepreneurship', 'This course explores entrepreneurship from the perspective of modern economic analysis. Economic profit and the return to entrepreneurship. The economics of risk and uncertainty. The economics of asymmetric information and information technology. Pricing and investment decisions. Public policy and entrepreneurship. Entrepreneurship and the knowledge economy. Prerequisite(s): permission of the instructor.', 'ECON', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8051', 'ECON-3883', 'Special Topics in Economics', 'Special topics in economics to allow students to take advantage of their own particular interests and the interests of current and visiting faculty. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8053', 'ECON-3913', 'Managerial Economics', 'An introduction to the economics of organizations and management, and an examination of the organizational and personnel problems firms face. Throughout consider the policy environment firms operate in, and how firms respond to changes in this environment. Topics include recruitment, remuneration, team production, and internal organization. While our perspective will be game-theoretic, it will emphasize intuition over formal results. Prerequisite(s): ECON 1013, ECON 2623 (or equivalent) with a minimum grade of C-.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-2623","with","minimum","grade","C-","required","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8054', 'ECON-3923', 'International Trade Theory', 'The course explores the theory and practice of international trade theory from a variety of perspectives. This course provides an introduction to the basis, consequences and policies of international trade and to the multilateral trading system and institutions. Policy discussions will include contemporary developments in international trade including the North American Trade Agreement, the World Trade Organization and Non-Government Organizations. Prerequisite(s): ECON 1013, ECON 1023 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ECON 3923 or ECON 4113.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8055', 'ECON-3933', 'Intl. Finance and Institutions', 'International monetary economics including foreign exchange markets, adjustment mechanisms, speculations, capital flows and transfer problems, international liquidity, balance of payments and its interrelation with domestic policy, the I.M.F. and World Bank and international finance institutions. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ECON 3933 or ECON 4123.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8056', 'ECON-3943', 'Development Economics', 'Theories of economic development with specific reference to certain areas and conditions: the analytics of economic growth; barriers, balanced versus unbalanced strategies, technology. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ECON 3943 or ECON 4213.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8057', 'ECON-4013', 'History of Economic Thought', 'The course explores the ideas of the principal writers of the classical school of economic thought, particularly Smith, Malthus, Ricardo, Mill and Marx. Attention will also be given to the surrounding intellectual, political, and economic context within which these ideas were developed and the reasons why classical thought evolved into modern, neoclassical economics. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 4, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8059', 'ECON-4033', 'Advanced Microeconomic Theory', 'Selected topics in consumer and producer theory at an advanced mathematical level. Topics will include utility maximization, the indirect utility function, the expenditure function, consumer choice and the Slutsky equation, demand, consumers'' surplus, technology, profit maximization, the profit function, Hotelling''s lemma, cost minimization, the cost function and Shephard''s lemma, general equilibrium and welfare. Prerequisite(s): ECON 3113, and one of ECON 3613 or MATH 1023.', 'ECON', 3, 0, 4, '[{"codes":["ECON-3113","and","either","ECON-3613","or","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8060', 'ECON-4043', 'Advanced Macroeconomic Theory', 'Topics in macro theory, policy and empirical research depending on interests of the instructor and students. Examples of topics are consumption, investment, the Keynesian-neoclassical synthesis and the crowding out controversy, inflation, trade-offs, expectations and incomes policies, policy problems of open economics. Prerequisite(s): ECON 3123, and one of ECON 3623, MATH 1023.', 'ECON', 3, 0, 4, '[{"codes":["ECON-3123","and","either","ECON-3623","or","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8069', 'ECON-4523', 'Industrial Organization 2', 'Advanced topics in industrial organization are examined. These include pricing strategies, strategic behaviour, game theory, advertising, informational asymmetries and disclosure laws. Prerequisite(s): ECON 3113 or ECON 3523.', 'ECON', 3, 0, 4, '[{"codes":["ECON-3113","or","ECON-3523"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8071', 'ECON-4613', 'Econometrics', 'This course aims to provide an understanding of basic econometric techniques with emphasis on applications in empirical research. The first half of the course covers a comprehensive review of the classical regression model and the underlying assumptions. The second half of the course presents models that are frequently used in empirical research such as qualitative response regression models, instrumental variables and time-series analysis. Prerequisite(s): ECON 2613 and ECON 2623.', 'ECON', 3, 0, 4, '[{"codes":["ECON-2613","and","ECON-2623"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8072', 'ECON-4623', 'Advanced Topics: Econometrics', 'Extends the methods of Econometrics 1. Topics covered include binary choice models, systems of equations, and dynamic econometric models. Prerequisite(s): ECON 4613.', 'ECON', 3, 0, 4, '[{"codes":["ECON-4613"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8078', 'ECON-4903', 'Honours Seminar', 'This objective of this course is to provide a foundation for an honours thesis. The course will adopt a seminar format with scheduled lectures. Topics covered will include but not limited to the organization of honours thesis, identification and discussion of the research question, how to conduct a literature review, making effective use of the library resources, presentation of results, and applications to graduate schools. Prerequisite(s): ECON 1013/ECON 1023 with a minimum grade of C-.', 'ECON', 3, 0, 4, '[{"codes":["ECON-1013","and","ECON-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8080', 'ECON-4913', 'Game Theory', 'Games are played whenever people interact, wherever there are strategies to adopt and outcomes or prizes to win. This means games are played everywhere, from economics to evolutionary biology, from prison escapes to online poker, and from romantic liaisons to military standoffs. We develop the Nash equilibrium and several refinements. Prerequisite(s): ECON 3113 with a minimum grade of C-.', 'ECON', 3, 0, 4, '[{"codes":["ECON-3113","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8114', 'EDUC-3203', 'Introduction to Education', 'This course provides an introductory overview of the teaching profession for students beginning or considering a career in education. The course strives to help individuals better understand the purpose, structure and operation of public schools in Canada with a particular focus on the role of the professional educator. (Not for credit towards the Bachelor of Education program).', 'EDUC', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8134', 'EDUC-4003', 'Practicum 1', 'The first designated block of supervised student teaching that involves observation, reflection, team teaching, and some introductory small group and full group instruction, under the supervision of a school-based associate teacher and a School of Education University advisor. Pre-service teachers begin to build a personal portfolio that reflects their beginning growth in professional practice.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8139', 'EDUC-4053', 'Healthy Learning Environments', 'Pre-service teachers will explore how to create equitable, safe, positive and diverse learning environments. Theory and practice research in recognizing and supporting wellbeing across stages of human development, mental health, and key educational transitions will be explored. Students will explore healthy relationships to learning and management within the classroom as well as the policies, resources, and partnerships across school communities.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8146', 'EDUC-40A3', 'Practicum 2', 'The second block of supervised student teaching. Pre-service teachers continue to observe, reflect and develop professional practice. Under the supervision of a school-based associate teacher and a School of Education University advisor, pre-service teachers take on more responsibility in the classroom in terms of practicum. Pre-service teachers continue to develop a personal portfolio that reflects their beginning growth in professional practice.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8147', 'EDUC-40B3', 'Teaching Math: Elem School 2', 'Fundamental issues in elementary mathematics education include the nature of mathematics and our purposes in teaching mathematics. Drawing on relevant documents and current research, this course provides pre-service teachers with opportunities to investigate and use instructional and assessment materials for elementary school mathematics. Prerequisite(s): EDUC 4173 with a minimum grade of B-, or permission of the instructor.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4173","with","minimum","grade","B-","required","or","instructor","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8148', 'EDUC-40C3', 'Teaching Math: Middle School', 'In this course pre-service teachers investigate and develop instructional and assessment materials for middle school mathematics with an emphasis on connections and mathematics as problem solving using relevant documents and current research. Through developing and sharing materials with colleagues, pre-service teachers examine and engage with a wide range of topics in the middle school curriculum. Prerequisite(s): EDUC 4173 or EDUC 4183 with a minimum grade of B-, or permission of the instructor.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4173","or","EDUC-4183","with","minimum","grade","B-","required","or","instructor","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8150', 'EDUC-40E3', 'Human Geography Sec. School 1', 'Using relevant documents and current research, topics in teaching human geography will include cultural patterns and processes, population geography, urban geography, political geography, agricultural and rural land use and industrialization and  economic development. A variety of teaching strategies will be aimed at infusing geography skills and pedagogy into social studies teaching and learning.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8153', 'EDUC-4103', 'Strategies Teaching 2nd Lang', 'The major focus will be teaching French as a second language. Course topics will be investigated in terms of theoretical foundations and classroom application. This course is normally taught in French.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8154', 'EDUC-4113', 'Teach. Soci. Studies Sec Sch 1', 'This course focuses on the principles and methods of teaching social studies in secondary school, with emphasis on the social studies knowledge, skills, and attributes that contribute to the development of engaged citizens. Topics include: inclusive social studies planning, community building, social studies assessment strategies, disciplinary thinking, critical literacy, inquiry and project-based teaching and learning approaches, citizenship, democracy and identity development.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8156', 'EDUC-4133', 'Teaching Elem Lang Arts 1', 'This course centers on children''s language and literacy learning processes, introducing current teaching methodologies and assessment approaches which support literacy development. Drawing on relevant curriculum documents and current research, we examine speaking and listening, reading and viewing, writing and other forms of representing as inter-related processes which support an integrated approach to literacy learning across the curriculum.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8157', 'EDUC-4143', 'Teaching Science: Seco Sch 1', 'This course is designed as an introduction to constructivist secondary school science as it relates to relevant curriculum documents with due consideration of the diversity of students that populate our classrooms. Topics will include lesson and unit planning, assessment and technology integration. These will be considered using a critical lens of research-informed theory and practice within the context of "teacher as reflective practitioner."', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8158', 'EDUC-4153', 'Teaching Science: Elem Sch', 'This course is an introduction to science education at the elementary level. It will address supporting theory, current research and lesson planning surrounding constructivist modes of instruction. Individual components of a science lesson will be addressed. The integration of science with other subjects will be studied through examples that align with STSE, STEM and STEAM curricular initiatives.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8160', 'EDUC-4173', 'Teaching Math: Elem School 1', 'This course addresses how elementary students become mathematically literate. The focus is on relevant documents and research-informed methods for teaching mathematics to elementary students. Pre-service teachers develop discovery activities and explore how elementary students think about and learn mathematics. Practices for teaching children to reason, to solve problems employing a variety of strategies, and to communicate mathematically are addressed.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8161', 'EDUC-4183', 'Teaching Math: Secondary Sch 1', 'This course introduces current methods for teaching secondary mathematics. Drawing on relevant documents and current research, pre-service teachers engage in discovery activities examining how secondary students think about, and build knowledge and skills in, mathematics. The overall objective is to learn how to help secondary students to grow in their mathematical literacy, and to fill gaps in knowledge and skills.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8163', 'EDUC-41A3', 'Energy, Power, Transport Tech', 'This course will provide an introduction to the philosophical and practical dimensions involved with teaching energy, power and transportation technology in Atlantic Canada schools. Topics will include learning theories in technology education, creativity and ingenuity in design and problem solving, introductory electronics, and renewable energy technologies. In addition, this course will explore how advances in energy, power and transportation technologies connect to broader pedagogical dimensions of education for sustainability, community outreach and the development of a critical technological literacy.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8164', 'EDUC-41B3', 'Communications Technology', 'This is a project-oriented content course where students are exposed to a range of communications technologies that are used and taught in the Nova Scotia public school program.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8165', 'EDUC-41C3', 'Production Technology', 'This is a project-oriented content course where students are exposed to a range of production skills and technological processes. The course content is tailored to match those topics typically taught in the Nova Scotia public school program.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8166', 'EDUC-41D3', 'Teaching Biotechnology', 'This course will allow students to work closely with the biotechnology curriculum that is currently emerging in the Nova Scotia public school program.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8168', 'EDUC-41F3', 'Soci, Hist, Phil Found. of Ed.', 'Enacting culturally and socially responsive pedagogy is the responsibility of every teacher. Effective teachers work to understand diverse people, histories and cultures. Using theory from education''s foundations disciplines, this course provides pre-service teachers with a set of lenses through which to understand and address endemic social inequality in schools and society.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8172', 'EDUC-4203', 'Literacy Across the Curriculum', 'This course will examine literacy across the curriculum by exploring the mutual supporting roles of reading and viewing, speaking and listening, and writing and representing as students learn within and across different subject areas and grade levels.  Students in this course will be encouraged to develop a critical reflective approach regarding the notion of literacy and text.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8177', 'EDUC-4233', 'Elementary Language Arts 2', 'This course further develops language and literacy learning methodologies in the context of digital, visual, and print literacies within a critical literacy framework. It examines how to adapt content, strategies, and assessment for literacy learners across social, cultural, and learning differences with particular attention to differentiation and culturally responsive pedagogy in provincial, national, and global educational contexts. Prerequisite(s): EDUC 4133 or equivalent, with a minimum grade of B-.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4133","with","minimum","grade","B-","required","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8178', 'EDUC-4243', 'Teaching Elem Social Studies', 'This course focuses on the principles and methods of teaching social studies in elementary school, with emphasis on the social studies knowledge, skills, and attributes that contribute to the development of engaged citizens. Topics include: disciplinary thinking, treaty relationships, interdisciplinarity, inquiry and project-based teaching and learning approaches, citizenship, democracy and identity development, critical literacy, human rights and diverse perspectives.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8180', 'EDUC-4263', 'Curric Prac for Diverse Learn', 'This course engages with relevant policies and curriculum documents as well as research informed instructional theories and practices related to diversity, equity and inclusion. Pre-service teachers will examine, design and develop inclusive practices to support diverse learners'' progress and transitions through the education system.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8185', 'EDUC-42A3', 'Media and the Environment', 'This course will examine the role traditional and emergent media play in constructing and transforming our cultural, political, scientific and personal perspectives and understanding of our environment. Drawing on contemporary critical themes of media theory and practice, the course will examine how media frames and discourses are created to enable particular cultural forms of political economy and power. Prerequisite(s): ESST 1023 and ESST 2003, or permission of the instructor.', 'EDUC', 3, 0, 4, '[{"codes":["ESST-1023","and","ESST-2003","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8186', 'EDUC-42B3', 'Sustainable Technologies', 'This course will examine the role of technology in the context of sustainability. It will critically explore from social, political and historical perspectives, how technological development has contributed both positively and negatively to the environmental crisis. Emphasis will be placed on how innovation with information, solar, wind, tidal and biomass technologies provides a path toward a more sustainable future. Prerequisite(s): ESST 1023 and ESST 2003, or permission of the instructor.', 'EDUC', 3, 0, 4, '[{"codes":["ESST-1023","and","ESST-2003","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8188', 'EDUC-42D3', 'Principles & Prac (Secondary)', 'EDUC 42D3 is an introduction to teacher education. Pre-service teachers engage in reflective practice to consider their own identity, integrity, and professionalism as they explore the art and science of teaching. Topics include an introduction to curriculum frameworks, integration across subject areas, various forms of lesson planning, instructional methods and models, assessment principles and strategies, and tools for creating safe learning environments.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8189', 'EDUC-42E3', 'Principles & Prac(Elementary)', 'EDUC 42E3 is an introduction to teacher education. Pre-service teachers engage in reflective practice to consider their own identity, integrity, and professionalism as they explore the art and science of teaching. Topics include an introduction to curriculum frameworks, integration across subject areas, various forms of lesson planning, instructional methods and models, assessment principles and strategies, and tools for creating safe learning environments.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8190', 'EDUC-42F3', 'Topics in Education', 'This course explores a specific topic related to education, the particular topic to be determined according to current concerns in the field of education as well as student needs and interests. The latter will be established through consultation with faculty.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8192', 'EDUC-42H3', 'Drama and Performative Inquiry', 'Located within Arts scholarship, this course embraces curriculum theory and practice as applied and interwoven. Course emphasis includes: theatre competencies, drama as a vehicle for understanding cultural and global contexts and literacies through character, role, plot and narratives across time and curricular areas, with a dedication to equitable learning spaces.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8193', 'EDUC-42K3', 'Indigenous Education', 'This course explores teachers'' roles in addressing Reconciliation through meaningful opportunities to integrate Indigenous knowledge, cultures, and worldviews into elementary and secondary teaching in Nova Scotia. Students will explore historical and contemporary aspects of treaty education and Mi''kma''ki in order to consider more broadly Indigenous Peoples'' experiences in Canada.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8195', 'EDUC-42M3', 'Principles/Prac 2 (Secondary)', 'This course draws on pre-service teachers'' practica in order to address a range of professional issues including educational law, professional roles, duties and responsibilities of teachers, ethics, professional relationships and communities of inquiry, the role of teachers'' unions and associations, school-based technology, school/community partnerships including school transitions and communication with parents/guardians, and the hiring process including resume writing, interview preparation, and job search. Prerequisite(s): EDUC 42D3 or equivalent.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-42D3","or","equivalent."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8196', 'EDUC-42N3', 'Principles/Prac 2(Elementary)', 'This course draws on pre-service teachers'' practica in order to address a range of professional issues including educational law, professional roles, duties and responsibilities of teachers, ethics, professional relationships and communities of inquiry, the role of teachers'' unions and associations, school-based technology, school/community partnerships including school transitions and communication with parents/guardians, and the hiring process including resume writing, interview preparation, and job search. Prerequisite(s): EDUC 42E3 or equivalent.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-42E3","or","equivalent."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8197', 'EDUC-4303', 'Creative Arts: Elementary', 'This course introduces pre-service teachers to the teaching and infusion of creative arts across the curriculum at the elementary school level. Emphasis will include textual, visual and performative arts. The purposes and powers of the creative arts will be explored.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8198', 'EDUC-4313', 'TEACHING PE & HLTH LIVING 1', 'This course introduces current methods for teaching physical education at secondary levels within an inclusive school setting. Drawing on relevant documents and current research, preservice teachers explore the pedagogical approaches to promoting activity in a variety of settings (gymnasium, outdoors, regular classroom) with a view to promoting active and healthy lifestyles.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8200', 'EDUC-4333', 'Equity and Inclusive Schooling', 'This course examines the foundations of social justice and equity and their relationship to the principles of inclusive schooling. Pre-service teachers will consider the systemic barriers that shape public education within a Canadian human rights framework and explore the first voice - lived experience of minoritized communities.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8202', 'EDUC-4353', 'Teaching Engl: Sec School 1', 'This course provides an approach to teaching English that emphasizes the relatedness of listening, speaking, reading, viewing and writing in curriculum and in language learning and development. The course stresses the practical application of literacy learning theories from current research and relevant curriculum documents. The teaching of literature and writing processes is examined from the perspective of assessing and supporting diverse learners.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8211', 'EDUC-4433', 'Asmnt for Teaching & Learning', 'This course introduces pre-service teachers to the principles of assessment, focusing on the creation, use, interpretation and analysis of multiple and appropriate assessment tools and measures, the alignment of assessment with instruction, and the use of assessment data, gathered from a range of sources, for a variety of purposes, including addressing achievement gaps.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8218', 'EDUC-4503', 'Digital Literacy & Curriculum', 'This course explores critical digital literacies for the empowerment of effective teaching and learning practices within diverse classroom contexts. The complexity of technology integration will be examined from the perspective of overlaps with pedagogical and content knowledge in the context of teacher as reflective practitioner. Through the use of current digital tools and classroom strategies, students will explore concepts such as Blended Learning, Digital Citizenship, new literacies, Universal Design for Learning, design thinking in STEAM environments, assistive technology, digital divide, and digital citizenship.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8223', 'EDUC-4553', 'Creative Arts: Secondary', 'This course provides pre-service teachers with opportunities to explore and reflect on the purposes and powers of the creative arts, while practicing with colleagues how to teach the creative arts in secondary schools, including the infusion of creative arts across the curriculum. Emphasis will include textual, visual and performative arts.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8225', 'EDUC-4563', 'Educational Explorations', 'This course provides an opportunity for the exploration of a variety of educational issues through participating in formats such as institutes, workshops, and mini-courses. Evidence of 3 credit hours course equivalency, program relevance, and appropriate academic standards are to be submitted for prior approval to the Director. Evaluation is on a Pass/Fail basis. Available only to education students.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8226', 'EDUC-4573', 'Strat Tech: Energy/Power', 'This course is a lab-based introduction to a variety of teaching methodologies applicable to the Energy, Power and Transportation strand of technology education in Atlantic Canada schools. Emphasis will be placed upon the development of technological competence, practical dimensions of teaching technological problem solving, the design of appropriate learning activities and the planning and maintenance of a safe and stimulating learning environment for all students.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8227', 'EDUC-4583', 'Teach Strat Tech: Production', 'This course will address teaching methodologies for production technology. Themes of study will include materials science, processing materials, manufacturing, prototyping, life cycle analysis (LCA) and design for the environment (DfE). A critical component of this course will be the impact of production technology on society and the environment.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8228', 'EDUC-4593', 'Teach Strat Tech: Comm', 'This course will address teaching methodologies for communications technology. Themes of study will include communication systems, graphic and design communications and electronic communications. A critical component of this course will be the impact of communications technology on society and the environment.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8231', 'EDUC-4613', 'Teach Soci. Studies: Sec Sch 2', 'This course builds on the philosophical foundations of social studies education developed in EDUC 4113. It offers an opportunity for students to engage with current research to explore curriculum knowledge in depth, including but not limited to: building communities of inquiry, treaty education, reconciliation, social responsibility and community action, controversial issues, democratic participation, human rights and infusing diverse perspectives. Prerequisite(s): EDUC 4113 with a minimum grade of B-.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4113","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8233', 'EDUC-4633', 'Gender. Sexuality & Schooling', 'This course focuses on human sexual development and identity with an emphasis on adolescent and preadolescent sexuality. The course is organized around five units: (1) sexuality as a discourse of desire; (2) sexuality as a discourse of respect for self and others; (3) sexuality as a discourse of diverse ways of being; (4) sexuality as a discourse of love; and (5) sexuality as a discourse on sexual representations in popular culture. Attention will be given to social constructions of gender, gendered relations, and masculinity and femininity, and the ways these are manifest in curriculum and school settings.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8234', 'EDUC-4643', 'Teaching Science: Seco Sch 2', 'This course builds upon the theoretical and philosophical foundations of EDUC 4143 focusing further on relevant curriculum documents and research-informed theory and practice in the delivery of a science education within an inclusive education framework. Central to this study is a critical review of societal influences on curriculum and what constitutes scientific literacy. Issues of the environment are considered from a perspective of the responsible local and global citizen. Prerequisite(s): EDUC 4143 with a minimum grade of B-.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4143","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8235', 'EDUC-4653', 'Music Education: Elem School', 'This course will introduce a theoretical framework related to how children develop musically in elementary school. The practical implications of this theoretical model will be explored and related to the music curriculum of Nova Scotia.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8236', 'EDUC-4663', 'Music Ed for the Sec School 1', 'This course focuses on the principles and practice of music education in junior and senior high school programs. Both traditional and contemporary theoretical frameworks and their practical applications will be introduced and examined critically.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8237', 'EDUC-4670', 'Prac for the TESOL Program', '', 'EDUC', 0, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8238', 'EDUC-4673', 'Teach Engl: Second Language', 'This course introduces students to some of the major current teaching methods in English as a Second or Foreign Language. It is designed to help prepare teachers for teaching English to ESL speakers either in Canada or abroad. This course may be taken as part of the TESOL Certificate Program.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8239', 'EDUC-4683', 'Linguistics for Teachers', 'This course introduces students to the fundamentals of linguistics: the sound system (phonetics and phonology), word system (morphology), syntax, grammar, discourse analysis, and sociolinguistics. Although it may be taken by all interested students, it is primarily designed to be taken with EDUC 4673 and EDUC 4863 of the Acadia TESOL Certificate program for those who wish to teach English as a second or foreign language.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8241', 'EDUC-4703', 'Teaching Pe & Healthy Living 2', 'This advanced course will investigate how to design, deliver and assess an innovative and inclusive physical education program in junior, middle and high schools in the 21st century. Pre-service teachers will develop an understanding of research and practices examining how physical literacy and movement competency represents the foundation for lifelong participation and enjoyment in sport/recreation/active lifestyles. Prerequisite(s): EDUC 4313 or KINE 3143 or equivalent.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4313","or","KINE-3143","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8246', 'EDUC-4753', 'Teaching Seco in English 2', 'Drawing on principles introduced in EDUC 4353, this course offers an extended examination of how social, cultural and learning differences affect English teaching and learning in secondary classrooms. Practical issues in the teaching and assessment of literature learning, language usage, and writing are explored from the perspective of cultural responsiveness and differentiation. Prerequisite(s): EDUC 4353 or equivalent, with a minimum grade of B-.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4353","with","mimumum","grade","B-","","required","or","Department","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8247', 'EDUC-4763', 'Creative Integration of Curric', 'This elective course surveys a range of approaches through which prescribed outcomes in Elementary Language Arts, Mathematics, Science and Social Studies curriculum can be integrated in classroom practice. While theories of curriculum integration form the foundation for the course, the emphasis is on the notion of creativity as a means to situate learning in meaningful contexts. This course is offered at both the undergraduate and graduate levels.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8248', 'EDUC-4773', 'Place & Outdoor-T&l Meth', 'This course explores how learning can move beyond traditional indoor classrooms and how local and natural places can be critical sites for teaching. Pre-service teachers will learn how to design and deliver experiential and embodied outdoor learning activities that are linked to the curriculum. Students will understand the environmental and social benefits of incorporating local people and places into teaching practices.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8249', 'EDUC-4783', 'Teaching Math in Seco Sch 2', 'Fundamental issues in secondary mathematics education include the nature of mathematics and our purposes in teaching mathematics. Drawing on relevant documents and current research, this course provides pre-service teachers with opportunities to investigate and use instructional and assessment materials for high school mathematics. Prerequisite(s): EDUC 4183 with a minimum grade of B-.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4183","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8250', 'EDUC-4793', 'Curric Issue: Fren 2nd Lang', 'This course builds on the philosophical foundations of French as second language education developed in EDUC 4103. It offers an opportunity for students to examine carefully the specific curricula they will encounter as teachers in the secondary public school setting. Prerequisite(s): FRAN 4403 or EDUC 4103 with minimum B- grade.', 'EDUC', 3, 0, 4, '[{"codes":["FRAN-4403","or","EDUC-4103","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8258', 'EDUC-4863', 'Acquisition of Language', 'This course focuses on how language is acquired, and how different theories of language learning have shaped the way that teachers teach English as an additional language. There will be sociocultural, physiological, and psychological analysis of language acquisition. The course may be taken as part of the TESOL Certificate Program.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8260', 'EDUC-4893', 'Directed Readings in Education', 'Designed to broaden the student''s understanding of the field and to satisfy special interests. Students are expected to present a definite plan of study. Prerequisite(s): EDUC 4923.', 'EDUC', 3, 0, 4, '[{"codes":["EDUC-4923"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8263', 'EDUC-4923', 'Practicum 3', 'The third block of supervised student teaching. Working with a school-based associate teacher and a School of Education University advisor, pre-service teachers take on more responsibility in the classroom with increased independent practice in planning, classroom instruction and assessment. Pre-service teachers continue to develop a personal portfolio that reflects their beginning growth in professional practice.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8264', 'EDUC-4933', 'Practicum 4', 'The final block of supervised student teaching. Working with a school-based associate teacher and a School of Education University advisor, pre-service teachers are expected to take on full responsibility in the classroom with independent practice in planning, classroom instruction and assessment. Pre-service teachers complete their professional growth portfolio and present it as a culmination of the four practica.', 'EDUC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8267', 'EDUC-5003', 'Theories Human Dev & Learning', 'This course provides a framework for thinking about human development and learning. Using a multi-theoretical perspective, it explores the physical, cognitive, behavioural, and emotional growth of individuals spanning the entire developmental trajectory. It also examines major concepts and theories of learning that inform our understanding of how knowledge and worldview are influenced through the interactions of individuals and their environments.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8269', 'EDUC-5013', 'History of Education', 'This course surveys, from a national as well as a regional perspective, the development of the Canadian school system from its colonial beginnings until the 1990s. The main focus is on the process of curriculum development, the social and cultural contexts in which it occurred, the principles that guided it, and the programs of study that emerged from it.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8270', 'EDUC-5023', 'Philosophy of Education', 'This course examines selected aspects of education from a philosophical perspective. Topics included are the relationship between theory and practice; dimensions of educational value; the nature of knowledge and the curriculum; moral education; the teacher and controversial issues; and the school as object and agent of reform.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8271', 'EDUC-5033', 'Counselling Theories', 'This course is an introduction to the field of counselling.  Philosophical foundations and historical bases of the counselling profession are considered from a critical perspective and current issues and future trends are explored. A significant portion of the course is devoted to the study of the major theories of counselling, both historical and current.  Prerequisite: Admission to the MEd Counselling program', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8272', 'EDUC-5043', 'Sociology of Education', 'This course is designed to study social problems emanating from such institutions as the family, the community, and political and religious organizations, and to illustrate how these problems impinge upon the schools and the role of the teachers and students.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8273', 'EDUC-5053', 'Topics in Education', 'This course is designed to allow students to engage in the study of special topics that are of emerging interest in their core area. While these studies can be undertaken as a group, they may also consist of instructors working directly with individual students.  Prerequisite(s): 9h graduate courses or their equivalent, at the discretion of the Director.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8274', 'EDUC-5063', 'Incl Educ and Social Justice', 'Foundational concepts embedded within the principles of equity, diversity, inclusion and decolonization are examined using the analytical tools of intersectionality, anti-racist education, ableism, gender, culture, and power.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8275', 'EDUC-5066', 'Coun Practicum & Group Super', 'Students participate in a minimum 500-hour supervised counselling practicum that necessitates full-time availability for the 16-week residency to meet practicum requirements. The practicum is accompanied by a 36-hour group supervision class to support practicum interns'' professional growth and development during the practicum period. Preference is given to those who have completed additional counselling courses. Enrolled students have full time status. Prereqs: EDUC 50F3, EDUC 5033, EDUC 5133, EDUC 5623, and EDUC 5583', 'EDUC', 6, 0, 5, '[{"codes":["EDUC-50F3,","EDUC-5033,","EDUC-5133,","EDUC-5623","and","EDUC-5583"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8276', 'EDUC-5073', 'Curr/Instruct Inclusive Educ', 'This course examines inclusive curriculum and instructional practices that will assist teachers in meeting students'' diverse learning needs in educational settings. Students will explore and critique relevant research related to inclusive school communities as well as issues around equitable assessment and instructional practices. Prerequisite or Corequisite(s): EDUC 5063.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5063"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8282', 'EDUC-50C3', 'School Counselling Programs', 'This course examines the roles and functions of school counsellors within a Canadian context, in the planning, development, implementation, and evaluation of programs aligned with various models of school counselling. Relevant ethical, legal, and diversity issues are considered in the context of provision of counselling, consultation, and coordinating services in the school setting.  Prerequisites: EDUC 5033 and EDUC 5133', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8283', 'EDUC-50D3', 'Ethics in Counselling Practice', 'This course provides a critical analysis of professional, ethical, legal, and diversity issues related to practice, teaching, supervision, and research in counselling. Students are encouraged to explore personal beliefs and values, review ethics and legal documents, consider procedures for processing ethical inquiries and complaints, and engage in application of ethical decision-making processes. Prerequisite: 12 hours of coursework in the program', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8284', 'EDUC-50E3', 'Counselling Across Lifespan', 'This course examines the application of theories of growth, learning, and identity formation in working with clients across the lifespan. Students will explore change strategies and consultative processes alongside ethical, equity, legal, and diversity considerations relevant to life stages. Students develop an understanding of significant life transitions and changes, as well as the role of counselling in supporting client well-being. Prerequisite(s): EDUC 5033 and EDUC 5133.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8285', 'EDUC-50F3', 'Counselling Pre-Practicum', 'The 40-hour pre-practicum lab experience moves students toward the practice of integrating  their beginning skills and strategies into an intentional counselling process in a simulated environment. While under supervision, students are encouraged to enhance self-awareness, further develop counselling competencies, analyse their emerging counselling theoretical orientation, and attune to ethical, legal, and culturally responsive practices.   Prerequisite or concurrent: EDUC 5033 and EDUC 5133', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8286', 'EDUC-50G3', 'Research Literacy', 'This course focuses on major research paradigms most often used by professional educators. Emphasis will be placed on the ability to read and interpret basic research language and to recognize common research methodologies employed in qualitative, quantitative and mixed methods approaches.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8287', 'EDUC-50H3', 'Disability St Educ', 'The course introduces students to theories of disability and considers how historic and contemporary disability definitions shape societal responses to disabled people. Disability Studies offers a critical framework for understanding disability as a social/political/cultural phenomenon. It also supports examinations of the normative ideals informing social policies and practices and the significant consequences they produce for disabled people. Prerequisite/Corequisite(s): EDUC 5063.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8288', 'EDUC-50J3', 'Assessment in Counselling', 'In this course students become familiar with general and formal assessment practices and their uses to inform intervention. Students obtain experience in the use of selected standardized assessment instruments frequently employed in the exploration of cognitive, academic, emotional, social, and behavioral functioning. Development of a critical perspective towards ethical and diversity considerations, conceptualization, purposes, and methods of assessment is promoted.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8289', 'EDUC-50K3', 'Clinical Mental Health Counsel', 'This course provides a foundation for working with clients who are living with a mental illness. Students will become familiar with the Diagnostic and Statistical Manual of Mental Disorders, Fifth Edition, and become conversant with evidence-supported and emerging approaches to prevention and intervention. The intent of the course is to establish a critical, conceptual, and procedural framework across the mental health continuum. Prerequisites: EDUC 5033 and EDUC 5133', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8290', 'EDUC-50L3', 'Interpersonal Communication', 'This course examines influences of communication style, context, and culture on relationships. It considers verbal and nonverbal, direct and indirect, oral and written communication. Foundations of effective communication and healthy relationships, and processes that enhance or detract from these are considered. In particular, conflict management and resolution approaches such as mediation are explored.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8292', 'EDUC-5106', 'Sem/Prac.:Incl Educ Spec Top', 'This course provides a) a seminar experience in which students read and discuss the literature on inclusive practice, followed by b) a practicum experience offering opportunities for application, reflection, collaboration with peers, and feedback from instructors. The focus of the course varies, concentrating on general inclusive practice, or on inclusive practice in literacy education, or in mathematics education. Prerequisite or Corequisite(s): EDUC 5063.', 'EDUC', 6, 0, 5, '[{"codes":["EDUC-5063"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8293', 'EDUC-5113', 'Qualitative Research in Educ', 'This course examines the traditions and paradigms of interpretive research in educational contexts. Practical, ethical, and theoretical issues are shared through class readings, discussion, and practical application. Opportunities are provided for students to learn and practice a variety of interpretive research methods and strategies. Students actively engage in analyzing data from a variety of interpretive perspectives. The intended outcome of the course is to provide students with skills and understandings in a wide range of interpretive research approaches that can be put into practice in classrooms and other research settings. Prerequisite(s): EDUC 5513.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5513"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8294', 'EDUC-5123', 'Curric Prac Incl School', 'This course examines curriculum programs, policies, and practices that are responsive to learner diversity in current educational contexts. Curricular and instructional design are examined within frameworks for equity and inclusive schooling.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8295', 'EDUC-5133', 'Counselling Skills', 'This course focuses on salient conditions, skills, and processes that have been associated through research with effective counsellor-client relationships and positive client growth. Through participation in lectures, discussions, and structured exercises, including role playing and video-recorded simulated counselling sessions, students integrate multiple skills into the beginnings of a therapeutic process.  Prerequisite or concurrent: EDUC 5033', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8296', 'EDUC-5143', 'Educational Explorations', 'This course provides an opportunity for the exploration of a variety of educational issues through participation in formats such as institutes, workshops, and mini-courses. Evidence of 3h equivalency (120 hours of approved voluntary professional development activities), program relevance, and appropriate academic standards are to be submitted for prior approval to the Graduate Coordinator. Evaluation is on a pass/fail basis. Available only to students enrolled in an Acadia University M.Ed. program or Director-approved extension programs (example: the NSAC technology program).', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8297', 'EDUC-5153', 'Readings in Education', 'This course is designed to permit individual students to pursue interest areas in depth through readings of the pertinent and current literature. Students can expect to be paired with faculty expertise and assigned a core reading list. Through Socratic instructor-led discussion of this literature, students have the opportunity to gain an enhanced understanding of the field.  Tangible deliverables for the course will be determined mutually by the student and the supervising instructor. Prerequisite(s): 9h graduate courses or their equivalent, at the discretion of the Director.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8298', 'EDUC-5163', 'Assistive Tech: Literacy', 'Assistive Technology (AT) includes a wide variety of strategies, services and tools to support all students in the classroom. This course focuses on introducing the participant to current conceptual models and use of assistive technology supporting access to literacy skill development for students with learning differences as well as discussion of integrating AT into the Program Planning Process.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8299', 'EDUC-5173', 'Assistive Tech: Learn&Leisure', 'Assistive Technology (AT) includes a wide variety of strategies, services and tools to support all students in the classroom. Participants will be introduced to current conceptual models and use of assistive technology necessary for some students with disabilities to access classroom learning and leisure activities. Course participants will explore the processes involved in the assessment and planning for appropriate utilization of AT in the school environment.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8300', 'EDUC-5183', 'Acquisition of Language', 'This course focuses on how language is acquired, and how different theories of language learning have shaped the way that teachers teach English as an additional language. There will be sociocultural, physiological, and psychological analysis of language acquisition. The course may be taken as part of the TESOL Certificate Program.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8301', 'EDUC-5193', 'Linguistics for Teachers', 'This course introduces students to the fundamentals of linguistics: the sound system (phonetics and phonology), word system (morphology), syntax, grammar, discourse analysis, and sociolinguistics. Although it may be taken by all interested students, it is primarily designed to be taken with EDUC 5693 and EDUC 5183 of the Acadia TESOL Certificate program for those who wish to teach English as a second or foreign language.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5693","and","EDUC-5183"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8302', 'EDUC-5203', 'Intro: Educational Technology', 'Technology has great potential to empower the teaching and learning process. This course will address integration strategies that align with learning theory and emergent models such as TPACK. While this course will emphasize the practical implementation of instructional technologies in educational settings, it also seeks to develop a critique of which instructional technologies are pedagogically sound.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8303', 'EDUC-5213', 'Organiz. Thry/Sch Culture', 'This course focuses on principles of traditional and critical organizational theory and their application to educational institutions. Concepts include bureaucracy, professional organizations, innovative organizations, learning organizations, and post-modern conceptions of organizations. Attention is given to principles of organizational cultures and politics and their application to schools, as well as their relevance to leadership and school development.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8305', 'EDUC-5233', 'Counselling Families', 'This is an introductory course in counselling families and systemic approaches. In addition to an examination of the philosophical and historical underpinnings of family therapy, the course examines systemic theories and family therapy research. Students will have opportunities to consider the practical application of those theories to working with parents/guardians, couples, and families in school and agency settings.  Prerequisites: EDUC 5033', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8306', 'EDUC-5243', 'Supervision', 'This course is designed to study the principles, methods and techniques used in the supervision of instruction in the public school system, with emphasis on the evaluation of the teaching-learning process. This course may require observation of practice-teachers in the schools and discussion observations with the practice-teachers in a supervisory capacity.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8309', 'EDUC-5273', 'Education and the Law', 'This course examines statute and case law relating to public education in Canada. The objective is to clarify general legal principles through an investigation of such topics as authority in education, teacher rights, student rights and teacher/school board liability. A major focus is the educational implications of the Charter of Rights and Freedoms.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8310', 'EDUC-5283', 'Creative Integrat. Curric Elem', 'This elective course surveys a range of approaches through which prescribed outcomes in elementary language arts, mathematics, science, and social studies curriculum can be integrated in classroom practice. While theories of curriculum integration form the foundation for the course, the emphasis is on the notion of creativity as a means to situate learning in meaningful contexts. This course is offered at both the undergraduate and graduate levels.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8311', 'EDUC-5303', 'Principles of Asmnt in Educ', 'This course entails an examination of both summative and formative assessment in relation to various educational purposes. Professional issues such as the role of the teacher and student in assessment, bias, morality, and ethics are explored. Existing assessment practices and processes used in programme planning and curriculum implementation will be critically analyzed.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8312', 'EDUC-5313', 'Assessment for Learning', 'This course introduces students to the properties, levels, qualifications, and ethical considerations of standardized assessment. Students will have practical experience in the administration, interpretation, analysis, and sharing of assessment of Level A and B tests. Existing assessment practices and processes used in programme planning and curriculum implementation will be critically analyzed from an inclusive education lense.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8319', 'EDUC-5513', 'Research Design in Education', 'This course is designed to provide an introduction to multiple paradigms and approaches to research design. Emphasis is placed on participants reading, understanding, and critically engaging with research literature and developing a grounding in ethical best-practices for research with human subjects. Moreover, a focus of the course is on applying the methodologies used to design, analyse and interpret educational research.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8320', 'EDUC-5523', 'Quantitative Meth Educ Res', 'This course provides a background for the educator who must use statistics in research, evaluation and planning. The fundamental statistical tools are reviewed and particular statistical methods applicable to educational problems are introduced in this course. While the student uses computers to calculate and to manage the data, an emphasis is placed upon the interpretation of statistical results. The following topics are part of this course: linear regression and correlation, multiple regression analysis, analysis of variance, and non-parametric statistics.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8321', 'EDUC-5543', 'Theories of Career Development', 'This course examines theories of vocational development and choice, meanings attached to work and leisure, and uses of occupational and educational information. Approaches for assisting individuals in exploration and decision-making related to work in the context of lifespan issues are actively explored. Consideration is given to issues related to equity and diversity as they relate to work-life. Prerequisite(s): EDUC 50J3.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-50J3"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8322', 'EDUC-5553', 'Topics in Counselling', 'Different sections of this course are offered each year to address specialized areas important to counsellors such as addictions, play therapy, sexual diversity, spirituality, trauma-informed practice and counselling in Indigenous communities. Each of these courses covers key concepts, frameworks for practice, current research, ethical principles, and the application of diversity-sensitive practices. For students in the COUN program, or by permission of instructor.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8323', 'EDUC-5563', 'Career Devel Process and Prac', 'Students will acquire specific competencies to offer career development or career counselling to individuals or groups. Topics covered: current trends in holistic career development, examination of pertinent terminology, navigating identity, work across the life span, examining constraints on work choices and life satisfaction, use of formal and informal assessment tools and application of career development knowledge to a volunteer case study.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8326', 'EDUC-5583', 'Counsel. Strategies/Interven.', 'This course builds upon an existing theoretical and skill foundation via conceptual and experiential exploration of counselling strategies and techniques. Students will be able to articulate a theoretical rationale for the selected strategies and techniques and will hone competency in their implementation. Prerequisite(s): EDUC 5033 and 5133.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8327', 'EDUC-5593', 'Feminist Counselling', 'Feminist counselling provides an opportunity for students to examine concerns that women may have as a result of living in a male-dominated society. This course integrates feminist principles within contemporary theoretical positions. It explores gender stereotypes, sex role socialization, institutionalized sexism, lifespan issues for women, and provides a feminist vision of counselling and psychotherapy. Prerequisite(s): EDUC 5033.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8328', 'EDUC-5603', 'Topics in Educ Technology', 'This course is designed to familiarize the student with current and emergent technologies that have potential to empower teaching and learning. With constructivist pedagogy as a core foundation, students will evaluate tools and approaches from a critical stance. In remaining current, topics will vary but may include such things as multimedia tools, e-learning strategies, digital literacy, assistive technologies and the implications of IT research.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8331', 'EDUC-5623', 'Group Counsel: Theory & Prac', 'This course provides a conceptual and experiential introduction to group counselling theory, models, skills, strategies, and techniques. It affords opportunity for the acquisition and application of self-awareness, knowledge, and competencies related to group counselling and leadership. Students explore group development, process, and dynamics; therapeutic factors; facilitator and member roles; ethical and legal considerations; and culturally responsive group practices. Prerequisites: EDUC 5033 and 5133', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5033","and","EDUC-5133"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8332', 'EDUC-5633', 'Curriculum Foundations', 'This course is designed to examine the nature of curriculum and the basic principles of the curriculum making process.  The nature of curriculum is investigated via consideration of a range of historical perspectives. Curriculum as a field and as a practice is examined through foundational theoretical models. Special attention is given to the role of educators, administrators, and others who influence the development of curriculum. The integration of theory and practice and recent innovations in curriculum organization serve as reference points throughout this course.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8333', 'EDUC-5643', 'Mjr Theor Devel: Curric Study', 'This course focuses on current issues in the field of curriculum studies. The course integrates contemporary work in the social sciences and the humanities in the analysis of curriculum. Students are invited to critically examine the impact of theory that influences curriculum development in schools. Prerequisite or Corequisite(s): EDUC 5633 or permission of the instructor', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5633","","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8334', 'EDUC-5653', 'Literacy Development', 'This course is designed to examine the theoretical constructs of literacy development. The course provides an opportunity to investigate how language, both spoken and written, is learned. Instructional implications of theory and research provide a framework for examining topics such as developmental learning, holistic teaching, language across the curriculum, and evaluation.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8335', 'EDUC-5663', 'Curriculum Practice', 'This course provides an opportunity for students to apply the theoretical implications from previous courses (i.e. 5633 and 5643) to the examination and development of curricula. Students are required to design and develop a curricular project. Prerequisite(s): EDUC 5633, EDUC 5643, or permission of the instructor.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5633","and","EDUC-5643","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8336', 'EDUC-5673', 'Current Research/Theory Curric', 'This course is designed to examine recent research and theoretical developments in a specific subject matter area (sections will be assigned to specific specialty) and how they affect the design of instruction and curriculum. Such developments are examined in terms of their impact on current teaching and curricular initiatives. If using the course to meet concentration requirements, the focus of the study must be in the concentration area. Prerequisite(s): EDUC 5633, EDUC 5643, or permission of the instructor.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5633","and","EDUC-5643","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8339', 'EDUC-5693', 'Teach. English as a 2nd Lang', 'This course introduces students to some of the major current teaching methods in English as a Second or Foreign Language. It is designed to help prepare teachers for teaching English to ESL speakers either in Canada or abroad. This course may be taken as part of the TESOL Certificate Program.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8342', 'EDUC-5713', 'Project in Education', ' The focus of the project in this course is on practical applications grounded in scholarly work. The project should be a substantial piece of work with a written component. Projects might include, but are not limited to: development of software or artistic presentation, curriculum development, creation of a professional development program, action research and systematic  program evaluations.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-5513","or","Permission","of","the","Instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8348', 'EDUC-5763', 'Culture, Language, & Education', 'This course focuses on the relationships between culture, language, and identity as they relate to human development and schooling. Topics include: culture, language, identity, ethnicity, race, gender, and socio-economic status.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8349', 'EDUC-5773', 'Comm. Perspect. School/Society', 'Education and employment are increasingly driven by globalization; this loss of local control is a worldwide phenomenon. What happens to communities and our sense of belonging in the new "global marketplace"? What does it mean to be a citizen in a consumerist society? This course considers how teachers and schools can respond to these massive social, economic, and technological changes. Topics include cultural identity, social justice, and human and ecological development in both rich and poor countries.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8354', 'EDUC-5843', 'Instructional Design', 'This course investigates historical and current developments in instructional design. Selected instructional systems are examined in terms of a design-delivery-evaluation model. A major focus is the application of models to specific curricular areas in elementary and/or secondary schools.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8355', 'EDUC-5853', 'Online Technology in Education', 'This course explores the integration of online technology into educational practice. The ways in which technology is being integrated are considered as well as the implications. Particular attention is given to the role that technological developments have played in inviting educators to reconsider our thinking with regard to fundamental educational concepts, such as learning and schooling. If using the course to meet concentration requirements, the focus of the study must be in the concentration area.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8358', 'EDUC-5873', 'Technology & Curriculum', 'Technology has been broadly described as "a way of adapting". In an effort to lend context to learning, progressive curriculum initiatives have sought to integrate this notion of technology with subjects of science, mathematics, engineering and the arts.  Acronyms of STEM and STEAM have become common place in curriculum literature. This curriculum goes beyond using instructional technology to promote learning to include problem solving and critical thinking as a human endeavor to adapt. This course will address the historical evolution of technology as an integrated and inescapable component of 21st century education.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8360', 'EDUC-5913', 'Theor. Persp. Leadership', 'This course is intended to familiarize students with past and present thinking on leadership, especially as it applies to educational settings. Consideration is given to previous research on leadership, including that on traits, behaviour, situational leadership, and charismatic leadership. The course moves towards a focus on democratic and inclusive forms of educative leadership.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8361', 'EDUC-5923', 'Sem & Practicum in Leadership', 'This course is intended to provide graduate students in leadership with field experience in appropriate settings. Placements are chosen by the program coordinator in consultation with students. The course consists of regular seminars. Cases from field experiences are presented and discussed. Availability of this course depends on student numbers and practicum site availability.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8362', 'EDUC-5933', 'Equity and Leadership', 'This course examines intersectional and cultural leadership models and contexts within organizations with an emphasis on educational settings. Coursework is informed by current research and practices in leadership that are founded on principles of equity and commitments to decolonization.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8363', 'EDUC-5943', 'Change Thry/Learning Organ.', 'Change is a fundamental, and frequently problematic, aspect of organizational life. This course focuses on the process of change and examines the tensions and contradictions involved in this process. Attention is given to the premises under which change occurs and ways in which the process can be undertaken in a democratic and inclusive manner.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8364', 'EDUC-5953', 'Schools and Social Justice', 'This course re-examines and deconstructs the roles which schools play in society. Instead of viewing schools merely as sites where knowledge gets passed from one generation to another, the focus switches to the roles which schools play in the distribution of social and economic benefits and in the reproduction of inequity. Central topics include poverty and education, knowledge and power, curriculum and ideology, and the reproduction of advantage and disadvantage.', 'EDUC', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8366', 'EDUC-5966', 'Graduate Thesis', 'Prerequisite(s): EDUC 5113 or EDUC 5523.', 'EDUC', 6, 0, 5, '[{"codes":["EDUC","5513","and","either","EDUC-5113","or","EDUC-5523"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8367', 'EDUC-8013', 'Foundations of Educ Inquiry', 'An examination of the purpose, process, nature and ideals of education. Students engage with enduring educational philosophical and theoretical traditions and perspectives, the history of educational thought and the philosophy of education, in particular. A variety of foundational perspectives provide deeper understandings of the theoretical and methodological underpinnings of education. Corequisite(s): EDUC 8013 is a corequisite of EDUC 8023 is a prerequisite for the remaining courses in the program.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8368', 'EDUC-8023', 'Meth Perspec on Educ''l Rsrch', 'An examination of the import of methodological paradigms in educational research (building on the foundations of educational inquiry). Students investigate: (a) ontological assumptions; (b) epistemological views; (c) the role of logic, sound evidence and justified beliefs; (d) axiology (values and biases); and, (e) rhetorical (research reporting structures) components of educational inquiry. Corequisite(s): GEDU 8023 is a corequisite of GEDU 8013 is a prerequisite for the remaining courses in the program.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8369', 'EDUC-8033', 'Doctoral Sem:Cont Educ Theory', 'An exploration of how educational philosophy, research paradigms and theories are manifested in contemporary educational research debates and dialogues. Through an intensive examination of a range of theories that inform studies in education, students gain an advanced and comprehensive understanding of contemporary educational theory within the Canadian and international contexts. Prerequisite(s): EDUC 8013 and EDUC 8023. EDUC 8043 is a corequisite of EDUC 8033.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013,","EDUC-8023,","and","EDUC-8043"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8370', 'EDUC-8043', 'Focused Educational Studies', 'A focused exploration of research topics reflective of the current roster of doctoral students. In a seminar setting, individual students study the research and theoretical literature in the educational area(s) that background and inform their research interest(s). Prerequisite(s): EDUC 8013: and EDUC 8023. EDUC 8033 is a corequisite of EDUC 8043.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013,","EDUC-8023,","and","EDUC-8033"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8371', 'EDUC-8053', 'Adv Resrch Sem: Focus on Meth.', 'Students gain detailed knowledge and technical expertise related to methods appropriate to their research question(s), aligned with philosophical and methodological orientations. Issues related to research design process are addressed, as they differ from method to method. Prerequisite(s): EDUC 8013 and EDUC 8023.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013","and","EDUC-8023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8372', 'EDUC-8063', 'Special Topics Educ Studies', 'An exploration of a selected topic in educational studies to provide students with detailed knowledge and further preparation for advanced research. Prerequisite(s): EDUC 8013 and EDUC 8023.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013","and","EDUC-8023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8373', 'EDUC-8073', 'Special Topics Educ Studies', 'An exploration of a selected topic in educational studies to provide students with detailed knowledge and further preparation for advanced research. Prerequisite(s): EDUC 8013 and EDUC 8023.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013","and","EDUC-8023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8374', 'EDUC-8083', 'Independent Study 1', 'An Independent Study related to topics in educational studies. The curriculum for this course will be determined by the supervisor of the course in consultation with the student and other faculty members, as necessary. Prerequisite(s): EDUC 8013 and EDUC 8023.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013","and","EDUC-8023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8375', 'EDUC-8093', 'Independent Study 2', 'An Independent Study related to topics in educational studies. The curriculum for this course will be determined by the supervisor of the course in consultation with the student and other faculty members, as necessary. Prerequisite(s): EDUC 8013 and EDUC 8023.', 'EDUC', 3, 0, 8, '[{"codes":["EDUC-8013","and","EDUC-8023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8376', 'EDUC-8109', 'Comp. Portfolio Examination', 'Develop and orally defend an extensive scholarly portfolio demonstrating sufficient breadth, depth, creativity and engagement to undertake substantive research in the field. Comprising 10-15 artifacts, students will demonstrate knowledge and competence in each of five areas: general, in-depth, research, professional and collegial, and teaching and instruction (graded Pass/Fail). Corequisite(s): Students complete the first five required courses (EDUC 8013, EDUC 8023, EDUC 8033, EDUC 8043, and EDUC 8053) and any additional special topics (EDUC 8063, EDUC 8073) and/or independent studies courses (EDUC 8083, EDUC 8093) while generating the contents of their portfolio.', 'EDUC', 9, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8377', 'EDUC-8900', 'Phd Holding Course', '', 'EDUC', 0, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8378', 'EDUC-8990', 'Dissertation Continuation', '', 'EDUC', 0, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8379', 'EDUC-899Z', 'Dissertation', 'The dissertation must constitute a substantial and original contribution to the study of education. To complete this course, students must prepare a research proposal for approval by an appropriate faculty dissertation committee, complete the proposed study, and publicly defend the completed draft in a final oral examination (graded Pass/Fail). Prerequisite(s): successful completion of all course work and successful completion of EDUC 8109.', 'EDUC', 18, 0, 8, '[{"codes":["EDUC-8109","and","successful","completion","of","all","course","work"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8387', 'ENGL-1213', 'Composition 1', 'In this course, students will read a variety of essays and articles to help them learn to write a unified and coherent academic essay. Emphasis is on formulating a clear thesis, demonstrating an awareness of purpose and audience, and developing a personal writing voice in expository essays. Students cannot proceed to a major in English if they have taken only English 1213/ENGL 1223. ENGL 1213 is not a prerequisite for English courses at the 2000 and 3000 levels.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8388', 'ENGL-1223', 'Composition 2', 'In this course, students build on the basic elements of writing covered in ENGL 1213, but the emphasis is on argumentation. Students in this term will read at least one literary text in addition to essays, and they will learn the strategies of persuasive, effective writing, including those that pertain to the critical, literary essay. Please note that ENGL 1223 is not a prerequisite for English courses at the 2000 and 3000 levels. Prerequisite(s): ENGL 1213.', 'ENGL', 3, 0, 1, '[{"codes":["ENGL-1213"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8390', 'ENGL-1313', 'Comp. 2nd Lang Students 1', 'This course is designed for students who do not speak English as a first language. The course will focus primarily on the development of writing skills. Special attention will be given to fundamentals of grammar, vocabulary building, sentence structure, analysis of texts, and the organization of written argument.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8391', 'ENGL-1323', 'Comp. 2nd Lang Students 2', 'This course is designed for students who do not speak English as a first language. The course will focus primarily on the development of writing skills. Special attention will be given to fundamentals of grammar, vocabulary building, sentence structure, analysis of texts and the organization of written argument, and an introduction to research and documentation techniques. Prerequisite(s): ENGL 1313.', 'ENGL', 3, 0, 1, '[{"codes":["ENGL-1313"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8393', 'ENGL-1413', 'Writing & Reading Critically 1', 'This course introduces students to fiction, drama, and poetry from a range of periods. Students will develop analytical skills and learn strategies for writing clearly and persuasively.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8394', 'ENGL-1423', 'Writing & Reading Critically 2', 'This course introduces students to fiction, drama, and poetry from a range of periods. Students will develop analytical skills and learn strategies for writing clearly and persuasively.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8396', 'ENGL-2003', 'Creative Writing Workshop', 'An exploration of literary expression in a variety of genres. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8398', 'ENGL-2013', 'Explore Creative Writ: Intro', 'An introduction to the fundamentals of creative writing including technique and process through writing, reading, lecture, discussion, and workshop participation. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8399', 'ENGL-2033', 'Print Cult. & Hist of the Book', 'Print Culture and the History of the Book introduces students to the codex form from pre-modern to contemporary times. Closer attention will be given to medieval manuscript books and their influence on early printed books, on the means of production from Gutenberg-era presses to print-on-demand resources, and on descriptive bibliography as a way of recording books through the ages. Prerequisite(s): ENGL 1406 (ENGL 1413/1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8401', 'ENGL-2113', 'Heroes&Villains Pre-Mod World', 'A study of the epic-heroic tradition in ancient, classical, and medieval literature. Particular attention will be given to aspects of heroism, gender identity, and mythopoesis. May be taken for Classics credit. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): IDST 2433.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8402', 'ENGL-2153', 'Theory and Practice of Editing', 'This is a hands-on introduction to editorial theory and practice which offers a behind-the-scenes look at the evolution and dissemination of scholarly and creative texts, and teaches students practical skills associated with the editorial process, including electronic editing. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8403', 'ENGL-2163', 'Medieval Literature 1', 'An exploration of the medieval origins and development of the Legend of King Arthur. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8404', 'ENGL-2173', 'Medieval Literature 2', 'A study of Geoffrey Chaucer''s Canterbury Tales. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8406', 'ENGL-2183', 'Shakespeare 1', 'This course will involve the intensive study of selected plays by Shakespeare. Its main goal is to help students develop both a critical and a theatrical eye. Careful attention will be paid to the complexity of Shakespeare''s language, as well as to the plays'' roles as cultural artefacts both today and in the past. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): Credit can be obtained for either ENGL 2223 and ENGL 2233, or for one or both ENGL 2183 and ENGL 2193.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8407', 'ENGL-2193', 'Shakespeare 2', 'This course will involve the intensive study of selected plays by Shakespeare. Its main goal is to help students develop both a critical and a theatrical eye. Careful attention will be paid to the complexity of Shakespeare''s language, as well as to the plays'' roles as cultural artefacts both today and in the past. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): Credit can be obtained for either ENGL 2223 and ENGL 2233, or for one or both ENGL 2183 and ENGL 2193.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8408', 'ENGL-2273', 'Sixteenth Century Literature', 'Selected poetry and prose of the sixteenth century, with emphasis on the works of Sidney, Spenser, and the poetry of Shakespeare. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8410', 'ENGL-2283', 'Seventeenth Century Studies', 'A study of seventeenth century literature emphasizing poetry and prose by major authors (including Milton). Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8414', 'ENGL-2313', 'Adv Eng Comp: Intl Students', 'This course is offered to international students in their upper years to refresh the principles of academic writing. It will allow students to refine their abilities in writing and critical thinking by reviewing writing skills and extending these to include more analysis through advanced writing methods. Prerequisite(s): ENGL 1323. Restricted to students whose first language is not English.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1323"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8415', 'ENGL-2353', 'The Romantic Imagination', 'This course explores the ways that British Romantic Period authors turned to the imagination as a tool for revolutionary and counterrevolutionary innovations and perceptions. The influence and impact of this antidote to enlightenment reason will be surveyed through the works of William Blake, William Wordsworth, Samuel Taylor Coleridge, Percy Shelley, Mary Shelley, John Keats, Matthew Lewis, Lord Byron and others. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ENGL 2386 or ENGL 2353/ENGL 2363.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8416', 'ENGL-2363', 'Romantic Women', 'This course focuses on the ways that the revolutionary politics of the British Romantic Period (1785 - 1830) amplified and challenged the voices of its women writers. We will interrogate the idea of "Romanticism" and its construction of women through the works of Jane Austen, Charlotte Smith, Mary Robinson, Mary Wollstonecraft, Anna Laetitia Barbauld, Joanna Baillie, Letitia Elizabeth Landon, and others. Prerequisite(s): ENGL-1483 and ENGL-1493 or ENGL-1413 and ENGL-1423 or ENGL-1406; Minimum grade C- required. Antirequisite(s): Credit can be obtained for only one of ENGL 2386 or ENGL 2353/ENGL 2363.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8418', 'ENGL-2383', 'Restoration & Early 18C', 'This course will introduce students to British literature and culture of the period 1660 to 1730. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8420', 'ENGL-2393', 'Later Eighteenth-Century Lit', 'This course will introduce students to British literature and culture of the period 1730 to 1800. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8421', 'ENGL-2413', 'Victorian Literature & Culture', 'This course situates Victorian literature in its historical, social, and political contexts, introducing students to canonical and non-canonical works in order to understand the nineteenth-century issues with which writers were generally preoccupied. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ENGL 2476 or ENGL 2413/ENGL 2423.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8422', 'ENGL-2423', 'Victorian Art & Aesthetics', 'This course examines the work of the Pre-Raphaelites, the writers of British Aestheticism, and the writers of late century Decadence of the Fin-de-Siècle. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of ENGL 2476 or ENGL 2413/ENGL 2423.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8425', 'ENGL-2563', 'Canadian Literature 1', 'This course will provide an overview of significant developments in the history of Canadian literature in English up to World War Two, stressing the influence of Canada''s colonial heritage on the shaping of the country''s literature. The course will address the historical contexts of the works under study and will examine important themes, issues, and aesthetic considerations. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8426', 'ENGL-2573', 'Canadian Literature 2', 'A survey of Canadian literature in English from World War Two to the present. The course will provide an overview of significant developments in English-Canadian literature as well as a more detailed exploration of particular writers, themes, issues and literary concerns, such as postcolonialism, multiculturalism, gender and postmodernism. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8429', 'ENGL-2683', 'American Literature 1', 'This course examines American literature of various genres (captivity narratives, slave narratives, essays, journals, stories and poetry) from the letters of Christopher Columbus, through the novels and poetry of the American Renaissance, to the Civil War poetry of Walt Whitman. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8430', 'ENGL-2693', 'American Literature 2', 'Students will study the development of American poetry and fiction (including the emergence of Realism and Naturalism) from the Civil War to the 1930s. Major writers to be studied may include Henry James, Mark Twain, Emily Dickinson, Willa Cather, Robert Frost, Sherwood Anderson, Ernest Hemingway, and Wallace Stevens. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8433', 'ENGL-2773', 'Eighteenth-Century Fiction', 'This course will introduce students to tales and novels written in Britain from the 1680s to the 1790s. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8435', 'ENGL-2783', 'Nineteenth-Century Fiction', 'A study of the forms and functions of nineteenth-century fiction. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8446', 'ENGL-3053', 'Experimental Poetry', 'Introduces students to the origins and developments of experimental poetry, beginning with the revolutionary movements of the early 20th century (dada, imagism, surrealism, etc.), followed by an exploration of movements throughout the 20th century to the present. Experimental movements examined might include Objectism, Black Mountain poetics, L=A=N=G=U=A=G=E Poetry, and Dub poetry. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8448', 'ENGL-3073', 'Advanced Theory, Research', 'Focusing on theoretical approaches and debates central to the study of literatures and cultures in English, this senior course will introduce students to best practices in research project development and advanced academic writing. Topics may include affect theory, critical race theory, cultural studies, digital studies, ecocriticism, feminism, formalism, gender/queer/trans/sexuality studies, genre theory, new historicism, postcolonialism, and psychoanalysis.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-2083","and","ENGL-2093;","Minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8450', 'ENGL-3083', 'Adv Creative Writing 1: Poetry', 'An advanced course emphasizing craft, style and individual development in the writing of poetry. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) and permission of the Department.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8452', 'ENGL-3093', 'Ad Creative Writing 2: Fiction', 'An advanced course emphasizing craft, style, and individual development in the writing of fiction. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) and permission of the Department.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8453', 'ENGL-3103', 'Shakespeare and Medicine', 'This course explores intersections between Shakespeare and the discourses and practices of medicine. We will examine such plays as All''s Well That Ends Well, King Lear, and The Winter''s Tale, reading their representations of the body alongside early modern accounts of anatomy, physiology, and psychology. Specific topics may include ability/disability, aging, disease, herbalism, mental health, morbidity, pharmacology, pregnancy/lactation, and sex/sexuality. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8456', 'ENGL-3283', 'Drama to 1600', 'A study of English drama from the late Middle Ages to 1600, including the Mystery Cycles and morality plays. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8458', 'ENGL-3293', 'Renaissance Drama', 'A study of English plays from the Renaissance with an emphasis on non-Shakespearean drama. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8460', 'ENGL-3483', 'Nineteenth Century Poetry', 'This course provides a study of nineteenth-century poetry and poetic theory, introducing students to several important genres in the long nineteenth-century: lyric forms, the sonnet, the verse novel, the dramatic poem and the epic. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8463', 'ENGL-3503', 'Poetry of Atlantic Canada', 'This course exposes students to a selection of works from the long and rich tradition of poetry in Atlantic Canada, from the Loyalist verse of colonial times to the poetry of the diverse and multicultural region of today. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8464', 'ENGL-3513', 'Fiction of Atlantic Canada', 'From the early nineteenth century sketches of Thomas McCulloch and Thomas Haliburton to the lyrical and comic contemporary novels of David Adams Richards, Lynn Coady and Wayne Johnston, the Atlantic Provinces have made a substantial contribution to Canadian fiction, and this course provides a historically and stylistically diverse sample of what Atlantic fiction writers have to offer. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8465', 'ENGL-3523', 'The Writer and Nature 1', 'This course traces the development of Nature Writing in English to the end of the nineteenth century. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8466', 'ENGL-3533', 'The Writer and Nature 2', 'An exploration of modern and postmodern colonial texts which have helped to shape an emerging ecological vision of nature. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8468', 'ENGL-3553', 'Modern American Poetry', 'In this course, students examine trends in American poetry from the 1930s to the present. The course will focus on collections of poetry by such poets as Langston Hughes, Allen Ginsberg, Sylvia Plath, Anne Sexton, Adrienne Rich, and Sharon Olds. Attention will be given to the historical contexts and critical debates that inform the works under study. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8469', 'ENGL-3563', 'Modern American Novel', 'This course offers a critical study of the American novel, in all its variety and diversity, from 1930 to the present. Writers to be studied may include Zora Neale Hurston, Carson McCullers, Richard Wright, Ralph Ellison, Jack Kerouac, and Truman Capote. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8470', 'ENGL-3573', 'Modern Canadian Poetry', 'This course will look at modern Canadian poetry and poetics from the early 20th century to the present, emphasizing modernism and how modernist and post-modernist ideas and movements, internationally and nationally, have shaped Canadian poetry. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8475', 'ENGL-3613', 'CanLit 3: Contemp. Fiction', 'An introduction to contemporary Canadian fiction through the shortlisted texts of a major national literary prize. Students will develop close-reading skills while studying the history of literary prizes in Canada, examining how and by whom literary value is created and conferred, situating works in social and political contexts, and participating in debates about the significance of Canadian literature today.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8476', 'ENGL-3663', 'Postcolonial Lit: S. Asian Lit', 'This course introduces students to contemporary South Asian literature written in English. Focusing on literature from India and the subcontinent, the course encourages students to recognize how South Asian writers explore issues of political and cultural autonomy through literature. Students will study works from writers as diverse as R.K. Narayan, Salman Rushdie, Nissim Ezekiel, Arundhati Roy, and Jean Arasanayagam. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8477', 'ENGL-3673', 'Postcolonial Lit: African Lit', 'Introduces students to contemporary African Literature focusing on how African writers use literature to counter imperial legacies of invasion, settlement, and cultural destruction. To develop their historical and cultural understanding of African peoples, students will apply postcolonial reading strategies to works of various genres, tackling issues such as race, gender, language and nationalism. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8478', 'ENGL-3683', 'Caribbean Literature', 'Introduces students to Caribbean literature, focusing on how Caribbean literature emerges as a creative and self-affirming response to an imperial history of slavery and indentured labour. Students will apply postcolonial reading strategies to works of various genres, tackling issues such as race, gender, language creaolisation and hybridity. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8483', 'ENGL-3723', 'Fantasy', 'The genre of fantasy, from its antecedents to the present and in a variety of forms such as novels, picture books, graphic novels, and short fiction, taking into consideration changes in the perceptions and the construction of childhood and gender roles. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8484', 'ENGL-3733', 'The Historical Novel', 'A consideration of novels where a serious effort has been made to recreate the atmosphere of an earlier period at the time of writing. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8485', 'ENGL-3743', 'Tolkien: Author and Critic', 'This course explores J.R.R. Tolkien''s The Lord of the Rings in the context of Tolkien''s career as a teacher and scholar of medieval language and literature. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8486', 'ENGL-3753', 'Studies in the Short Story', 'This course will introduce students to the short story written in English. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8487', 'ENGL-3763', 'Canadian Short Story', 'The short story is considered a particular forte of Canadian writers, and this course will introduce students to a selection of Canada''s finest and most engaging practitioners of the genre. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8488', 'ENGL-3773', 'Modern British Poetry', 'A study of the evolution of modern and contemporary British poetry. Poetry will be studied in its historical, cultural, and linguistic contexts. Poems will be selected to represent historical developments such as modernism, feminism, and postcolonialism as well as cultural topics such as war, religion, love, and politics. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8492', 'ENGL-3793', 'Modern British Fiction', 'A study of the evolution of modern and contemporary fiction written in the UK. Fiction will be studied in the context of the historical, political, and technological transformation of British culture with a focus on critical concepts such as race, gender, and language. Fiction will be selected to represent literary movements such as modernism, postmodernism, and postcolonialism. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8495', 'ENGL-3833', 'Writing by Women 1', 'The historical development, in English, of women''s writing from the late eighteenth century to the 1920s. Texts will include American, British, and Canadian writers. Cultural and literary theory will be used to focus on the interrelationship of text/context, genre and gender, author(ity) and the relations of cultural production. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8496', 'ENGL-3843', 'Writing by Women 2', 'An examination of modern and post-modern texts in English that reflect the wide range and cultural diversity of women writing in the twentieth and twenty-first centuries. Through the study of women''s fiction and poetry from around the world students will explore such subjects as feminist theory and ecocriticism, gender and ethnicity, revisionist mythmaking, and growing up female. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8503', 'ENGL-3903', 'Canadian Children''s Literature', 'An exploration of Canadian culture and childhood as presented in Canadian children''s literature over time and across regions, including selections of poetry, picture books, fantasy, historical fiction, and realist novels for younger and older readers, taking into consideration changes in the perceptions and the construction of childhood and gender roles. May be taken for Women''s and Gender Studies credit. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8504', 'ENGL-3953', 'VisualVerbal Meaning Making', 'An exploration of primarily twentieth and twenty-first century picturebooks, comics, and other visualverbal texts, for specific ages and/or crossovers, with particular attention to the relationships between words, images, and design, and to cultural and publishing contexts, and so to considerations of multimodal media and its audiences. Prerequisites: ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8505', 'ENGL-3973', 'Children''s Literature 1', 'An introduction to the variety of periods and genres in children''s literature ranging from the first Golden Age to the present with selections from younger and older readers, including poetry, picture books, fantasy historical fiction, and realist novels, taking into consideration changes in the perceptions and the construction of childhood and gender roles. May be taken for Women''s and Gender Studies credit. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8507', 'ENGL-3983', 'Children''s Literature 2', 'An introduction to the body of folk and fairy tales that are the foundation for much of children''s literature, covering their development from oral into written and illustrated versions, exploring a variety of the adaptations and reworkings over their history to the present day, and taking into consideration changes in the perceptions and the construction of childhood and gender roles. May be taken for Women''s and Gender Studies credit. Prerequisite(s): ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","or","ENGL-1406;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
