INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8652', 'EVAN-7013', 'Praxis', 'An international short-term mission and study experience sponsored by Canadian Baptist Ministries (CBM) under the supervision of CBM Global Field Staff. Students will explore the application of Integral Mission theology and theory in a developing country. Offered in partnership with CBM. Limited seats. Competitive application process. Recommended prior study: EVAN 5033 or EVAN 5043.', 'EVAN', 3, 0, 7, '[{"codes":["EVAN-5033","or","EVAN-5043"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8653', 'EVAN-7133', 'Apologetic Engagement Contemp', 'This course will orient students to the field of Christian apologetics in contemporary context and equip them to engage faith and culture for ministry. We will examine the rationale for apologetics and its place in contemporary society, identify and explore cultural shifts that need to be addressed by the church, explore the nature of worldview and the philosophical viability of faith, and consider some major issues in apologetics today. Special topics include the existence of God, the problem of pain, the authority of the Bible, the supremacy of Christ, creation-evolution and other religions, while considering how Christians express their faith in contemporary context. Cross-listed as THEO 7133.', 'EVAN', 3, 0, 7, '[]');
