INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8733', 'FRAN-1013', 'Beginning French 1', 'This course is intended for students whose first language is neither English nor French and whose second language is not French. All other students must obtain permission from the Department in order to register. This course introduces basic grammar and vocabulary. Emphasis is placed on written and oral communication. Students who have completed FRAN 1013 and 1023 may continue in FRAN 1113 and 1123.', 'FRAN', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8734', 'FRAN-1023', 'Beginning French 2', 'This course is intended for students whose first language is neither English nor French and whose second language is not French. All other students must obtain permission from the Department in order to register. This course introduces basic grammar and vocabulary. Emphasis is placed on written and oral communication. Students who have completed FRAN 1013 and 1023 may continue in FRAN 1113 and 1123. Prerequisite(s): FRAN 1013. Note: Students who enroll in FRAN 1023 may not enroll simultaneously or subsequently in FRAN 1013.', 'FRAN', 3, 0, 1, '[{"codes":["FRAN-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8735', 'FRAN-1113', 'Basic French 1', 'FRAN 1113 introduces basic French grammar and communication. It is intended for students who are false beginners, students who studied Core French for several years, or students who studied French years ago, but who have not proceeded beyond the level of Grade 9/10 Core French. Students with more than Grade 9/10 Core French cannot register in this class without permission. Prerequisite(s): Placement test or permission. Note: Students who enroll in FRAN 1113 may not enroll simultaneously or subsequently in  FRAN 1013 or FRAN 1023.', 'FRAN', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8736', 'FRAN-1123', 'Basic French 2', 'FRAN 1123 is a continuation of the introduction to basic French grammar and communication begun in FRAN 1113. It is intended for students who are false beginners, students who have studied Core French for several years, or students who studied French years ago, but who have not proceeded beyond the level of Grade 9 or 10 Core French. Note: Students who enroll in FRAN 1123 may not enroll simultaneously or subsequently in FRAN 1113, FRAN 1013, or FRAN 1023.', 'FRAN', 3, 0, 1, '[{"codes":["FRAN-1113","or","placement","test","or","permission."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8737', 'FRAN-1213', 'Intermediate French 1', 'FRAN 1213 is a review of intermediate French grammar. While effective communication, both oral and written, is stressed, students will be assessed primarly on their written expression. It is recommended that it be taken at the same time as FRAN 2153. Antirequisite(s): FRAN 1613, FRAN 1623. Note: Students who enroll in FRAN 1213 may not enroll simultaneously or subsequently in FRAN 1013, FRAN 1023, FRAN 1113, or FRAN 1123.', 'FRAN', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8738', 'FRAN-1223', 'Intermediate French 2', 'FRAN 1223 is a continuation of the review of intermediate French grammar begun in FRAN 1213. While effective communication, both oral and written, is stressed, students will be assessed primarly on their written expression. It is recommended that it be taken at the same time as FRAN 2163. Antirequisite(s): FRAN 1613, FRAN 1623. Note: Students who enroll in FRAN 1223 may not enroll simultaneously or subsequently in FRAN 1213, FRAN 1113, FRAN 1123, FRAN 1013, or FRAN 1023.', 'FRAN', 3, 0, 1, '[{"codes":["FRAN-1213","or","placement","test","or","permission."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8739', 'FRAN-1613', 'French for Immersion Students', 'FRAN 1613 is a review of intermediate French grammar. It is designed to enable Immersion students to build on their strengths while becoming aware of and remedying ingrained errors. Selected texts will be analyzed in order to apply the grammatical structures studied and to enrich vocabulary. It is recommended that it be taken at the same time as FRAN 2153. Prerequisite(s): Placement test or permission. Antirequisite(s): FRAN 1213, 1223. Note: Students who enroll in FRAN 1613 may not enroll simultaneously or subsequently in FRAN 1013, FRAN 1023, FRAN 1113, or FRAN 1123.', 'FRAN', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8740', 'FRAN-1623', 'French for Immersion Students2', 'FRAN 1623 is a continuation of the review of intermediate French grammar begun in FRAN 1613. The purpose of the course is to enable Immersion students to build on their strengths while becoming aware of and remedying ingrained errors. Selected texts will be analyzed to apply the grammatical structures and to enrich vocabulary.  It is recommended that it be taken at the same time as FRAN 2163. Prerequisite(s): FRAN 1613 or placement test or permission. Antirequisite(s): FRAN 1213, FRAN 1223. Note: Students who enroll in FRAN 1623 may not enroll simultaneously or subsequently in FRAN 1613, FRAN 1113, FRAN 1123, FRAN 1013, or FRAN 1023.', 'FRAN', 3, 0, 1, '[{"codes":["FRAN-1613","or","placement","test","or","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8741', 'FRAN-2003', 'Français, affaires', 'Exploration du français des affaires et de l''importance économique et commerciale des régions de langue française dans le monde contemporain. Ce cours allie l''apprentissage du français spécialisé pour le milieu des affaires (commerce, finance, fiscalité, administration) à une découverte interactive de la francophonie en Europe, en Amérique du Nord et en Afrique. Cours recommandé particulièrement pour les étudiants en administration et en commerce, ou pour les futurs entrepreneurs indépendants dans le contexte canadien. Préalable normal: FRAN 1223, FRAN 1623 ou un équivalent.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-1223","or","FRAN-1623"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8742', 'FRAN-2013', 'Français Avancé, Niveau 1', 'Étude systématique de la syntaxe du français écrit, lecture et analyse de textes, et une initiation à la traduction de l''anglais au français qui permettront à l''étudiant de mieux maîtriser des outils de communication pouvant se révéler utiles dans de nombreuses circonstances de la vie professionnelle. Préalable normal: FRAN 1223 ou FRAN 1623, de préférence avec une moyenne minimale de B, ou test de placement ou permission. Note: Students who enroll in FRAN 2013 may not enroll simultaneously or subsequently in FRAN 1613/1623, FRAN 1213/1223, FRAN 1113/1123, or FRAN 1013/1023.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-1223","or","FRAN-1623","preferably","with","a","grade","of","B-,","or","placement","test","or","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8743', 'FRAN-2023', 'Français avancé, niveau 2', 'Étude systématique de la syntaxe du français écrit, lecture et analyse de textes, et une initiation à la traduction de l''anglais au français qui permettront à l''étudiant de mieux maîtriser des outils de communication pouvant se révéler utiles dans de nombreuses circonstances de la vie professionnelle. Préalable normal: FRAN 2013 ou test de placement ou permission. Veuillez noter que les étudiants qui s''incrivent dans FRAN 2023 ne peuvent pas s''inscrire simultanément ou ultérieurement dans FRAN 1613/1623, FRAN 1213/1223, FRAN 1113/1123, FRAN 1013/1023.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-2013","or","placement","test","or","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8744', 'FRAN-2033', 'Le Français de la Santé', 'Ce cours s''adresse aux professionnels futurs ou actuels dans le domaine de la santé qui désirent améliorer leurs compétences orales et interpersonnelles et développer leur vocabulaire médical. Préalable normal: FRAN 1223, FRAN 1623 ou équivalent avec une note minimale de B-. Veuillez noter que les étudiants qui s''incrivent dans FRAN 2033 ne peuvent pas s''inscrire simultanément ou ultérieurement dans FRAN 1613/1623, FRAN 1213/1223, FRAN 1113/1123, FRAN 1013/1023.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN","1223,","1623","ou","équivalent","avec","une","note","minimale","de","B-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8745', 'FRAN-2113', 'Panorama litt franc 1', 'À travers les textes littéraires, c''est l''évolution de la culture et de la société qui devient évidente. Lire, c''est aussi améliorer sa compréhension de la richesse et de la diversité linguistique des époques passées. Un choix de textes permettra de se familiariser avec l''évolution de la France entre les premiers textes en français et l''époque de la Révolution de 1789. Veuillez noter que les étudiants qui s''incrivent dans FRAN 2113 ne peuvent pas s''inscrire simultanément ou ultérieurement dans FRAN 1613/1623, FRAN 1213/1223, FRAN 1113/1123, FRAN 1013/1023.', 'FRAN', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8746', 'FRAN-2123', 'Panorama litt franc 2', 'Au 19ème et au 20ème siècles, la littérature française joue un rôle important dans l''ensemble de la culture mondiale, par son prestige, son originalité et son influence. Un choix de textes majeurs permettra de comprendre l''évolution des différents genres littéraires du premier romantisme jusqu''à l''ère de la déconstruction et de la littérature commerciale de masse. Veuillez noter que les étudiants qui s''incrivent dans FRAN 2123 ne peuvent pas s''inscrire simultanément ou ultérieurement dans FRAN 1613/1623, FRAN 1213/1223, FRAN 1113/1123, FRAN 1013/1023.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-2113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8747', 'FRAN-2153', 'Expr orale 1', 'Apprentissage de stratégies de communication et de structures langagières qui permettront à l''étudiant d''être à l''aise dans des situations de communication courantes. Jeux, présentations orales, discussions, débats sur des sujets variés seront utilisés avec des documents authentiques, articles de magazine, émissions de radio et de télévision, films et chansons. Il est recommandé que ce cours soit suivi en combinaison avec FRAN 1213 ou FRAN 1613. Les étudiants qui auront déjà obtenu un crédit en FRAN 2013/FRAN 2023 ne seront pas admis à ce cours. Les étudiants qui s''inscrivent en FRAN 2153 ne peuvent pas s''inscrire simultanément ou ultérieurement en FRAN 1113, FRAN 1123, FRAN 1013, ou FRAN 1023.', 'FRAN', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8748', 'FRAN-2163', 'Expr orale 2', 'Poursuite du travail entrepris en FRAN 2153. Il est recommandé que ce cours soit suivi en combinaison avec FRAN 1223 ou FRAN 1623. Les étudiants qui auront déjà obtenu un crédit en FRAN 2013/FRAN 2023 ne seront pas admis à ce cours. Les étudiants qui s''inscrivent dans FRAN 2163 ne peuvent pas s''inscrire simultanément ou ultérieurement dans FRAN 2153, FRAN 1113, 1123, 1013 ou 1023.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-2153"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8749', 'FRAN-2713', 'Compréh et expr écrites', 'Apprentissage progressif du français écrit: lire et écrire d''une façon plus efficace. L''accent sera mis sur l''acquisition d''un vocabulaire plus riche, la maîtrise de structures utiles pour l''expression écrite et les techniques de l''autocorrection. Les lectures seront tirées de documents médiatiques récents. L''étude de la grammaire en soi joue un rôle mineur dans ce cours. Il est donc fortement recommendé de suivre en même temps FRAN 2013/FRAN 2023. Les spécialistes de français doivent suivre ce cours ou bien le FRAN 3733. Les étudiants qui s''inscrivent en FRAN 2713 ne peuvent pas s''inscrire simulanément ou ultérieurement dans FRAN 1113/1123, FRAN 1013 ou 1023. Préalable normal: FRAN 1223 ou FRAN 1623.', 'FRAN', 3, 0, 2, '[{"codes":["FRAN-1223","or","FRAN-1623"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8750', 'FRAN-3013', 'Langue fran. et analyse ling', 'S''appuyant sur une terminologie linguistique en français, on analysera à partir d''exemples concrets le fonctionnement de la langue française dans son état actuel, son évolution historique et sa diversité géographique. Initiation à la phonétique et à la phonologie, à l''analyse morphologique, syntaxique, ainsi qu''aux bases de la lexicologie, de la sémantique et de la sémiotique.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2013,","FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8751', 'FRAN-3023', 'Bases de traduction générale', 'Renforcement des capacités écrites de communication. D''une part, on révisera des structures syntaxiques avancées en français et en anglais, de façon parallèle; d''autre part, on travaillera intensivement (avec un système de double correction) des traductions de textes A-F (70%) et F-A (30%) dans tous les domaines - d''articles de journaux aux brochures touristiques - et à divers niveaux de langue.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2013,","FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8752', 'FRAN-3133', 'Littérature française moderne', 'Lecture et analyse d''oeuvres choisies des romanciers, dramaturges et poètes les plus représentatifs du 20ème siècle. on mettra l''accent chaque année sur un genre spécifique, selon les désirs du professeur et des étudiants: roman, théâtre, poésie ou chanson.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8753', 'FRAN-3153', 'Expr orale avancée, niveau 3', 'Les étudiants apprendront un vocabulaire et des expressions se rapportant à des thèmes tirés de leur vécu. Des débats, discussions et présentations orales leur permettront de mettre ce savoir en pratique. L''improvisation y jouera aussi un rôle important. Des bulletins de nouvelles et des chansons serviront d''exercices de compréhension orale.', 'FRAN', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8754', 'FRAN-3163', 'Expr orale avancée, niveau 4', 'Poursuite du travail entrepris en FRAN 3153.', 'FRAN', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8755', 'FRAN-3203', 'Voix de femmes', 'Ce cours cherche à mettre en valeur la richesse et la diversité des ouvres de femmes écrivains de langue française. À travers un choix d''ouvres de différents siècles, on examinera, entre autres problématiques, la venue de la femme à l''écriture, l''inscription de l''expérience féminine dans les textes et la mise en question de présupposés politiques, sociaux et esthétiques courants.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8756', 'FRAN-3213', 'Littérature jeunesse', 'Étude des formes littéraires, passées et présentes, qui visent surtout les enfants de 2 à 12 ans: contes populaires, comptines, chansons, albums pour enfants, histoires pour jeunes, bandes dessinées, pages internet.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8757', 'FRAN-3323', 'La lit migrante au Québec', 'Exploration d''un phénomène nouveau et important dans la littérature québécoise contemporaine: la publication d''ouvres écrites en français, au Québec, par des auteurs venus de pays divers comme le Brésil, l''Égypte, la Chine, l''Italie, Haïti. on abordera des thèmes reliés à l''enfance, au souvenir, à l''exil forcé ou volontaire, à l''adaptation à une nouvelle société et aux différences culturelles.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8760', 'FRAN-3443', 'Panorma des litt francophones', 'Ce cours étudie les principaux mouvements de migration, de déportation et d''exil qui ont créé une FRANcophonie en Amérique. Des auteurs de la Martinique, de la Guadeloupe, d''Haïti, de l''Acadie, de la Louisiane, de l''Ontario et du Manitoba seront étudiés. Prérequis: FRAN 2113/FRAN 2123 ou avec la permission du département.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8761', 'FRAN-3513', 'L''Acadie d''aujourd''hui', 'Exploration de la culture acadienne des provinces maritimes du Canada, mais aussi de la Louisiane, de la Nouvelle-Angleterre, du Québec, du Canada francophone et de la France. À l''aide de documents authentiques (chansons, films, articles de journaux, émissions de radio et de télévision, textes, sites Internet), nous aborderons les différents aspects de la réalité de l''Acadie et des Acadiens.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8762', 'FRAN-3523', 'Litt acadienne', 'Depuis les années 1950, une littérature extrêmement riche affirme l''importance de l''espace imaginaire acadien dans la francophonie. Cet espace imaginaire remonte au 16ème siècle; on peut en suivre les traces écrites et orales. Avec Antonine Maillet et 25 ans d''édition en Acadie, une littérature moderne s''affirme, tout en redécouvrant la richesse de son passé, dans toutes les régions de l''Acadie, ce «pays imaginaire».', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8763', 'FRAN-3633', 'Le Québec moderne', 'Le cours a pour but l''exploration de la spécificité socioculturelle du Québec. À l''aide de documents authentiques (chansons, films, articles de journaux, émissions de radio et de télévision), nous aborderons les aspects suivants de la réalité québécoise: la géographie, l''histoire, la langue, la religion, la famille, l''éducation et les arts.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8764', 'FRAN-3643', 'Panorama litt Québecoise', 'Les grandes étapes du développement d''une littérature originale française en terre d''Amérique, des récits de voyage d''explorateurs et de missionnaires de la Nouvelle-France au roman moderne, en passant par la poésie des 19ème et 20ème siècles et le roman de la terre. L''accent sera mis sur les genres narratifs - roman et nouvelle - leur évolution formelle et thématique, et les idéologies dominantes qui s''inscrivent dans les ouvres littéraires à une époque donnée.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8765', 'FRAN-3703', 'La France contemporaine', 'Exploration au moyen - entre autres - de films, de textes, de sites internet, des traits principaux qui caractérisent la France et les Français d''aujourd''hui.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8766', 'FRAN-3733', 'Expression écrite avancée', 'Cours destiné à ceux et à celles qui ont réussi le FRAN 2013/FRAN 2023 (ou sont en train de le suivre) et veulent continuer à développer leurs compétences dans les domaines de la lecture en français et du français écrit. Des exercices de compréhension, de contraction de texte et de rédaction, enrichis de l''analyse de textes modèles, initieront les étudiants à une variété de genres et de styles.', 'FRAN', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8767', 'FRAN-3743', 'Compréhension écrite avancée', 'Ce cours vise les étudiants qui maîtrisent bien la grammaire fondamentale du français et cherchent à consolider leurs compétences en abordant des sujets plus complexes. L''étude des structures sera renforcée par la lecture d''une variété de textes permettant d''acquérir de meilleures connaissances des cultures francophones, tout en développant le vocabulaire et la maîtrise d''expressions idiomatiques. Préalable: FRAN 2023.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8768', 'FRAN-4003', 'Sociolinguistique', 'Ce cours vise à faire prendre conscience aux étudiants des politiques linguistiques qui existent à travers le monde. Les étudiants compareront les efforts faits par les gouvernements de plusieurs pays pour protéger leurs minorités linguistiques. Le Canada et ses minorités francophones feront l''objet d''une attention particulière. on fera appel régulièrement à des enregistrements audio et vidéo.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8771', 'FRAN-4203', 'Traduction générale', 'Ce cours aborde certains problèmes fréquents de la traduction de l''anglais vers le français. Des exercices porteront sur les difficultés lexicales, grammaticales et syntaxiques. D''autres exercices pratiques de traduction de courts textes de types divers seront proposés à partir d''une réflexion sur l''éthique et la profession des traducteurs et traductrices.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8772', 'FRAN-4403', 'Enseignement du français', 'Les étudiants se familiariseront avec les méthodes actuelles d''enseignement du français langue seconde. Le curriculum multidimensionnel y sera expliqué. Les implications pédagogiques en seront dégagées. Des plans de leçon permettront de mettre en pratique ces connaissances méthodologiques.', 'FRAN', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8773', 'FRAN-4413', 'Lectures dirigées 1', 'Ce cours permet aux enseignants et aux étudiants d''aborder des sujets spécifiques qui ne feraient pas l''objet d''un cours déjà existant, y compris la possibilité d''un cours en création littéraire. Les sujets et le cadre en sont déterminés par accord entre le département, l''enseignant et les étudiants concernés.', 'FRAN', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8774', 'FRAN-4423', 'Lectures dirigées 2', 'Ce cours est le complément du cours FRAN 4413, le cas échéant.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-4413"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8776', 'FRAN-4553', 'Littérature francophone', 'Ce cours analyse certains textes de la FRANcophonie incluant les auteurs africains et antillais. Certains concepts du post colonialisme sont aussi analysés à travers les théories de Jean-Paul Sartre, d''André Breton. Ces textes faciliteront la compréhension des mouvements des indépendances et des autonomies en Afrique et dans les Antilles. Prérequis: FRAN 2113/FRAN 2123 ou équivalent ou avec la permission du département.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8777', 'FRAN-4613', 'Litt Québecoise contemp', 'La nouvelle, le théâtre, la poésie et la chanson sont de plus en plus populaires au Québec. Comment les analyser sinon en examinant les caractéristiques propres de chacun? Ce cours propose donc l''étude de la spécificité du texte dramatique, du langage poétique et de l''oralité ainsi que l''explication de textes représentatifs de ces genres dits brefs.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8778', 'FRAN-4713', 'Le théâtre classique', 'Le 17ème siècle constitue le premier âge d''or du théâtre français. Les auteurs y posent les bases d''une dramaturgie qui hantera la création théâtrale en France pendant trois siècles: grandes passions entrant en conflit avec les valeurs morales et sociales acceptées, folies de l''être humain livré à ses obsessions: Corneille, Racine ou Molière nous font toujours réfléchir aux mouvements de l''âme humaine.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8780', 'FRAN-4823', 'La liberté', 'Ce thème révolutionnaire par excellence sera étudié dans l''oeuvre de philosophes et romanciers tels que Rousseau ou Diderot, de romanciers tels que l''abbé Prévost, et d''auteurs de théâtre tels que Beaumarchais. on se concentrera particulièrement sur les auteurs du «siècle des lumières».', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8781', 'FRAN-4833', 'Le roman au 18e siècle', 'En France, le dix-huitième siècle est une époque importante pour l''évolution du roman, un genre qui est encore à ses débuts. Romans épistolaires, récits à la première personne, narrations encadrées, romans expérimentaux, les formes foisonnent on étudiera. Nous étudierons un choix d''ouvrages qui permettront de suivre les transformations que cette forme encore jeune est en train de subir.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8782', 'FRAN-4913', 'Le roman au 19e siècle', 'Étude de romans représentatifs des principaux mouvements littéraires du dix-neuvième siècle: le romantisme, le ré alisme et le naturalisme.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8783', 'FRAN-4923', 'Poésie théâtre 19e siècle', 'Étude de poèmes et pièces de théâtre représentatifs des principaux mouvements et genres littéraires du dix-neuvième siècle.', 'FRAN', 3, 0, 4, '[{"codes":["FRAN-2113,","FRAN-2123"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8899', 'GEOL-1010L', 'GEOL 1013 Laboratory', '', 'GEOL', 0, 1, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8900', 'GEOL-1013', 'Our Dynamic Earth', 'An introduction to the Earth; its composition, internal structure, external features, and physical evolution. The concepts of sea-floor spreading and plate tectonics provide a framework for the origin and development of continents, oceans, mountains and volcanoes, and lead to an appreciation of an evolving, dynamic Earth. Field trips required. (3h lab).', 'GEOL', 3, 0, 1, '[{"codes":["GEOL-1010L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8901', 'GEOL-1020L', 'GEOL 1023 Laboratory', '', 'GEOL', 0, 1, 1, '[{"codes":["GEOL-1023"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8902', 'GEOL-1023', 'Earth Hist: Global Change', 'Changes in the Earth''s continents, oceans, biosphere, and atmosphere over the past 4.6 billion years. The application of understanding of the past as a key to future global changes. Other topics include mass extinctions, plate tectonics, paleomagnetism, geologic dating, mountain-building and mineral resources. (3h lab). Prerequisite(s): GEOL 1013, or equivalent with a minimum grade of C-.', 'GEOL', 3, 0, 1, '[{"codes":["GEOL-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-1020L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8903', 'GEOL-1033', 'General Oceanography', 'Offshore and deep-water oceanography, emphasizing an interdisciplinary approach and including geological, biological, physical and chemical aspects. History of oceanography; exploration techniques, instruments and vessels; origin of oceans and ocean basins; physiography of the ocean basins; deep-sea sediments; continental drift, sea-floor spreading and plate tectonics; marine volcanism; waves, tides and ocean currents; climatology and sea- level changes; marine ecology; marine resources.', 'GEOL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8911', 'GEOL-1073', 'Natural Disasters', 'Natural disasters, their causes and effects and the science that underlies decision-making, prediction, and remediation. Topics include volcanoes, earthquakes, tsunamis, rivers and flooding, mass wasting and erosion, subsidence, coastal hazards, severe weather, climate change, impacts and extinctions.', 'GEOL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8921', 'GEOL-2040L', 'GEOL 2043 Laboratory', '', 'GEOL', 0, 1, 2, '[{"codes":["GEOL-2043"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8922', 'GEOL-2043', 'Tech: Petrology & Stratigraphy', 'Origin, occurrence, composition, and classification of igneous, sedimentary, and metamorphic rocks. An integrated overview of petrogenetic processes in a plate tectonic framework, including magma genesis, clastic and carbonate depositional processes, stratigraphic principles, and metamorphic zones and facies. Laboratory study of rocks in hand sample and thin section. (3h lab). Prerequisite(s): GEOL 2133 with a minimum grade of C-; Prerequisite or Corequisite(s): GEOL 1023 with a minimum grade of C-.', 'GEOL', 3, 0, 2, '[{"codes":["GEOL-2133","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-1023","with","minimum","grade","C-","required"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["GEOL-2040L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8924', 'GEOL-2083', 'Field Methods', 'Held each spring for twelve days, focusing on field work and processing of field data to familiarize students with techniques of geological mapping. Involves electronic and manual measurement of field data including use of GPS instruments and laptop computers and subsequent preparation of maps, sedimentary sections, and cross-sections in paper and digital form.', 'GEOL', 3, 0, 2, '[{"codes":["GEOL-2043","with","a","minimum","grade","C-","or","permission","of","the","department."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8929', 'GEOL-2130L', 'GEOL 2133 Laboratory', '', 'GEOL', 0, 1, 2, '[{"codes":["GEOL-2133"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8930', 'GEOL-2133', 'Mineralogy', 'Crystal symmetry and structure. Mineral chemistry, physical properties, associations, and uses. Identification of common minerals in hand sample. X-ray diffraction, transmitted light optical theory, and introduction to the petrographic microscope. (3h lab). Prerequisite(s): GEOL 1013 with a minimum grade of C- (corequisite with Departmental permission). Corequisite(s): CHEM 1013.', 'GEOL', 3, 0, 2, '[{"codes":["GEOL-1013","with","minimum","grade","C-","required","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-1013"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["GEOL-2130L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8931', 'GEOL-2210L', 'GEOL 2213 Laboratory', '', 'GEOL', 0, 1, 2, '[{"codes":["GEOL-2213"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8932', 'GEOL-2213', 'History of Life', 'The morphology, classification and evolution of the major groups of animals and plants in the fossil record. Emphasis will be on invertebrate paleontology, but attention will be given to the origin of life, Precambrian fossils, trace fossils, micro-fossils, fossil algae, vascular plants, lower vertebrates, dinosaurs and man. Laboratory work will include a systematic survey of the major groups of organisms having a fossil record. (3h lab). Prerequisite(s): BIOL 1123 or GEOL 1023 with minimum grades of C-.', 'GEOL', 3, 0, 2, '[{"codes":["BIOL-1123","or","GEOL-1023","with","minimum","grades","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-2210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8939', 'GEOL-2700L', 'GEOL 2703 Laboratory', '', 'GEOL', 0, 1, 2, '[{"codes":["GEOL-2703"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8940', 'GEOL-2703', 'Applied Geomorphology', 'Basic concepts in geomorphology including fluvial systems, continental glaciation, coastal processes, mass wasting, soil development, strength of materials, weathering, periglacial geomorphology, and airphoto interpretation. Emphasis will be on the environmental application of these concepts. Laboratory work will concentrate on airphoto interpretation and mini-projects related to some of these themes. (3h lab). Prerequisite(s): GEOL 1013 with a minimum grade of C-.', 'GEOL', 3, 0, 2, '[{"codes":["GEOL-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-2700L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8945', 'GEOL-2750L', 'GEOL 2753 Laboratory', '', 'GEOL', 0, 1, 2, '[{"codes":["GEOL-2753"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8946', 'GEOL-2753', 'Atmosphere/Weather/Climate', 'The composition, structure, and dynamics of the atmosphere; weather, climate, and biogeographic patterns; microclimatology; paleoclimates, paleogeography, and extinctions; human effect on air quality; climate change. (3h lab). Prerequisite(s): Second-year standing.', 'GEOL', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["","GEOL-2750L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8949', 'GEOL-3100L', 'GEOL 3103 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3103"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8950', 'GEOL-3103', 'Introduction to Geochemistry', 'Investigation of chemical principles involved in geologic processes, emphasizing those acting on the surface and in near-surface environments. Topics include weathering, mineral exploration and environmental geochemistry applications. May be offered in alternate years. (3h lab). Prerequisite(s): GEOL 2133 with a minimum grade of C-; Prerequisite or Corequisite(s): CHEM 1023.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2133","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-1023"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["GEOL-3100L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8953', 'GEOL-3300L', 'GEOL 3303 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3303"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8954', 'GEOL-3303', 'Sedimentary Geology', 'Study of clastic, chemical and biogenic sedimentation and diagenetic processes, sedimentary environments and facies and reservoir development. Field and laboratory techniques for the analysis, interpretation and classification of sediment and sedimentary rock textures, compositions and structures. (3h lab). Prerequisite(s): GEOL 2043 with a minimum grade of C-.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2043","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-3300L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8959', 'GEOL-3400L', 'GEOL 3403 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3403"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8960', 'GEOL-3403', 'Igneous Petrology', 'The origin of magmas, their evolution, and crystallization. Igneous provinces and the relation between igneous activity and tectonics. Patterns of igneous activity through geological time. Laboratory studies of classical and local igneous rock suites. (3h lab). Prerequisite(s): GEOL 2043 with a minimum grade of C-.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2043","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-3400L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8961', 'GEOL-3500L', 'GEOL 3503 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3503"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8962', 'GEOL-3503', 'Metamorphic Geology', 'The mineralogical, textural, and structural characteristics of metamorphic rocks and the development of metamorphic facies. Contact and regional metamorphism, metasomatism, and anatexis are considered in detail. Current ideas relating metamorphism and tectonic setting provide the framework. Laboratory studies of classical and local metamorphic rock suites. (3h lab). Prerequisite(s): GEOL 2043, GEOL 3603 with minimum grades of C-; GEOL 3403 recommended.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2043","and","GEOL-3603","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-3403","recommended"],"textExtension":"- Recommended prior to taking this course, but is not required."},{"codes":["GEOL-3500L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8965', 'GEOL-3600L', 'GEOL 3603 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3603"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8966', 'GEOL-3603', 'Structural Geology & Tectonics', 'Rock structures and their geometric representation. Principles of stress and strain applied to brittle and ductile rock deformation. Fractures, faults, folds, and foliations: classification and mechanisms of formation. Plate boundary and intraplate tectonics. Practical work includes map interpretation, graphic and computer techniques for analyzing structural data, and field studies of deformed rocks. (3h lab). Prerequisite(s): GEOL 2043 with a minimum grade of C-.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2043","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-3600L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8971', 'GEOL-3720L', 'GEOL 3723 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3723"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8972', 'GEOL-3723', 'Hydrogeology', 'Groundwater as part of the hydrologic cycle. Physical aspects of water movement in geologic materials - both saturated and unsaturated. Groundwater resource mapping and exploitation. Groundwater chemistry and biology: drinking water quality, contamination and associated health concerns. Exposure to laboratory and field techniques for groundwater monitoring. Field trips may be required. (3h lab). Prerequisite(s): GEOL 2703 with a minimum grade of C-.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2703","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-3720L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8974', 'GEOL-3733', 'Sat. Remote Sens Image Analy.', 'An introduction to the principles, practices and applications of satellite remote sensing. Electromagnetic spectra, satellite platforms, image enhancement, image classification and interpretation. Environmental and resource applications will be discussed. Laboratory work focuses on using image analysis programs to analyze satellite imagery. (3h lab). Prerequisite(s): GEOL 2703 or BIOL 2033, with a minimum grade of C-, and permission of the instructor.', 'GEOL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8977', 'GEOL-3820L', 'GEOL 3823 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3823"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8978', 'GEOL-3823', 'Exploration/Enviro Geophysics', 'Principles and applications of geophysical methods used by the exploration and environmental geologist, including seismic, magnetic, gravimetric, electromagnetic, electric, and radiometric methods. May be offered in alternate years.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-2043","with","minimum","grade","C-",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8987', 'GEOL-4010L', 'GEOL 4013 Laboratory', '', 'GEOL', 0, 1, 4, '[{"codes":["GEOL-4013"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8988', 'GEOL-4013', 'Global/North American Geol', 'Global tectonics, processes at convergent plate margins, worldwide Phanerozoic orogenic belts and Precambrian tectonics. An integrative study of the geological evolution of North America, including stratigraphy, structural development, and Quaternary history but with an emphasis on comparative tectonic evolution of the Cordilleran, Appalachian, and Precambrian orogenic belts. Laboratory work includes map interpretation and petrological studies of rock suites (3h lab). Prerequisite(s): GEOL 3603 with a minimum grade of C-.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-3603;","MIN","GRADE","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-4010L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8989', 'GEOL-4083', 'Senior Field School', 'Advanced field methods of geological mapping and preparation of maps and reports. Includes 8 days preceding the Fall term and continues into the term.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-2083","and","GEOL-3603","both","with","a","minimum","grade","of","C-,","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('8992', 'GEOL-4303', 'Carbonate Sediment. Field Sch', 'This course focuses on the sedimentology, oceanography, and diagenesis of carbonate sediments and rocks of Bermuda. Investigation of Nova Scotia limestones introduces key concepts. Lectures and field exercises focus on carbonate depositional environments and the development of groundwater and hydrocarbon reservoirs in limestone. Assignments use sedimentologic, ecologic, and chemical techniques to understand the deposition of carbonate facies. Prerequisite GEOL 3323 or permission of the instructor.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-3323","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9000', 'GEOL-4713', 'Glacial Geology', 'A treatment of specific topics in glacial geoscience with particular emphasis on environmental change during the Quaternary time period.  Topics covered will include glaciations, glacial landscapes, glacial hazards, paleoclimate, Quaternary dating techniques, human activity and exploration in glaciated terrain. Prerequisite: Permission of the instructor.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-2703"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9001', 'GEOL-4800L', 'GEOL 4803 Laboratory', '', 'GEOL', 0, 1, 4, '[{"codes":["GEOL-4803"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9002', 'GEOL-4803', 'Mineral Deposits', 'The nature, occurrence and origin of mineral deposits, with emphasis on metallic deposits. (3h lab). Prerequisite(s): GEOL 3403, GEOL 3603, both with a minimum grade of C-.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-3403","and","GEOL-3603","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-4800L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9003', 'GEOL-4810L', 'GEOL 4813 Laboratory', '', 'GEOL', 0, 1, 4, '[{"codes":["GEOL-4813"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9004', 'GEOL-4813', 'Mineral Exploration', 'Introduction to mineral exploration techniques, economic deposit .evaluation strategies, and mining and processing methods. Offered only when the corresponding graduate course GEOL 5883 is taught. (3h lab). Prerequisite(s): GEOL 4803 with a minimum grade of C-.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-4803;","MIN","GRADE","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GEOL-4810L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9007', 'GEOL-4833', 'Exploration & Envir Geochem.', 'Geochemical principles and techniques applied in mineral exploration and environmental geochemistry. Includes theory of dispersion, natural precipitation barriers, solubility, sorption and the design and execution of geochemical surveys, analysis of samples, and interpretation of results. Offered only when the corresponding graduate course (GEOL 5833) is taught. Prerequisite(s): GEOL 3103, GEOL 4803, or CHEM 2853, with a minimum grade of C-, or permission of the instructor.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-3103","or","GEOL-4803","or","CHEM-2853;","MIN","GRADE","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9008', 'GEOL-3840L', 'Geol 3843 Laboratory', '', 'GEOL', 0, 1, 3, '[{"codes":["GEOL-3843"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9009', 'GEOL-3843', 'Energy Resources', 'Overview of nonrenewable and renewable sources of energy associated with earth processes and materials, including carbon-based, geothermal, nuclear, tidal, solar, wind, and hydroelectric energy sources, generation, transmission, and storage. Topics also include processes and environments of formation of the required materials, exploration for, production of, and temporal supply and demand for these resources.', 'GEOL', 3, 0, 3, '[{"codes":["GEOL-1013","and","GEOL-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9010', 'GEOL-4853', 'Geochemical Material Transfer', 'Introduction to the theory of material transfer and its use in interpreting geochemical and mineralogical controls on rock composition and formation, including water-rock and melt-crystal reactions and physical grain fractionation. Interpretation of results using petrologic hypothesis testing and error propagation. Corequisite(s): GEOL 3403 or GEOL 3503. Offered only when the corresponding graduate course (GEOL 5823) is taught.', 'GEOL', 3, 0, 4, '[{"codes":["GEOL-3403","or","GEOL-3503"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9011', 'GEOL-4913', 'Special Projects 1', 'Guided study in an area of particular interest under the direction of a staff member. Such work may be based on lecture, field, laboratory or library study, or all four, focusing on aspects of earth science not normally covered in the scheduled course offerings. The student may have responsibility in programming the research in addition to its conduct. Prerequisite(s): Permission of the Department.', 'GEOL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9012', 'GEOL-4923', 'Special Projects 2', 'Guided study in an area of particular interest under the direction of a staff member. Such work may be based on lecture, field, laboratory or library study, or all four, focusing on aspects of earth science not normally covered in the scheduled course offerings. The student may have responsibility in programming the research in addition to its conduct. Prerequisite(s): Permission of the Department.', 'GEOL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9013', 'GEOL-4933', 'Special Projects 3', 'Guided study in an area of particular interest under the direction of a staff member. Such work may be based on lecture, field, laboratory or library study, or all four, focusing on aspects of earth science not normally covered in the scheduled course offerings. The student may have responsibility in programming the research in addition to its conduct. Prerequisite(s): Permission of the Department.', 'GEOL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9017', 'GEOL-5013', 'Appalachian Geology', 'An overview of the geology and tectonic evolution of the Appalachian mountain belt. Emphasis is on Atlantic Canada; however, the entire orogen is covered, and comparison is made with correlative mountain systems in Europe and elsewhere.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9024', 'GEOL-5226', 'Paleoecology', 'Principles of paleoecology and the application of these to actual field problems.', 'GEOL', 6, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9025', 'GEOL-5303', 'Adv Topics in Sedimentology', 'Advanced studies in sedimentology. Topics may include: carbonate sedimentology and diagenesis, phosphogenesis and phosphorite accumulation, iron formation sedimentology and petrography, sediment lithogeochemistry, and Precambrian oceanography.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9030', 'GEOL-5433', 'Advanced Igneous Petrology 1', 'Modern approaches to theoretical and practical study of selected igneous rock groups - petrography, geochemistry, magma genesis in relation to tectonic environment, relations to metallogenesis.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9031', 'GEOL-5443', 'Advanced Igneous Petrology 2', 'Modern approaches to theoretical and practical study of selected igneous rock groups - petrography, geochemistry, magma genesis in relation to tectonic environment, relations to metallogenesis.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9033', 'GEOL-5533', 'Advanced Metamorphic Geology', 'Studies in metamorphic geology, including some of structural-metamorphic geology, chemography, phase relationships of metamorphic rocks, tectonics and metamorphism.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9038', 'GEOL-5633', 'Applied Structural Geology', 'Structural methods used in the analysis of deformed rocks, statistical treatment of data, sections, polydeformation, low to high metamorphic grade terrains, migmatite and gneiss, granite tectonics and fabrics, mylonite.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9039', 'GEOL-5703', 'Quaternary Paleoecology', 'Principles of Quaternary paleoecology and the application of these to actual field problems with special emphasis on Holocene climate change.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9040', 'GEOL-5713', 'Advanced Quaternary Enviro', 'An advanced treatment of specific topics in Quaternary geoscience with particular emphasis on methods of investigating environmental change. Topics covered will include methods of paleoclimate reconstruction, advanced dating techniques, records of Holocene climate change, exploration in glaciated terrain. Prerequisite(s): Permission of instructor.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9041', 'GEOL-5743', 'Topics in Soil Science', 'An examination of soils from a mineralogical and geochemical perspective, including dissolution, hydrolytic and oxidative soil forming processes, soil evolution and maturity, the effect of substrate composition on soil type, organic matter composition and decomposition, adsorption, desorption, controls on permeability, and essential nutrient and micronutrient cycling. Prerequisite(s): Permission of instructor.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9043', 'GEOL-5823', 'Geochemical Material Transfer', 'Introduction to the theory of material transfer and its use in interpreting geochemical and mineralogical controls on rock composition, including water-rock and melt-crystal reactions and physical grain fractionation. Interpretation of results using petrologic hypothesis testings and error propagation.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9044', 'GEOL-5833', 'Adv Exploration/Env Geochem', 'Geochemical principles and techniques applied to mineral exploration and applied geochemistry. Includes theory of dispersion, natural precipitation barriers, solubility, sorption and the design and execution of geochemical surveys, analysis of samples and interpretation of results, including statistical evaluation technologies and data quality assessment.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9046', 'GEOL-5873', 'Advanced Mineral Deposits', 'Studies in economic geology, which may include the occurrence, characteristics, geochemistry and physical properties of a variety of mineral deposits, opaque mineral petrography and texture interpretation, and application of isotopic systematics, fluid inclusion microthermometry and other analytical procedures to studies of ore genesis.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9047', 'GEOL-5883', 'Advanced Mineral Exploration', 'Introduction to mineral exploration techniques, economic deposit evaluation strategies, and mining and processing methods. (3h lab).', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9048', 'GEOL-5903', 'Graduate Seminar 2', 'Review of current research topics and problems in the Geological Sciences. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOM 5903. Prerequisite: GEOL 5900', 'GEOL', 3, 0, 5, '[{"codes":["GEOL-5900"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9049', 'GEOL-5913', 'Special Topics in Geology 1', 'Review and analysis of selected topics and problems in Geology, utilising library, field and laboratory methods as required and involving preparation and presentation of formal papers. Specific topics, format, and content of the course will be established for each student by the department.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9050', 'GEOL-5923', 'Special Topics in Geology 2', 'Review and analysis of selected topics and problems in Geology, utilising library, field and laboratory methods as required and involving preparation and presentation of formal papers. Specific topics, format, and content of the course will be established for each student by the department.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9051', 'GEOL-5933', 'Special Topics in Geology 3', 'Review and analysis of selected topics and problems in Geology, utilising library, field and laboratory methods as required and involving preparation and presentation of formal papers. Specific topics, format, and content of the course will be established for each student by the department.', 'GEOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9052', 'GEOL-5960', 'Graduate Thesis', '', 'GEOL', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9054', 'GEOM-5903', 'Applied Geomatics Seminar 2', 'Review of current research topics and problems in Applied Geomatics or the Geological Sciences. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOL 5900 and BIOL 5013/5023. Prerequisite: GEOM 5900', 'GEOM', 3, 0, 5, '[{"codes":["GEOM-5900"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9055', 'GEOM-5913', 'Spcl. Top. in Appld Geomatics', 'Review and analysis of selected topics and problems in applied geomatics using field and laboratory methods as required and involving the preparation and presentation of formal papers or reports. Specific topics, format and content of the course will be established for each student by the NSCC Applied Geomatics Research Group advisor and the relevant department.', 'GEOM', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9056', 'GEOM-5923', 'Spcl. Top. in Appld Geomatics', 'Review and analysis of selected topics and problems in applied geomatics using field and laboratory methods as required and involving the preparation and presentation of formal papers or reports. Specific topics, format and content of the course will be established for each student by the NSCC Applied Geomatics Research Group advisor and the relevant department.', 'GEOM', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9057', 'GEOM-5933', 'Spcl. Top. in Appld Geomatics', 'Review and analysis of selected topics and problems in applied geomatics using field and laboratory methods as required and involving the preparation and presentation of formal papers or reports. Specific topics, format and content of the course will be established for each student by the NSCC Applied Geomatics Research Group advisor and the relevant department.', 'GEOM', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9058', 'GEOM-5990', 'Appld Geomatics Research Proj', 'The Applied Geomatics Research Project consists of a technical report, the form of which is determined by the project sponsoring proponent(s), the academic advisors and the candidate. This course will be evaluated by a committee which will normally consist of the proponent and the CoGS and Acadia advisors. A syllabus distinct to each project will be developed and approved by the supervisory committee before commencement.', 'GEOM', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9060', 'GERM-1013', 'German for Beginners 1', 'Students acquire basic speaking, reading and writing skills in German by using different learning tools (project work, internet and online tasks, video clips etc.). A variety of group and pair-activities combined with grammatical instruction will provide students with ample opportunity to strengthen and increase their communication skills.', 'GERM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9061', 'GERM-1023', 'German for Beginners 2', 'Students acquire basic speaking, reading and writing skills in German by using different learning tools (project work, internet and online tasks, video clips etc.). A variety of group and pair-activities combined with grammatical instruction will provide students with ample opportunity to strengthen and increase their communication skills. Prerequisite(s): GERM 1013 or equivalent.', 'GERM', 3, 0, 1, '[{"codes":["GERM-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9064', 'GERM-2013', 'Intermediate German 1', 'After a quick review of basics, new grammatical structures are introduced. Comprehension and speaking as well as writing are practiced, using as aids, texts and slides on modern Germany. Prerequisite(s): GERM 1023 or equivalent.', 'GERM', 3, 0, 2, '[{"codes":["GERM-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9065', 'GERM-2023', 'Intermediate German 2', 'After a quick review of basics, new grammatical structures are introduced. Comprehension and speaking as well as writing are practiced, using as aids, texts and slides on modern Germany. Prerequisite(s): GERM 2013 or equivalent.', 'GERM', 3, 0, 2, '[{"codes":["GERM-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9068', 'GERM-2513', 'Intermed Conversa German 1', 'The emphasis is on the acquisition of vocabulary, idioms and sentence structure necessary for dealing with situations in everyday life as well as for mastering conversations on relevant topics. Written work is involved. Grammar is reviewed on an ad hoc basis only. Prerequisite or Corequisite(s): GERM 2013 or permission of the Department.', 'GERM', 3, 0, 2, '[{"codes":["GERM-2013","or","permission","of","Department"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9069', 'GERM-2523', 'Intermed Conversa German 2', 'The emphasis is on the acquisition of vocabulary, idioms and sentence structure necessary for dealing with situations in everyday life as well as for mastering conversations on relevant topics. Written work is involved. Grammar is reviewed on an ad hoc basis only. Prerequisite or Corequisite(s): GERM 2023 or permission of the Department.', 'GERM', 3, 0, 2, '[{"codes":["GERM-2023","or","permission","of","Department"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9070', 'GERM-2813', 'Modern German Culture, Society', 'Examining the German experience from the 1960s to the age of globalization, this course asks the question: What does modern German Culture look like? Sources will include contemporary texts, films, music, media, literature, and the German language. This course is taught in English.', 'GERM', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9072', 'GERM-2913', 'Germany: From War to War', 'Reflections of German political and social history from WWI to WWII. This course explores Germany''s complex social and political history in an interdisciplinary way through literary and historical narratives. It focuses on writers whose work commented on and responded to major historical events from the beginning of World War I to the Third Reich. This course is taught in English. Antirequisite(s): Credit can be obtained for only one of GERM 2913 or HIST 2943.', 'GERM', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9073', 'GERM-2923', 'Germany: Division, Unification', 'Reflections of German political and social history from the end of WW II to Reunification through its literature. Readings examine Germany and Germans in the post World War II era, their retrospective interpretation of the war and the Holocaust, and their view of the place of a divided, then reunited Germany in the world. This course is taught in English. Antirequisite(s): Credit can be obtained for only one of GERM 2923 or HIST 2923.', 'GERM', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9075', 'GERM-3013', 'Advanced German 1', 'Main topics are speaking, reading, writing German at the advanced level, review of German grammar, introduction to written composition, discussion of nonfictional and fictional German texts. Prerequisite(s): GERM 2023 or permission of the Department.', 'GERM', 3, 0, 3, '[{"codes":["GERM-2023","or","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9076', 'GERM-3023', 'Advanced German 2', 'Main topics are speaking, reading, writing German at the advanced level, review of German grammar, introduction to written composition, discussion of nonfictional and fictional German texts. Prerequisite(s): GERM 3013.', 'GERM', 3, 0, 3, '[{"codes":["GERM-3013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9079', 'GERM-3313', 'Modern/Contemp German Lit 1', 'A study of literary developments in Germany from the turn of the century to World War II.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9080', 'GERM-3323', 'Modern/Contemp German Lit 2', 'A study of literary developments in Germany since World War II.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9082', 'GERM-3413', 'History of German Literature 1', 'A survey of literary and cultural developments from the beginnings of German literature until the age of Enlightenment. Prerequisite(s): permission of the Department.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9083', 'GERM-3423', 'History of German Literature 2', 'A survey of literary and cultural developments from the late eighteenth to twentieth century.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9084', 'GERM-3503', 'Reformation to Enlightenment', 'This course will focus on the study of representative authors of this period such as Martin Luther, Hans Sachs, Martin Opitz, J.J.C. von Grimmelshausen, J.C. Gottsched, and G.E. Lessing.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9086', 'GERM-3603', 'Clascl Per. & Early Romantics', 'A survey of the major ideas and literature of the classical period. The attention focuses on the works of Goethe and Schiller. Introduction to the theoretical and poetic works of early romantic authors such as Wackenroder, Tieck, Schlegel, and Novalis.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9088', 'GERM-3703', 'Pre-Realist Period', 'This course deals with the literature from the age which overlaps Classicism and Romanticism and includes authors, dramatists and poets who do not fit in those categories or certain works by otherwise Classical and Romantic poets that cannot be seen as belonging (completely) to Classicism or Romanticism. The course will study a cross section of plays, novellas and poems by Heinrich von Kleist, Eduard Mörike, Franz Grillparzer, Georg Büchner, Heinrich Heine, Adalbert Stifter.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9090', 'GERM-3803', 'Realism', 'This course focuses on the literature of the age of Realism which lies roughly between 1850 and 1900. It will include works by Gottfried Keller, Wilhelm Raabe, Theodor Storm, Conrad Ferdinand Meyer, the early Thomas Mann, and Friedrich Nietzsche. Special emphasis will be placed on the works of Theodor Fontane.', 'GERM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9094', 'GERM-4813', 'Individual Readings', '', 'GERM', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9095', 'GERM-4823', 'Individual Readings', '', 'GERM', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9099', 'GREE-1103', 'Elementary Greek I', 'Introduction to classical Greek, using a reading rather than a conversational approach. Emphasis is on learning the basics of Greek grammar. This course counts toward the second language requirement.', 'GREE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9100', 'GREE-1113', 'Elementary Greek II', 'Completion of the introduction to classical Greek continuing with the reading approach and course materials used in Elementary Greek I. This course counts toward the second language requirement. Prerequisite(s): GREE 1103.', 'GREE', 3, 0, 1, '[{"codes":["GREE-1103"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9103', 'GREE-2906', 'Selected Read Greek Texts', 'Selections from classical Greek authors. Prerequisite(s): GREE 1113 with a minimum grade of B-.', 'GREE', 6, 0, 2, '[{"codes":["GREE-1113","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9104', 'GREE-3006', 'Advanced Greek', 'Grammatical readings of a sampling of ancient Greek texts in literature and philosophy, selected to prepare students for graduate study in Classics. Students must be prepared to make a significant investment of time in their study of Greek at this level. Prerequisite(s): GREE 2006 with a minimum grade of B-.', 'GREE', 6, 0, 3, '[{"codes":["GREE-2006","with","minimum","grade","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9105', 'GREE-3013', 'Foundations NT Greek 1', 'Careful study of the New Testament is based upon access to the language in which it was originally written. This course will equip students to use the many tools available for the study of the New Testament in its original language. In order to prepare students for careful and critical study, foundational New Testament Greek grammar and vocabulary will be covered.', 'GREE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9106', 'GREE-3023', 'Foundations NT Greek 2', 'This course builds on GREE 3013, focusing on developing vocabulary acquisition and a more in-depth understanding of grammar. At the end of the course, students should be able to translate portions of the Greek New Testament. Prerequisite: GREE 3013.', 'GREE', 3, 0, 3, '[{"codes":["GREE-3013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9107', 'GREE-3106', 'Hellenistic Greek', 'Readings from a large variety of Jewish, Christian, and pagan texts from the Hellenistic and Roman periods. Prerequisite(s): GREE 2006 with a minimum grade of B-.', 'GREE', 6, 0, 3, '[{"codes":["GREE-2006;","MIN","GRADE","B-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9111', 'GREE-5013', 'Foundations NT Greek 1', 'Careful study of the New Testament is based upon access to the language in which it was originally written. This course will equip students to use the many tools available for the study of the New Testament in its original language. In order to prepare students for careful and critical study foundational New Testament Greek grammar and vocabulary will be covered.', 'GREE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9112', 'GREE-5023', 'Foundations NT Greek 2', 'This course builds on GREE 5013, focusing on developing vocabulary acquisition and a more in-depth understanding of grammar. At the end of the course, students should be able to translate portions of the Greek New Testament. Prerequisite: GREE 5013.', 'GREE', 3, 0, 5, '[{"codes":["GREE-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9114', 'GREE-6013', 'Intermediate Greek', 'Intermediate Greek builds upon the foundation of an introductory year of Greek. The focus of the course is on increasing students'' reading skill by building vocabulary, solidifying introductory grammatical foundations, introducing the student to Greek syntax, and reading larger portions of New Testament text. Prerequisite: GREE 5013 and GREE 5023, or permission of the instructor based on qualifying test.', 'GREE', 3, 0, 6, '[{"codes":["GREE-5013","and","GREE-5023","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9116', 'GREE-7013', 'Greek Exegesis of Matthew', 'In this course, students will study the Greek text of Matthew''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033 and Greek language skills learned in GREE 6013. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and Matthew''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Matthew and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9117', 'GREE-7023', 'Greek Exegesis of Luke', 'In this course students will study the Greek text of the Gospel of Luke and the Book of Acts. Luke-Acts is a two-part work that describes the life and ministry of Jesus and moves seamlessly to the life and ministry of the church, with the early church''s ministry modelled upon the ministry of Jesus. This course will examine the narrative and theological unity of Luke-Acts, focusing particularly on the mission of the early church. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9118', 'GREE-7033', 'Greek Exegesis of John', 'In this course students will study the Greek text of John''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033 and the Greek language skills learned in GREE 6013. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and John''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in John and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9119', 'GREE-7043', 'Greek Exegesis Romans & Galat', 'In this course students will study the Greek text of the Epistles of Romans and Galatians by applying the hermeneutical and exegetical skills learned in BIBL 5033 and the Greek language skills learned in GREE 6013. In addition to studying the contents, contexts, and interpretive issues involved in the study of the apostle Paul''s major epistles to the churches in Galatia and in Rome, the epistles'' contribution to the Christian teaching regarding righteousness and justification before God will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Romans, Galatians and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9120', 'GREE-7053', 'Greek Exegesis: Hebrews&James', 'In this course, students will study the epistle to the Hebrews and James by applying the hermeneutical and exegetical skills learned in BIBL 5033 and the Greek language skills learned in GREE 6013. In addition to studying the contents, contexts, and interpretive issues involved in the study of Hebrews and James, these letters'' contribution to the Christian understanding of Jesus Christ''s saving work will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Hebrews and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9121', 'GREE-7063', 'Greek Exeg Phil, Col, Eph, Phi', 'In this course, students will study Paul''s Prison Epistles by applying the hermeneutical and exegetical skills learned in BIBL 5033 and the Greek language skills learned in GREE 6013. In addition to studying the contents, contexts, and interpretive issues involved in the study of these epistles, these letters'' contribution to Christology and a life of integrity in the face of adversity will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in the Prison Epistles and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 6013.', 'GREE', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9122', 'GREE-7713', 'Study of Septuagint of Genesis', 'In this course students will translate sections of the Greek version of Genesis, which dates from more than two centuries before the time of Christ and which was used by the Early Church. Students will use both Greek and Hebrew skills in the study of the book''s translation technique and will compare the Greek text to the Hebrew text. Consideration will also be given to the use of this text in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in Genesis. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","and","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9123', 'GREE-7723', 'Study of Sept of Josh to Kings', 'In this course, students will translate sections of a Greek version of Joshua, Judges, 1 and 2 Samuel, or 1 and 2 Kings, dating from more than two centuries before the time of Christ and used by the Early Church. Students will use both Greek and Hebrew skills in the study of the book''s translation technique and will compare the Greek text to the Hebrew text. Consideration will also be given to the use of the texts in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in the Septuagint. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","and","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9124', 'GREE-7733', 'Septuagint Chronicles Thru Neh', 'In this course students will translate selected texts of the Greek version of 1 and 2 Chronicles, Ezra, or Nehemiah, which date from two centuries before to two centuries after the time of Christ and which were used by the Early Church. Students will use both Greek and Hebrew skills in the study of the books'' translation technique and will compare the Greek text to the Hebrew text. Consideration will also be given to the use of the texts in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in the Septuagint. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","and","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9125', 'GREE-7743', 'Study of Greek Version Daniel', 'In this course students will translate one of the Greek versions of the Book of Daniel (Old Greek or Theodotion), which date from the second century before to second century after the time of Christ and which were used by the Early Church. Students will use both Greek and Hebrew skills in the study of the books'' translation technique and will compare the Greek text to the Hebrew-Aramaic text. Consideration will also be given to the use of the texts in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in the Septuagint. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","and","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9126', 'GREE-7753', 'Study of Sept of Amos & Isaiah', 'In this course students will translate selections of the Greek text of the Books of Amos and Isaiah which dates more than two centuries before the time of Christ and which were used by the Early Church. Students will use both Greek and Hebrew skills in the study of the book''s translation technique and will compare the Greek text to the Hebrew text. Consideration will also be given to the use of the text in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in the Septuagint. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","and","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9127', 'GREE-7763', 'Study of Septuagint of Psalms', 'In this course students will read sections of the Greek text of the Book of Psalms which date more than two centuries before the time of Christ and which were used by the Early Church. Students will use both Greek and Hebrew skills in the study of the book''s translation technique and will compare the Greek text to the Hebrew text. Consideration will also be given to the use of the text in the New Testament. This course will develop Greek translation skills, and will provide students with the foundation for advanced study in the Septuagint and further research in the Septuagint. Prerequisite: GREE 6013, HEBR 5013, and completion of, or simultaneous enrolment in, HEBR 5023.', 'GREE', 3, 0, 7, '[{"codes":["GREE-6013","AND","HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5023"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9131', 'GREE-7913', 'Directed Study in Greek 1', 'Advanced independent study of Greek texts (Septuagint, New Testament, Apostolic Fathers, etc.) or grammar under the supervision of a professor.', 'GREE', 3, 0, 7, '[]');
