INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9137', 'HEBR-3013', 'Foundations Biblical Hebrew 1', 'Careful study of the Old Testament is based upon access to the language in which it was originally written. This course will equip students to access the many tools available for the study of the Old Testament in its original language. In order to prepare students for careful and critical study, foundational Hebrew grammar and vocabulary will be covered.', 'HEBR', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9138', 'HEBR-3023', 'Foundations Biblical Hebrew 2', 'This course builds on HEBR 3013, focusing on developing vocabulary acquisition, and a more in-depth understanding of grammar. By the end of the course, students should be able to translate portions of the Old Testament. Prerequisite: HEBR 3013.', 'HEBR', 3, 0, 3, '[{"codes":["HEBR-3013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9140', 'HEBR-5013', 'Foundations Biblical Hebrew 1', 'Careful study of the Old Testament is based upon access to the language in which it was originally written. This course will equip students to access the many tools available for the study of the Old Testament in its original language. In order to prepare students for careful and critical study foundational Hebrew grammar and vocabulary will be covered.', 'HEBR', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9141', 'HEBR-5023', 'Foundations Biblical Hebrew 2', 'This course builds on HEBR 5013, focusing on developing vocabulary acquisition, and a more in-depth understanding of grammar. By the end of the course, students should be able to translate portions of the Old Testament. Prerequisite: HEBR 5013.', 'HEBR', 3, 0, 5, '[{"codes":["HEBR-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9143', 'HEBR-6013', 'Intermediate Hebrew', 'Intermediate Hebrew builds upon the foundation of an introductory year of Hebrew. The focus of the course is on increasing students'' reading skill by building vocabulary, solidifying introductory grammatical foundations, introducing the student to Hebrew syntax, and reading larger portions of Old Testament text. Prerequisite: HEBR 5013 and HEBR 5023 or permission of the instructor based on qualifying test.', 'HEBR', 3, 0, 6, '[{"codes":["HEBR-5013","HEBR-5023","or","instructor","permission"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9151', 'HEBR-7713', 'Hebrew Exegesis of Genesis', 'In this course students will study the Hebrew text of Book of Genesis by applying the hermeneutical and exegetical skills learned in BIBL 5023 and the Hebrew language skills learned in HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in Genesis and other Old Testament narratives. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9152', 'HEBR-7723', 'Hebr Exeg Deuteronomistic Text', 'In this course students will study selected Hebrew texts from Joshua, Judges, 1 and 2 Samuel, or 1 and 2 Kings, by applying the hermeneutical and exegetical skills learned in BIBL 5023 and Hebrew language skills learned in HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in these books and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9153', 'HEBR-7733', 'Hebrew Exegesis: Chron Thr Neh', 'In this course students will study the Hebrew text of the books of 1 and 2 Chronicles or Ezra-Nehemiah by applying the hermeneutical and exegetical skills learned in BIBL 5023 and the Hebrew language skills learned in HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in 1 and 2 Chronicles or Ezra-Nehemiah and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9154', 'HEBR-7743', 'Hebrew Exegesis of Daniel', 'In this course students will study the Hebrew text of the Book of Daniel by applying the hermeneutical and exegetical skills learned in BIBL 5023 and the Hebrew language skills learned in HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in Daniel and other prophetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9155', 'HEBR-7753', 'Hebrew Exegesis: Amos&Isaiah', 'In this course students will study the Hebrew text of the books of Amos and Isaiah by applying the hermeneutical and exegetical skills learned in BIBL 5023 and the Hebrew language skills of HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in Amos, Isaiah and other prophetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9156', 'HEBR-7763', 'Hebrew Exegesis of Psalms', 'In this course students will study the Hebrew text of the Book of Psalms by applying the hermeneutical and exegetical skills learned in BIBL 5023 and Hebrew language skills learned in HEBR 6013. This course will provide students with the foundation for preaching, teaching, and further research in Psalms and other poetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 6013.', 'HEBR', 3, 0, 7, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-6013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
