INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0NzY1MDk4', 14765098, '0013980', '8466', 'ENGL-3533', 'ENGL3533', 4.5, 5, 4, 4, 'He gets actual conversation going. What may appear to be &quot;easiness&quot; is actually respect for your individual thought process. He is interested in getting you interested, not inundated or in and out.', '[]', NULL, 0, NULL, NULL, 4, 0, 0, 1219417020, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0Nzk0NTg1', 14794585, '0001453', NULL, NULL, 'APPLSING', 4, 4, 4, 3, 'Paula is my choice for voice at Acadia. She is sure of herself, and is not arrogant like some. She helped me fix some vocal problems and I''m doing much better now. She let''s me chose the repertoire I want to sing, and helps me learn without stress.', '[]', NULL, 0, NULL, NULL, 2, 0, 0, 1220410029, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODIyODQz', 14822843, '0029615', '11707', 'SOCI-2113', 'SOCI2113', 4.5, 5, 4, 4, 'Brittain is one of the most intelligent professors acadia has!! ... his teaching tactics are awesome .. they guy is so crazy and fun! .. he makes the material easy to understand! This guy knows his stuff!! .. super good guy too, very willing to help you understand.', '[]', NULL, 0, NULL, NULL, 4, 0, 0, 1221761773, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODQ4Njcz', 14848673, '0012762', '7647', 'COMM-1213', 'COMM1213', 2.5, 2, 3, 5, 'Very intense prof, make sure you read the chapter prior to class and follow her instructions very carefully!', '[]', NULL, 0, NULL, NULL, 4, 1, 1, 1223044479, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODU3ODI2', 14857826, '0039699', NULL, NULL, 'POLSPOLS', 1.5, 2, 1, 5, 'How much psychobabble can you take&#63; That''s the question you need to ask before taking a Whitehall course - every single one is infested with it. Unfortunately, his perpetual deconstruction of everything has blinded him to openness about any other theories. Smart man, no doubt, but take one class with him and you will have taken them all.', '[]', NULL, 0, NULL, NULL, 5, 4, 0, 1223497233, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODUxMDI0', 14851024, '0039699', '11057', 'POLS-1403', 'POLS1403', 1.5, 2, 1, 5, 'Very smart man. Shame he can''t communicate it in a way that''s comprehensible to anyone with an IQ under 200. Asks more questions than he answers, full of postmodern nonsense and useless babble. Leaves even smart people feeling lost and confused. Smart guy, horrible teacher.', '[]', NULL, 0, NULL, NULL, 3, 4, 0, 1223224126, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODUxMDM2', 14851036, '0016390', '9239', 'HIST-2303', 'HIST2303', 2.5, 3, 2, 3, 'Way too overbearing. Says &quot;wild&quot; and &quot;time out, people!&quot; way too much, and refers to his students collectively as &quot;gang.&quot; Too much to take so early in the morning. More about historical ideas than events, and is hard to follow. Makes you discuss the concepts with the person beside you every ten minutes, which is inane and annoying.', '[]', NULL, 0, NULL, NULL, 4, 0, 1, 1223225073, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODUxMDQ3', 14851047, '0013980', NULL, 'ENGL-1406', 'ENGL1406', 4.5, 5, 4, 2, 'Doesn''t lecture, gets a conversation going and gives you a chance to make your voice heard in a non-pressuring environment. Open to different opinions and flexible in how he runs the class. Easygoing. Only complaint is he''s a definite atheist and can occasionally be a little disrepectful. Usually pretty openminded though. Favorite class of the year', '[]', NULL, 0, NULL, NULL, 3, 0, 0, 1223225478, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE0ODUxMDY0', 14851064, '0016415', NULL, 'HIST-1113', 'HIST1113', 5, 5, 5, 3, 'Enjoyed the 8:30s and I am NOT a morning person. Worth getting up for. Funny and interesting, fairly straightforward. Uses good powerpoints but doesn''t read straight off them. Makes it obvious what''s important for the test without saying so straight out. Put in the work, do the reading, show up for class, and you''ll do fine.', '[]', NULL, 0, NULL, NULL, 4, 0, 0, 1223226154, 1788283343);
