INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE1NTI3Mjc5', 15527279, '0037539', '9945', 'MATH-1023', 'MATH1023', 5, 5, 5, 2, 'This is university. It''s not meant to be easy, it''s meant to prepare you for the real world. And in the real world, you won''t always be spoon-fed instructions for everything you do. Anyone with a brain will find Dr. Curry to be a perfectly adequate teacher, and very helpful outside of class. She''s also pretty funny in a dry way, which I like.', '[]', NULL, 0, NULL, NULL, 4, 0, 6, 1236871857, 1788283344);
