INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE2MjM3Njgx', 16237681, '0018366', NULL, NULL, 'ENGLLIT', 5, 5, 5, 4, 'Anne Quema is the best teacher I have ever had. She is AMAZING. She takes you on an intellectual journey with every lecture and guides you to a place where you can understand the concepts in your own terms. She teaches true critical thinking. Quema is challenging, thoughtful and enlightening. She is kind and has a fantastic sense of humour. Superb!', '[]', NULL, 0, NULL, NULL, 5, 1, 0, 1255469647, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTE2MzA2NjM1', 16306635, '0029615', '11703', 'SOCI-2013', 'SOCI2013', 5, 5, 5, 2, 'He is an amazing prof! So interesting to listen to and he brings many interesting interpretations of the world to every class. He is a die hard Marxist which is awesome! He takes theories that have the potential to be so boring and brings them to life. Truly a magical man!', '[]', NULL, 0, NULL, NULL, 3, 0, 0, 1257261770, 1788283347);
