INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTEwMTIxNDk2', 10121496, '0024914', NULL, NULL, 'MATH37134753', 4.5, 5, 4, 4, 'Holger''s great! His assignments are LONG, but understand them, and you''re set for the midterms and exams. He does have a distinct teaching style, which can be confusing, but only at first. Above all, he has a ton of enthusiasm, and even brought my PDEs class pizza for our final tutorial before the exam.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1123980539, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTEwMTIyODk2', 10122896, '0015754', NULL, NULL, 'SHAKESPEARE', 4.5, 5, 4, 4, 'I loved having Dr. Slights as a professor.  I found her teaching style to be engaging, and not only that, she was incredibly open to varying interpretations of Shakespeare.  She wasn''t the type to belittle any student''s ideas, even if she didn''t particularly agree with them.  I only wish I had had the opportunity to take other classes with her.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1124044493, 1788283346);
