INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0MjMwMzA1', 24230305, '0011148', NULL, 'PHIL-2016', 'PHIL2016', 3, 3, 3, 4, 'Anna is an amazing Prof!  She is incredibly passionate about what she teaches and you can see that she lives and breathes philosophy.  It is possible to do well in her classes, but be prepared for an absolutely brutal final exam!  On the upside, she gives really detailed feedback on your test answers and papers which make it easier to up your mark', '[]', 'A-', 1, 0, NULL, 2, 0, 0, 1420462912, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0MjQ1NzA5', 24245709, '0040072', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 5, 'Never take againHomework is boring and so dofficult.', '[]', NULL, 1, NULL, NULL, 1, 5, 1, 1420629567, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0MjQ4NTk4', 24248598, '0003429', '6963', 'BIOL-3423', 'BIOL3423', 5, 5, 5, 2, 'Glenys is by far my favorite professor, she is super organized, explains things super well and does excellent drawings on the board to reinforce concepts. She is almost always available for meeting to discuss conceptsthings you may be unsure of and is helpful and kind and just all-around wonderful. Take any of her classes, you will love them!', '[]', 'Rather not say', 0, 1, NULL, 4, 1, 0, 1420651655, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0MjQ4Njc0', 24248674, '0008859', NULL, NULL, 'PHILOSOPHYLOGIC', 4.5, 4, 5, 3, 'I could listen to Wilks lecture for hours and hours, he is so engaging and interesting. His sense of humour is fantastic and he makes any topic captivating. His tests are completely fair and gives you the essay questions in advance. He is completely open to discussing the questions in and outside class. Overall, amazing prof, take his classes!!', '[]', NULL, 0, 1, NULL, 5, 0, 0, 1420652177, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0MjQxMjE4', 24241218, '0048856', NULL, NULL, 'ORGANICLAB', 2, 3, 1, 5, 'By far the worst lab experience I''ve ever had. She takes points off for everything and seemed genuinely pleased with herself for reporting a quarter of the students in the course for "plagiarism" last year. Avoid if possible.', '[]', NULL, 1, NULL, NULL, 1, 11, 5, 1420569757, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0Mjc2MTc0', 24276174, '0038515', '10989', 'PHYS-1053', 'PHYS1053', 5, 5, 5, 3, 'Anna really cares about you and your progress through the course. She takes the time to learn everyone''s names and gives tons of extra help. She''s the most personable and friendly professor I have had and her notes are extremely neat and clear. Everything is posted online shortly after class, really liked her!', '[]', 'A+', 1, 0, NULL, 1, 3, 1, 1421094352, 1788283339);
