INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDQ2NDc0', 24446474, '0018550', NULL, NULL, '2043', 4, 4, 4, 2, 'Going into his class I didn''t know what to expect,  had heard a lot of things .. mostly bad but as with everyone I give them a fair shake and Rodger ended up being on of the best profs I have ever had! Was more than fair with marking and providing help. If you fail this course or do poorly you deserved it, not an everyone gets a trophy type class.', '[]', 'A-', 1, 1, NULL, 1, 3, 2, 1425943124, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDQ5NzE2', 24449716, '0133590', '6837', 'BIOL-1123', 'BIOL1123', 4, 4, 4, 2, 'I believe she is new to lecturing, and when I had her,  it might have been one of her first large lecture groups. As the semester progressed, she grew more confident . I think she just needs to get a handle on teaching! But she knows her stuff, and is more than willing to give help if you need it! She''s very passionate, and a total sweetheart!!', '[]', NULL, 1, NULL, NULL, 3, 7, 0, 1426024097, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDQyNjQw', 24442640, '0133590', '6837', 'BIOL-1123', 'BIOL1123', 4.5, 5, 4, 3, 'Although she is very quiet, she is also very helpful. Very eager and helpful, just sit near the front and you will be fine! :)', '[]', 'A-', 1, 1, NULL, 2, 4, 0, 1425846033, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDQyNjU2', 24442656, '0133592', NULL, NULL, '1120L', 3, 3, 3, 4, 'Juan Carlos is a nice enough guy, but I would not take another one of his labs if I didn''t have to. He tries to be helpful, but my biggest problem with his labs was that you wern''t always given all of the necessary information to answer the questions. If you have good TA''s, you''ll be fine though.', '[]', NULL, 1, NULL, NULL, 3, 1, 0, 1425846370, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDU0MDY4', 24454068, '0015407', NULL, NULL, 'CREATWRITING', 5, 5, 5, 3, 'Dr. Campbell will make you a better writer. She is a wonderfully encouraging teacher who really wants you to improve your craft. So deserving of her tenure.', '[]', NULL, 1, NULL, NULL, 2, 0, 0, 1426119501, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDY2MDU4', 24466058, '0000768', NULL, NULL, 'MANAGERIALAC', 4, 4, 4, 1, 'Very accommodating to students needs + helpful. Makes assignments on connect with show the correct answer after the first attempt so you can go back', '[]', 'A', 1, 1, NULL, 5, 0, 0, 1426525973, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDY4NTU1', 24468555, '0028980', '7203', 'BUSI-3753', 'BUSI3753', 3, 3, 3, 4, 'Would not take another class by her again. Wonderful lady but should not be teaching business . She prefers personal stories and feelings - I felt like every class was a therapy session! Tonnes of reading - which are all on the tests. If you hate people talking about themselves (students) don''t take her class!', '[]', NULL, 1, NULL, NULL, 1, 1, 1, 1426592013, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDY4NTY3', 24468567, '0018503', '8623', 'ESST-4003', 'ESST4003', 5, 5, 5, 1, 'Fantastic professor! Easy A+. This course is project based and students   choose the topics and field trips - John makes it all happen! No complaints!', '[]', NULL, 1, NULL, NULL, 1, 0, 0, 1426592270, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDcwOTEz', 24470913, '0024548', NULL, 'MATH-1213', 'MATH1213', 3.5, 4, 3, 2, 'Midterms are exactly like assignments and practice midterms. Ask him what will be on the midterm and he will tell you.  Do the assignments and practice tests and you''ll do good.', '[]', 'A+', 1, 0, NULL, 3, 1, 0, 1426626520, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDg3MTgw', 24487180, '0016415', NULL, NULL, '2283', 5, 5, 5, 4, 'FAVORITE PROF. Duke makes each student feel special & he truly cares about your success. So passionate & could make anything interesting. He''s hilarious & very approachable.  Just an all around amazing person (with a great accent too!). Take a class with him, you won''t regret it. When I graduate, I''m going to miss him more than I care to admit.', '[]', NULL, 1, NULL, NULL, 2, 0, 0, 1427053157, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDg3MTk3', 24487197, '0016655', NULL, NULL, '2613', 4, 3, 5, 4, 'Dr. Sedgwick is probably the most hilarious & easy-going professor I have had thus far. However, he has high expectations & will make you work hard for your grade. Definitely knows his stuff & is passionate about his work. Just an all around great guy & awesome prof!', '[]', 'Incomplete', 1, 1, NULL, 5, 0, 0, 1427053425, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDk0NTAz', 24494503, '0021658', '8403', 'ENGL-2163', 'ENGL2163', 4, 4, 4, 3, 'He is so passionate about what he teaches that it is hard not to be as well. He''s a little intense, but in a good way. He assigns a lot of reading and expects it to be done but it''s not that bad. Contrary to what I have hear, he''s not that hard of a marker. At least, I didn''t find he was. I''m taking another class partially because he teaches it.', '[]', NULL, 1, NULL, NULL, 4, 0, 0, 1427199244, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDk0NTE3', 24494517, '0034445', NULL, 'ENGL-2386', 'ENGL2386', 4, 4, 4, 3, 'Very passionate about the subject, and he''s pretty funny too. Definitely a lot of reading, and he''s a little tough with the marking but not too bad on essays. He''s very opinionated but encourages you to disagree with him and share your opinions and thoughts. He also apparently appreciates some good sarcasm.', '[]', NULL, 1, NULL, NULL, 4, 0, 0, 1427199454, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NDk1NTE0', 24495514, '0133590', NULL, NULL, '3243', 4, 5, 3, 3, 'Great at sparking class participation. Very knowledgeable and dedicated and super passionate about fungi.', '[]', 'A+', 1, NULL, NULL, 2, 4, 1, 1427210282, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTAyMDEy', 24502012, '0012981', '8429', 'ENGL-2683', 'ENGL2683', 3.5, 4, 3, 3, 'I am a science student taking Lisa''s American Literature class and am really enjoying it. She goes over readings and has class discussions so that everyone understands (not just the English majors), which makes you feel comfortable in the class. I definitely recommend any English or non-English majors to take one of her classes!', '[]', NULL, 1, NULL, NULL, 4, 3, 0, 1427305780, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTAyMzA=', 2450230, '0012762', NULL, NULL, 'COMM', 4, 4, 4, 4, 'Key to success in her class: your attitude will reflect your grade. Don''t go in all negative because of what you''ve &quot;heard&quot;. You''ll just set yourself up for defeat. I agree, she''s good, just misunderstood at times.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1094478229, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTE1ODIz', 24515823, '0132938', '7997', 'ECON-1013', 'ECON1013', 4.5, 4, 5, 3, 'The guy''s a total beauty.  Tallest guy in the world.  Knows his economics', '[]', NULL, 1, NULL, NULL, 2, 3, 4, 1427629966, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTEyMjM4', 24512238, '0018154', '11325', 'PSYC-2020L', 'PSYC2020L', 4.5, 5, 4, 4, 'Karmen is a hard marker, but she will do anything to help her students and gives good feedback so that you can keep improving which to me is the best thing a prof could do for a student. If you need help go see her! She is so approachable and friendly and will make time to see you outside her office hours if need be. Favorite prof as of this year.', '[]', 'B+', 1, 1, NULL, 1, 1, 0, 1427488910, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTI1OTE1', 24525915, '0011148', NULL, 'PHIL-2006', 'PHIL2006', 3, 3, 3, 2, 'I''ve taken many classes of Anna Wilk''s. She''s an absolute sweetheart and total genius when it comes to Philosophy. Her higher level courses are very different from her introductory courses, though, which are easy A''s. I think research jobs might suit her better than teaching but she''s a good professor.', '[]', NULL, 1, NULL, NULL, 1, 0, 0, 1427813620, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTI1OTc0', 24525974, '0029112', '10996', 'PHYS-1513', 'PHYS1513', 4.5, 4, 5, 1, 'Svetlana is one of the smartest people I have ever met. Looking into her research is inspiring, she''s incredible. She''s so keen for Physics and women in the sciences, and although her Astronomy class is a joke to pass she does it for the love of Phsyics. A genius crossed with a sweetheart crossed with a hottie. She''s the greatest.', '[]', NULL, 1, NULL, NULL, 1, 2, 0, 1427814095, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTM0MDU5', 24534059, '0047076', NULL, NULL, '1010', 4.5, 4, 5, 3, 'Very clear with what she wants with lab reports.', '[]', 'A+', 1, 1, NULL, 1, 0, 2, 1427925871, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTM1NTM2', 24535536, '0031457', NULL, 'CHEM-2583', 'CHEM2583', 3, 3, 3, 5, 'Intro chem is an easy course due to the fact that you''re allowed a cheat sheet. He is not a good prof in analytical chemistry, he gives 3 assignments a week and spends way too much time on theory and only gives math questions on midterms that we weren''t prepared for. He gives a lot of bonus marks due to the amount of failing though.', '[]', 'Not sure yet', 1, 1, NULL, 3, 1, 0, 1427966620, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTMyMzIz', 24532323, '0040072', '7997', 'ECON-1013', 'ECON1013', 4, 5, 3, 3, 'He is very loud, and passionate about what he teaches. The examples in class are almost the same as the test and if he offers tutorials go to them!  If you are struggling, go to his office hours, he is really helpful', '[]', 'A+', 1, NULL, NULL, 3, 1, 4, 1427905012, 1788283342);
