INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NTU2NTgw', 24556580, '0037539', '9945', 'MATH-1023', 'MATH1023', 1.5, 2, 1, 4, 'Eva talks way to fast most of the time and goes off topic often. She will ask a question to the class and stand there and look at us until we answer. She will run around when there is no point, like to close the door. She also makes you do group math to get you to talk to your neighbors and for you to "get to know them". I hated going to class.', '[]', 'A+', 1, NULL, NULL, 2, 2, 0, 1428424507, 1788283344);
