INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjI1MDc0', 24625074, '0003040', NULL, NULL, 'FOODCOMM', 3.5, 3, 4, 3, 'Her classes are really dry, as she reads from the slides for an entire hour and a half. Also, she is terrible at getting marks back as she is ''soooo busy'' all the time. However, she is a nice professor and she is important in the decision making for internships.', '[]', 'A-', 1, NULL, NULL, 4, 0, 0, 1429477015, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjI4MTk5', 24628199, '0003040', NULL, 'NUTR-1342', 'NUTR1342', 2, 1, 3, 3, 'Not a good professor at all. Says she''s always ''busy with the internships'' and doesn''t give any help and if she does then it''s late. Gives crappy feedback and is so boring. Reads directly off the slides. Only go to class if you don''t feel like reading the slides yourself.  Not impressed with her at all.', '[]', NULL, 1, NULL, NULL, 3, 1, 0, 1429533083, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjI5MzQ4', 24629348, '0000907', NULL, 'APSC-1133', 'APSC1133', 4, 3, 5, 2, 'Dr. Mitchell is a great prof. Has lots of cool anecdotes of his engineering past. Lectures are filled with good examples and he knows his stuff. Sometimes hard to read what is on the board, I suggest sitting near the front of the class. If you can do the assignments you''ll pass no problem.', '[]', NULL, 1, NULL, NULL, 5, 2, 1, 1429540779, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjIxMzcx', 24621371, '0031124', NULL, NULL, '2743', 1, 1, 1, 5, 'Walking contradiction. Used to work for IBM but refuses to use ACORN or any Powerpoint slides. Doesn''t respond to e-mails. He wrote the textbook, which isn''t that bad, but hardly references it during lecture. Cries over the need to think critically, yet was a drill Sargent in the army, training individuals to murder people for resource supremacy.', '[]', NULL, 1, NULL, NULL, 1, 1, 3, 1429383252, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjIzNjM3', 24623637, '0037418', '9990', 'MATH-2243', 'MATH2243', 1, 1, 1, 4, 'Have taken many math and stats classes and this class with Dr. Lu was one of the worst of my university experience. He is very unclear lecturing, confuses basic points and rarely follows the lecture schedule textbook, assignments are long but fair. Overall a well designed class with very poor execution', '[]', 'A-', 1, 0, NULL, 5, 1, 0, 1429456252, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjM1ODQ=', 2463584, '0016415', NULL, 'HIST-1106', 'HIST1106', 4.5, 4, 5, 4, 'Not the easiest professor, but he _really_ knows what he''s talking about. His marking isn''t hard, it''s fair. Do your work and you''ll do well in his class (he doesn''t like slackers).  But if you don''t want to work, why bother to go to university anyways&#6', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1094894747, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0NjMyNTAx', 24632501, '0036828', NULL, NULL, '2413', 1.5, 1, 2, 3, 'lovely person. horrible prof. so disorganized, wastes so much time in class, cancels all the time, & still tests you on material she never found time to cover. her on-skype office hours were useless - she talked for 45 mins about a diagram method build a thesis and wouldnt answer my questions, and still didn''t hand back my paper pitch for weeks!', '[]', 'A+', 1, 0, NULL, 4, 0, 0, 1429563347, 1788283344);
