INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0OTA3MjM0', 24907234, '0024548', NULL, 'MATH-1213', 'MATH1213', 4, 5, 3, 2, 'Easiest A+ I have ever received. Midterms are exactly like the practice midterms and assignments. So, if you make sure you understood how to do the assignment (which are also very easy, just follow the textbook examples) then you will do great. Any questions, go see him and he will basically tell you the answer. Great prof. Wants to see us excel.', '[]', NULL, 1, NULL, NULL, 5, 2, 0, 1432721933, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0OTA3Mjgz', 24907283, '0012762', NULL, NULL, 'COMM', 3, 3, 3, 4, 'A lot of people do not like Kendra. However, I found that if you participated every class and made the best of bad grades she came through in the end. Though at times it seemed like she was just out to get the students, by going to her office hours frequently and showing her that you''re trying she eases up on grading you significantly. GO SEE HER.', '[]', 'A', 1, 1, NULL, 3, 1, 1, 1432722721, 1788283363);
