INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0OTI3OTQ1', 24927945, '0018154', NULL, NULL, 'PSYC', 5, 5, 5, 4, 'I love Karmen! She is so intelligent, passionate, helpful, and kind. I could listen to her talk for hours and I left every lecture replaying what she taught me. Her tests are incredibly tough, but you learn so much it is completely worth it!', '[]', NULL, 1, NULL, NULL, 4, 1, 0, 1433195947, 1788283348);
