INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI0OTY5OTU2', 24969956, '0028980', '7203', 'BUSI-3753', 'BUSI3753', 5, 5, 5, 3, 'Dr. Dye is my favourite business professor at Acadia. Her approach is a refreshing break from an otherwise moneyprofit based curriculum. She will challenge how you visualize ''difference'' and broaden your mind on the ways in which corporations and other businesses approach the topic. You should do the readings. They are enriching and well chosen.', '[]', NULL, 0, 1, NULL, 1, 1, 0, 1434466626, 1788283348);
