INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NTg2ODI4', 25586828, '0034695', '10468', 'MUSI-4143', 'MUSI4143', 4.5, 5, 4, 2, 'Mark Hopkins is a great music professor at Acadia University, and one of my favourites. Always willing to help, and gives great feedback! If you are willing to work hard, then you will do very well in this course!', '[]', 'A', 1, 1, NULL, 3, 0, 0, 1449573589, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NTg3MTA3', 25587107, '0002460', NULL, 'MUSI-1333', 'MUSI1333', 4.5, 5, 4, 2, 'Christian Rushton was there for me this year when I wasn''t doing well in the school of music. I didn''t know if I was going to continue on with this programme, but she was there for me throughout the whole time, and she helped me through a lot. She will be there for anyone with open arms, just ask! The best Music Director for the school of music!', '[]', NULL, 0, 0, NULL, 1, 0, 0, 1449574653, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NTk5NTEw', 25599510, '0016390', '9374', 'HIST-3653', 'HIST3653', 5, 5, 5, 4, 'Dr Dennis'' lectures are amazing. I''ve taken multiple classes from him and I learned so much about American history. You have to work hard to get good marks, but he''s very willing to help.', '[]', NULL, 1, 1, NULL, 5, 0, 0, 1449616138, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NTkwNzc4', 25590778, '0016655', '9273', 'HIST-2613', 'HIST2613', 2.5, 3, 2, 4, 'The course material is interesting, but Sedgwick was not the regular prof for this course and it showed. He tended to ramble, did not have clear objectives and the provided course outline was not helpful. While I felt I did end up learning alot, my grade did not reflect this because he was not clear about what he wanted but was very particular.', '[]', 'C+', 0, 0, NULL, 3, 0, 1, 1449587212, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NTkwOTk3', 25590997, '0016415', '9237', 'HIST-2283', 'HIST2283', 5, 5, 5, 2, 'FAV PROF EVER. I''m a business major but if I could major in Duke I would. He''s an amazing lecturer, super intelligent and brings genuine opinions to the classroom. For an elective there is a fair amount of work involved but its interestng and he is a fair marker. TAKE ENVIRO HISTORY W. DUKE YOU WONT REGRET IT', '[]', 'A', 0, 1, NULL, 1, 5, 0, 1449587866, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjA0MDAy', 25604002, '0050655', NULL, 'ESST-2033', 'ESST2033', 5, 5, 5, 3, 'Great class; opened my brain to different methods of leadership', '[]', 'A-', 1, 1, NULL, 4, 0, 0, 1449656289, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjA0Nzk0', 25604794, '0037406', NULL, 'PSYCH-2143', 'PSYCH2143', 3.5, 3, 4, 2, 'Randy is an awesome professor. Her material is almost always clear and concise and her tests/quizzes are as well. She easily brings her notes to life during her lectures (which is why attendence is helpful, but not mandatory), although sometimes you lose that detail trying to take your notes as fast as she speaks. This was a great class. Cute kids!', '[]', 'A', 1, 0, NULL, 1, 0, 0, 1449659844, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjA0OTQw', 25604940, '0001916', NULL, 'BIO-2563', 'BIO2563', 3, 3, 3, 2, 'Trevor would be a great professor if he was a little more organized. It''s stressful never knowing what your mark is in a class. His slides (and his lectures to a degree) are often pretty messy, but they''re easy to make clear when you revisit them. He''s done really neat work and he has a good sense of humor. He''s a smart man and an okay teacher.', '[]', 'A', 1, 0, NULL, 1, 0, 1, 1449660329, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjA1MDYw', 25605060, '0037406', NULL, 'PSYCH-2143', 'PSYCH2143', 4.5, 4, 5, 2, 'Dr. Newman is a sweet woman who is gifted at teaching. Her ability to keep class engaging is second to none. Her marking is fair and she''s really understanding. She''s one of my favourite profs I''ve had and I would definitely take another class of hers.', '[]', 'A', 1, 0, NULL, 1, 0, 0, 1449660808, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjAzOTQz', 25603943, '0036828', '8614', 'ESST-1003', 'ESST1003', 3.5, 4, 3, 4, 'Donna likes to tell stories; while they can be rough to get through, there''s usually knowledge in there. Not the best lecturer, but certainly knows her stuff', '[]', 'A+', 1, 1, NULL, 2, 0, 0, 1449656029, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjE0MTY=', 2561416, '0016779', NULL, NULL, '18THCENT', 4, 5, 3, 2, 'Good prof, utalize his office hours and you will getg a B or better!', '[]', NULL, 0, NULL, NULL, NULL, 0, 1, 1098129604, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjI0MTM4', 25624138, '0021212', '9943', 'MATH-1013', 'MATH1013', 4, 4, 4, 4, 'He is a pretty good prof. hard marker but clear cut.', '[]', NULL, 1, 0, NULL, 1, 1, 0, 1449744219, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjI1Njcx', 25625671, '0133715', NULL, 'BIOL-2023', 'BIOL2023', 3, 3, 3, 2, 'Russell is very knowledgeable about the subject matter, having worked in the field before become a professor at Acadia. He is very interactive in class. However, he tends to get off topic. He is equally approachable outside of class. Sometimes it''s not clear what information is important (or what will be tested). Not a hard course overall.', '[]', NULL, 1, NULL, NULL, 1, 5, 2, 1449749594, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjI2MDEw', 25626010, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 4, 4, 4, 3, 'Todd is definitely one of the best profs I''ve had in my 4 years at Acadia! His lectures are incredibly well organized. Each powerpoint is exactly 12 slides long, and each slide is informative, yet concise. Unfortunately, the course itself contains a lot of material, and the tests are tough. But show up to class, take notes, and you should be fine!', '[]', NULL, 1, NULL, NULL, 3, 0, 1, 1449750665, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjI2MjUx', 25626251, '0000902', '8911', 'GEOL-1073', 'GEOL1073', 3.5, 3, 4, 2, 'There''s a lot of material to cover in Natural Disasters, but it''s fairly interesting. Also, David teaches it at a reasonable pace. His powerpoints are informative, and he explains the material very well. What''s especially great about David is the fact that he''s very specific in terms of what he expects for assignments, and what''s on midterms.', '[]', NULL, 1, NULL, NULL, 2, 0, 0, 1449751299, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjI2NTg1', 25626585, '0016390', '9191', 'HIST-1613', 'HIST1613', 3.5, 4, 3, 4, 'It''s evident that Dr. Dennis is passionate about history. He brings an abundance of energy and enthusiasm to class. His lectures are also very informative. The material is fairly easy to follow, but you have to keep up with the readings. And there are a lot of assigned readings, especially for a 1st year course!', '[]', NULL, 1, NULL, NULL, 4, 0, 0, 1449752141, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NjgwNDM5', 25680439, '0033740', '6633', 'APSC-2113', 'APSC2113', 3.5, 4, 3, 3, 'His accent is the toughest thing about his courses. Very reasonable guy and an easy marker. Talks to his students like a friend, very approachable for questions', '[]', 'A-', 1, NULL, NULL, 4, 2, 0, 1450087441, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzA2OTE1', 25706915, '0011148', '10922', 'PHIL-2233', 'PHIL2233', 3, 4, 2, 4, 'Good prof and a kind person with a real interest and knowledge of the material. She''s very open to help students during office hours and makes an effort to explain the readings - which can be a bit dry & confusing - in a way that makes sense. Exam was difficult.', '[]', NULL, 1, 1, NULL, 5, 0, 0, 1450194588, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzA3MzA0', 25707304, '0016390', '9191', 'HIST-1613', 'HIST1613', 4, 4, 4, 4, 'Passionate about the subject matter & is willing to help students in whatever way he can. His lectures are really engaging, & he is just a nice person all around. Going to class, doing the readings, & going to his office hours/tutorials are essential to doing well. Would definitely take another Dennis course!', '[]', NULL, 1, 1, NULL, 5, 0, 0, 1450195709, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzA3NzY1', 25707765, '0037751', '11140', 'POLS-3513', 'POLS3513', 5, 5, 5, 3, 'Dr. Brickner teaches material in a way that makes it interesting, concise, and relevant. She has a great ability to cultivate discussion and her personality makes class enjoyable. Very approachable and cares about students'' success. Assessments were fair. Best prof at Acadia and by far my favourite class!', '[]', NULL, 1, 1, NULL, 5, 0, 0, 1450197044, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzM5Mjk1', 25739295, '0024914', '9943', 'MATH-1013', 'MATH1013', 3.5, 4, 3, 3, 'Holger cares about how the students do. Very good office hours. Sometimes gets dragged off topic. Overall I really liked him as a first year calculus professor, would take his class again.', '[]', NULL, 1, 0, NULL, 3, 0, 0, 1450327761, 1788283345);
