INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzQwNjI1', 25740625, '0004338', '9744', 'KINE-2003', 'KINE2003', 5, 5, 5, 1, 'Very easy prof. Great to learn more and great feedback. Slow at responding to emails. Easy marker.', '[]', 'A', 1, 0, NULL, 1, 0, 0, 1450347327, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1NzY4Nzg2', 25768786, '0034094', NULL, 'BUSI-2413', 'BUSI2413', 1, 1, 1, 5, 'Challenging course, he marks very hard with little to no feedback. Seemed like a nice guy but really ended up screwing us all over for final grades. Dissapointed in how the course turned out. It should be an easy class but it was too much for an introductory course.', '[]', NULL, 1, 1, NULL, 5, 7, 0, 1450484799, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1ODA4OTk1', 25808995, '0024282', '7670', 'COMP-1813', 'COMP1813', 4.5, 4, 5, 2, 'He posts his lectures online so you can rewatch making the assignments very easy if you put in any work.', '[]', 'A', 1, NULL, NULL, 1, 0, 0, 1450838072, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1ODEwMTE3', 25810117, '0042843', '7141', 'BUSI-2423', 'BUSI2423', 3.5, 4, 3, 4, 'engaging class. never bored to come see donna... only problem is don''t expect to get your grades back fast. On both midterm occasions she made us come to her office to get them (no prob) except they were never done :( BUT TAKE MARKETING FROM HER SHE KNOWS LOTS AND YOU CAN BASK IN HER KNOWLEDGE. Seriously though, she''s interesting.', '[]', 'A-', 1, 1, NULL, 5, 0, 2, 1450866587, 1788283344);
