INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1ODMzNTM1', 25833535, '0011703', '6714', 'ART-3023', 'ART3023', 5, 5, 5, 4, 'There was no prerequisite on this course but I am really glad I had done art in High School, especially drawing! Painting is hard work but I enjoyed the class a lot. Prof. Leidl has high expectations but was there for all of us. It is important to attend all the classes, otherwise it is really hard to catch up!', '[]', 'A', 1, 1, NULL, 4, 0, 0, 1451250320, 1788283361);
