INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI1ODQyNDY0', 25842464, '0133590', '6993', 'BIOL-3663', 'BIOL3663', 4.5, 5, 4, 2, 'Alison is one of the best profs at Acadia, her passion for fungi and also her students is evident in every lecture and lab. Gives long lectures with a lot of content but is also very clear with content that will be tested. A fair marker and great prof to learn from. Also has a interesting research program and variety of interests. Great class!', '[]', 'A+', 1, 1, NULL, 3, 2, 0, 1451381612, 1788283340);
