INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2MzU1MTI=', 2635512, '0031457', NULL, NULL, 'INTROCHEM', 3, 3, 3, 3, 'Not very helpful when it comes to prep for midterms, and doesn''t even mention them or go over answers after. Not a bad guy, his class just always seems like a waste of time, doesn''t spend any extra time on hard subjects or less on common concepts- just goes through the slides at a monotomous pace', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1099403583, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2MzY4MjM3', 26368237, '0027644', '10908', 'PHIL-1423', 'PHIL1423', 4, 3, 5, 1, 'Very enthusiastic and fair. If you go to class you shouldn''t have a problem. Very clear about upcoming tests, never any surprises so you know exactly what to study to excel. Only downside is that if you ask him a question he''ll take like 30 minutes to answer it because like one thing just leads into another and he''ll talk for days. Nice guy tho.', '[]', 'A', 1, 0, NULL, 0, 1, 0, 1461542217, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2MzY4Mjcx', 26368271, '0132938', '7998', 'ECON-1023', 'ECON1023', 5, 5, 5, 1, 'Best prof I''ve had so far. Young prof so still ironing some things out, but still very good and can only get better. Sometimes tests are tougher than you expect but he''s very good about following the bell curve, so it works out. Make use of his offie hours, they''re very beneficial. Very good at replying to emails! Doesn''t believe in multiple choice', '[]', 'A+', 1, 0, NULL, 5, 1, 4, 1461542571, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2Mzc5MzI2', 26379326, '0132938', '8014', 'ECON-2713', 'ECON2713', 5, 5, 5, 3, 'Excellent professor! Very approachable and helpful. Makes sure that when you leave the class you really feel like you have learned something. Classes are interesting and very worth while. Would definitely recommend!', '[]', NULL, 1, NULL, NULL, 0, 1, 6, 1461662350, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2Mzc5MzY4', 26379368, '0050655', '8614', 'ESST-1003', 'ESST1003', 4, 4, 4, 3, 'Alice is a great prof and really encourages class discussion, she is young and really takes an interest in students. She is very helpful with office hours! Has done some pretty cool research too!', '[]', NULL, 1, NULL, NULL, 5, 0, 0, 1461662990, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2Mzk1Nzc3', 26395777, '0034094', '7187', 'BUSI-3433', 'BUSI3433', 2.5, 3, 2, 5, 'One minute I think you are going to be a great professor, til you scream at the entire class for being distracted. This prof is not someone who you want to get on your bad side, because it will reflect on your grades. He expects us to recite the entire Consumer Behaviour book which is unrealistic. Overall I was not impressed, now I hate marketing.', '[]', NULL, 1, 1, NULL, 5, 7, 0, 1461776297, 1788283363);
