INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2NDE2NDgz', 26416483, '0012071', '9283', 'HIST-2783', 'HIST2783', 4.5, 4, 5, 4, 'Dr. Dalton has an an awesome personality that shines through in her lectures, which she tries to make as relevant and interesting as possible. Course content was really engaging, readings were manageable, and she is very willing to help students outside class. Tough marker so be prepared to work for a good grade.', '[]', NULL, 1, 0, NULL, 5, 0, 0, 1461939206, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI2NDE2NTgz', 26416583, '0015407', '8496', 'ENGL-3843', 'ENGL3843', 5, 5, 5, 3, 'Dr. Campbell teaches difficult material in a concise and nuanced way. She values students'' creativity and gives opportunities for creative writing. She is very approachable and will often mark generously if you go to her office hours and participate in class. Great prof and engaging course!', '[]', NULL, 1, NULL, NULL, 0, 0, 0, 1461939749, 1788283356);
