INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3MDIyMDMz', 27022033, '0046951', NULL, 'MUSI-2800', 'MUSI2800', 4, 4, 4, 4, 'Triatan sets high, yet obtainable, ensemble goals. His semester of running wind ensemble was by far one of the best experiences I''ve had at Acadia. He is a bit awkward when talking to him, but he genuinely cares about his students and the final product. Take any class you can with him! As long as practice and attend class, you''ll get along great!', '["Respected","Skip class? You won''t pass.","LOTS OF HOMEWORK"]', 'A', 1, 1, 1, 0, 0, 0, 1475925120, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3MDIyMDQ2', 27022046, '0003479', '13578', 'MUSI-2013', 'MUSI2013', 4, 4, 4, 4, 'If you are not computer savy, this course is HARD. Go to class, ask questions, and you''ll be fine. Eugine has frequent office hours, quick to respond to emails, and has a LOT of patience. If you don''t go to class and skip homework assignments, he wont help you. Super nice and approachable.', '["Skip class? You won''t pass.","LOTS OF HOMEWORK","ACCESSIBLE OUTSIDE CLASS"]', 'B-', 1, 1, 1, 0, 0, 0, 1475925615, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3MDM1MjYy', 27035262, '0018550', NULL, 'PLANT-2043', 'PLANT2043', 2, 2, 2, 4, 'Doesn''t do review before midterms, probably because he openly admits to not writing midterms until the night before the test. He picks questions from his previously made midterms at random and no matter if he talked about it in class or not. He openly admits to hating his subject and said he barley passe it himself yet makes it difficult to learn.', '["Tough Grader","Skip class? You won''t pass."]', 'C-', 1, 1, 0, 0, 1, 1, 1476367712, 1788283353);
