INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3MzQxNTc0', 27341574, '0018366', NULL, 'ENG-2006', 'ENG2006', 5, 5, 5, 4, 'Anne Quema is my FAVOURITE prof at Acadia. I am so inspired by her, and she makes me want to do better. I had her last year and I absolutely loved the experience, so I was THRILLED that my year long English course was going to be with her! If you go to her office when you need help, she will go above and beyond to help you! LOVE THIS PROF! :)', '["Gives good feedback","Inspirational","Clear grading criteria"]', 'A-', 1, 1, 1, 5, 0, 1, 1480969157, 1788283341);
