INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NDk3MTUw', 27497150, '0040072', '7997', 'ECON-1013', 'ECON1013', 5, 5, 5, 3, 'i loved the class always full of energy,  jokes and knowledge. Always ready for questions and makes sure you understand before moving on. Watches a lot of game of thrones', '["Respected","Participation matters","BEWARE OF POP QUIZZES"]', 'C', 1, 0, 1, 5, 0, 1, 1481741617, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTA0Mjg5', 27504289, '0012118', '6633', 'APSC-2113', 'APSC2113', 1, 1, 1, 5, 'Difficult man', '["BEWARE OF POP QUIZZES","TEST HEAVY"]', 'Not sure yet', 1, 1, 0, 5, 4, 0, 1481761828, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTEwNTg4', 27510588, '0012118', '6614', 'APSC-1073', 'APSC1073', 4, 4, 4, 1, 'Paul seemed like a "typical prof" in terms of being straight forward at the start,  made it seem like you need to be independent to succeed and such, but he is a great guy if you need to talk to him one on one. Not the most interesting class, but most mandatory classes aren''t. Pretty easy class,  do well on tests/assignments as there aren''t many.', '["Tough Grader","BEWARE OF POP QUIZZES","LECTURE HEAVY"]', 'A-', 1, 1, 1, 0, 2, 4, 1481806052, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTEzNjk2', 27513696, '0149576', '11090', 'POLS-2683', 'POLS2683', 4, 4, 4, 3, 'Awesome prof. He''s clear with what he expects and makes all of the serious content lighter with his jokes. Great marker, but DON''T take him for granted, as he''s now aware that he''s known as an ''easy marker''. Not a guy you wanna mess with, so get on his good side. Lecture content is interesting and he encourages discussion.', '["Gives good feedback","Clear grading criteria","Hilarious"]', 'A', 1, 0, 1, 0, 13, 2, 1481814644, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTEzOTgz', 27513983, '0139613', NULL, 'POLS-2006', 'POLS2006', 4, 4, 4, 3, 'One of the friendliest politics profs. She wants students to succeed so she''s understanding and will give you great feedback. In her canadian courses the material can be a little dry, but she''s aware of it so she tries to make it interesting. More work but less stressful. Super approachable, i highly recommend.', '["Gives good feedback","Respected","ACCESSIBLE OUTSIDE CLASS"]', NULL, 1, 1, 1, 5, 0, 0, 1481815362, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTUyOTQ3', 27552947, '0039663', '7288', 'CHEM-1023', 'CHEM1023', 5, 5, 5, 3, 'Dr. Tong is great and really cares about his class and the success of his students. The entire First Year Chem Team is amazing and put in SOOOO much more time and effort than they need to. His accent is kind of hard to understand, but he is very enthusiastic about what he is saying. He was often the best part of my day!', '["Inspirational","ACCESSIBLE OUTSIDE CLASS","Hilarious"]', NULL, 1, 0, 1, 0, 0, 1, 1482054046, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTYwNDEx', 27560411, '0028980', '7149', 'BUSI-2733', 'BUSI2733', 4, 4, 4, 3, 'Very interesting prof - little patience for mistakes, however. Marks much harder on tests than assignments, in my experience.', '["Gives good feedback","Get ready to read","GROUP PROJECTS"]', 'A', 1, 0, 1, 5, 1, 0, 1482103110, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTYwNTI1', 27560525, '0047642', NULL, 'BUSI-1073', 'BUSI1073', 5, 5, 5, 4, 'Best prof Ive had so far in the business department - definitely would recommend to anyone considering his class', '["Respected","ACCESSIBLE OUTSIDE CLASS","Amazing lectures"]', 'A', 1, 0, 1, 0, 1, 0, 1482103661, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTYzMzM5', 27563339, '0151851', '9699', 'KINE-1333', 'KINE1333', 5, 5, 5, 3, 'Lauren is the bomb! She is really passionate about what she teaches and is the most approachable prof I have ever had. It''s a lot of material but if you study you will do great. Take her class!!', '[]', 'A-', 1, 1, 1, 0, 0, 0, 1482140361, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTc0MDg4', 27574088, '0043166', '9267', 'HIST-2533', 'HIST2533', 3, 3, 3, 4, 'Passionate about history, complete geek (in the best way). Extremely particular with  papers, but if you''re going to be so strict with a due date deadline, maybe you shouldn''t take a month to grade a midterm because "you didn''t feel like doing it" because I assure you, we don''t feel like writing your tests/assignments. Good prof, feedback is slow.', '["Tough Grader","Get ready to read"]', NULL, 0, 1, 1, 5, 0, 0, 1482190485, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTk3NzQ3', 27597747, '0133715', NULL, 'BIOL-2023', 'BIOL2023', 5, 5, 5, 2, 'Russell is awesome! You won''t meet a prof that cares as much as he does!', '["Inspirational","ACCESSIBLE OUTSIDE CLASS","Caring"]', 'A', 1, 0, 1, 0, 0, 0, 1482355030, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTkwNzU0', 27590754, '0029615', NULL, 'SOC-1013', 'SOC1013', 5, 5, 5, 3, 'Dr. Jim is one of the funniest and kindest dudes you will ever have as a professor. He is definitely one-of-a-kind and talks to his students on their level, in their language. If you have an issue with swearing, maybe steer clear of the class, but if you want to learn a lot and have fun while doing it, Jim is the man for you!', '["Inspirational","Hilarious","Amazing lectures"]', 'A', 1, 1, 1, 5, 1, 0, 1482317019, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NTkxODEy', 27591812, '0151851', '9699', 'KINE-1333', 'KINE1333', 5, 5, 5, 3, 'Lauren is awesome, she''s very smart and knows what she''s talking about. She''s very approachable and easy to talk to. There''s a ton of material so don''t skip class, but it''s all really interesting. Keep up on your notes and know your anatomy and you''ll be fine. Really fun and interesting class.', '["Skip class? You won''t pass.","Amazing lectures","LECTURE HEAVY"]', 'A-', 1, 1, 1, 0, 0, 0, 1482322814, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjAyNzMw', 27602730, '0133715', NULL, 'BIOL-2023', 'BIOL2023', 4, 4, 4, 4, 'Russell is very knowledgeable in his field and is available for students almost all the time. His testing can be funky at times and he''s not always clear what kind of answers he expects on tests. If you are good at remembering lots of details you''ll do fine. He also gives lots of bonus assignments and question which evens it out.', '["ACCESSIBLE OUTSIDE CLASS","Caring","EXTRA CREDIT"]', 'B+', 1, 1, 1, 0, 0, 0, 1482409734, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjE0NjA4', 27614608, '0041142', NULL, 'HKMN-323', 'HKMN323', 5, 5, 5, 3, 'Great professor! Extremely knowledgeable and teaches many things about nutrition that can be applied to everyday living. Talks quite quickly occasionally, but she is always willing to slow down or repeat what she just said. Highly recommended!', '["Respected","Hilarious","Caring"]', 'A-', 1, 1, 1, 0, 1, 0, 1482528815, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjMwODE=', 2763081, '0000768', '7114', 'BUSI-1013', 'BUSI1013', 1, 1, 1, 4, 'One of the worst business prof at Acadia! He can''t seem explain anything well, can''t teach to save his life. He''s all about competition, does not distribute grade fairly. His book is horrible, doesn''t teach you much about accounting.', '[]', NULL, 0, NULL, NULL, NULL, 0, 1, 1100684587, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjMzODY1', 27633865, '0031453', NULL, 'MATH-2233', 'MATH2233', 3, 3, 3, 3, 'Her English is terrible. This made the class harder than it needed to be. She puts all the notes online so you''d be better off skipping class and teaching yourself (like more than half the class did). She marks pretty tough so try to limit mistakes.', '["Tough Grader"]', 'B', 1, 0, 0, 5, 0, 0, 1482894159, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjQ4OTc5', 27648979, '0024045', '7329', 'CHEM-3143', 'CHEM3143', 5, 5, 5, 3, 'Probably the most caring professor in the Chemistry department at Acadia. His office hours are flexible and he goes out of his way to aid his students. Although some students find his lecture style dry, he is very witty and loves to show the applications of the theory. CHEM 3143 required more of a background in analytical chem than biochem.', '["ACCESSIBLE OUTSIDE CLASS","Clear grading criteria","Caring"]', 'A+', 1, NULL, 1, 5, 1, 1, 1483180457, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjQ5MDEx', 27649011, '0024859', '7368', 'CHEM-4723', 'CHEM4723', 4, 4, 4, 4, 'Dr. Jha is an excellent professor for topics in biochemistry, CHEM 4723, as his research background is medicinal chemistry. The course required a thorough background in organic chemistry, so those interested in taking this course should keep the following in mind: testing is on structural modification of drugs, assignments are quite content heavy.', '["Gives good feedback","Skip class? You won''t pass.","Clear grading criteria"]', 'A-', 1, 1, 1, 0, 3, 0, 1483181554, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjUwMTA3', 27650107, '0000768', '7127', 'BUSI-2013', 'BUSI2013', 4, 4, 4, 1, 'Class was a little dull because he just went over questions, but his dry sense of humour key it interesting. He definitely cared about how his students did, and would stop to explain any questions, even if the question already had been asked. If you do the homework he assigns before going to class it definitely helps.', '["Participation matters","Clear grading criteria","Hilarious"]', 'A+', 1, 0, 1, 5, 0, 0, 1483204754, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjUwMTE5', 27650119, '0046920', '7134', 'BUSI-2223', 'BUSI2223', 5, 5, 5, 2, 'I loved him. He was funny, told you exactly what you needed to know, didn''t make anyone feel dumb, and would do many practice questions so you really knew what you were doing. The group projects aren''t bad unless you get a horrible group. Go to him for help and he will help you with questions.', '["Respected","ACCESSIBLE OUTSIDE CLASS","GROUP PROJECTS"]', 'A+', 1, NULL, 1, 5, 6, 0, 1483204962, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjUyNzgx', 27652781, '0040072', '8012', 'ECON-2613', 'ECON2613', 3, 3, 3, 5, 'I took stats with Burc and I spent all semester hating the class. I failed almost everything I handed in. I just didn''t understand anything. However, he helped me as much as he could and I ended up passing the class. If you need help, go to him and he will help you. Going to see him could make the difference between a pass and a fail.', '["Skip class? You won''t pass.","GRADED BY FEW THINGS","Caring"]', 'C-', 1, 1, 1, 0, 2, 0, 1483296277, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NjYwMjU4', 27660258, '0151851', '9699', 'KINE-1333', 'KINE1333', 5, 5, 5, 3, 'Lauren is awesome! She''s related really well to the students and is always helpful and open to any questions.  There''s a lot of material to cover so try not to miss class and don''t be afraid to approach her after class if you have questions.  Definitely recommend to take her class.', '["Gives good feedback","Respected","ACCESSIBLE OUTSIDE CLASS"]', NULL, 1, 0, 1, 0, 0, 0, 1483407816, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3Njc2NDI3', 27676427, '0021421', '9764', 'KINE-2413', 'KINE2413', 5, 5, 5, 2, 'Jonathan is really passionate and makes lectures so interesting! There is a ton of material but the midterms are extremely fair. Gives great examples and keeps the whole class engaged. Makes learning enjoyable!', '["Hilarious","Amazing lectures","Caring"]', 'A', 1, 1, 1, 0, 0, 0, 1483608103, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3Njk0MjM4', 27694238, '0139613', '11057', 'POLS-1403', 'POLS1403', 4, 4, 4, 3, 'The lectures are dry but she does her best to throw jokes in. She is a relatively easy marker, considering I did  not do any of the readings or buy the textbook and was still successful in the course.', '["Participation matters","Clear grading criteria","GROUP PROJECTS"]', 'B+', 1, 1, 1, 0, 2, 0, 1483891768, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3Njk4NDcw', 27698470, '0150055', '7143', 'BUSI-2513', 'BUSI2513', 1, 1, 1, 4, 'By far the worst professor I''ve had in my 4 years. Useless lectures; he reads off the PowerPoints and does not go into any detail, very hard to understand. He is very unorganized and the scheduling for the class was atrocious. We had an "in-class assignment" (actually a test, no notes) worth 10% of our grade 2 days before the final.', '["Tough Grader","GROUP PROJECTS"]', 'B', 1, 0, 0, 5, 1, 1, 1483956546, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3Njk5MTg3', 27699187, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 5, 5, 5, 4, 'Best prof I have had at Acadia University. If you put in the effort he will recognize that and you will get a good mark. If you do not attend class and seek extra help this is a VERY difficult course. This course made me look forward to Mondays and would recommend it to anyone who has a passion in chemistry.', '["Gives good feedback","Clear grading criteria","EXTRA CREDIT"]', 'A+', 1, 1, 1, 0, 0, 0, 1483963049, 1788283342);
