INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NzA4Nzgz', 27708783, '0150055', '7143', 'BUSI-2513', 'BUSI2513', 4, 4, 4, 3, 'I think most people absolutely dislike this man, however, for myself, I found it to not be THAT bad. Yes, I see where everyone is coming from. His assignments are actually tests, his project had no guidance or rubric, and yes, his classes are so boring and dry. However, if you study the slides, you should do fine in the course, simple as that.', '["GRADED BY FEW THINGS","GROUP PROJECTS"]', NULL, 1, 0, 1, 0, 1, 2, 1484061864, 1788283345);
