INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NzE4NDc4', 27718478, '0034413', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'I suck at Chem and almost failed the lab but still managed to pull a B- in this course so like, this is a good prof if you suck at Chem. He was able to keep me awake in the 8:30am lecture which in itself is a feat. Also he brought Ouzo to class and showed us pictures of his new cat so like, 10/10.', '["Respected","Hilarious","Amazing lectures"]', 'B-', 1, 0, 1, 0, 0, 0, 1484169720, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NzM0NDgw', 27734480, '0150055', '7143', 'BUSI-2513', 'BUSI2513', 1, 1, 1, 4, 'If you want to learn by a prof just reading the slide then you have to go teach yourself everything all over again then take his class. He is very rude and doesn''t give you much help when needed. WORST CLASS I HAVE EVEN TAKEN!', '["Tough Grader","TEST HEAVY","GRADED BY FEW THINGS"]', NULL, 1, 0, 0, 0, 0, 0, 1484504469, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3NzQ3NzI4', 27747728, '0021658', '8403', 'ENGL-2163', 'ENGL2163', 5, 5, 5, 3, 'HE IS SO FUNNY. always makes me laugh and actually enjoy class. he brings a lot of history into his lectures which really helps me understand the subject matter. always open to questions and even if you are wrong he is very supportive. he is a tough marker, but once you get used to the way he marks, its very easy to get an A', '["Inspirational","Hilarious","Caring"]', 'A-', 1, 0, 1, 5, 0, 0, 1484735479, 1788283349);
