INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3ODc5MTU4', 27879158, '0139613', '11056', 'POLS-1303', 'POLS1303', 3, 3, 3, 3, 'Pretty boring professor, great person outside of teaching... Knows what she''s talking about, but doesn''t implement her teaching in the most enjoyable ways. Also graded on way to many little assignments... Personally, I think it''s too much work for a first year class.', '["Participation matters","ACCESSIBLE OUTSIDE CLASS","LECTURE HEAVY"]', 'B-', 1, 1, 0, 5, 0, 3, 1488714830, 1788283357);
