INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3ODc5MTcw', 27879170, '0006798', '9230', 'HIST-2213', 'HIST2213', 5, 5, 5, 2, 'Great guy, would take again & highly recommend to anyone... The Turkey jokes are golden. His lectures are interesting and funny, you''ll learn a lot.', '["Skip class? You won''t pass.","Clear grading criteria","Hilarious"]', 'B', 1, 1, 1, 0, 4, 0, 1488715339, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3ODcxMzA0', 27871304, '0012762', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 5, 'One of the hardest markers I''ve had. She''s horrible for feedback, will not tell you when she see''s you doing something the wrong way, so that you continue to screw up. Don''t even get me started about emailing her, you have to be so specific and formal or she refuses to answer. Drop her class as soon as you see it, trust me! Shes Acadias worst prof!', '["Tough Grader"]', NULL, 1, NULL, 0, 5, 3, 0, 1488450214, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3ODk5NDk2', 27899496, '0015754', '8410', 'ENGL-2283', 'ENGL2283', 5, 5, 5, 4, 'Dr. Slights is a wonderful professor and one of the most respected people at Acadia. She has taught me valuable skills about Shakespeare and English literature in general. Anyone that wants to learn something should take her class!! A+++', '["Gives good feedback","Respected","Caring"]', NULL, 1, 1, 1, 5, 0, 0, 1489258173, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTA3MDEx', 27907011, '0024670', '9954', 'MATH-1313', 'MATH1313', 5, 5, 5, 4, 'Great Prof, really hard class. Multiple marking schemes makes a bad test not so bad. Have to show up to class though and the assignments will be HARD.', '["Respected","Skip class? You won''t pass.","ACCESSIBLE OUTSIDE CLASS"]', NULL, 1, 1, 1, 0, 1, 0, 1489513774, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTA3MDI2', 27907026, '0024914', '9943', 'MATH-1013', 'MATH1013', 5, 5, 5, 4, 'Great Prof but Calculus is hard and not much fun. Definitely cares about the students and has tons of office hours.', '["ACCESSIBLE OUTSIDE CLASS","Clear grading criteria","Caring"]', NULL, 1, 1, 1, 5, 1, 0, 1489513921, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTA3MTEw', 27907110, '0001042', '7654', 'COMP-1113', 'COMP1113', 4, 4, 4, 1, 'Show up and pay attention, having facebook etc. open during lectures is a bad idea. Print up your assignments and code from each chapter for your mid-term and your final and the class is easy, like, really easy if you just pay attention.', '["Hilarious","GRADED BY FEW THINGS"]', 'A+', 1, 0, 1, 0, 1, 0, 1489515373, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTA3MTIy', 27907122, '0139613', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 3, 'Great Prof! Not a Politics Major but I''ll likely take another Crandall class before I graduate.', '["ACCESSIBLE OUTSIDE CLASS","Clear grading criteria","Caring"]', NULL, 1, 0, 1, 5, 1, 0, 1489515492, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTE5MjI1', 27919225, '0011703', '6712', 'ART-3013', 'ART3013', 5, 5, 5, 4, 'Wow, this was a hard class but I learned a lot. I exoectef it to be easy but it was definitely not!', '["Tough Grader","Gives good feedback","Respected"]', 'B+', 1, 1, 1, 5, 0, 0, 1489859379, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTI1OTA1', 27925905, '0046920', '7134', 'BUSI-2223', 'BUSI2223', 4, 4, 4, 3, 'Honestly a beauty, you have to go to class, but that''s because he takes the time to give examples and help further your understanding. Is super reasonable with deadlines and marking and just wants to see students do well. Accessible in his office often and will help walk you through any problems. Also makes what would be a boring class, enjoyable', '["Gives good feedback","Skip class? You won''t pass.","ACCESSIBLE OUTSIDE CLASS"]', 'A+', 1, 1, 1, 0, 6, 0, 1490047538, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM1NDIx', 27935421, '0039699', '11057', 'POLS-1403', 'POLS1403', 5, 5, 5, 4, 'He was a great prof. He makes you work for an A, but he cares that you do well and if you show him you''re willing to do the work, he will help you. He lays out clear criteria and makes it easy to follow assignment instructions and homework. He requires you do the readings every week, and its heavy, but he''s a great prof.', '["Get ready to read","Participation matters","Clear grading criteria"]', 'A', 1, 1, 1, 0, 3, 6, 1490213268, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM1NDU4', 27935458, '0152004', '12104', 'WGST-1413', 'WGST1413', 3, 3, 3, 2, 'Sarah is smart and knows what she is talking about, making it easy to understand course concepts. Overall, she was a fine prof, not necessarily one I would take a class with again. Tends to lead boring lectures, but if you ask questions she is sure to make sure you understand.', '["Gives good feedback","Participation matters","Clear grading criteria"]', 'B+', 1, 1, 0, 0, 0, 0, 1490213741, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM1NDcz', 27935473, '0008859', '10907', 'PHIL-1413', 'PHIL1413', 3, 3, 3, 1, 'Boring lectures. Lots of reading, although it''s not necessary to do them because he lays out the topics covered in slideshows quite nicely.', '["Get ready to read","GRADED BY FEW THINGS","LECTURE HEAVY"]', 'B', 1, 1, 0, 5, 0, 0, 1490213961, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM1NzE2', 27935716, '0012981', NULL, 'ENG-1413', 'ENG1413', 3, 3, 3, 2, 'She takes attendance but it is not for grades, you have few opportunities to get grades, a few essays and small debate and maybe a grammar quiz... study poems and short stories and a few novels, I only read the ones I planned to write an essay on! Nice women! Marks based on her overall opinion on her essay no real rubric', '["Get ready to read","Participation matters"]', NULL, 1, 0, 1, 0, 0, 0, 1490216980, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM4NTMy', 27938532, '0033740', '6668', 'APSC-3413', 'APSC3413', 5, 5, 5, 3, 'Tango can be hard to understand sometimes, but he cares and doesn''t take it out on your marks. All around, the guy is just one of the most amazing people and you should appreciate just being able to know the guy. Stay on his good side, go to classes, and make some jokes with him, he''s chill and cool.', '["Hilarious","Caring","GROUP PROJECTS"]', NULL, 1, NULL, 1, 5, 2, 1, 1490275224, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTM4OTQ3', 27938947, '0046920', '7134', 'BUSI-2223', 'BUSI2223', 5, 5, 5, 4, 'Best Professor on campus, cares about his students doing well more than any other teacher at this school. He''s super flexible with assignment dates and test dates if you''re really busy. Goes out of his way to make sure you understand the material. All around great guy.', '["Skip class? You won''t pass.","Caring","GROUP PROJECTS"]', 'A', 1, 0, 1, 0, 7, 0, 1490279537, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MDgx', 27945081, '0024548', NULL, 'MAT-1213', 'MAT1213', 5, 5, 5, 2, 'Very good prof. to understand and teaches very well. If you need any help, he is approachable during class-time and during his office hours. Super duper caring and funny! Recommend him 100%', '["Respected","Inspirational","Amazing lectures"]', 'A+', 1, 0, 1, 5, 1, 0, 1490390234, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MDk1', 27945095, '0037418', NULL, 'MATH-1223', 'MATH1223', 1, 1, 1, 1, 'His lectures are so boring and since I have class in the morning with him, I always snooze off instead of listening to him. In fact, he himself seems rather bored! His accent is horribly thick, making it hard to understand. DO NOT TAKE HIS COURSE!!! I do not recommend him.', '["LECTURE HEAVY"]', 'A-', 1, 1, 0, 5, 0, 0, 1490390514, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MTA4', 27945108, '0031453', NULL, 'MATH-2233', 'MATH2233', 1, 1, 1, 3, 'Her accent makes it very confusing to understand her, even if you sit in the front like I did. Okay and everything but she is unapproachable out of class. She posts every note online which is a plus, so just teach yourself, just like the majority of the teachers.', '["Tough Grader"]', 'B+', 1, 0, 0, 5, 0, 0, 1490390869, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MTI2', 27945126, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 2, 2, 2, 4, 'Had him for OT. Go to class because of daily quizzes on the reading. Amazing lecturer, not so great guy and less stellar marker. He was always interesting but he wants very word for word answers on tests. As for the essay, try to get an old rubric since it is very detailed and will help a lot. This was during core year so it was mandatory.', '["Tough Grader","Participation matters","Amazing lectures"]', 'B', 1, 1, 0, 5, 0, 0, 1490391257, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MTQ4', 27945148, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 2, 2, 2, 3, 'Have him for ManSci. Is not the best prof, he is new so he clearly has a lot of learning to do in terms of prof/student interaction and communication. The quizzes are smaller versions of the midterms so if you don''t know the material well you won''t perform well on the midterm that is usually within a week of the quiz. If struggling go see him.', '["ACCESSIBLE OUTSIDE CLASS","GRADED BY FEW THINGS","LECTURE HEAVY"]', 'A-', 1, 0, 0, 0, 0, 0, 1490391512, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ1MTc0', 27945174, '0003973', NULL, 'BUSI-2993', 'BUSI2993', 1, 1, 1, 2, 'Had her for PD. The class is stupid and is basically to push the Co-op program to second year students. It is not a required core class so get out of it!!! And there were weekly assignments that were super easy, guaranteed A''s if you put like an hour or two of work. However, her midterms were unnecessarily difficult and averages were in the 60''s.', '["Tough Grader","LOTS OF HOMEWORK"]', 'A', 1, 0, 0, 0, 3, 2, 1490391888, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ5Nzgy', 27949782, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 4, 'Teri is an awesome lab instructor! She is very intense which made a lot of the labs stressful, but whenever you need help she''s there. Likes to see you succeed, and is very helpful during office hours if you''re having difficulty with the lab/class material.', '["ACCESSIBLE OUTSIDE CLASS","Hilarious","Caring"]', 'A', 1, 1, 1, 0, 2, 1, 1490563320, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTQ5OTc4', 27949978, '0012762', NULL, 'COMM-1023', 'COMM1023', 1, 1, 1, 4, 'Awful  teacher, does not have any empathy for student performance.  Overload on untestable information and minimal feedback on  work and group presentation.', '["Tough Grader","GROUP PROJECTS"]', 'B', 1, 1, 0, 5, 3, 0, 1490566523, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTU2NzY4', 27956768, '0015959', '7597', 'CODE-1013', 'CODE1013', 5, 5, 5, 2, 'I would highly recommend that anyone take one of Mary''s classes. They are fairly easy- if she sees that you are putting in at least a little work and coming to class, you will get a good grade. She is very caring and willing to push things back for you if you have a good reason. Very reasonable. Amazing woman.', '["ACCESSIBLE OUTSIDE CLASS","Caring","GROUP PROJECTS"]', 'A+', 0, 1, 1, 0, 0, 0, 1490694036, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTU3MzE5', 27957319, '0041312', '8393', 'ENGL-1413', 'ENGL1413', 5, 5, 5, 4, 'One of the best! She''s completely brilliant. She gives AMAZINGLY detailed feedback on your writing projects that is so helpful. Just one semester with her has improved my writing so much! In 90 minutes with her I gained more understanding and appreciation of poetry than in my entire prior education. Understanding with deadlines. I hope she returns!', '["Gives good feedback","Get ready to read","Caring"]', 'A', 1, 1, 1, 5, 3, 0, 1490700838, 1788283362);
