INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTU5NTg1', 27959585, '0050946', '10345', 'MUSI-3003', 'MUSI3003', 2, 2, 2, 4, 'You think, hey sure I''m interested in rock music and how it came about so I''ll take this class it looks super interesting and a light elective. But the prof is so dead set on making it hard so people don''t call it a bird course and as a result gives bad grades.', '["Tough Grader","Get ready to read"]', NULL, 1, 1, 0, 5, 1, 0, 1490721091, 1788283360);
