INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI3OTc4NjQ3', 27978647, '0133594', NULL, 'PSYCH-1023', 'PSYCH1023', 4, 4, 4, 3, 'She is an excellent prof. 9/10 would highly recommend. She is so motivated and driven it is very impressive. Exams are easy if you go to class and take notes. Exams are only based on class lectures', '[]', NULL, 1, 1, 1, 0, 0, 0, 1491048048, 1788283341);
