INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4MDY2OTg0', 28066984, '0024045', '7288', 'CHEM-1023', 'CHEM1023', 3, 3, 3, 4, 'Dr. Zamlynny is a really nice guy that genuinely cares about his students. He really wants them to use his office hours so he can help them. However, his lectures are thick with math and theory, and his accent can be difficult to understand. So take his class knowing you might have to push yourself a little just to follow along.', '["Skip class? You won''t pass.","Caring","LECTURE HEAVY"]', 'A', 1, 0, 0, 0, 1, 0, 1492506348, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4MDY3MDAx', 28067001, '0011148', '10908', 'PHIL-1423', 'PHIL1423', 4, 4, 4, 4, 'Dr. Wilks is super passionate about Philosophy. She is also incredibly intelligent and pulls knowledge from many other faculties. She is very stuck in her views though, so if you differ in opinions you might be in for a rough semester. And she only grades two midterms and a final exam, so if you bomb one, you might bomb the entire class.', '["Gives good feedback","Get ready to read","GRADED BY FEW THINGS"]', 'A', 0, 0, 1, 5, 0, 0, 1492506657, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4MDc4NTgy', 28078582, '0011148', '10908', 'PHIL-1423', 'PHIL1423', 1, 1, 1, 4, 'Dr. Wilks knows a great amount about Philosophy. However, she did not set up a course that was conducive of actually learning it. She gave us a "history of philosophy". I found it fairly interesting, but I found it totally irrelevant to real world application. We spent no time creating our own arguments, but rather learning those of others. 0/10', '["Tough Grader","Inspirational","TEST HEAVY"]', 'F', 1, 1, 0, 5, 2, 0, 1492610117, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4MDczOTgx', 28073981, '0003100', '9271', 'HIST-2593', 'HIST2593', 4, 4, 4, 4, 'He clearly cares about teaching, and has the passion for it, his classes were engaging. He required extensive papers for a second year course, and marked them far to harshly! His exams were not easy, but not hard and did not makeup the bulk of the grade. He''s engaging and intelligent, but he should realize not all knowing, others are intelligent to', '["Tough Grader","SO MANY PAPERS","Amazing lectures"]', 'A', 1, 1, 0, 5, 1, 1, 1492553760, 1788283355);
