INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4MTAwMTc4', 28100178, '0013980', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 4, 'Lance is amazing, definitely the best prof I''ve had so far. He is very open to your ideas and shows he cares. He is extremely helpful, for example, he responds very quickly to emails. In ENGL1406 specifically, the course covered not only texts but films as well, and he presented them in an interesting way. He is so great at what he does, a 10/10!', '["Gives good feedback","Get ready to read","Amazing lectures"]', NULL, 1, 1, 1, 5, 0, 0, 1492807305, 1788283349);
