INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTQ5MjYz', 28949263, '0039663', '7286', 'CHEM-1013', 'CHEM1013', 3, 3, 3, 3, 'His accent is very hard to understand but he is a really funny and adorable teacher. Most of the time he expects us to do the powerpoints and everything ourself the night before class and when giving examples he expects you to know how to do them without teaching you. He waits for everyone to complete the examples before going over them.', '["Get ready to read","Participation matters","Skip class? You won''t pass."]', NULL, 1, 1, 0, 0, 0, 0, 1511293763, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTQ5Mjgx', 28949281, '0021212', '9943', 'MATH-1013', 'MATH1013', 4, 4, 4, 2, 'I find his methods are not exactly the best methods to teach the materials. He does help with homework and will go over anything If you are having trouble. He is a hard marker on exams and such but you are pretty well prepared usually.', '["Tough Grader","Gives good feedback"]', NULL, 1, 0, 1, 0, 0, 0, 1511294025, 1788283353);
