INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTU1MTQ0', 28955144, '0015407', NULL, 'ENGL-2156', 'ENGL2156', 2, 2, 2, 4, 'Being in Dr. Campbells class legitimately gave me anxiety to the point where I had to leave the room. Just the ambience and vibe of being in her class made my hands shake. Her tests are nothing like you would study for. You could study on all the articles online and not one of the articles will be mentioned on the tests.', '["Skip class? You won''t pass.","SO MANY PAPERS","LECTURE HEAVY"]', NULL, 1, 0, 0, 0, 0, 0, 1511430986, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTU1Mjk5', 28955299, '0026142', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 2, 'This man is a straight up diamond in the rough! He loves what he is doing and is passionate about it. I would recommend this class to anyone even if they are not doing business, just for an elective. Why can''t every teacher be like him, he gets his students engrossed with his teaching because he is so enthusiastic about it all.', '["BEWARE OF POP QUIZZES","Hilarious","Amazing lectures"]', NULL, 1, 1, 1, 5, 0, 0, 1511437305, 1788283360);
