INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTYwMDc0', 28960074, '0132938', NULL, 'ECON-3213', 'ECON3213', 5, 5, 5, 3, 'Davis and Kayahan are the main reasons I enjoyed Economics so much. They genuinely care about the material. Davis is always available in his office and enjoys when students come to him for assistance (as long as you tried to figure it out yourself beforehand).', '["Gives good feedback","ACCESSIBLE OUTSIDE CLASS","Clear grading criteria"]', 'A', 1, NULL, 1, 5, 0, 3, 1511623545, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTc0NzY0', 28974764, '0023439', '11701', 'SOCI-2003', 'SOCI2003', 5, 5, 5, 4, 'Brilliant prof with tons of real world experience to back it up. The class material is a bit dry, but she makes it interesting and relevant. There are a lot of projects to do, which is a lot of a work, but it gives you lots of chances to get your grades up. She is very generous with her office time and funny! Only negative: she grades very slowly.', '["Gives good feedback","Respected","SO MANY PAPERS"]', 'A', 1, 0, 1, 5, 0, 0, 1511858397, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTc2Njgx', 28976681, '0029615', NULL, 'SOC-2103', 'SOC2103', 5, 5, 5, 2, 'I was dreading this class, it sounded so boring. Jim made it my favourite class so far! Hilarious guy, super insightful, encourages independent thought and encourages you personally. If you pay attention and participate you will probably be a better human by the time you finish his class. Can''t recommend enough! I will take any class he teaches.', '["Participation matters","Hilarious","Amazing lectures"]', 'A', 1, 1, 1, 5, 1, 1, 1511873019, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTc3MzQ2', 28977346, '0152004', '11707', 'SOCI-2113', 'SOCI2113', 5, 5, 5, 2, 'Sarah was by far the best sociology professor I have ever had. She is caring, understanding and most importantly easy going. She is very approachable and is willing to help you whenever. She makes sure to get everyone comfortable with one another by class discussions and group work! I would definitely recommend taking classes with Sarah!', '["Caring","GROUP PROJECTS","Would take again"]', 'Not sure yet', 1, 1, 1, 0, 1, 0, 1511876892, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTc3MzQz', 28977343, '0152004', '11707', 'SOCI-2113', 'SOCI2113', 5, 5, 5, 2, 'Sarah is an amazing prof. She really wants to make sure everyone does good in her class. If someone doesn''t understand something she will do everything she can to make sure they understand.', '["Tests? Not many","Amazing lectures","Caring"]', NULL, 1, 1, 1, 0, 1, 0, 1511876880, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI4OTcwNzg4', 28970788, '0015959', '7622', 'CODE-3583', 'CODE3583', 5, 5, 5, 2, 'She is a fantastic teacher, my first time in a CODE class and i would take anything that she is teaching. She is so sweet and caring and really wants to see her students do well.', '["Gives good feedback","Respected","ACCESSIBLE OUTSIDE CLASS"]', 'A', 1, 0, 1, 0, 0, 0, 1511807114, 1788283362);
