INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MDMwMjUx', 29030251, '0033740', NULL, 'APSC-1013', 'APSC1013', 4, 4, 4, 2, 'Tango is great, although not very experienced. He genuinely cares about the students, and will go out of his way to help you, although he often simply can''t. Ultimately though, the design course is so easy that anyone struggling with it has no business blaming the teacher. Also, his enthusiasm is hugely entertaining.', '["Inspirational","Hilarious","Amazing lectures"]', 'A', 1, 1, 1, 0, 0, 0, 1512380163, 1788283350);
