INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTE0MjI5', 29114229, '0024859', '7286', 'CHEM-1013', 'CHEM1013', 1, 1, 1, 4, 'His accent isnt as bad as people say, and its not him that makes the class not enjoyable, its the chemistry. I find chemistry very difficult and even sitting in the classroom was a snooze fest. I ended up skipping a lot and reading and studying notes from his very nicely done power points. Weekly assignments, 3 midterms, and a final.', '["LOTS OF HOMEWORK"]', 'C-', 1, 0, 0, 0, 1, 1, 1512863571, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTE1MDE3', 29115017, '0037539', '9979', 'MATH-2013', 'MATH2013', 4, 4, 4, 5, 'Dr. Curry is great overall. Very challenging course, but its a course for math majors and chem majors so it should be hard. Lots of homework, have to dedicate multiple hours a week to assignments. No midterms, just five unit tests that were 2-3 pages each. Very enthusiastic but can be a bit scattered at times.', '["LOTS OF HOMEWORK","ACCESSIBLE OUTSIDE CLASS","Tests? Not many"]', 'Not sure yet', 1, 0, 1, 5, 0, 1, 1512870721, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTE2NzE3', 29116717, '0022952', NULL, 'NURT-1503', 'NURT1503', 3, 3, 3, 5, 'I took this class as an elective, and boy was that a mistake. This class is easily the hardest class I''ve taken in all my years of schooling. Dr. Durant most definitely knows what he is talking about, but he doesn''t explain it well. It is almost impossible to study for, and YOU MUST PASS THE EXAM OR YOU FAIL THE COURSE! Do not take as an elective.', '["Skip class? You won''t pass.","Tests are tough","LECTURE HEAVY"]', NULL, 1, NULL, 0, 0, 2, 0, 1512909526, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTE2NzU1', 29116755, '0016415', NULL, 'HIST-2633', 'HIST2633', 5, 5, 5, 3, 'Dr Duke was an amazing prof to have. I enjoyed every lecture I had with him, he makes the information easy to understand and he will entertain you along the way. He is highly knowledgeable in his field. The final group project was an amazing experience and I am very glad to have been a part of it. I would absolutely take any class that he teaches!!', '["Inspirational","Amazing lectures","GROUP PROJECTS"]', NULL, 0, NULL, 1, 0, 3, 0, 1512909812, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTE2ODE0', 29116814, '0019405', '8735', 'FRAN-1113', 'FRAN1113', 5, 5, 5, 2, 'I took French as an elective, and I have to say Dr. Delpeche was a real treasure. He made things easy to understand, and his class wasn''t really all that hard. He wants his students to succeed and will try his hardest. He can be a bit hard to understand at times, and his notes are an absolute mess but overall I am very glad to have him as my prof.', '["ACCESSIBLE OUTSIDE CLASS","Hilarious","Caring"]', NULL, 1, NULL, 1, 5, 0, 0, 1512910194, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTExODQ3', 29111847, '0037418', NULL, 'MATH-2233', 'MATH2233', 1, 1, 1, 3, 'Dr. Lu did not teach the stats lab I was in. On several occasions he simply stared at his own material, totally dumbfounded. His lab average was 40% lower than the lab under another instructor. He is the graduate organizer in math, so will be around awhile. AVOID AT ALL COSTS', '[]', NULL, 1, 1, 0, 5, 0, 0, 1512847783, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTI3NjUx', 29127651, '0149576', '11090', 'POLS-2683', 'POLS2683', 5, 5, 5, 4, 'Super good guy, pretty easy marker. always available during office hours unless otherwise stated pretty sarcastic so don''t take his jokes personally', '["Gives good feedback","Participation matters","Amazing lectures"]', NULL, 1, 0, 1, 5, 11, 0, 1512988102, 1788283357);
