INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTU5ODE0', 29159814, '0040072', '8012', 'ECON-2613', 'ECON2613', 5, 5, 5, 4, 'At the beginning of the year, Econ 2613 (Stats) was my least favourite class but by the end of the year I was kind of sad it was ending. Burc was a great prof and he was always available to help in and/or out of class. If you are actually interested in learning something new and being challenged, Burc is the professor for you.', '["Gives good feedback","Skip class? You won''t pass.","ACCESSIBLE OUTSIDE CLASS"]', 'A-', 1, 0, 1, 0, 0, 0, 1513103938, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTU5ODU0', 29159854, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 4, 'I would not recommend Kendra Carmichael. She is vague and does not support students like other profs do. Classes were hard to sit through and the marking was so picky it wasn''t even fair. Top it all off with a group project that''s worth 20% of your mark where you get the exact same as all other members. AVOID', '["Tough Grader","GRADED BY FEW THINGS","GROUP PROJECTS"]', 'A', 1, 1, 0, 5, 2, 0, 1513104026, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTY0NTM5', 29164539, '0031459', NULL, 'CLAS-1123', 'CLAS1123', 5, 5, 5, 2, 'Sonia Hewitt is one of the nicest profs that I have had so far at Acadia. Although her classes can be a little dull at times - due to the material - she makes it much better than it could be with a different prof. She knows a lot about the material, is really into it, and clearly enjoys teaching the course which makes the lectures so much better.', '["Caring","LECTURE HEAVY","Would take again"]', NULL, 1, 1, 1, 5, 3, 0, 1513115984, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTYyMDk5', 29162099, '0034413', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Amazing prof, so funny and nice. Really cares about his students and the topics he is teaching. I love him.', '["Get ready to read","Hilarious","Would take again"]', NULL, 1, 0, 1, 0, 1, 0, 1513109835, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MTYyMTkx', 29162191, '0034413', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Matthew Lukeman is my favourite prof at this university, he is so precious and pure. He smiles at me like I''m his best friend, yet I have only spoken to him to get my midterms back. His lectures saved my life, and are the reason I don''t completely hate chemistry. Also take Chem in our world, you won''t regret it.', '["Respected","Hilarious","Amazing lectures"]', NULL, 0, 1, 1, 0, 0, 0, 1513110042, 1788283351);
