INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MjU3OTA2', 29257906, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 4, 4, 4, 2, 'If you show up and pay attention, you will understand that the material is not hard to master. He takes his time going through the core problems step by step to grasp the concept as majority of the work is based on these fundamentals. However, if you don''t put in the work of a &quot;student&quot;, don''t expect to pass.', '["Gives good feedback","ACCESSIBLE OUTSIDE CLASS","Would take again"]', 'A+', 1, NULL, 1, 5, 0, 0, 1513603706, 1788283345);
