INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzIwODA=', 2932080, '0016415', NULL, NULL, 'ENVIROHIST', 5, 5, 5, 3, 'Hands down my favorite class i''ve taken in my 4 years at acadia.  Not only is he extremely clear, but the course material is interesting as well.  A fun good humoured prof who really cares about his students.  I only regret not having had the chance to take more classes from him!! Take one if you ha', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1102419920, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzIxMzc=', 2932137, '0003429', NULL, NULL, 'DEVELOPMENT', 4.5, 5, 4, 5, 'Extremely interesting course and very good teaching skills.  ALOT of information to learn, but she is a fair tester so it works out.  The class takes alot of work - but its worth it!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1102420174, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzIxNjIw', 29321620, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 4, 4, 4, 4, 'One of the most difficult classes I''ve taken so far. Dr. Ellis knows his material inside and out and is very willing to help but you must attend class. His tests are very long but he gives practice tests that are almost identical to the real thing which is very helpful. Hardest part of the course is the lab (especially the lab exam).', '["Tough Grader","Skip class? You won''t pass."]', 'A-', 1, 1, 1, 0, 0, 0, 1513989244, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzQ5MDk2', 29349096, '0024670', '9954', 'MATH-1313', 'MATH1313', 3, 3, 3, 5, 'She''s a very nice lady, but she makes things way more difficult and confusing than they need to be. Assignments and tests are HARD. She recycles a lot of her questions, so it''s helpful to have tests and assignments from previous years. Textbook is useless. She has multiple grading schemes which gives you somewhat of a shot at passing.', '["Tough Grader","Skip class? You won''t pass.","Tests are tough"]', 'A-', 1, 0, 0, 0, 0, 0, 1514445376, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzU3NTI2', 29357526, '0001916', NULL, 'STATS-2233', 'STATS2233', 3, 3, 3, 3, 'Tries his best to make the material understandable. Little boring lectures but a really nice guy.', '["Respected","ACCESSIBLE OUTSIDE CLASS","Tests? Not many"]', NULL, 1, 0, 1, 0, 0, 0, 1514570505, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzUyMjA2', 29352206, '0037751', '11149', 'POLS-3693', 'POLS3693', 4, 4, 4, 4, 'Dr. Brickner cares a lot for her students, but it was difficult this semester because of labour action. She gets feedback on her assignments back late (almost a month for an essay) and it became frustrating when we went into our final exam not knowing our grades. That being said, she is incredibly supportive and wants us to learn. She''s passionate!', '["Tough Grader","Get ready to read","LECTURE HEAVY"]', 'A', 1, 1, 1, 5, 0, 0, 1514485568, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzUyMjQ3', 29352247, '0139613', '11189', 'POLS-4403', 'POLS4403', 5, 5, 5, 4, 'Dr. Crandall''s specialty is constitutional law, so this class fit perfectly with her area of expertise. The reading was heavy and the assignments were sometimes boring, but she understood that and made it as interesting as it could be. The final project was a podcast instead of an essay, and participation was crucial throughout the course!', '["Gives good feedback","Participation matters","Clear grading criteria"]', 'A', 1, 1, 1, 5, 0, 0, 1514485889, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzUyMjYy', 29352262, '0149576', '11115', 'POLS-3173', 'POLS3173', 5, 5, 5, 3, 'Dr. Mutlu cares about his students and it shows in the course. He is open to extensions and different learning styles, and his passion for IR shines through during simulations. He isn''t afraid to challenge students and wants us to have a good time while learning, and that is a combination not found in many profs. Dr. Mutlu is one of a kind', '["Gives good feedback","Participation matters","Caring"]', 'A+', 1, 1, 1, 0, 10, 0, 1514486073, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzUyMjg2', 29352286, '0003100', '9362', 'HIST-3533', 'HIST3533', 4, 4, 4, 4, 'Dr. Henderson loves his subject and his lectures show it, even if the subject is profoundly boring. Some texts were quite boring and I found his grading somewhat arbitrary as there was a heavy focus on group projects (30% of the total grade) and that had a detrimental effect on my mark. However, he loves his craft and deserves a lot of respect', '["GRADED BY FEW THINGS","Caring","GROUP PROJECTS"]', 'A-', 1, 1, 0, 0, 1, 0, 1514486338, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzY1OTA4', 29365908, '0149576', '11090', 'POLS-2683', 'POLS2683', 4, 4, 4, 3, 'Professor Mutlu''s lectures were interactive and he would often engage in lively debate with a few of the more vocal students in class. Overall, I feel like I absorbed the information pretty well. His tests and grading are really fair and you know what''s expected of you.', '["Participation matters","Skip class? You won''t pass.","Tests? Not many"]', 'A+', 1, NULL, 1, 5, 4, 3, 1514768186, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzY2Mjk5', 29366299, '0037751', '11096', 'POLS-2893', 'POLS2893', 4, 4, 4, 4, 'Her lectures were very engaging and flexible, with us frequently spending at least half the time in debate. She didn''t seem to draw much on the required text in class, but did expect us to reference it in the papers and final. Overall a very accessible and interesting course; would recommend.', '["Gives good feedback","Respected","Tests? Not many"]', 'A', 1, 0, 1, 5, 0, 0, 1514800635, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzY2MzA4', 29366308, '0000671', '8618', 'ESST-3003', 'ESST3003', 3, 3, 3, 3, 'Professor Bissix''s lectures were very laid back and interesting. Sometimes this was appreciated, as we were given the opportunity to influence our learning processes, but sometimes it seemed to be due to disorganisation and the lack of clear deadlines for assignments made a very Type-A person like myself stressed at times.', '["Tough Grader","GROUP PROJECTS"]', 'A', 1, NULL, 0, 5, 1, 0, 1514801046, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzc2MjE=', 2937621, '0000957', NULL, NULL, 'ANTHRO', 4.5, 5, 4, 1, 'Great prof..definaty reccomend to the non soc majors just cause her classes are so intersting and fun! Her accent cracks me up...shes wonderful!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1102443960, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5MzcxNTQ5', 29371549, '0024670', '9954', 'MATH-1313', 'MATH1313', 4, 4, 4, 5, 'Great professor who clearly loves math. She turned my hardest course into one of my favourite.', '["Gives good feedback","Tests are tough","LECTURE HEAVY"]', 'A-', 1, 1, 1, 0, 0, 0, 1514894526, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzg5MjE3', 29389217, '0037539', '9979', 'MATH-2013', 'MATH2013', 2, 2, 2, 4, 'Dr. Curry would be a really great prof if she weren''t so disorganized. She really cares about students doing well, but her level of forgetfulness/ general disorganization makes this class way more difficult than it needs to be. Quizzes are only difficult because she doesn''t specify what will be on them, so treat each quiz like a cumulative midterm.', '["LOTS OF HOMEWORK","Caring","Tests are tough"]', 'A-', 1, 0, 0, 5, 1, 0, 1515084767, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzk1NDU0', 29395454, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 4, 4, 4, 2, 'She is very approachable. Although she is quiet, if you ask her to re-explain something, she has no problem doing so. She is very organized. Also gives hints on what kind of questions are going to be on the midterms. Overall great prof.', '["ACCESSIBLE OUTSIDE CLASS","Caring","Would take again"]', NULL, 1, 0, 1, 0, 0, 0, 1515165054, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzk1NDg2', 29395486, '0021212', '9943', 'MATH-1013', 'MATH1013', 4, 4, 4, 4, 'He is very approachable, and always makes sure that the students understand. Always open to answer any questions from assignments, or tests. He is very clear on how to answer questions. Overall a really good prof.', '["Tough Grader","Gives good feedback","ACCESSIBLE OUTSIDE CLASS"]', NULL, 0, 0, 1, 0, 0, 0, 1515165297, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzk1NjEy', 29395612, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 4, 4, 4, 4, 'She is very intimidating at first, but do not be scared to approach her because she is always available to answer questions and she makes sure that the students understand the material. Make sure to record all the procedures before hand, since she checks every class. She is strict but she is a great prof who knows her stuff.', '[]', NULL, 1, 1, 1, 0, 0, 3, 1515166163, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Mzk1Njk5', 29395699, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 3, 3, 3, 2, 'She takes so long to go over examples, and then leaves little time to do the assignments. She is very approachable and kind, but her work is just so slow. The labs were very boring and felt like a waste of time. The material is not hard it is just boring. Overall she is a good prof and cares for her students', '[]', NULL, 1, 1, 0, 5, 0, 0, 1515166771, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDA5MzA0', 29409304, '0003479', '10119', 'MUSI-1063', 'MUSI1063', 5, 5, 5, 2, 'I took music theory for non music majors with Eugene and it was a lot of fun! He explained every topic so clearly and was very easy to follow. His tests were fair and easy as well. Makes music theory fun and easy!', '["Gives good feedback","Skip class? You won''t pass.","ACCESSIBLE OUTSIDE CLASS"]', 'A+', 1, 1, 1, 0, 0, 0, 1515387676, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDA5MzEz', 29409313, '0133715', '6987', 'BIOL-3613', 'BIOL3613', 2, 2, 2, 4, 'This was by far one of the hardest classes I have ever taken. He lectures fast and talks fast so its difficult to take notes. He jumps around a lot in lecture and its hard to follow. His tests are long and difficult, and seems to ask about the smallest details.', '["Tough Grader","Tests are tough"]', NULL, 1, NULL, 0, 0, 1, 1, 1515388118, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDE4NjE5', 29418619, '0034094', NULL, 'BUS-2413', 'BUS2413', 2, 2, 2, 5, 'He is so tough on group project if you in a bad group good luck! Also he is a tough marker and cant do anything if your group is in trouble.', '["Tough Grader","SO MANY PAPERS","GROUP PROJECTS"]', 'C-', 1, 1, 0, 0, 4, 1, 1515474482, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDI0Njkx', 29424691, '0047642', NULL, 'BUSI-3773', 'BUSI3773', 5, 5, 5, 2, 'Attendance is not mandatory but for what reason would you miss one of Ryan''s Classes? Honestly a life changing professor. If you care you''ll get the grade. Acadia has won the lottery with this one. G.O.A.T.', '["Respected","Inspirational","Caring"]', NULL, 1, 0, 1, 5, 0, 0, 1515532885, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDIxOTIw', 29421920, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 4, 'Todd is really great and his lectures are super interesting! His only downfall is in his tests, there is an insane amount of information to memorise. He asks questions on the specific facts on his slides and not theory questions. So you have to memorise EVERYTHING. Other than that, an absolute gem!!!', '["Hilarious","Caring","Tests are tough"]', 'A', 1, 0, 0, 0, 0, 0, 1515513175, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDM0ODc4', 29434878, '0047642', '7246', 'BUSI-4773', 'BUSI4773', 5, 5, 5, 3, 'Ryan is an unbelievable professor. He is very inspirational and will do everything he can to help you succeed. He is like having a good friend as a prof that wont ever get upset or disrespect anyone. If you just want to sit down on your computer the whole class, this is not for you. Showing up to the classes and participating alone will get you far', '["Gives good feedback","Participation matters","Amazing lectures"]', 'A-', 1, NULL, 1, 0, 0, 1, 1515657386, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDM5NTY4', 29439568, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 5, 5, 5, 3, 'Very good prof. She knows a lot and takes her time to explain it. Very open to questions and approachable. Her tests are straightforward, no trick questions. She tests mainly on like facts, not so much applied knowledge.', '["Skip class? You won''t pass.","Clear grading criteria","TEST HEAVY"]', NULL, 1, 1, 1, 5, 0, 0, 1515703793, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDQ1Mzk=', 2944539, '0012762', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 5, 'She is having personal issue. That''s why she failed me.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1102500128, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDUwMzQz', 29450343, '0001612', NULL, NULL, '2050L', 5, 5, 5, 3, 'Helene is amazing! Had her for Microbiology lab and I can''t even begin to describe how wonderful she is. Very helpful, even with lecture material, and sincerely cares about students'' progress.', '["Hilarious","Amazing lectures","Caring"]', 'A-', 1, 1, 1, 0, 0, 0, 1515941983, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDUzNzM0', 29453734, '0018550', '6856', 'BIOL-2043', 'BIOL2043', 4, 4, 4, 3, 'Awesome Prof! His lectures are concise and aren''t packed with useless information. You learn what you''ll be tested on. If you go to class you will do great.', '["Skip class? You won''t pass.","Would take again"]', 'A', 1, NULL, 1, 0, 0, 0, 1516020978, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NDc3MzE4', 29477318, '0012981', NULL, 'ENG-3553', 'ENG3553', 5, 5, 5, 3, 'If you''re interested in modern poetry, this a great course! Interesting selection of poems (including the more shocking stuff by Olds and Sexton!).', '["Gives good feedback","Get ready to read","Participation matters"]', NULL, 1, 1, 1, 0, 1, 0, 1516354312, 1788283350);
