INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Njk5OTUz', 29699953, '0132938', '7998', 'ECON-1023', 'ECON1023', 5, 5, 5, 4, 'Interesting lectures, uses examples that are current and intuitive. Memorization won''t help, you need to understand concepts thoroughly, and be able to apply them to real-life scenarios. He does teach everything you need to know in class, but he doesn''t put all the info on the slides, so attendance is pretty much mandatory.', '["Skip class? You won''t pass.","Amazing lectures","LECTURE HEAVY"]', NULL, 1, 1, 1, 0, 0, 3, 1522098160, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5Njk5OTc5', 29699979, '0026142', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 2, '&quot;I care more about the people my students become than the scores on the tests they take&quot; is the perfect quote to describe Mike.', '["Respected","Inspirational","ACCESSIBLE OUTSIDE CLASS"]', NULL, 1, 0, 1, 5, 0, 0, 1522098524, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzA1OTk2', 29705996, '0037406', '11326', 'PSYC-2023', 'PSYC2023', 5, 5, 5, 5, 'Randy-Lynn is so awesome. Rated high in difficulty because the material is tough but she tries her hardest to help everyone succeed. She goes through lots of practice. Try and go to class because the material is hard but she posts good slides. Only two tests in the course plus the exam. She always makes funny comments which make my day.', '["Inspirational","GRADED BY FEW THINGS","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1522187314, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzA2MDE2', 29706016, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 5, 5, 5, 5, 'Karmen is so awesome, and always ready to help. She will do anything to help you succeed. Lots of papers for the lab, and assignments. She gives good feedback though, and there is room for improvement. E-mail''s back quickly. I absolutely loved her and she is the only thing that made RDA bearable. Content is very difficult.', '["Tough Grader","Gives good feedback","SO MANY PAPERS"]', NULL, 1, 1, 1, 0, 0, 0, 1522187487, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzA5NTUw', 29709550, '0000907', '6616', 'APSC-1113', 'APSC1113', 3, 3, 3, 2, 'Not a great prof but if you do the assignments and make good notes before midterms its not too hard to get an A. Lectures are just countless examples and he''s too baked to even know how to do them', '["Gives good feedback","Clear grading criteria"]', 'A', 1, 0, 1, 5, 5, 0, 1522248610, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzE2NjQ1', 29716645, '0016655', '9273', 'HIST-2613', 'HIST2613', 1, 1, 1, 4, 'Marks way too hard for what the class is supposed to be. Doesn''t give any guidelines or rubrics for projects and papers. Talks way too much about nothing important; rambles and goes on tangents that don''t make sense with the material. Likes to talk about himself/ hear himself talk. Interesting material but he butchers it. I regret taking this class', '["Tough Grader","GRADED BY FEW THINGS","GROUP PROJECTS"]', 'Not sure yet', 1, 0, 0, 0, 0, 1, 1522350636, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzE5NTI0', 29719524, '0018154', '11364', 'PSYC-3133', 'PSYC3133', 5, 5, 5, 4, 'Karmen is so fun and has the best anecdotes in class!', '["Tough Grader","Respected","Hilarious"]', NULL, 1, 1, 1, 0, 0, 0, 1522420094, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzEyMTQ3', 29712147, '0133592', NULL, NULL, '1110LAB', 4, 4, 4, 3, 'Juan was a very funny professor and was very caring about his students. I personally had to stop by his office when I was confused on my lab report and needed help. He was interested in trying to help me and cared about whether I did good or not. He made sure when I left that I understood everything well.', '["Respected","Hilarious","Caring"]', 'B+', 1, 1, 1, 0, 1, 1, 1522275719, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzQ3Njk3', 29747697, '0000907', '6616', 'APSC-1113', 'APSC1113', 2, 2, 2, 3, 'Needs to learn how to teach. TAs were very harsh on assignments, he has no office hours, no sympathy for students well-being, no solid criterion in which you can follow, his voice is quiet to the point where I struggle to not fall asleep, class average on test 1 was 30 percent... too much for 250 characters.', '["Tough Grader","LOTS OF HOMEWORK"]', 'A-', 1, 0, 0, 5, 2, 0, 1522928122, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTI5NzU1NjQ=', 2975564, '0021212', '10007', 'MATH-2723', 'MATH2723', 4.5, 4, 5, 3, 'He knows his**** and has a quirky math sense of humour....Good Prof', '[]', 'B+', 0, 1, NULL, NULL, 0, 0, 1102685362, 1788283353);
