INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzEzMzU1', 21313355, '0002460', NULL, 'MUSI-4666', 'MUSI4666', 2, 3, 1, 5, 'Although she helped me improve my voice, she was by far the least supportive professor I''ve ever had. She''d forget what she assigned me and when I''d remind her she''d act like I made it up. There wasn''t any continuity. During my last lesson she decided to begin teaching me an entire new way to approach my entire repertoire..two days before my jury.', '[]', NULL, 0, NULL, NULL, 1, 1, 0, 1359674981, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzEzMzg3', 21313387, '0001453', NULL, NULL, 'SCENESTUD', 4, 5, 3, 2, 'Paula is amazingly positive. I had her for a month while my teacher was away, and her lessons left me feeling so happy. Although I don''t think she transforms her students voices like other professors do, she refines them wonderfully.', '[]', NULL, 0, NULL, NULL, 2, 0, 0, 1359675481, 1788283362);
