INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzMwMjk1', 21330295, '0034413', '7296', 'CHEM-1123', 'CHEM1123', 5, 5, 5, 2, 'Dr. Lukeman is one of the best teachers I have ever had! He makes class very interesting and exciting with little stories he tells and experiments he does pertaining to chemistry. He is also extremely good at explaining material and is very approachable for extra help! He is SO good looking too which is a bonus!', '[]', NULL, 0, NULL, NULL, 3, 1, 0, 1360337732, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzU5NDQw', 21359440, '0000671', '8618', 'ESST-3003', 'ESST3003', 2, 2, 2, 4, 'Glyn is a great professor. By nature, he is definitely not a hand-holder.  He prefers his students to learn for themselves, which is extremely effective under his guidance .  In my opinion, many students need to be more open to his style of teaching and make an effort to take initiative in his courses as to achieve the fullest potential benefit.', '[]', NULL, 0, NULL, NULL, 5, 3, 0, 1361540810, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzU5NjQ2', 21359646, '0034933', NULL, 'RECR-3103', 'RECR3103', 4.5, 4, 5, 2, 'The material he chooses to cover in History and Phil. of Leisure is extremely interesting!  The delivery is also really effective (not everyone''s cup of tea, though).  His touch of dry humour made this course even better!', '[]', NULL, 0, NULL, NULL, 4, 0, 0, 1361547246, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIxMzU5Njg2', 21359686, '0016779', '8393', 'ENGL-1413', 'ENGL1413', 2.5, 1, 4, 4, 'Interesting lectures, but his expectations in grading do not reflect what he teaches. He was not helpful in providing helpful feedback.  After receiving an A- on a rough draft of a paper, I asked how I could improve on the final. He responded by telling me I had done fine and did not need to improve, leaving me questioning the validity of my mark.', '[]', NULL, 0, NULL, NULL, 5, 2, 1, 1361548281, 1788283355);
