INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyMTY0ODU4', 22164858, '0036828', '7830', 'CREL-1206', 'CREL1206', 2, 3, 1, 3, 'I love Donna...very down to earth and easy to talk to. The only thing, she is very dis-organized! She is fairly easy, is willing to help but only allows 15 min per person and then only confuses you more once you get there! Her class is dry and you don''t seem to cover anything! If you want to learn the course you have to read the textbook! GOOD LUCK', '[]', NULL, 0, NULL, NULL, 5, 0, 0, 1381263086, 1788283344);
