INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyMTc1NDM0', 22175434, '0023439', '11770', 'SOCI-3223', 'SOCI3223', 4.5, 5, 4, 2, 'Awesome prof. She does tend to get off topic at times but she is extremely funny and engaging. Always willing to help and is very interested in what she is teaching.', '[]', NULL, 0, NULL, NULL, 3, 0, 0, 1381672730, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyMTkxMDA0', 22191004, '0016779', NULL, NULL, '18THCENTURY', 3, 3, 3, 5, 'Scary at first! Not always approachable. Take the time to go to office hours & take advice on how to improve, it will pay off. The fact that I had to push myself made it so much more rewarding in the end when I got an A- on my final essay. Took time to point out the grade before leaving the exam & expressed that he was proud with my improvement.', '[]', 'B+', 0, 0, NULL, 4, 0, 1, 1382100529, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyMjQ1MDk4', 22245098, '0024914', '9943', 'MATH-1013', 'MATH1013', 2.5, 3, 2, 4, 'Holger is a very kind man. I just wish he was a good teacher. He''s not clear at all, does not properly explain things, and he expects you to be able to understand and apply concepts that are only tangentially related to what is taught in class.', '[]', 'Not_Sure_Yet', 0, 0, NULL, 4, 13, 0, 1383357141, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyMjY2ODYz', 22266863, '0004338', NULL, NULL, 'KINE', 4, 5, 3, 1, 'She doesn''t want you to just memorize and spit out facts, she really wants you to actually apply the information you''ve learned in real life settings, which is very useful and I feel more prepared for my future career because of it. She''ll sometimes go off on random tangents, but you don''t mind because they''re so interesting!', '[]', NULL, 0, NULL, NULL, 2, 0, 0, 1383746905, 1788283353);
