INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzAzNDQz', 22703443, '0012762', '7647', 'COMM-1213', 'COMM1213', 2.5, 2, 3, 4, 'This class is a lot harder than a first year business communication class should be, but Prof Carmichael is very interested in and loves communication. She is a tough marker, but she is fair. She didnt give us any real surprises. Great lady to talk to and she can be quite helpful. Do your work, don''t think it''s a bird course and you will do fine.', '[]', 'F', 0, 1, NULL, 1, 2, 1, 1389004388, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzEwNjU1', 22710655, '0001042', '7656', 'COMP-1123', 'COMP1123', 2, 1, 3, 2, 'The assignments in his classes are way easier than they should and he does not prepare students well enough for their future classes. I went into the Exam with an A and came out with a C because I did what the question asked, which was not what he wanted.', '[]', NULL, 0, NULL, NULL, 5, 3, 2, 1389093118, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzM4NDU0', 22738454, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 4, 4, 4, 2, 'Great lab professor. Lots of different experiments done so you get  range of practice with a wide range of equipment and chemicals. Quizzes are easy as she always tells you the week before what is on them. Also walks you through the lab before so you know exactly what is expected. She is awesome.', '[]', 'Rather_Not_Say', 0, 1, NULL, 1, 0, 1, 1389528024, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzM4NDY3', 22738467, '0003100', '9185', 'HIST-1413', 'HIST1413', 4, 4, 4, 2, 'Great history prof! His lectures are for the most part pretty interesting, and very little depends on you reading the textbook. He also does group work activities which are easy grades to help boost your mark. Midterms are easy if you study, and overall a very engaging, fun prof! Highly recommend the course', '[]', NULL, 0, NULL, NULL, 3, 0, 0, 1389528313, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzU3NTAz', 22757503, '0018259', NULL, 'MUSI-1130', 'MUSI1130', 5, 5, 5, 4, 'Michelle is the best, she will go above and beyond to help you understand the material and tries her best to make it a fun class, which is not easy to do with theory. I really hope she gets a more permanent position at the school of music', '[]', 'A+', 0, 1, NULL, 4, 0, 0, 1389807609, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzU4MjU1', 22758255, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 3, 2, 4, 5, 'The most ridiculously hard marker I have ever come across. Expects 2nd years students, who are learning brand new concepts and topics to write like they''re writing their dissertation. She is unbelievable. Organized yes, but all in all I couldn''t stand her. I also found her condescending.', '[]', NULL, 0, 1, NULL, 1, 1, 2, 1389816244, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzY4NDkw', 22768490, '0012118', '6644', 'APSC-2413', 'APSC2413', 1, 1, 1, 4, 'Arrogant, and often wrong. Makes up rules. Grades seem arbitrary.', '[]', NULL, 0, NULL, NULL, 5, 7, 1, 1390040452, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzc2MzYw', 22776360, '0021658', '8485', 'ENGL-3743', 'ENGL3743', 4.5, 5, 4, 3, 'He''s really helpful if you go see him in his office about writing your paper. But he''s a hard marker. As long as you go to class and participate he''s a really good prof and he makes lectures interesting and enjoyable.', '[]', NULL, 0, NULL, NULL, 4, 0, 0, 1390300048, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzgyMDI2', 22782026, '0016390', NULL, NULL, 'HISTANY', 4.5, 5, 4, 3, 'He''s a great professor. For any History Students, you will not find a professor more passionate about what he is teaching, or more eager to share that passion with his students. He tried to tie together all the historical thread to focus on the big picture, which is a powerful way of teaching history for those who catch on. One of the best Acadia.', '[]', NULL, 0, NULL, NULL, 5, 0, 0, 1390405473, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyNzk1OTgz', 22795983, '0022921', '10984', 'PHYS-1023', 'PHYS1023', 1, 1, 1, 5, 'Very confusing. He follows the book to some extent but makes up some things himself which make no sense, and doesn''t explain. Overall, avoid taking a first year class with him, considering he usually only  teaches 3rd and 4th year quantum mechanics.', '[]', 'Incomplete', 0, 0, NULL, 3, 0, 1, 1390815177, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODAyNTU0', 22802554, '0015754', NULL, NULL, 'SHAKESPEARE', 2, 1, 3, 1, 'She is passionate about Shakespeare and her enthusiasm is certainly infectious. But I found her to be unsympathetic to extenuating circumstances, especially when it came to extensions. I know profs aren''t here to coddle, but c''mon: a fatally ill family member?  We''re expected to be "intellectually productive" with that on our minds? Her words.', '[]', NULL, 0, NULL, NULL, 4, 1, 0, 1390961975, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODIwMzUy', 22820352, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 2, 1, 3, 4, 'If for some reason you came to university to become less intelligent heres the class for you. Made up definitions, basic concepts most elementary students know, and aimless reading are all the bonuses you get for taking a course with this clown. Save yourself from hours of pulling your hair out and just don''t come to acadia', '[]', NULL, 0, NULL, NULL, 5, 4, 3, 1391600422, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODIwOTYy', 22820962, '0037418', '9990', 'MATH-2243', 'MATH2243', 1, 1, 1, 4, 'Very hard to follow in class, notes for the class are the only help.', '[]', 'Not_Sure_Yet', 0, 0, NULL, 4, 0, 0, 1391613218, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODM5NDQz', 22839443, '0016390', NULL, 'HIST-1106', 'HIST1106', 4.5, 5, 4, 3, 'This guy was the reason I switched my major to history. Besides being a total cutie, his lessons had depth, were extremely challenging, and he had a good sense of humor. Some of the readings really made me think, which is what a like, rather than memorizing facts.', '[]', NULL, 0, NULL, NULL, 5, 0, 0, 1392287679, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODM5NDU0', 22839454, '0006798', '9228', 'HIST-2203', 'HIST2203', 5, 5, 5, 2, 'Be prepared for lots of Turkey jokes. If you get the notes from the lectures, that''s all you need to do okay. I thoroughly enjoyed the humor and he was always prepared and a fast marker. He actually learned my name, which is rare in large classes. Reasonable and eager to answer questions. Highly recommend.', '[]', 'B+', 0, 1, NULL, 2, 2, 0, 1392288015, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODQ0ODI5', 22844829, '0039699', NULL, NULL, 'POLITICALTHEORY', 3, 3, 3, 5, 'Well, 10 years since I''ve graduated, and this professor is the only name I still remember. And not only that, I can recall parts of his lectures word for word. Get past the alpha male- his lectures challenge, provoke, and stimulate ones inner self to think critically about the socially prescribed world in which we think we understand ourselves.', '[]', 'B+', 0, 1, NULL, 4, 2, 0, 1392562443, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODk5Njk5', 22899699, '0000916', NULL, NULL, 'ECON2213MACRO', 4.5, 5, 4, 4, 'Course material can be very dull & difficult at times. Class can even cause drowsiness. However, Moussa is a great guy & really does a great job explaining material in the easier ways & also jokes about it & relates it to current issues. Genuinely WANTS you to understand. Also is a very lenient marker & a sharp dresser as well. Recommended for ECON', '[]', 'A-', 0, 0, NULL, 1, 0, 0, 1394470605, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODk5NzYz', 22899763, '0024548', NULL, 'MATH-1213', 'MATH1213', 3.5, 5, 2, 1, 'Amazing professor and I have a man crush on him. Hard to understand so sit at front. Loves when students speak up and asks questions. Honestly, you don''t need the workbook. Got an A+ without buying it. His acorn notes are his own workings throughout the whole textbook and that is MORE than you need for the easy evaluations. Love this guy. Take JP.', '[]', 'A+', 0, 0, NULL, 5, 1, 0, 1394472228, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODk5ODY2', 22899866, '0022952', '10583', 'NUTR-1503', 'NUTR1503', 3.5, 3, 4, 3, 'He wrote the textbook. He really knows his stuff so he can answer questions and explain well if you ask.. but goes through things too fast and with not a lot of explanation during lecture. Biggest negative about him being so knowledgeable is that he thinks students can understand, grasp concepts or know what to remember easier than what is reality.', '[]', 'A-', 0, 1, NULL, 2, 4, 0, 1394474538, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODk5ODc5', 22899879, '0000957', '11700', 'SOCI-1113', 'SOCI1113', 2.5, 2, 3, 3, 'Not a good professor. She is a lovely person, but not a good professor. She may have been years ago, but now she is scatter-brained, easily distracted, goes off topic a lot. There are questions on the tests about herself. Lectures are a joke and then tests are much harder in relation. If you are here to be EDUCATED, do not take this class.', '[]', NULL, 0, NULL, NULL, 5, 0, 0, 1394474851, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyODk5ODg3', 22899887, '0024282', '7670', 'COMP-1813', 'COMP1813', 4.5, 4, 5, 1, 'One of the best profs at explaining foreign concepts to people who have never taken (or will) another COMP course ever. Also very funny during lectures. Assignments are easy if you have familiarity with the programs. Likely everyone will have to be good at new things due to this course. NO FINAL EXAM. Best elective course at Acadia University.', '[]', 'A+', 0, 0, NULL, 1, 0, 0, 1394475122, 1788283343);
