INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyOTI1MjU3', 22925257, '0047076', NULL, NULL, 'INTROCHEMLAB', 5, 5, 5, 2, 'Ashley is strict and to the point but she''s also a caring teacher, helpful and understanding. Follow her rules and work hard and you''ll be rewarded. Very smart, helpful and cares if you do well in her class.', '[]', 'B+', 0, 1, NULL, 1, 0, 1, 1395239104, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyOTI1MzQ5', 22925349, '0008859', '10916', 'PHIL-2103', 'PHIL2103', 4.5, 4, 5, 3, 'I''ve taken three classes from Ian so far and I can''t wait to take more. He is by far the most intelligent person I have ever had the pleasure of meeting, his lectures are very interesting and he has a nice touch of dry humour to boot. On top of that, he is a fair marker. I definitely recommend his classes if you don''t mind rather heavy readings.', '[]', NULL, 0, 1, NULL, 5, 1, 0, 1395240171, 1788283345);
