INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyOTI4NTAw', 22928500, '0034413', '7294', 'CHEM-1113', 'CHEM1113', 5, 5, 5, 2, 'I took the "Chem Major" intro chemistry class with lukeman and I did not regret it. He goes at a faster pace then the other courses, but gives you a day in class to do a problem set on the chapter that you just covered, which is the most helpful thing I had ever received in my first year of university.', '[]', NULL, 0, NULL, NULL, 1, 0, 0, 1395308259, 1788283351);
