INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyOTI5MzYx', 22929361, '0012762', '7647', 'COMM-1213', 'COMM1213', 3.5, 4, 3, 4, 'There is no doubt this is a very challenging course, but if you are willing to put in the time and effort, it is possible to walk away with a good grade. This is one of those courses that gets students to decide if they are really going to be business students or not. Work very hard and go to office hours. If you do this you will be just fine.', '[]', NULL, 0, NULL, NULL, 3, 2, 2, 1395325040, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIyOTI5Njg4', 22929688, '0021212', '9945', 'MATH-1023', 'MATH1023', 5, 5, 5, 4, 'Karsten is a god. He''s super clear on the board. Will explain any assignment question you ask, in class. I was bad at math before this course, he helped. His hair is phenomenal, don''t get distracted by that or the hand that''s not holding the chalk. Super enthusiastic, talks loud, prepares you well for tests. Highly recommend!', '[]', 'Not_Sure_Yet', 0, 0, NULL, 4, 3, 0, 1395329941, 1788283353);
