INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTIzNTI5NzA5', 23529709, '0012118', '6659', 'APSC-2813', 'APSC2813', 4.5, 5, 4, 2, 'One of the best professors I have ever had: he uses a practical approach to engineering.  There is no single right answer on tests or midterms, just about how you justify your assumptions.  No solutions available, but 110% helpful if you can track him down for help (he is a very busy fellow). He teaches more common sense than anything. A+!', '[]', 'A', 0, 1, NULL, 2, 1, 7, 1408046217, 1788283352);
