INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDAxODk3', 34001897, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 5, 5, 5, 4, 'Dr. Ellis is one of my favorite prof''s I''ve ever had at Acadia, so fun! Inorganic is obviously a tough course but with all of his bonus marks he gives out he makes it easier to do well in the course! He goes fast through slides so I recommend asking questions. Gives out mock midterms, VERY similar to the real ones. Labs are long but lots of fun!', '["Skip class? You won''t pass.","Caring","EXTRA CREDIT"]', 'A', 1, 1, 1, 0, 0, 0, 1607539394, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDAxOTkw', 34001990, '0003429', '6922', 'BIOL-3153', 'BIOL3153', 5, 5, 5, 3, 'Dr. Gibson is SO SWEET! Favorite bio prof! She truly cares about every student and wants you to do well. Open to any and all questions and helps you with whatever you''re confused on. Course is quite lecture heavy but she tries to go slow and help everyone understand! Definitely will be taking another course of hers!', '["Accessible outside class","Participation matters","Caring"]', 'A', 1, 1, 1, 0, 0, 0, 1607539660, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDAyMDc2', 34002076, '0015486', '6900', 'BIOL-2813', 'BIOL2813', 3, 3, 3, 4, 'Course was taken online because of COVID. Lectures are PACKED with information and weekly quizlets were quite difficult. Don''t take this course if you''re looking for an &quot;easy elective&quot; because you need to put work in to do well! Matt is a good guy but enjoys testing everyone''s knowledge with hard quizzes. Personally wouldn''t recommend..', '["Get ready to read","Skip class? You won''t pass.","Lecture heavy"]', 'B+', 1, 0, 0, 0, 0, 0, 1607539948, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDE0OTg0', 34014984, '0169986', '11315', 'PSYC-1013', 'PSYC1013', 3, 3, 3, 4, 'he''s an okay prof, i only took psyc1013 cuz i thought it was going to be a bird course but it''s really not. you have to study very carefully and the way he phrases his midterm and quiz questions are literally so sneaky. Midterms are hard, quizzes are okay. He''s really organized and easy to talk to though', '["Accessible outside class","Lecture heavy"]', 'B+', 1, 0, 1, 0, 0, 1, 1607608628, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDE1OTU=', 3401595, '0031457', '7288', 'CHEM-1023', 'CHEM1023', 2, 2, 2, 4, 'Worst course I''ve ever takin. Its sooo boring and its hard as hell. He seems like a nice guy but his teaching sucks. The midterms are extremly unprepared for and even when you try to prepare it doesnt help. This course is making my life miserable as I write this.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1109588169, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDE2MDc4', 34016078, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 5, 5, 5, 3, 'Great professor. Would not change anything! He makes lectures fun to attend because he is so funny and has a very easy going personality.', '["Clear grading criteria","Hilarious","Amazing lectures"]', NULL, 1, 0, 1, 0, 0, 0, 1607616453, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDIyNTUz', 34022553, '0026142', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 3, 'Acadia''s greatest professor. Most amazing prof ever. Course load is the usual. Hilarious teacher that tries to make learning as fun as possible. Can be accessed through instagram, LinkedIn and through class. Best course I''ve ever taken', '["Inspirational","Hilarious","Amazing lectures"]', 'A+', 1, 0, 1, 5, 0, 0, 1607638132, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDIyNjI2', 34022626, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 4, 'Tough grader. Provides a decent amount of feedback but still super tough grader. Hardest marker for sure. Sweet lady though and extremely caring.', '["Get ready to read","Participation matters","Tough grader"]', 'A-', 1, NULL, 0, 5, 1, 0, 1607638361, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDM5ODM3', 34039837, '0176491', NULL, 'PSY-2113', 'PSY2113', 2, 2, 2, 3, 'I was so excited to take Abnormal Psychology, but Bell did an awful job at teaching this class online. There were no lectures and it was basically self taught. We had only 2 classes a week, Q&amp;A which was absolutely pointless, and group work on Fridays. I am sure she may be different in a classroom setting, however I had an awful experience with her', '[]', NULL, 1, NULL, 0, 5, 0, 0, 1607735831, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDM5ODcw', 34039870, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 3, 3, 3, 4, 'I had the lab section of RDA with Karmen online and did not like it one bit. Classes were boring and information was difficult to retain. Labs were graded very difficult with not much instruction. However, she is good at responding to questions. Seems like a good person, just didn''t like the teaching/grading techniques.', '[]', NULL, 1, 1, 0, 0, 0, 0, 1607735980, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDMxNDY5', 34031469, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 5, 5, 5, 3, 'Joe is hilarious and always makes the class fun! He lectures a lot but they are always interesting so it isn''t hard to pay attention. His assignments are clear and short, as long as you pay attention it will be easy to get a fantastic mark!', '["Graded by few things","Hilarious","Amazing lectures"]', NULL, 1, NULL, 1, 0, 0, 0, 1607697967, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDMxNTAz', 34031503, '0016390', '9358', 'HIST-3493', 'HIST3493', 4, 4, 4, 4, 'Dennis is a really understand and fun prof to have, you can tell he is very knowledgeable! It is very reading heavy and if you don''t read then you won''t be able to get your participation points. He also posts slides but they often don''t contain much of what he said when lecturing, so make sure you take notes!!', '["Gives good feedback","Get ready to read","Skip class? You won''t pass."]', NULL, 1, 1, 1, 5, 0, 0, 1607698301, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDU2MDI3', 34056027, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 2, 2, 2, 5, 'This prof is challenging. Not completely unfair, but at times overly challenging. This hasn''t been the easiest semester for anyone but having no lectures recorded and then tearing the class'' essays to shreds has been a mild nightmare. Take his courses with a light workload. Prepare to dump far more time than usually required for 2000 level classes', '["Lots of homework","Get ready to read","Tough grader"]', 'Not sure yet', 1, 0, 0, 5, 0, 0, 1607890226, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDc0MDcw', 34074070, '0016655', '9270', 'HIST-2563', 'HIST2563', 1, 1, 1, 4, 'I read Sedgwicks ratings before taking the class but figured I would be ok. I was wrong. While Sedgwick is helpful if you go to office hours he marks incredibly hard on stuff like citations details. If youre going to take a class with him you better be ok getting a worse mark than youre used to.', '["Accessible outside class","Get ready to read","Tough grader"]', NULL, 1, 0, 0, 0, 0, 1, 1607992540, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDcwOTky', 34070992, '0047076', '7286', 'CHEM-1013', 'CHEM1013', 1, 1, 1, 5, 'Rude. No feedback ever.', '["Skip class? You won''t pass.","Graded by few things","Tough grader"]', 'D', 1, 1, 0, 0, 1, 0, 1607981704, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDg3MjA1', 34087205, '0045565', '7153', 'BUSI-2803', 'BUSI2803', 4, 4, 4, 3, 'Overall good professor. This class was just a-lot of reading. In class group case study''s I would recommend reading before the class as he only gives you 35mins and you can run out of time.', '["Group projects","Beware of pop quizzes"]', 'A', 1, 1, 1, 5, 0, 0, 1608067647, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDg3Mjcz', 34087273, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 5, 5, 5, 3, 'Really good fair professor. Questions are very fair asks what he teaches. Do his assigned practice questions and this class should not be a problem.', '[]', 'A+', 1, 0, 1, 5, 0, 0, 1608067906, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDg3OTMw', 34087930, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 5, 'Professor Kapoor is by far, the hardest, most unfair teacher that I know. He is not understanding, his midterms are so hard, and I do not have hope for his final exam. The questions are so specific, and based on textbook memory, which is a lot to remember! On the second midterm, only 12/50 students scored above 70%. Majority failed.', '["Test heavy","Group projects","Tough grader"]', 'Not sure yet', 1, 1, 0, 5, 0, 0, 1608070191, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDk4ODg2', 34098886, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 1, 1, 1, 3, 'Easily the worst professor that I have had thus far at Acadia (4th year student). He is extremely lazy. In &quot;lectures&quot; he just tells you to use websites to find information for completing projects, while avoiding teaching any material himself. 3.5 months in this course and I''ve learned absolutely nothing. Docks major points for trivial things.', '["Group projects"]', 'Not sure yet', 1, 0, 0, 0, 0, 0, 1608129497, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDk5MTE3', 34099117, '0000768', '7169', 'BUSI-3113', 'BUSI3113', 5, 5, 5, 2, 'Ian is the best. Teaches you exactly what you need to know to ace his tests and assignments. His participation grade system makes you stay engaged during class, and is an easy way to boost your mark. Throws some small tricks into his tests, but nothing that is unfair. The strategies he teaches for solving problems are very helpful. Very clear prof.', '["Participation matters","Clear grading criteria","Hilarious"]', 'A+', 1, 0, 1, 0, 0, 0, 1608130925, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDk5MjY0', 34099264, '0026142', '7220', 'BUSI-4113', 'BUSI4113', 4, 4, 4, 3, 'Audit was a boring class (3hr Monday night), but Mike tried his best to make the most of it. Had him before, and this was definitely my least favorite class with him but it wasn''t awful. Mike cares deeply for his students and will do everything in his power to help you succeed academically, and professionally. Can mark a bit tough. Incredible guy.', '["Gives good feedback","Respected","Caring"]', 'A', 1, 0, 1, 0, 0, 0, 1608131871, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MDk5Mzgx', 34099381, '0169986', '11315', 'PSYC-1013', 'PSYC1013', 4, 4, 4, 2, 'Took intro psych as an elective, and the class was 100% online this year. Tests are high stakes: 2 Midterms (worth 22.5% of your grade each), and a cumulative final exam (worth 45%). I feel like this class MAY have been a bit harder in person, but having access to notes during tests made it a freebie A+. Only tested on stuff in posted slides.', '["Graded by few things","Clear grading criteria"]', 'A+', 1, 0, 1, 0, 0, 0, 1608132524, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTA0ODEw', 34104810, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 1, 1, 1, 5, 'Did a lot of praying this semester hopefully it was enough', '[]', NULL, 1, 0, 0, 5, 0, 0, 1608149966, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTIwNDI4', 34120428, '0036828', '7841', 'CREL-2533', 'CREL2533', 5, 5, 5, 2, 'Donna hands down is an amazing person. Always willing to help you get an A and takes time out of her day to meet with every student one on one. I found her class to be very flexible with due dates and especially during COVID. This semester was difficult but Donna helped me through it.', '["Accessible outside class"]', 'Not sure yet', 1, 0, 1, 5, 0, 0, 1608222897, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTM2NDU0', 34136454, '0139532', '11701', 'SOCI-2003', 'SOCI2003', 4, 4, 4, 3, 'Casey was one of my favourite professors because of her heart. This year being the first for online learning has been very challenging for a lot of students and staff and Casey is one person who made this transition to an online world easier. Gives extensions when needed and is very understanding. She wants to see you do well so ask questions!', '["Gives good feedback","Caring"]', NULL, 1, 1, 1, 5, 0, 0, 1608308156, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTQ4NzQ0', 34148744, '0170402', '9191', 'HIST-1613', 'HIST1613', 5, 5, 5, 2, 'Professor Di Giorgio is a straight up gangster, I took this class and didn''t know what to expect but she was the most chill prof ever, take a course taught by her if you get the chance', '[]', 'A', 1, NULL, 1, 5, 0, 0, 1608397650, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTUxMTEz', 34151113, '0102067', '11751', 'SOCI-3013', 'SOCI3013', 1, 1, 1, 4, 'Lectures are hard to follow. His explaining makes me confused. Online covid class so no attendance but professionalism/participation markmore assignments as if there wasnt enough. Provides readings-good but way to many, be prepared to read. Boring class. Tough grader based on his opinion. If you do not go above and behind, dont expect a good mark.', '["Lots of homework","Get ready to read","Tough grader"]', 'Not sure yet', 1, 1, 0, 0, 0, 0, 1608414493, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTYyMg==', 341622, '0016415', NULL, NULL, '2113', 4, 4, 4, 5, 'He''s too moody!!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1037230327, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTg3MjIx', 34187221, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 4, 'Youre not going to enjoy this class but heres a few tips to get through it. Write down every single thing he says and everything on the slides. Then study it religiously before reading the textbook front to back. The tests will be ridiculously hard and you will receive very little help. If you dont want this to hurt your GPA then study hard.', '["Get ready to read","Skip class? You won''t pass.","Tough grader"]', 'A', 1, 1, 0, 5, 0, 0, 1608755373, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTg5MzA5', 34189309, '0024327', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 3, 'Dr. Biro was a great prof- always cared about his students and wanted them to do well, he also always responds to emails in a timely fashion (thank god). Flexible on due dates given valid reason and is super approachable- no question is a stupid question. He is very clear on what he is looking for, however, very tough grader. Definitely recommend!', '["Accessible outside class","Get ready to read","Caring"]', 'A', 1, 0, 1, 5, 0, 0, 1608771723, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTg5NDI4', 34189428, '0027644', '10907', 'PHIL-1413', 'PHIL1413', 5, 5, 5, 3, 'Ramsay may seem a little scatter brained at first but it''s only because the topics are difficult to understand in the beginning. He is actually super knowledgable and knows what he is talking about. He''s super clear on tests, midterms and exams- you shouldn''t be shocked at the questions when you see them. If you attend class it''s an easy A.', '["Skip class? You won''t pass.","Hilarious","Lecture heavy"]', 'A', 1, 0, 1, 5, 0, 0, 1608772852, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTgwNDgy', 34180482, '0024548', NULL, 'MATH-2233', 'MATH2233', 4, 4, 4, 1, 'Easy class tbh. Stats is usually so hard like in first year I had a bad prof who was mean and didn''t mark clearly and had hard material. this class was total opposite. even online it was actually easy to follow. will take his classes for stats again lol also the exams r super similar to practice problems in the text book', '["Respected","Clear grading criteria","Caring"]', 'A+', 1, 0, 1, 5, 0, 0, 1608683425, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MTkzMDI1', 34193025, '0015486', '6900', 'BIOL-2813', 'BIOL2813', 5, 5, 5, 2, 'Gave weekly quizzes that made up the mark, they were online and just from the powerpoints. They were timed and gave enough time to look some answers up, but not enough to look everything up. Diagram heavy for some.', '["Clear grading criteria","Lecture heavy","EXTRA CREDIT"]', 'A+', 1, 0, 1, 0, 0, 0, 1608825629, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjA4MDc=', 3420807, '0015407', NULL, NULL, 'ENGLISH', 5, 5, 5, 3, 'So very helpful and in always such a great mood! A+ for enthusiasm.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1109962081, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjA4NTQ=', 3420854, '0016779', NULL, NULL, '18THCNOVEL', 5, 5, 5, 3, 'Great material, and the prof knows it inside and out. Less reliance on Powerpoints than some, but is that always a bad thing&#63; Work hard and get rewarded.', '[]', NULL, 0, NULL, NULL, NULL, 0, 3, 1109963121, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjA4NjE=', 3420861, '0018366', NULL, NULL, '2006BRIT', 4.5, 5, 4, 4, 'Part English prof, part philosopher. Tough material, but she helps you plow through it, and perhaps, you just might be enlightened. Once you do a few essays and presentations for her, you''ll think you can do anything.', '[]', 'A', 0, 0, NULL, NULL, 1, 0, 1109963320, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjA5NjU3', 34209657, '0176491', '11336', 'PSYC-2113', 'PSYC2113', 4, 4, 4, 5, 'Kathryn is sweet and a good prof, but the way she went about Abnormal Psychology wasn''t the best. Having it online was difficult, and the 1-2 assignments per week were extremely long. She never lectured once, just had to do the assignments and met once per week to do a group activity. Not my preferable way of learning.', '["Accessible outside class","Test heavy"]', 'C', 1, 1, 1, 5, 0, 0, 1609196143, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjE3OTU2', 34217956, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 5, 5, 5, 4, 'Very good prof, he teaches the material well although he goes through it pretty fast, but will always answer questions. Lots of bonus marks. Practice midterms are basically identical to the actual ones. Also has tutorials before midterms (very helpful) Don''t think about skipping cause otherwise you''ll have no idea what is going on.', '["Gives good feedback","Clear grading criteria","EXTRA CREDIT"]', 'A+', 1, NULL, 1, 0, 0, 0, 1609364089, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjI0Mzg1', 34224385, '0012981', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 3, 'Dr. Narbeshuber is an excellent teacher. Come to class and get your work done, and she will see that you succeed. If you show her that you care, she will show you the same in return.', '["Respected","Participation matters","Caring"]', NULL, 1, 1, 1, 0, 1, 0, 1609552196, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjI0ODM=', 3422483, '0012762', NULL, NULL, 'COMM', 1, 1, 1, 4, 'Power trip, Self serving,  control freak. No positive feedback ever. By far the worst prof I have ever had. Hopefully she doesn''t get tenior. God help the poor students then.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1110033420, 1788283363);
