INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjI2OTM0', 34226934, '0036828', '7838', 'CREL-2413', 'CREL2413', 5, 5, 5, 4, 'Donna is easily the kindest, most caring prof who loves what she teaches and it shows. Shes easy to approach and ask questions to, and makes the time to meet with you after class if needed. She truly cares about her students and the material she teaches. Would take her classes again 100%.', '["Accessible outside class","Hilarious","Caring"]', NULL, 0, 1, 1, 5, 0, 0, 1609629382, 1788283344);
