INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjI4Njk4', 34228698, '0026142', '7220', 'BUSI-4113', 'BUSI4113', 1, 1, 1, 2, 'Unpopular opinion, but I do not think Kennedy is a good prof. His lectures are terrible you learn nothing, puts way to much weight on participation (30%) just a way to give favorites higher marks. We had to do audit cases for this class and each was only worth 15% each which was rather low for the work that was required.', '[]', NULL, 1, 1, 0, 5, 1, 0, 1609687313, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjM0NTQ4', 34234548, '0012981', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 2, 'Class discussions made the semester fun. There''s quite a bit of reading but it wasn''t too, too much for me. The exam is heavily related to class discussion so that made it fairly unstressful. The professor is approachable and nice.', '["Gives good feedback","Get ready to read","Skip class? You won''t pass."]', 'B+', 1, 1, 1, 0, 0, 0, 1609793297, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjMwNjE3', 34230617, '0012981', NULL, 'ENG-1413', 'ENG1413', 1, 1, 1, 3, 'She is awful. Dry, mumbling lectures, weeks late on grading, and required and in person class with no online option during Covid-19 pandemic, without wearing a mask. 10% of grade was attendance so if youre an athlete find another prof. I got 80s and 90s in my other classes and almost failed this one. Withdraw when you have the chance, trust me.', '["Lecture heavy","Tough grader"]', NULL, 1, 1, 0, 0, 0, 1, 1609721324, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjMxNDg=', 3423148, '0012762', NULL, NULL, 'COMM', 1, 1, 1, 5, 'Rude, selfcentered, all about control, has her favoritys, really... presentation on how to clean a fish. Wow an A...', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1110054031, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjQ5NTQ4', 34249548, '0000768', '7168', 'BUSI-3083', 'BUSI3083', 4, 4, 4, 4, 'Feltmate is truly amazing at explaining accounting concepts. His classes consist of going though textbook problems slowly and he clearly shows how each step is calculated . However, his tests can be challenging but at this level of accounting that is to be expected. If you study hard and listen you should pull off a great mark in this course.', '["Gives good feedback","Respected","Amazing lectures"]', 'A-', 1, 1, 1, 5, 0, 0, 1610047746, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjQ5NjA3', 34249607, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 1, 1, 1, 5, 'Has no interest in helping students succeed. Has to be one of the most lazy professors I have ever had. Gets you to learn everything on your own using the website links he posts. Avoid if you can.', '["Get ready to read"]', 'B-', 1, 1, 0, 0, 0, 0, 1610048266, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjQwODYz', 34240863, '0046920', '7134', 'BUSI-2223', 'BUSI2223', 4, 4, 4, 4, 'Writes tiny notes on the white bored which are near impossible to read. Makes no references to the textbook so if you miss copying his notes or cant see thats not good news for you. His MC on midterms are tough but you can still get an 80% if you take a zero. Pro about Stephen is he says exactly what long answers are on the tests/exam.', '[]', 'A', 1, 1, 0, 0, 0, 0, 1609884782, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjUwMDg5', 34250089, '0015754', NULL, 'ENG-1406', 'ENG1406', 5, 5, 5, 4, 'Jessica was one of my favorite professors I have had so far (I am in my second year now). She is so kind and helpful and makes everyone in the class feel included. Would definitely recommend her classes to anyone. She also helped me A LOT with my writing and I learned so much more from one semester with her compared to all of highschool english.', '["Gives good feedback","Participation matters","Caring"]', 'C+', 1, 1, 1, 5, 0, 0, 1610053487, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjY1MzA=', 3426530, '0001453', NULL, NULL, 'PAPPLIED', 1.5, 1, 2, 3, 'Yeah, she''s a great prof for women if you are a SOPRANO. If you aren''t. Your voice will be ruined by the end of four years because she tries to make you sing HIGH all the TIME. She also plays favorites.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1110186401, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MjcyNzkw', 34272790, '0008339', '6982', 'BIOL-3573', 'BIOL3573', 5, 5, 5, 3, 'Mike is an amazing professor and his courses are super interesting. PRO TIP: Go to class and take good notes -- his midterms/exams are based on the lecture slides AND include all the weird things he talks about.', '["Gives good feedback","Respected","Clear grading criteria"]', 'A+', 1, 0, 1, 0, 0, 0, 1610565593, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0Mjg5MTQ5', 34289149, '0043166', '9267', 'HIST-2533', 'HIST2533', 1, 1, 1, 4, 'For someone who is so strict on submission deadlines shes very nonchalant about returning work in a timely manner. She took over a month to return work she knew would have to be rewritten- the only explanation she gave was that she wasnt in the mood to grade. If youre thinking about taking any of her classes for electives, dont!', '["Lecture heavy","Tough grader"]', 'B', 1, 1, 0, 5, 0, 0, 1610980231, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0Mjg5ODky', 34289892, '0026327', '9060', 'GERM-1013', 'GERM1013', 5, 5, 5, 2, 'Professor Thomas was my favourite professor this semester. He takes the time to ensure that everyone has an understanding of the subject, and is easy to get in contact with. He requires participation unless you have a good excuse, but he''s very understanding about technology issues. It''s an easy course to pass, as long as you put the work in.', '["Gives good feedback","Respected","Participation matters"]', 'A+', 1, 1, 1, 5, 0, 0, 1610997713, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0Mjg5OTEy', 34289912, '0050946', '10110', 'MUSI-1013', 'MUSI1013', 5, 5, 5, 3, 'Professor D''Amato was incredible. He''s caring, brilliant, and hilarious. He provides the resources for everyone to get a good grade, as long as you attend class, participate in the occasional discussion, and connect with him. He''s very flexible; he let me do my exam as a multimedia project instead of an essay! Ask him about his past, it''s amazing.', '["Gives good feedback","Participation matters","Hilarious"]', 'A-', 1, 0, 1, 0, 0, 0, 1610998052, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzA2MjQz', 34306243, '0001042', NULL, 'COMP-1000', 'COMP1000', 1, 1, 1, 5, 'While likely a well respected researcher Dr. Trudel is a poor teacher. He lacks compassion and sympathy for human beings and instead of creating lectures or teachable materials assigns textbook readings and expects that to be sufficient for the course. That could work for some: I found it tiring and a terrible introduction to computer programming.', '["Get ready to read"]', 'C', 1, 0, 0, 5, 0, 0, 1611331604, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzAyMjU1', 34302255, '0050655', '8623', 'ESST-4003', 'ESST4003', 2, 2, 2, 4, 'Alice Cohen is a very nice woman who is a hard marker and does not make assignment criteria clear. This past class was very unorganized as many students including myself had no idea what was going on or what to do. In the end she gave everyone in groups different grades without knowing who did what for each part.', '["Participation matters","Group projects","Tough grader"]', 'B', 1, 1, 0, 0, 0, 0, 1611240908, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzAyODA1', 34302805, '0036828', '7830', 'CREL-1206', 'CREL1206', 5, 5, 5, 2, 'Donna is an awesome prof. She gives awesome feedback and is extremely accessible. Although, the past 2 years she has stopped teaching this class after 1st semester and got another prof to teach the rest. This can cause problems for many because you sign up for Donna but when she leaves halfway, you can''t drop because u would lose 2 credits.', '["Gives good feedback","Accessible outside class","Caring"]', 'A-', 1, 1, 1, 5, 0, 0, 1611250025, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzAyODU0', 34302854, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 3, 3, 3, 5, 'Karmen was awesome at replying to my many questions in emails, but she''s the hardest grader I''ve had. I know 3 people who failed RDA this year solely because of Karmen''s difficulty in the lab. She expected us to be able to write research papers to a 4th year level when we are only just learning how to. Was very stressful as RDA is a required course', '["Lecture heavy","Tough grader"]', 'C', 1, 1, 0, 0, 1, 0, 1611250607, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzE0OTgz', 34314983, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 2, 2, 2, 3, 'Choose your groups wisely. overall hasn''t changed the course in over 20 years seems dated but not hard work.', '["Group projects","So many papers"]', 'A', 1, 0, 1, 0, 0, 0, 1611614272, 1788283342);
