INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0MzQ4MDY2', 34348066, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 1, 1, 1, 5, 'Doesn''t post any material or record his lectures so you better hope you understand his stick figure drawings on Microsoft teams the first time around because he won''t be going over it again. Expect to do more work for worse grades than any class you''ve experienced before.', '["Lots of homework","Skip class? You won''t pass.","Tough grader"]', NULL, 1, 1, 0, 5, 0, 0, 1612737228, 1788283355);
