INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTMyNDg=', 3453248, '0012762', NULL, NULL, 'COMMUNICATIONS', 5, 5, 5, 2, 'Many find this prof hard but I would beg to differ. I am an average student (B''s and C+''s) and I did very well in her class, because I went to office hours to seeked extra assistance. If you are afraid to participate, she will make you feel comfortable. Show an interest and you''ll do well. Great!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1110793368, 1788283363);
