INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTQ2MjQ0', 34546244, '0011148', '10925', 'PHIL-2313', 'PHIL2313', 1, 1, 1, 5, 'Dropped/ withdrawn from class. She goes on and on in her lectures, and information can be irrelevant. Midterm was fair, but essay was brutal and if you do not put enough beef in you will be in trouble. Not sure what the exam is like since I dropped the the class on the last day of classes... however Exam outline is 1000% pure essay?! :(', '["Skip class? You won''t pass.","Graded by few things","Tough grader"]', 'Drop/Withdrawal', 1, 0, 0, 0, 0, 0, 1618352424, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTQ4NjQ3', 34548647, '0036828', '7830', 'CREL-1206', 'CREL1206', 5, 5, 5, 2, 'Donna is the best! She enjoys getting to know her students, and she tries her best to do anything in her power to help you succeed! She is very respected, a lot of students from her class loves her! Content for the class is great and she is able to engage students with the class material and with students. I would take her classes again!', '["Gives good feedback","Respected","Accessible outside class"]', 'B', 1, 1, 1, 5, 0, 0, 1618399105, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTQ4NjUz', 34548653, '0169986', '11319', 'PSYC-1113', 'PSYC1113', 4, 4, 4, 3, 'Dan is great. When you need help, he is willing to sit down and help you with any doubts you have. He is very down to earth and does not go over the top with his lectures, he is a great intro to psych prof and I recommend anyone to take his intro classes!', '["Gives good feedback","Respected","Accessible outside class"]', 'B-', 1, NULL, 1, 5, 0, 0, 1618399566, 1788283343);
