INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTQyMDQ3', 34542047, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'Run. Just Run. You will never find another professor that will give you 30 and 40 percent on papers for writing in a way that &quot;doesn''t flow well.&quot; She takes away points for every time you make a grammar or spelling mistake not just for the overall act of poor grammar. I have a GPA of 3.83 and receive good grades in all other classes. Please RUN', '["Participation matters","Tough grader"]', 'Drop/Withdrawal', 1, 1, 0, 5, 1, 0, 1618294350, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0NTQyMDg4', 34542088, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'She honestly seems like a great person very nice and seems to want to connect with people. BUT every time you try to email her on a day that isn''t her mandated day of work there will be NO response the work she assigns is the same work as grade 9 social studies yet she still finds a way to grade every report and like its a 3rd yr NASA course.', '["Skip class? You won''t pass.","Tough grader"]', 'F', 1, 1, 0, 5, 1, 0, 1618295405, 1788283363);
