INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0Njc0ODE0', 34674814, '0034413', '7292', 'CHEM-1053', 'CHEM1053', 5, 5, 5, 2, 'Chemistry in our world was incredible! I enjoyed it a lot and it was an easy A. Especially when you transition from a regular Chemistry class to a class that is for non-science majors. He is extremely helpful, uses a lot of visuals and great explanations for those who may not be familiar with chemistry! Highly recommend chemistry in our world!', '["Gives good feedback","Respected","Hilarious"]', 'A', 1, 1, 1, 0, 0, 0, 1619870016, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0Njk1NDI1', 34695425, '0180912', '11315', 'PSYC-1013', 'PSYC1013', 5, 5, 5, 3, 'i absolutely loved taking intro psych from him! he would play the ukulele at the beginning and end of every class and his lectures were by far the most engaging of any other classes i have taken. he is super chill and was great at making even an online class seem interesting. (also we had zero group work, which is a plus in my opinion)', '["Respected","Amazing lectures","Caring"]', 'B-', 1, NULL, 1, 0, 1, 0, 1620097373, 1788283348);
