INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0ODczNzU5', 34873759, '0016415', '9237', 'HIST-2283', 'HIST2283', 5, 5, 5, 2, 'Loved this course and Duke soooo much, definitely one of my top 3 favorite profs at Acadia. He truly wants to see all of his students succeed and always offers a helping hand and words of wisdom! He was an extremely fair marker and I can''t wait to take another one of his courses.. I would HIGHLY recommend this class or ANY class with him!!', '["Hilarious","Amazing lectures","Caring"]', 'A', 0, 1, 1, 0, 0, 0, 1622334642, 1788283343);
