INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0ODczNzkw', 34873790, '0047062', '6996', 'BIOL-3753', 'BIOL3753', 3, 3, 3, 2, 'Very funny and relaxed guy! He really wants his students to understand what he is teaching rather than memorize.. Research and term paper assignments were intimidating at first but ended up being fine, he was a very fair marker! If you keep up with the lectures and notes then this course should be an easy A- or higher!!', '["Get ready to read","Clear grading criteria","Hilarious"]', 'A+', 1, 0, 1, 0, 0, 0, 1622335385, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM0ODczODAz', 34873803, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 3, 3, 3, 2, 'Lots of little and tedious assignments/quizzes, but they were all pretty easy! Took it as an online course so didn''t fully get to know the prof but she was a very fair marker and made all of her assignments very easy to follow. I''ve always hated French but she made it tolerable! Keep up with the lecture notes and you''ll be fine..', '["Lots of homework","Participation matters","Clear grading criteria"]', 'A+', 0, 0, 1, 5, 0, 0, 1622335711, 1788283350);
