INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MTA0OTEx', 35104911, '0021211', NULL, 'PHIL-1213', 'PHIL1213', 1, 1, 1, 5, 'Dont take 8:30am classes because you will fall asleep. All he does is talk about the books youll be reading but in a very boring way of explaining what happens. He doesnt post notes so you need to pay attention to what hes saying but no one understands what hes saying because its so boring and he cant explain it in a way for us to understand', '["Lots of homework","Get ready to read","Skip class? You won''t pass."]', NULL, 1, 1, 0, 5, 0, 0, 1633461450, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MTAzMTUy', 35103152, '0016415', '9165', 'HIST-1003', 'HIST1003', 5, 5, 5, 3, 'He is a stand-up Pro he is the head of the History department and he diverse it, such a nice guy if you ask him for help he will do all that he can. First years should go to him for advice all ways. Be it for class selection or just general questions on writing papers or the history department he will give you a direct and fair answer', '["Gives good feedback","Accessible outside class","Caring"]', 'A-', 1, 0, 1, 5, 0, 0, 1633390784, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MTEwOTY0', 35110964, '0000664', '10982', 'PHYS-1013', 'PHYS1013', 4, 4, 4, 4, 'Lectures are kinda boring. However, very chill professor and answers all questions clearly. He really simplifies physics for you and makes you understand the idea. Class is not easy, it''s physics.', '["Gives good feedback","Lots of homework","Test heavy"]', 'Not sure yet', 1, 0, 1, 0, 0, 0, 1633655453, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MTI3MzY1', 35127365, '0039383', '6920', 'BIOL-3143', 'BIOL3143', 5, 5, 5, 2, '**Animal Behaviour** Laura is an amazing prof. This was her first year actually teaching I believe and she is a natural! She knows what she is talking about and is very interested in lecture/lab material. No final exam! She is super into bugs so not exactly my jam, but makes sure to relate to other animals as well. Very fun and relatable. Very cool', '["Graded by few things","Hilarious","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1634302814, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MTI3MzY4', 35127368, '0027644', '10934', 'PHIL-2713', 'PHIL2713', 3, 3, 3, 4, 'Marc is clearly interested in his class, but uses big words and doesn''t explain what they mean. If you are not a PHIL major, do not take this class.', '["Participation matters","Lecture heavy","Tough grader"]', NULL, 1, 1, 0, 5, 0, 0, 1634303002, 1788283350);
