INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzY3OTQ5', 35367949, '0071592', '6834', 'BIOL-1110L', 'BIOL1110L', 5, 5, 5, 1, 'Jennifer is super sweet. Her instructions are clear and she doesn''t hesitate to answer any questions to make sure you understand. Her test material is very fair, so you shouldn''t have to put in much work to do well. She also makes an effort to know you on a more personal level', '["Accessible outside class","Clear grading criteria","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1638654363, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzY4MDI1', 35368025, '0001916', '6892', 'BIOL-2563', 'BIOL2563', 2, 2, 2, 3, 'He''s a nice guy with a good sense of humour, but his lecture material is messy with a lot of random facts. Hard to tell what facts you have to remember for a test and which ones are useless. The readings are more clear if you have the time to read them. Quizzes are password protected, and you need to use lockdown browser so attendance is mandatory', '["Get ready to read","Test heavy","Lecture heavy"]', NULL, 1, 1, 0, 0, 0, 0, 1638655094, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzY4MDk0', 35368094, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 2, 2, 2, 3, 'She''s intimidating and unapproachable. Don''t skip a lab, it''s more work in the long run and she''ll fail you after 2 absences. Know your stuff before lab and write down procedures in the notebook, she''ll check. Overall she''s extremely unpleasant but the lab itself isn''t awful', '["Skip class? You won''t pass."]', NULL, 1, 1, 0, 0, 0, 0, 1638655859, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzY5NDg2', 35369486, '0169986', '11315', 'PSYC-1013', 'PSYC1013', 4, 4, 4, 3, 'Dan is great and makes lectures interesting. Attendance isn''t mandatory and all tests are online and open book including midterms and the final.', '["Respected","Graded by few things"]', NULL, 1, 0, 1, 0, 0, 0, 1638669667, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzYxNDI1', 35361425, '0032242', '7288', 'CHEM-1023', 'CHEM1023', 5, 5, 5, 3, 'I loved this prof. she is sooo good at teaching and makes the class interesting. She gave us examples in class with real stuff, so that we can see how chem was working on that example. I will definetely take her again', '["Gives good feedback","Inspirational","Caring"]', 'A-', 1, 0, 1, 0, 0, 0, 1638556750, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzYxOTY4', 35361968, '0033740', '6623', 'APSC-1223', 'APSC1223', 5, 5, 5, 3, 'Prof Tango is amazing! He tells a lot of stories and likes to pick on students. He may be a little hard to follow due to his accent, but he seems to care about his students. Just show up and look like you''re paying attention.', '["Accessible outside class","Skip class? You won''t pass.","Hilarious"]', NULL, 1, 1, 1, 0, 0, 0, 1638558975, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzcyMDc2', 35372076, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'If you show up to class and laugh at his jokes (he is actually pretty funny) he''ll really like you. He very obviously cares about his students and wants them to succeed and streams all the lectures if you cant make it. The course material wasn''t my personal favourite but his personality is what kept me coming to class!', '["Accessible outside class","Hilarious"]', 'A+', 1, 0, 1, 5, 1, 0, 1638725941, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzcyMTAw', 35372100, '0021212', '9943', 'MATH-1013', 'MATH1013', 5, 5, 5, 3, 'Karsten is a great guy and remains passionate about teaching. Two weekly assignments, the online ones were fine but the written ones made me want to cry occasionally, although he is super helpful (GO TO HIS OFFICE HOURS!) Overall a great class!', '["Respected","Clear grading criteria","Caring"]', 'A+', 1, 0, 1, 5, 0, 0, 1638726236, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1Mzg2ODcy', 35386872, '0031453', NULL, 'MATH-1214', 'MATH1214', 3, 3, 3, 4, 'Dr. Zhang does have an accent, but it really isn''t that hard to understand. She''s clear and takes her time going through lectures. The midterm was also a fair difficulty, not too hard at all. Take notes, and go to class!', '["Lecture heavy","Accessible outside class"]', 'C+', 1, 0, 1, 3, 0, 0, 1648140187, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1Mzg3MDM2', 35387036, '0036828', '7830', 'CREL-1206', 'CREL1206', 4, 4, 4, 2, 'Dr. Seamone cares a lot, and she wants you to do well! She was very kind, and funny too. Go to class, complete the homework, and carefully do your essays. Only thing is that I found it slightly unclear as to what my essay was supposed to be about.', '["Gives good feedback","Caring","Accessible outside class"]', 'A-', 1, 1, 1, 3, 0, 0, 1648140278, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzgwNTg3', 35380587, '0024914', '9955', 'MATH-1323', 'MATH1323', 4, 4, 4, 3, 'He is a chill guy, and seems to enjoy teaching', '["Lots of homework","Accessible outside class","Clear grading criteria"]', NULL, 1, 0, 1, 5, 0, 0, 1638804463, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzgwOTM2', 35380936, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 1, 1, 1, 4, 'She was just generally super unpleasant. Not understanding, not patient, not forgiving. She is not afraid to yell at you. Course is passable if you go to class and do your work, but if you need help ask literally anyone else. Even if she does help you shes gonna be rude about it.', '["Skip class? You won''t pass.","Test heavy","Tough grader"]', 'A', 0, 1, 0, 0, 0, 0, 1638806283, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzgwOTk2', 35380996, '0050655', '8591', 'ENVS-1023', 'ENVS1023', 4, 4, 4, 4, 'You can get away with missing class but it will make your life more difficult. She can be intense but she is very helpful and super smart. The content she teaches is genuinely applicable, and she wants you to think critically. Overall tough prof, but super good prof. Learned a ton in her class.', '["Gives good feedback","Get ready to read","Tough grader"]', 'A', 1, 0, 1, 5, 0, 0, 1638806541, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzgxMTM1', 35381135, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 3, 'Fantastic prof. So kind, so smart. It is a big class so it can feel intimidating but if you ask for help he is ready to provide help. The course has ALOT of content so youve gotta be careful to keep on top of things if you skip class. He is super reasonable with how he tests you. He realizes its a lot.', '["Accessible outside class","Hilarious","Caring"]', 'A', 1, 0, 1, 0, 0, 0, 1638807097, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1MzgxMTc1', 35381175, '0037382', '8589', 'ENVS-1013', 'ENVS1013', 4, 4, 4, 4, 'Hard prof and hard class. It can feel daunting and overwhelming but I learned so much from his class. Grew my scientific writing and comprehension so much. He seems intense and the assignments are a lot of work, but if you go to office hours he is ready and willing to help.', '["Get ready to read","So many papers","Tough grader"]', 'A', 1, 0, 1, 0, 0, 0, 1638807278, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1Mzk4Mzkx', 35398391, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 5, 5, 5, 2, 'I can see where some of the negatives comments are coming from. She can come across as intimidating and strict, but needs to due to the nature of the course. Give her a chance, she''s actually really approachable, nice and understanding, especially 1 on 1. TA''s are very helpful too. Quizzes and reports boost your chem mark, and experiments are fun!', '["Skip class? You won''t pass.","Clear grading criteria","Caring"]', NULL, 0, 1, 1, 0, 0, 0, 1638892013, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1Mzk4NTcw', 35398570, '0031457', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Many don''t like his class, but I really enjoyed it. If you keep up w/ the material it isn''t hard to do well. Class avg. was low though, so maybe that''s just my opinion. Lots of work outside of class (vids, assignments) but it helps you to understand. Test questions very similar to in class examples. Good office hours, but rarely responds to emails.', '["Clear grading criteria","Caring"]', NULL, 1, 0, 1, 0, 0, 0, 1638892780, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDA1MTg2', 35405186, '0031453', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 1, 'you can not understand a single thing she says. i ended up teaching myself. i have no clue what she taught all semester.', '[]', NULL, 1, 0, 0, 5, 0, 0, 1638913846, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDA1MjYw', 35405260, '0031453', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 4, 'Literally DOES NOT TEACH!!!! You have to teach the entire course to yourself basically and she barely gives any assistance when it comes to answering questions about coursework, lengths of tests/exams, and what will be tested. All her examples are messy and unreadable making it extremely difficult to understand anything if you tune out for a second', '["Lecture heavy"]', 'Not sure yet', 1, 0, 0, 0, 0, 0, 1638914024, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDA1MzEx', 35405311, '0031453', NULL, 'MATH-1214', 'MATH1214', 1, 1, 1, 4, 'She cannot teach', '["Lots of homework","Get ready to read","Participation matters"]', 'D+', 1, 0, 0, 5, 0, 0, 1638914155, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDA1MzU1', 35405355, '0169986', NULL, 'PSYCH-1113', 'PSYCH1113', 5, 5, 5, 1, 'He is the best professor Ive been in a lecture with, he is so funny, and very helpful. Best prof Ive had.', '["Gives good feedback","Respected","Hilarious"]', 'A', 1, 0, 1, 0, 0, 0, 1638914256, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDA3Nzg1', 35407785, '0169986', '11389', 'PSYC-3613', 'PSYC3613', 5, 5, 5, 2, 'Dan has consistently been one of my favourite professors. Since COVID, his exams are online &amp; open-book. For Psycholinguistics in particular, the exams had a MCQ section, then long answer Q''s that we chose as a class &amp; could prepare our responses to prior to the day of test. Dan cares about his students success, is a great guy &amp; a great prof, 11/10', '["Graded by few things","Hilarious","Caring"]', 'Not sure yet', 1, 0, 1, 0, 0, 0, 1638921837, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDAxMTY5', 35401169, '0024548', NULL, 'MATH-2233', 'MATH2233', 2, 2, 2, 3, 'Content is easy but only if you teach it to yourself. Class lectures are confusing. He doesn''t fully show you how to fully complete any of the practice examples, only got an actual explanation of the content through the lab TAs. When you ask questions in class he refuses to explain thoroughly if he already went over the material.', '["Accessible outside class","Test heavy","Tough grader"]', NULL, 1, 0, 0, 5, 0, 0, 1638902567, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDE3ODg0', 35417884, '0169986', '11315', 'PSYC-1013', 'PSYC1013', 5, 5, 5, 3, 'Really great prof! I''m not super into psyc, but his lectures were interesting and made me want to learn more. Quizzes and tests were very fair. Questions were more application based, so open-book helped in terms of understanding concepts in order to be able apply them; but it wasn''t as easy as looking up answers in your notes.', '["Accessible outside class","Amazing lectures","Caring"]', 'A+', 1, 0, 1, 0, 0, 0, 1638982804, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDE4MjIw', 35418220, '0015486', '6841', 'BIOL-1813', 'BIOL1813', 3, 3, 3, 4, 'Overall a good prof. Usually goes out of his way to help students, and you can tell he puts a lot of effort into his lectures. However, they are VERY information heavy and his tests require a lot of memorization. Daily quizzes help review material. Only negative is it almost seems as though he wants students to do poorly in his class?', '["Graded by few things","Lecture heavy"]', NULL, 1, NULL, 0, 0, 0, 0, 1638983899, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDE5MTkw', 35419190, '0022952', NULL, 'NURT-1503', 'NURT1503', 1, 1, 1, 4, 'He doesn''t let you see what you got wrong or right on the midterms and gives you none to very little practice questions to prepare for the exam. The exam is worth 50% of your grade so you have to pass it in order to pass the class however there is no way to prepare for it except going over slideshows. When asked how to prepare he said read notes', '["Graded by few things"]', 'Not sure yet', 1, NULL, 0, 0, 1, 0, 1638986706, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDE5NDQ0', 35419444, '0139613', '11056', 'POLS-1303', 'POLS1303', 4, 4, 4, 2, 'Amazing prof! It''s clear what she expects in essays and quizzes. Classes can be quite lecture-heavy, but she makes it as interesting as possible. If you don''t love politics/government, not a good course for you though.', '["Clear grading criteria","Lecture heavy","Accessible outside class"]', 'A-', 1, 0, 1, NULL, 0, 0, 1648140258, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDE5NjI3', 35419627, '0017498', '9948', 'MATH-1210L', 'MATH1210L', 4, 4, 4, 3, 'It can be tricky first learning RStudio, so go to class! It''s important to hear the prof explain the lab clearly, and ask questions. You will have them. She will help you and is very nice.', '[]', 'Audit/No Grade', 0, 1, 1, NULL, 0, 0, 1648140233, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDI3MTc2', 35427176, '0000902', '8911', 'GEOL-1073', 'GEOL1073', 4, 4, 4, 3, 'He is a really good prof to have, only downside is he doesnt allow extensions to anyone, when he says something is due, it is due that day. Classes are fairly easy but it also is a lot of information thrown to you at once.', '["Gives good feedback","Participation matters","Lecture heavy"]', 'B', 1, 0, 1, 0, 0, 0, 1639006927, 1788283343);
