INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDI3NDM5', 35427439, '0145558', NULL, 'PSYCH-1110', 'PSYCH1110', 5, 5, 5, 2, 'She is an amazing prof, one of my favourites! She is very kind and welcoming, and also likes to joke around from time to time. She will literally help with anything, and even if you email her, she gets back pretty quickly. The only thing is you actually have to go to class or you will fail.', '["Gives good feedback","Participation matters","Skip class? You won''t pass."]', 'A-', 1, 1, 1, 0, 0, 0, 1639007631, 1788283354);
