INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDIwNzA1', 35420705, '0028980', '7196', 'BUSI-3613', 'BUSI3613', 5, 5, 5, 2, 'Incredibly understanding and easy to reach outside of class. Very educated in the subject and is always very helpful. If you are feeling lost or nervous, reach out: she will help you. Going to class and reading the book is super important because not everything is covered just in the presentations.', '["Gives good feedback","Accessible outside class","Clear grading criteria"]', 'A+', 1, 1, 1, 5, 0, 0, 1638990704, 1788283348);
