INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDIxOTQz', 35421943, '0031453', NULL, 'MATH-1214', 'MATH1214', 4, 4, 4, 3, 'Great prof, lays out semester within the first week very clearly. You get marked on participation but tells you to get the answers from classmates if you''re absent so participation isn''t mandatory if you''re prepared to teach yourself basic math. Very passionate and sweet teacher, language barrier made class harder so just do work in your own time.', '["Respected","Clear grading criteria","Caring"]', NULL, 1, 0, 0, 5, 0, 0, 1638993380, 1788283356);
