INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDMwMDQy', 35430042, '0034433', '7136', 'BUSI-2233', 'BUSI2233', 1, 1, 1, 5, 'Worst prof ever. Not because someone has a PhD means that they can teach. Does not know how to explain he just reads off the slides. Is not helpful with questions. Entire class failed the midterm at the end of the semester. I had to find a ton of extra help and pay for a tutor and stressed myself out for a passing grade.', '["Test heavy","Lecture heavy","Tough grader"]', 'C+', 1, 1, 0, 5, 0, 0, 1639015477, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDU1MTc2', 35455176, '0001050', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 5, 'Didn''t explain anything clearly, wouldn''t answer questions, lecture material was incoherent and didn''t align with the textbook, and would not respond to emails. Did not specify when quizzes would be, but acted as if they were scheduled. The only saving grace was the humour, but aside from that he was not very personable at all.', '["Get ready to read","Beware of pop quizzes","Tough grader"]', 'D', 1, 1, 0, 0, 0, 0, 1639136993, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDU1MTgx', 35455181, '0012762', '7647', 'COMM-1213', 'COMM1213', 4, 4, 4, 4, 'She''s a very tough grader, but providing you take the time to actually talk to her, you''ll do fine. The criteria isn''t always clear, but she''s happy to clarify any questions you may have, and she is extremely approachable.', '["Gives good feedback","Tough grader"]', 'A-', 1, 1, 1, 0, 0, 2, 1639137291, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDUxODA2', 35451806, '0024548', NULL, 'MATH-2233', 'MATH2233', 1, 1, 1, 4, 'I initially thought stats would be an easy class. Which it was at the start but the material got difficult towards the end of the semester. Professor Peng was blatantly rude during lectures, and stated that he didn''t care about how students did in class. The exam was very difficult, with material on it that he said wouldn''t be. Will be avoiding him', '["Skip class? You won''t pass.","Graded by few things","Tough grader"]', 'C', 1, 1, 0, 5, 0, 0, 1639109130, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDUxODc2', 35451876, '0018550', NULL, 'BIO-2043', 'BIO2043', 3, 3, 3, 3, 'I enjoyed Professor Evans'' class! He was very entertaining during lectures. Could be rude at times, and seemed to be very unorganized. He did care about how his students did in his class and wanted to help. Tests were difficult. Definitely need to attend class to take notes - some things he says are not on the lecture slides. Lots of memorization!!', '["Skip class? You won''t pass.","Hilarious","Caring"]', 'B+', 1, 1, 1, 0, 0, 0, 1639109367, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDUxOTI4', 35451928, '0017498', '9987', 'MATH-2230L', 'MATH2230L', 5, 5, 5, 3, 'Such a sweet person! Really cares about helping students. Was tricky to learn to use RStudio at first during the labs but she made it easier. Very understanding about students workloads and actually cares about mental health. Would definitely take a class taught by her again!!', '["Gives good feedback","Caring"]', 'Not sure yet', 0, 1, 1, 5, 0, 0, 1639109607, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDUxOTU4', 35451958, '0001612', NULL, NULL, '2050L', 5, 5, 5, 3, 'Such a sweet person! Loved the microbio labs taught by her. Super interesting labs. Helene made it easy to understand how to perform certain techniques. Cares about students and wants them to do well.', '["Gives good feedback","Inspirational","Hilarious"]', 'Not sure yet', 1, 1, 1, 0, 0, 0, 1639109725, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDg2Nzg4', 35486788, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'Walking into this class, I was very excited. That excitement changed instantly... she is probably the hardest marker I''ve ever had. When she marks, it is incredibly unfair and pathetic. You''ll lose marks for missing a comma or if it &quot;doesn''t flow right&quot;. Participation is key in this class and she will have obvious favourites. BEWARE!!', '["Tough grader"]', NULL, 1, 1, 0, 5, 0, 0, 1639349996, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDg2ODY3', 35486867, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'Kendra grades at a level that is simply unrealistic. There is no pleasing her in your papers, and she is unacceptably sarcastic towards your questions in class. If you do not participate in class by talking and adding input to her discussions you will receive a terrible end grade, and she will not like you as she has obvious favourites.', '["Participation matters","Skip class? You won''t pass.","Tough grader"]', 'Not sure yet', 1, 1, 0, 5, 0, 0, 1639350333, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDg2OTM2', 35486936, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'Stack keeps the class smiling with his cheesy jokes. He is so understanding and will help you anytime. He structures his lectures in a way that you can remember the material and is an all around great prof. I would highly recommend!', '["Accessible outside class","Hilarious","Caring"]', 'A+', 1, 0, 1, 0, 1, 0, 1639350622, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDg5MzUx', 35489351, '0022952', NULL, 'NURT-1503', 'NURT1503', 1, 1, 1, 5, 'He sucks! Avoid, avoid, avid! There is no way that this class is an intro way to much material. His class notes are long studying one chapter will take you one day. Only take as an elective if you are a Bio or Chem major. This class should really be reported.', '[]', NULL, 1, 0, 0, 0, 1, 0, 1639361537, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDgxODY5', 35481869, '0038515', '10989', 'PHYS-1053', 'PHYS1053', 5, 5, 5, 3, 'Anna genuinely cares about how well you do in the class. If you show up to class and show her you care shell help you achieve the grades you want! I was scared of taking physics but needed the credit and now I want to take more physics courses that Anna teaches!', '["Accessible outside class","Amazing lectures","Caring"]', 'A', 1, 0, 1, 0, 0, 0, 1639311503, 1788283339);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDgyNzI2', 35482726, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 2, 2, 2, 1, 'Ryan Stack is an awkward guy, his lectures are boring and his passion for Business is there, but un-comfort in the classroom is very pronounced. The lectures are insanely repetitive, you could miss 4 classes and not miss a thing. There is no want to be in his class and he relies heavily on the My Pearson lab, his own grading efforts aren''t there.', '["Lots of homework","Graded by few things","Test heavy"]', 'B-', 0, 0, 0, 5, 1, 2, 1639328252, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1NDk3Njg5', 35497689, '0045565', '7153', 'BUSI-2803', 'BUSI2803', 5, 5, 5, 1, 'Dr Wang is an amazing professor. Extremely chill and very understanding of other student matters. NO EXAM and plenty of easy marks to receive. Attendance was graded and textbook was needed but not mandatory. His lectures can be very long and he loves to keep students right until the end of class. Very interesting course and overall a great guy.', '["Respected","Clear grading criteria"]', 'A', 1, NULL, 1, 5, 0, 0, 1639417955, 1788283356);
