INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1ODM0NjA2', 35834606, '0021658', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 3, 'Dr. Whetter is an amazing prof. He is funny in his lectures, and it is easy to tell he enjoys what he teaches. He cares immensely that his students learn and understand the subject. He is always willing to provide lots of feedback and schedule a meeting to discuss your work. 100% take his class for first year english, or any course.', '["Get ready to read","Amazing lectures"]', NULL, 1, 1, 1, 0, 0, 0, 1644261244, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1ODM0Njk5', 35834699, '0169986', NULL, 'PYSC-1023', 'PYSC1023', 5, 5, 5, 2, 'Dan is a great prof. All of his lectures in my class were prerecorded, so attendance was optional. All testing is open book and multiple choice. Dan gives amazing and interesting lectures. He is very helpful and caring to his students. He helps prepare you for all testing. 10/10 amazing prof. wouldn''t recommend buying the textbook.', '["Respected","Hilarious","Amazing lectures"]', 'A', 1, 0, 1, 0, 0, 0, 1644262660, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1ODY4NjM3', 35868637, '0032242', '7288', 'CHEM-1023', 'CHEM1023', 5, 5, 5, 4, 'Cathy is the best prof I have ever had! She goes above and beyond to ensure hard working students have the opportunity to ask questions. Her office hours are extremely helpful. Highly recommend her courses!', '["Gives good feedback","Respected","Amazing lectures"]', 'B+', 1, 0, 1, 0, 0, 0, 1645382586, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTA0NTI0', 35904524, '0022921', '10984', 'PHYS-1023', 'PHYS1023', 5, 5, 5, 4, 'Absolutely would take this professor again. He is so understanding of the students work loads. He is very approachable and will go through the smallest steps with you without any judgement. He was considerate of the people online when in a hybrid format and always had the students best interest in mind. 100% would recommend.', '["Amazing lectures ","Gives good feedback","Caring"]', 'Incomplete', 1, 1, 1, NULL, 0, 0, 1646412747, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTA0NTM0', 35904534, '0033740', NULL, 'APSC-1013', 'APSC1013', 4, 4, 4, 2, 'Such a sweet professor. If you pay attention and engage in his antics he is bound to love you. His tests are very easy if you read over your notes and he will seek you out if you seem to be having difficulties with anything. He is a bit unorganized but it is all in good fun. He is very approachable and overall a good person.', '["Gives good feedback","Hilarious","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1646412931, 1788283350);
