INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTEwODA2', 35910806, '0037418', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 3, 'Wilson is a terrible professor. His course was painful, his lectures all over the place. I typically try and give a positive review for my professors but Wilson doesn&#39;t deserve it. If you take his course you will teach yourself enough to get the grade you&#39;re comfortable with, but Wilson Lu will not advance your understanding of the material', '[]', 'Not sure yet', 1, 0, NULL, 3, 1, 0, 1646659894, 1788283356);
