INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTQ1MjM5', 35945239, '0003100', NULL, NULL, 'HIST14131423', 5, 5, 5, 2, 'Henderson is an excellent teacher and makes the class fun, even though it is heavily lecture based he is able to make it intriguing. always look forward to this class.', '["Amazing lectures ","Respected","Lecture heavy"]', 'B', 1, 0, 1, 3, 0, 0, 1647524282, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTQ1MjY5', 35945269, '0024548', NULL, NULL, '1213', 1, 1, 1, 5, 'Doesnt give enough info in exam questions to make an accurate decision. Question was literally "true or false: if you reject the null hypothesis it''s a type 1 error". If H0 is FALSE it''s a type 1 error, but if its true then there is no error. We weren''t told the study results. His answer: "this is a confusing question to students"... ok so fix it?', '[]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1647525310, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTQ3NTEx', 35947511, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 1, 1, 1, 3, 'She does not respond to emails whatsoever. If you have questions outside of class time, you are out of luck. Overall, poor communication. The homework closely follows the textbook which makes it hard to complete sometimes.', '["Group projects","Lots of homework","Test heavy"]', 'A', 1, 0, NULL, 3, 1, 0, 1647563304, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTU1NTEw', 35955510, '0037418', NULL, 'MATH-1213', 'MATH1213', 5, 5, 5, 1, 'Awesome.', '["Hilarious","Caring","Respected"]', 'A+', 1, 1, 1, 3, 1, 4, 1647871560, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTU1NTIy', 35955522, '0015486', NULL, 'BIO-1853', 'BIO1853', 5, 5, 5, 2, 'Matt is a funny teacher and he makes classes easy to navigate. Although class may be sometimes boring, he finds a way to incorporate jokes and such into his power points. Matt is overall a beauty and tries to get to know his students.', '["Hilarious","Beware of pop quizzes","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1647871901, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTU5NDI3', 35959427, '0300770', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'I thought I was saved when I was given the option to take comms with a prof other than Carmichael... I was mistaken. She''s a nice person but there''s no clear grading scale and gives weird marks like 5.68/10. Gave me the worst mark I''ve ever received even though the content is laughably easy. Comms at Acadia is the absolute worst.', '["Participation matters","Skip class? You won''t pass.","Tough grader"]', 'C+', 1, 1, 0, 5, 0, 0, 1647922967, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTY3ODY2', 35967866, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 1, 1, 1, 4, 'It''s literally a beginner class but she marks so hard and expects so much from us. It''s ridiculous. Try to avoid her at all costs.', '["Group projects","Lots of homework","Test heavy"]', 'Not sure yet', 1, 0, NULL, 3, 1, 0, 1648069586, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTY3ODk4', 35967898, '0024548', NULL, NULL, '1223', 5, 5, 5, 3, 'I don''t get why everyone is so pressed. The midterm was a little difficult if you didn''t study but if you did, then it was super easy. Plus 90% of the time students don''t listen and ask literally the stupidest questions. Just pay attention', '[]', 'Not sure yet', 1, 0, 1, 3, 0, 1, 1648069949, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTY5NzEw', 35969710, '0037418', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 5, 'He doesn''t teach. You are expected to teach yourself. Avoid at all cost. His midterms are so hard and he doesn''t prepare you at all. Where''s a review class?', '["Tough grader","Get ready to read"]', 'C-', 1, 0, NULL, 3, 0, 0, 1648092301, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTYwNDY2', 35960466, '0000673', '7032', 'BIOL-4423', 'BIOL4423', 5, 5, 5, 2, 'Great prof', '["Amazing lectures ","Lecture heavy","Accessible outside class"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1647961891, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTYzMTYz', 35963163, '0145061', NULL, NULL, 'PHYS', 1, 1, 1, 2, 'Fine if you teach yourself, but good luck. His online lectures are horrible! The slides are useless and he always walks away from the mic. Never explains or takes questions from people online. He is so difficult to understand at the best of times. I wouldn''t have taken the course if I knew he would be so hard to comprehend.', '["Lecture heavy"]', 'Not sure yet', 1, 1, NULL, NULL, 0, 0, 1647990248, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTcyMDE0', 35972014, '0024548', NULL, NULL, '1223', 1, 1, 1, 5, 'We can''t show work for midterms so if u mess up the value in question 1 that you need to answer everything else, you''re done. I genuinely understand the material and spent so many hours studying, but did significantly worse due to a mindless error in part 1. It''s too bad we can''t submit a pdf of our calculations for partial points.', '["Tough grader","Graded by few things"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1648145701, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTg0MTYy', 35984162, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 1, 1, 1, 4, 'She honestly is the worst prof i''ve had so far. She just reads the textbook, gives way too much homework (so much that your grades suffer just to get it done), French grades went from 90''s to 50''s. She expects so much from you but does not give you the resources to succeed.', '["Tough grader","Lots of homework","Lecture heavy"]', 'Not sure yet', 1, 0, NULL, 3, 2, 0, 1648484306, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTk5MzI0', 35999324, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 3, 'I have taken both micro and animal biodiversity with Todd and he is by far one of the best profs I have had at Acadia thus far. Really cares about his students and is very fair in testing. Love attending his lectures, always tries to include jokes and keep it interesting. Would highly recommend taking a class with him!', '["Amazing lectures ","Caring","Respected"]', 'A', 1, 0, 1, NULL, 0, 0, 1648687008, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTk5MzY4', 35999368, '0001612', NULL, NULL, '2050L', 5, 5, 5, 3, 'I have had both micro and cell lab with her and I have loved them both. Helene is always available to help in anyway that she can and she truly cares about her students!', '["Gives good feedback","Caring"]', 'A+', 1, 1, 1, NULL, 0, 0, 1648687476, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMDM5', 35990039, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 1, 1, 1, 4, 'I don''t think that she should be a professor. She doesn''t know how to communicate clearly in class or by email. When I asked her a question about the explication on the course page, she copy and pasted the SAME explanation in her email. She does not put resources ANYWHERE, her course page is BLANK. I got A+ with a different professor, now B+ish.', '["Tough grader","Lots of homework","Graded by few things"]', 'B+', 1, 1, NULL, 3, 2, 0, 1648571858, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMDk2', 35990096, '0036828', '7830', 'CREL-1206', 'CREL1206', 1, 1, 1, 3, 'I did not like this prof AT ALL. I would get migraines in her class because of how long, boring and tiring they were! She read off her slides and would go on the LONGEST rants that had nothing to do with class, but her CAT. It was a waste of my time and my MONEY. I paid for my entire first year and I''m so mad that I wasted it on her class!', '["So many papers","Test heavy","Graded by few things"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1648572622, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMTY5', 35990169, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 4, 4, 4, 3, 'Professor Stack is really great! He makes sure that you know he''s available to help and he takes the time to really make sure you know what you''re doing. His lecture recaps the previous one which I like because it''s a good refresher. His MyLab assignments are very helpful for practice and an easy 25% if you do them. Highly recommend!', '["Clear grading criteria","Caring","Accessible outside class"]', 'Not sure yet', 1, 0, 1, NULL, 1, 0, 1648573269, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMjIw', 35990220, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 1, 1, 1, 4, 'Just don''t take this class if you still want to like french as a language... trust me', '["Tough grader","Test heavy","Graded by few things"]', 'B', 1, 1, NULL, 3, 2, 0, 1648573776, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMjQz', 35990243, '0012981', NULL, 'ENG-1413', 'ENG1413', 4, 4, 4, 3, 'I really enjoy Prof. Narbeshuber''s lectures. They are very interesting and she chooses good texts. You will have to buy quite a few books since 1406 is a year-long course, but you need them! She is a tough marker, but I still really enjoy the class. You have to work hard on essays and attend every class if you want to do well on tests and essays.', '["Tough grader","Participation matters","Gives good feedback"]', 'A-', 1, 1, 1, 3, 1, 0, 1648573992, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkwMzA2', 35990306, '0170402', '9191', 'HIST-1613', 'HIST1613', 5, 5, 5, 1, '*CREL1206 not HIST1613* Carla is AMAZING! She is super kind, a good lecturer and really likes involving students in related conversation. Everything that we discuss in class is on-topic and not a waste of time at all! Weekly journals are due on Fridays as a recap of that week''s religion. Super interesting course and I look forward to it!', '["Participation matters","Amazing lectures ","Gives good feedback"]', 'Not sure yet', 1, 1, 1, NULL, 1, 0, 1648574416, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkzNTE5', 35993519, '0015486', NULL, 'BIO-1853', 'BIO1853', 5, 5, 5, 2, 'great guy, incredibly understanding and so nice. Would take a class just for him to be my prof', '["Amazing lectures ","Hilarious","Caring"]', 'A-', 1, 0, 1, NULL, 0, 0, 1648603629, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkzNTQ4', 35993548, '0004338', '9694', 'KINE-1213', 'KINE1213', 5, 5, 5, 1, 'Easy grader and shes super nice. Class can get a bit boring tho.', '["Group projects","Lecture heavy"]', 'A', 1, 0, 1, 3, 0, 0, 1648603874, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM1OTkzNTcy', 35993572, '0043258', '9701', 'KINE-1413', 'KINE1413', 4, 4, 4, 5, 'Really smart, super nice and caring. Make sure when you take his class to show him you are putting in effort. If he knows your working hard he has been known to rework grades to give higher marks. Beauty', '["Participation matters","Lots of homework","Lecture heavy"]', 'B-', 1, 0, 1, 3, 0, 0, 1648604064, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDA2OTQx', 36006941, '0029615', NULL, NULL, 'SOCXXXX', 5, 5, 5, 2, 'In Jim''s class get ready to read and relate course material to your everyday life. Jim provides a strong structured course outline, able to accommodate any extrovert or introvert student. Classes are weighed heavy on participation, but it is for good reason. If you can talk about the material, you truly learned it and I believe that is the goal', '["Get ready to read","Participation matters","Caring"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1648819976, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDA2OTU1', 36006955, '0152004', NULL, 'SOCI-3263', 'SOCI3263', 4, 4, 4, 3, 'Even though I had to drop this course due to time constraints with varsity sports, Sarah is a kind and caring prof! The more you participate in discussions the more classmates and Sarah earn for opinions on sensitive topics. Sarah has always made an effort to let every student know they are special and studious which helps with engagement.', '["Group projects","Gives good feedback","Lecture heavy"]', 'Drop/Withdrawal', 0, 1, 1, 3, 0, 0, 1648820242, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDA2OTk4', 36006998, '0102067', '11705', 'SOCI-2103', 'SOCI2103', 5, 5, 5, 4, 'Jesse is one of the most caring profs I''ve had here at Acadia, although his grading is hard (with good reason) he holds high expectations for each student, and is always around to help you in whatever you need. This semester I was quite worried about being late to sign up for courses, Jesse was able to put me in right away! Very smart and caring', '["Tough grader","Get ready to read","Accessible outside class"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1648821033, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDAwMjA2', 36000206, '0170402', '7830', 'CREL-1206', 'CREL1206', 5, 5, 5, 2, 'Dr. Di Giorgio has been very kind, and beyond understanding this semester. She has done everything possible to make this class easy on us, and interesting. Listen in class, read the chapters, and you''ll do amazing in this class!', '["Amazing lectures ","Hilarious","Caring"]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1648697047, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDAwMjM0', 36000234, '0200912', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 3, 'Dr. Thiyagarajan is an amazing professor. Her grading material is very clear, and she gives feedback to help you to improve. English can be dry, but she does her best to make things interesting and different. She is also very kind and actually wants you to do well.', '["Get ready to read","Gives good feedback","Caring"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1648697329, 1788283352);
