INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDAxNzU3', 36001757, '0028980', '7203', 'BUSI-3753', 'BUSI3753', 5, 5, 5, 2, 'One of the nicest business profs at Acadia. Kelly Dye truly cares about what she teaches and how her students are doing. Her courses are engaging and she provides a lot of opportunities to get good marks in each class.', '["Clear grading criteria","Gives good feedback","Caring"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1648739766, 1788283348);
