INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDU1NDg1', 36055485, '0176491', '11336', 'PSYC-2113', 'PSYC2113', 2, 2, 2, 4, 'I took her class during the virtual school year (thx rona) and it was Monday: mandatory lecture, Wednesday: no class, work on your reading or Q&A, Friday: mandatory group work on a chapter. It didn''t contribute to my learning of the course material and we had to teach ourselves. If the tests weren''t open-book I easily would have flunked.', '["Tough grader","Get ready to read","Group projects"]', NULL, 1, 1, NULL, 3, 0, 0, 1649700212, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDU1NTg1', 36055585, '0034413', '7292', 'CHEM-1053', 'CHEM1053', 3, 3, 3, 2, 'Took his class in the virtual year. Online you''ll see it listed as a bird course, it has a lot more lectures and material than I expected though. He is an adaptable prof and seems to care for the students (though again it was virtual so a little hard to tell)', '["Lots of homework","Lecture heavy"]', NULL, 0, NULL, 1, NULL, 0, 0, 1649700628, 1788283351);
