INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDUxNjk0', 36051694, '0043258', '9701', 'KINE-1413', 'KINE1413', 5, 5, 5, 3, 'Dr. Landry is a very caring prof, if you show that you are working hard he will help you out. he does move quickly through his lectures but he is teaching two of the toughest Kin courses that are also very content-heavy by nature (anatomy & biomechanics) so people typically tend to struggle more with his classes.', '["Caring"]', 'B', 1, 1, 1, 3, 0, 0, 1649635534, 1788283354);
