INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDUzODUw', 36053850, '0034094', '7142', 'BUSI-2433', 'BUSI2433', 1, 1, 1, 5, 'Very nice person but Not a good professor, even though the semester was jammed all into a month and a half due to a strike, he still graded very hard, tested on 6 chapters gave 3 day notices before tests and way more dumb shi*. If you want to do good, avoid him take the class online or choose another prof. 
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDY5ODc1', 36069875, '0006798', '9194', 'HIST-1713', 'HIST1713', 4, 4, 4, 1, 'If you''ve taken WW1 or WW2 with Dr. Doerr, this course is similar. Completely multiple choice based except for the final paper. Weekly quizzes are very easy if you take good notes. Final essay is 1200-1500 words and you get a lot of options. He''s a great and funny guy, knows his stuff!! Would highly suggest any of his courses, especially this one!', '["Clear grading criteria","Hilarious","Respected"]', 'A+', 0, 0, 1, NULL, 0, 0, 1649861774, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDY5ODkz', 36069893, '0027644', '10908', 'PHIL-1423', 'PHIL1423', 4, 4, 4, 3, 'Took this as an easy elective and it was okay. Definitely confusing material but any philosophy will be. He'' very nice and approachable, knows his stuff and is super open to any questions. Go to lectures or else you may be confused. Definitely not the easiest bird course but not too bad if you''re willing to actually listen and take good notes.', '["Clear grading criteria","Caring","Lecture heavy"]', 'A-', 0, 0, NULL, 3, 0, 0, 1649861908, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDY5OTQx', 36069941, '0037406', '11344', 'PSYC-2193', 'PSYC2193', 5, 5, 5, 2, 'Hands down the best professor and course I''ve ever had. Dr. Newman is incredible and so passionate. She loves having discussions in class and gets everyone involved. She really connects with and cares about her students and makes it easy to do well in the course. Definitely take this course with her!! One of my highlights at Acadia!', '["Amazing lectures ","Inspirational","Caring"]', 'A', 0, 0, 1, NULL, 0, 0, 1649862255, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDYyMDk3', 36062097, '0038351', '8740', 'FRAN-1623', 'FRAN1623', 3, 3, 3, 4, 'I personally found Ms Davidson to be very understanding and kind. However, it does sometimes feel as though you''re not sure what you''re supposed to do, and assignments/ACORN are confusing. Midterms and exam were a fair difficulty.', '["Tough grader","Lots of homework","Lecture heavy"]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1649780088, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDYyOTEw', 36062910, '0003100', '9283', 'HIST-2783', 'HIST2783', 5, 5, 5, 3, 'I took this class as an elective and it was a great choice. Having come into this class with little knowledge about history, I did not feel out of place. Dr. Henderson was able to effectively cover materials and he seems to actually care about the topics. He is very knowledgeable and well respected.', '["Amazing lectures ","Lecture heavy"]', 'Not sure yet', 0, 1, 1, NULL, 0, 0, 1649784517, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDYyOTI3', 36062927, '0027644', '10934', 'PHIL-2713', 'PHIL2713', 2, 2, 2, 4, 'This was one of the most boring classes I''ve ever taken, and I don''t think Dr. Ramsay helped. His lectures are boring and he does not explain things well.', '["Get ready to read","Lecture heavy","Graded by few things"]', 'B-', 0, 0, NULL, 3, 0, 0, 1649784645, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDc3NzAw', 36077700, '0038351', '8735', 'FRAN-1113', 'FRAN1113', 1, 1, 1, 4, 'For a basic French class she expects a lot from her students. Lectures are just her reading from the textbook. Little to no communication with her students and is overall not very friendly. Unclear expectations for many assignments and never enough time allotted for her tests.', '["Lots of homework"]', 'A', 1, 0, NULL, 3, 0, 0, 1649947357, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MDg2NDUw', 36086450, '0034413', '7292', 'CHEM-1053', 'CHEM1053', 5, 5, 5, 1, 'absolutely love him as a prof, this class was so easier as 50% of marks were quizes he did in class. so this was an easy A+ but you need to go to the lectures. he is a great guy and really knows what he is talking about and seems to be interested in it as well. ive heard he is great for other classes as well... highly reccomend', '["EXTRA CREDIT","Respected","Lecture heavy"]', 'A+', 1, 1, 1, NULL, 0, 0, 1650067045, 1788283351);
