INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MTA3NDc2', 36107476, '0024548', NULL, NULL, '1223', 4, 4, 4, 2, 'Lots of time for assignments, fair exams. Does an excellent job of teaching and communicating. Genuinely wants to see his students succeed. Those who complain are those who do not put in the work and never go to class, he is blamed and disrespected for their own lack of effort. A great professor who deserves more recognition!', '["Accessible outside class"]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1650411760, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MTA5NDgw', 36109480, '0024548', NULL, NULL, '1223', 1, 1, 1, 5, '"Those who complain are those who do not put in the work and never go to class" ok lol I went to every single class and spent anywhere between a half an hour to 2 hours on stats every single night. He''s flat out disrespectful and yells at students for having questions. Puts misleading questions on exams. Class average was a 60. Avoid him if you can', '["Tough grader","Get ready to read","Graded by few things"]', 'Not sure yet', 1, 0, NULL, 3, 1, 2, 1650428943, 1788283346);
