INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MTAzNzk0', 36103794, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 5, 5, 5, 3, 'Awesome prof! I see a lot of people complaining about the testing but I see absolutely no issues at all. You need to attend class to understand the processes discussed in class but as long as you understand what''s going on, tests are fairly easy lol She''s very passionate and a complete sweetheart. Wish I had her for more courses!', '["Amazing lectures ","Respected","Graded by few things"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1650390560, 1788283341);
