INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MzQ4MjU5', 36348259, '0037751', '11057', 'POLS-1403', 'POLS1403', 5, 5, 5, 3, 'I absolutely loved having a class with Professor Brickner. Super kind and exciting. Often, I find professors do not want to have the hard conversations about politics, but she embraced them openly. I would recommend having her as a prof.', '["Clear grading criteria","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1652708920, 1788283352);
