INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MzQ4MzIz', 36348323, '0149576', '11090', 'POLS-2683', 'POLS2683', 3, 3, 3, 4, 'I took Mutlu during the covid/strike year, could be the reason I did not get the Mutlu this form is raving about. I felt he was not understanding of personal struggles outside of the classroom. Seeing his interaction with other students made me aware of this. Hard to catch up if you missed a class, found his writing had needless complexity to it.', '["Participation matters","Respected","Graded by few things"]', 'B', 1, 1, NULL, NULL, 0, 5, 1652709627, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MzQ4Nzc4', 36348778, '0031453', NULL, 'MATH-1213', 'MATH1213', 2, 2, 2, 5, 'Yes, there was a language barrier but in my opinion, that''s not the reason she''s a bad professor. She just doesn''t teach and makes everything complicated if you''re not good at math you are going to struggle heavily in this class.', '["Get ready to read"]', 'F', 1, 0, NULL, 3, 0, 0, 1652714231, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MzQ4ODMw', 36348830, '0037418', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 5, 'I do not like giving bad reviews but he was a horrible professor, and he came back from the strike and got even worse. He does not answer emails on time or sometimes not at all so don''t even bother sending them. He makes so many mistakes in his slides and is EXTREMELY BORING. please avoid him for your sake.', '[]', 'D', 1, 0, NULL, 3, 0, 0, 1652714520, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2MzQzMTI0', 36343124, '0040072', '7997', 'ECON-1013', 'ECON1013', 4, 4, 4, 4, 'Burc is a great prof.I had him for 3 classes my first year-Econ 1023, Econ 2613 and Econ 1013. He really Cares about his students and wants them to succeed if you work hard. My biggest tip is to attend at least one of his office hours as they are super helpful and that could be the reason you pass as he tends to bump up marks if you show you care.', '["Participation matters","Caring","Lecture heavy"]', 'C-', 1, 1, 1, NULL, 0, 0, 1652633370, 1788283342);
