INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU3NDM3', 36457437, '0001179', '11698', 'SOCI-1033', 'SOCI1033', 3, 3, 3, 3, '7 assignments &a mostly multiple choice final that you need to pass to pass the course. Exam went well but you genuinely need to study EVERYTHING in the course. Assignments are easy but she is a very tough grader: took off significant points when I went over the word count and had a simple typo. If u follow directions and proofread you''ll get an A+', '["Tough grader","Get ready to read","Graded by few things"]', 'A', 1, 0, 1, 3, 0, 0, 1654990197, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU4MTYy', 36458162, '0021211', '10901', 'PHIL-1113', 'PHIL1113', 3, 3, 3, 3, 'I am a visual learner and I really struggled to pay attention in his class because he does not use any powerpoints or other visual aids. There was a lot of reading, which I personally didn''t mind but others might not. Otherwise, the content was interesting and I did fairly well.', '["Get ready to read","Lecture heavy"]', 'A-', 1, NULL, NULL, 3, 0, 0, 1655045055, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU4MTcx', 36458171, '0181048', '8903', 'GEOL-1033', 'GEOL1033', 5, 5, 5, 2, 'Absolutely wonderful. She is caring and has a great sense of humour which make her lectures engaging and fun. She also provided an online and in-person option so that everyone would be able to learn at their own speed and comfort level. Even though there were several hundred people in the class, I really felt like she cared about every one of us.', '["Hilarious","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1655046080, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU5MzMw', 36459330, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'Extremely hard marker. If you don''t speak up in class you will not do well, talking in class saved my grade as I did awful on assignments, she is extremely receptive to the people who show up regularly and speak regularly.', '["Tough grader","Group projects","Lecture heavy"]', 'B', 1, 1, NULL, NULL, 0, 0, 1655090158, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU5MzQ2', 36459346, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 2, 'Super in depth lectures and examples and is so friendly, he really wants everyone to succeed. The tests are all on material he gave us in depth examples on, and he is always available to help.', '[]', 'A+', 1, 0, 1, 3, 1, 0, 1655090624, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU5MzUx', 36459351, '0001050', '7997', 'ECON-1013', 'ECON1013', 5, 5, 5, 1, 'Amazing professor, the lectures were light but informative, our whole grade was based off 10 quizzes that we had a week to complete each time one opened, and he always gave the answers in the lectures. No midterm. No exam.', '[]', 'A+', 1, 0, 1, NULL, 0, 0, 1655090703, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDU5MzYz', 36459363, '0040072', '8012', 'ECON-2613', 'ECON2613', 4, 4, 4, 4, 'This class was HARD, it seemed like he overcomplicated the simple things, but if you do the practice and go to his labs you''ll be fine. I cannot stress enough how important it is to go to his labs, he explains so many examples many of which were on the midterms and exams. Nice guy, rounded up my grade from a B- to a B. START ASSIGNMENTS EARLY', '[]', 'B', 1, 1, 1, NULL, 0, 0, 1655090965, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDUwMA==', 364500, '0006798', NULL, NULL, '2203', 2.5, 3, 2, 3, 'What a hottie...in that cute boy kind of way!!!!! ;)', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1037917329, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDUyOA==', 364528, '0006798', NULL, NULL, '4916', 3, 3, 3, 3, 'Great guy, but one never knows which Dr Doer is gonna show up.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1037917696, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDY0MTc4', 36464178, '0006798', '9194', 'HIST-1713', 'HIST1713', 5, 5, 5, 2, 'I loved taking this course with Doerr, he was really funny, and he made sure everyone understood the criteria. In the course i was in the final exam was easy and open book as well as every test. the only thing that was marked harsh was the final essay in the course. I did not read the textbook once but it will help you in the end.', '["Clear grading criteria","Hilarious","Lecture heavy"]', 'B+', 1, 0, 1, 3, 1, 0, 1655247326, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDY0NzQw', 36464740, '0000902', '8899', 'GEOL-1010L', 'GEOL1010L', 5, 5, 5, 1, 'LOVED the course and the prof, was super nice and caring, and always tried to help me with my essays and writing. He grades people fairly (only low marks because the big jump from high school). Didn''t have any tests, midterms, or a final which helped a lot. There is a little bit of writing and reading but the course is interesting so didn''t matter.', '["Amazing lectures ","Clear grading criteria","Gives good feedback"]', 'C-', 1, 0, 1, 3, 0, 0, 1655259668, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDY0NzYw', 36464760, '0169986', '11319', 'PSYC-1113', 'PSYC1113', 5, 5, 5, 1, 'One of the BEST profs here. This was my first class ever at Acadia and he made everyone feel welcome, he cracked quite a bit of joke and I enjoyed going to lectures. Graded everything easy and overall just a very kind person, lectures were interesting and finals and midterms were fairly easy. He also didn''t use textbooks to make it less expensive!', '["Amazing lectures ","Hilarious","Caring"]', 'C', 1, 0, 1, NULL, 1, 0, 1655260209, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDY0Nzc3', 36464777, '0181048', '8903', 'GEOL-1033', 'GEOL1033', 4, 4, 4, 1, 'Morgan is a very kind and caring prof and will help whenever needed. The class was fairly easy and they grade really well. Midterms and exams were a bit challenging. The only downside was they''re kind of all over the place and I found it really hard to learn like that. Though I still enjoyed the class and the questions after lectures online.', '["Caring","Lecture heavy","Online Savvy"]', 'B+', 1, 0, NULL, NULL, 0, 0, 1655260685, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDY4NjQ2', 36468646, '0037418', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 5, 'The worst prof I''ve had by far, He''s very kind towards his students and I like him as a person, but he cannot teach, he expects you to know everything already. The class average for our midterm was 39%, which should tell you everything you need to know. Stats is hard as is and having a prof who can''t teach well makes it 10x harder. AVOID if can!', '["Tough grader","Lots of homework","Graded by few things"]', 'D', 1, 1, NULL, 3, 1, 0, 1655399457, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NDYyNzE0', 36462714, '0013405', '10576', 'NUTR-1313', 'NUTR1313', 5, 5, 5, 3, 'She is amazing!', '["Inspirational","Caring","Respected"]', 'A-', 1, 0, 1, 3, 0, 0, 1655217689, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTA4MzAw', 36508300, '0034695', '10468', 'MUSI-4143', 'MUSI4143', 5, 5, 5, 3, 'Dr. Mark Hopkins is easily the best professor I have ever had at Acadia University. He is very accommodating to everyone and certainly the LEAST biased of every professor. He understands everyones various musical backgrounds and will work around that to make for a meaningful classroom experience. Definitely someone I look up to as a future Mus.Ed.', '["Inspirational","Respected","Accessible outside class"]', 'A', 1, 1, 1, 3, 0, 0, 1657193691, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTAxNzgx', 36501781, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 5, 5, 5, 3, 'I swear she''s really nice, literally talk to her during office hours and ask questions. I mentioned that I was struggling with something in another course, and the next lab we had she asked me how it went. Absolutely intimidating at first, but if you follow the rules (which she makes very clear) she is absolutely one of the best out there.', '["Gives good feedback"]', 'A-', 1, 1, 1, NULL, 0, 0, 1656880289, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTQ3Mjg2', 36547286, '0013980', '8394', 'ENGL-1423', 'ENGL1423', 5, 5, 5, 2, 'His lectures are long but engaging and his grading on essays are a lot more lax than other profs at Acadia. He grades based on the quality of work and points made whether than quantity or academic it is. The exam was super easy as well, we essentially wrote book reports for three hours. Id take him again in a heartbeat!', '["Get ready to read","Participation matters","Gives good feedback"]', 'A', 1, 0, 1, NULL, 0, 0, 1659035142, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTQ3Mjk3', 36547297, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 5, 5, 5, 5, 'Daniel Blustein is one of the most relaxed professors I have had at Acadia. His lectures are engaging and very accessible if you''ve missed a class. He is so incredibly sorted and his ACORN page is exquisite. All of his exams and midterms were open book, though it didn''t make the course any easier.', '["Tough grader","Amazing lectures ","Online Savvy"]', 'C+', 1, 0, 1, 3, 0, 0, 1659035429, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTQ3MzA1', 36547305, '0001179', NULL, 'SOCI-1006', 'SOCI1006', 2, 2, 2, 2, 'She was a sub professor half-way through my first semester and I have to give her props for cleaning up the previous profs missteps. She was very receptive to our feedback in class but it was exceptionally difficult outside of class to contact her. Her style of teaching was reading off of the massive slide shows and then quizzing you on theory.', '["Get ready to read","Group projects","Lecture heavy"]', 'A', 1, 0, NULL, 3, 2, 0, 1659035609, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTQ3MzMx', 36547331, '0036828', '7841', 'CREL-2533', 'CREL2533', 2, 2, 2, 3, 'She is a awesome prof to talk to outside of class but it doesn''t translate well to in-class time. She goes on several tangents and is quite rude to students who disagree with her opinion on the subject matter. Donna DOES NOT discuss feminism, or religion without a heavy bias. On the upside, its one paper at the end of the semester.', '["Get ready to read","Participation matters","Clear grading criteria"]', 'B+', 1, 1, NULL, NULL, 0, 0, 1659035948, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTQ3MzU5', 36547359, '0031056', '9185', 'HIST-1413', 'HIST1413', 3, 3, 3, 4, 'His lectures are really, really dry and he doesn''t seem to have much heart in the topic. If you miss a class however, you usually miss quite a bit of content because his slides summarize his points and don''t elaborate in slide notes. Pray you have a friend whos willing to take notes in the class when you''re not there.', '["Tough grader","Get ready to read","Lecture heavy"]', 'B-', 1, 1, NULL, 3, 0, 0, 1659036449, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTYxODcx', 36561871, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 1, 1, 1, 3, 'Incredible lecturer but very biased in treatment of students. Ended with a good grade and a better understanding of inorganic chemistry though.', '[]', 'A', 1, 1, NULL, 3, 0, 0, 1659584945, 1788283342);
