INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NTk3ODY5', 36597869, '0023439', NULL, 'SOC-2013', 'SOC2013', 5, 5, 5, 2, 'if you frequently attend classes, this class was a breeze. Dr. Frank thoroughly explains everything you need to know for this class and even walks you through her expectations for assignments. She will answer any question with a smile and really wants you to succeed in her class.', '["Clear grading criteria","Caring","Accessible outside class"]', 'A', 1, 1, 1, 3, 0, 0, 1660944008, 1788283349);
