INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NjIxMzMx', 36621331, '0018366', NULL, NULL, 'ENGL', 1, 1, 1, 5, 'Quema is the least personable, and rudest woman I''ve ever encountered. She truly puts the school to shame, and lacks humanity in her approach. She''s by the book in a infantry-like way, and acts more like a warden then an educator. F - Minus.', '[]', 'A', 1, 0, NULL, NULL, 1, 0, 1661959882, 1788283341);
