INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NjMxNjgy', 36631682, '0192432', '11386', 'PSYC-3383', 'PSYC3383', 4, 4, 4, 3, '2nd course I took with Dr. Blustein & I have to say, it was much better than the 1st! He was way better about answering questions this time around and was always open to feedback on his teaching methods, which I appreciated. The course was interesting and he''s a nice, easy going guy. A lot of complex info but he''s not an incredibly tough marker :)', '["Caring","Lecture heavy","Online Savvy"]', 'A+', 1, NULL, NULL, NULL, 0, 0, 1662578260, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NjMxNjkz', 36631693, '0037406', '11355', 'PSYC-3053', 'PSYC3053', 5, 5, 5, 2, 'One of my favourite profs! Randy is so kind & caring & genuinely wants her students to do well. Presents course material in an interesting and comprehendable way. Always open to questions. Makes time for her students outside of class time, despite also being the head of the department. If you have a chance to take a class with Dr. Newman, do it!', '["Inspirational","Caring","Respected"]', 'A+', 1, NULL, 1, NULL, 0, 0, 1662578598, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NjUxNDc3', 36651477, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 3, 'marked harshly on very few assignments. a 60% was considered a very good score compared to an average of 80 or above. she has very limited communication skills and was quick to run out of patience when people were uncomfortable participating or had nothing to contribute
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njc1MDI0', 36675024, '0042843', NULL, NULL, 'ALLCLASSES', 1, 1, 1, 5, 'Get ready to guess what your grade is on all assignments until after it''s considered final', '["Tough grader","Participation matters"]', 'Rather not say', 1, 1, NULL, NULL, 0, 0, 1664841219, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njc4MDM1', 36678035, '0169988', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 3, 'Really enjoyed taking this class. I have a lot of respect for Dr. Pinder; she is very knowledgeable, and she made the class interesting, and enjoyable (even for a non-English major). She leads group discussions very well. You definitely need to work for your grade in her class, but what would the point of university be if you didn''t?', '["Participation matters","Gives good feedback","Accessible outside class"]', 'Rather not say', 1, 1, 1, NULL, 0, 0, 1664929859, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njc4MDY2', 36678066, '0013405', '10577', 'NUTR-1323', 'NUTR1323', 5, 5, 5, 3, 'Really great prof! She is very knowledgeable, and her classes are very interesting. Weekly tests instead of midterms which was a nice stress-reducer. If you go to class and participate you will likely do well, you need to stay on top of the work, otherwise, it will pile up fast. She is very approachable and willing to offer clarity if you need it.', '["Clear grading criteria","Caring","Accessible outside class"]', 'Rather not say', 1, 0, 1, 3, 0, 0, 1664930471, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njg0NjE3', 36684617, '0000673', '6900', 'BIOL-2813', 'BIOL2813', 5, 5, 5, 3, 'Dr. Boates is a super kind, funny, and knowledgeable prof. He really wants to get to know his students, and makes lectures interesting by bringing in news stories and recent scientific discoveries/research. He moves a bit quickly through lecture material. Overall, he''s great and I''d highly recommend!', '["Hilarious","Caring","Lecture heavy"]', 'A-', 1, 1, 1, NULL, 0, 0, 1665154066, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njg0NjEx', 36684611, '0180912', '11337', 'PSYC-2123', 'PSYC2123', 5, 5, 5, 2, 'Dr. Leslie is a super funny, kind, quirky, and fun prof! He''s very fair when creating tests/midterms (no questions are unexpected), and he really wants his students to succeed. He has some cool research on dreaming going on outside of Acadia, too. Also, he plays the ukulele.', '["Inspirational","Hilarious","Caring"]', 'A', 1, 0, 1, NULL, 0, 0, 1665153887, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Njg2MjI5', 36686229, '0024548', NULL, 'MATH-1223', 'MATH1223', 3, 3, 3, 4, 'The midterm and exam were online, so I can''t really complain. However, if you''re not good at math, won''t be a good fit.', '["Lots of homework","Lecture heavy"]', 'A-', 1, 0, 1, 3, 0, 0, 1665248449, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NjgyMTc1', 36682175, '0016779', '8394', 'ENGL-1423', 'ENGL1423', 2, 2, 2, 5, 'Do not come into this class without having taken a university english course. You need a strong understanding of university writing to get a somewhat decent mark. Sometimes uses poems that aren''t appropriate and leaves the whole class feeling uncomfortable. Good luck', '["Tough grader","Beware of pop quizzes","Lecture heavy"]', 'A-', 1, 1, NULL, 3, 0, 0, 1665068156, 1788283355);
