INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2NzA5ODc5', 36709879, '0016779', '8394', 'ENGL-1423', 'ENGL1423', 1, 1, 1, 5, 'Ahern does not deliver class material effectively. Rather than ensuring students needs are met, Ahern belittles you and your abilities.. He is rude, arrogant and dominant in his beliefs. I would not recommend taking ANY classes with him.', '["Tough grader","Beware of pop quizzes","Test heavy"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1666064654, 1788283355);
