INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Nzc4MzEz', 36778313, '0042843', '7187', 'BUSI-3433', 'BUSI3433', 5, 5, 5, 4, 'I am not sure why Dr. Sears has such a low rating. She''s quite outgoing and enjoys talking about her personal life. However, she can be a tough grader, and sometimes unclear in her lectures. But, if you just show up to classes and email her when you have any questions, you''ll do good in her classes.', '["Tough grader","Participation matters","Caring"]', 'A-', 1, 1, 1, NULL, 0, 0, 1667531202, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Nzc4MzUz', 36778353, '0034094', '7187', 'BUSI-3433', 'BUSI3433', 3, 3, 3, 5, 'Here''s the truth. Kapoor is a difficult teacher, with biased opinions, and extremely hard midterms. Yes, he''s unfair, and mean, and you''ll probably cry. But, write down everything he says in class, review your notes every day, and READ the textbook chapters. You must try HARD in his classes. He''s not a bad guy, quite funny but a very hard teacher.', '["Tough grader","Get ready to read","Test heavy"]', 'C+', 1, 1, 1, 3, 0, 0, 1667531695, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Nzc4Mzcz', 36778373, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 2, 2, 2, 4, 'I genuinely don''t know or understand the importance of this teacher or class. He is SO boring, all we do is present and write group assignments weekly. He marks them so hard for no reason. He seems like a sweet guy, but this class is pointless. If you are stuck in a bad group, GOOD LUCK.', '["Tough grader","Group projects","Lots of homework"]', 'Incomplete', 1, 0, 1, NULL, 0, 0, 1667531977, 1788283342);
