INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2Nzk5Mzk5', 36799399, '0102067', '11751', 'SOCI-3013', 'SOCI3013', 1, 1, 1, 5, 'Jesse makes his lectures so boring. He does not engage with his students at all. He makes it so hard to pay attention and it''s so hard to know what you''re learning in his class from time to time. I do not recommend taking any of his classes.', '["Tough grader","Beware of pop quizzes","Test heavy"]', 'Drop/Withdrawal', 1, 1, NULL, 3, 0, 0, 1667953192, 1788283346);
