INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODA2NTUw', 36806550, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 5, 5, 5, 3, 'She is an amazing teacher and cares a lot about her students and actually wants them to succeed. She teaches concepts as if we were in high school which is really appreciated. Would definitely recommend her classes.', '["Amazing lectures ","Gives good feedback","Caring"]', 'A+', 0, 0, 1, NULL, 0, 0, 1668034703, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODE4MDE4', 36818018, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 3, 'Great teaching with even better looks.', '["Tough grader","Amazing lectures ","Respected"]', 'A+', 1, 0, 1, NULL, 0, 0, 1668191413, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODQ3NTY4', 36847568, '0034933', '7646', 'COMM-1013', 'COMM1013', 2, 2, 2, 5, 'The grading is very inconsistent. By that I mean if you do not quote the definition word by word this could result in loss of points, although it seems like sometimes if you don''t quote exactly he will still give some generous points. Does not state mistakes in grading, therefore it''s unclear on how to learn and improve from these mistakes.', '["Tough grader","Lecture heavy","Test heavy"]', 'B+', 1, 1, NULL, 3, 0, 0, 1668630202, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODU2MzQ1', 36856345, '0013835', '8200', 'EDUC-4333', 'EDUC4333', 1, 1, 1, 3, 'If you want to take a class where every time you speak and try to learn you immediately get shut down, then this is the class for you! After hours of preaching about giving students a safe space, there is 0 space to learn and grow in this classroom. Repetition of lectures and didn''t introduce a major assignment until 3 days before it was due.', '["Group projects","Lecture heavy","Graded by few things"]', 'A', 1, 1, NULL, 3, 1, 0, 1668712630, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODU2OTA2', 36856906, '0041312', NULL, 'ENG-1406', 'ENG1406', 2, 2, 2, 5, 'Michelle is a kind person, but she does not belong teaching a first year intro course. She is very difficult to please and expects higher standards than what most first years are capable of in their first semester. My confidence in writing was ruined after taking her course and caused me to have severe anxiety around writing essays in second year.', '["Tough grader","Get ready to read"]', NULL, 1, 1, NULL, 3, 0, 0, 1668715351, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODUyOTQ=', 3685294, '0016779', NULL, NULL, '18THCENNOVEL', 3, 3, 3, 3, 'Ahern is intelligent but arrogant. He''s a &quot;know-it-all&quot; and if you disagree with him, you will feel his wrath. He is a helpful/detailed but very tough marker. I''m not really sure that his class is useful/helpful... I don''t think I actually learned anything I can apply to my other classes...', '[]', NULL, 0, NULL, NULL, NULL, 2, 1, 1114153845, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODUzODEz', 36853813, '0140662', '7142', 'BUSI-2433', 'BUSI2433', 4, 4, 4, 1, 'As long as you show up to class for the participation activities and weekly quizzes you will pass. Not many assignments and only one test. Pretty simple class just show up.', '["Participation matters","Inspirational","Beware of pop quizzes"]', 'A-', 1, 1, 1, NULL, 0, 0, 1668699555, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODUzODM5', 36853839, '0140662', '7142', 'BUSI-2433', 'BUSI2433', 4, 4, 4, 2, 'Wenxia is a very easy going Prof who cares about her students, she is very understanding and easy going. Attendance is mandatory as she does a lot of participation activities. Wenxia is a very fair marker and spread the graded weight throughout multiple assignments, participation and quizzes.', '["Participation matters","Clear grading criteria"]', 'A-', 1, 1, 1, 3, 0, 0, 1668699676, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODUzODg0', 36853884, '0034433', '7134', 'BUSI-2223', 'BUSI2223', 3, 3, 3, 4, 'Don''t fall behind on lectures or you''ll get confused quickly. Take notes and pay attention during lectures. Don''t miss quizzes for every chapter. Study for midterms they''re tough. Show up and listen and you will do fine.', '["Lots of homework","Lecture heavy"]', 'B-', 1, 0, 1, NULL, 0, 0, 1668699967, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODUzOTEx', 36853911, '0150055', '7143', 'BUSI-2513', 'BUSI2513', 4, 4, 4, 2, 'Very easy prof for Operations Management. Attendance isn''t really necessary as long as you look at the notes online. Midterms and quizzes are also pretty easy, he allows a double-sided cheat sheet for everything.', '["Group projects","Clear grading criteria","Accessible outside class"]', 'A', 1, 0, 1, NULL, 0, 0, 1668700154, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODY0MDA3', 36864007, '0015754', NULL, NULL, 'ENG', 5, 5, 5, 3, 'Jessica is very passionate about English and does a great job of sharing that passion with her students. She gives great feedback on essays and is very accessible outside of class which makes the course very easy, and a great opportunity to improve.', '["Amazing lectures ","Clear grading criteria","Caring"]', 'A-', 1, 1, 1, NULL, 1, 0, 1670465027, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODY3MTg=', 3686718, '0021447', NULL, NULL, 'MATH', 4, 4, 4, 3, 'Really great prof! He actually makes math really interesting and explains it really well. He has a pretty good sense of humor. I also like the fact that there is no such thing as a dumb question in his class.', '[]', NULL, 0, NULL, NULL, NULL, 1, 0, 1114170436, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYwMTEx', 36860111, '0034413', '7309', 'CHEM-2513', 'CHEM2513', 4, 4, 4, 3, 'Lukeman is a hip dad through and through. He is beloved, approachable, always available for questions and a good lecturer. You do need to put in the work but he''s not one of those profs thats gate keeping things. He truly wants you to succeed. He''s also easily distracted so watch out for that.', '["Hilarious","Respected","Accessible outside class"]', 'A', 1, 1, 1, NULL, 0, 0, 1668736660, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYwMTQw', 36860140, '0021212', '9945', 'MATH-1023', 'MATH1023', 5, 5, 5, 3, 'Dr. K is a beautiful sole with a luscious pony tail that could make anyone jealous.Unfortunately he teaches calculus. It is not his fault intro calc sucks but he was amazing and made it so much more manageable than I could have thought.', '["Participation matters","Lots of homework","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1668736904, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYzNjk2', 36863696, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 4, 4, 4, 4, 'Dan Blustein is a great prof. I had to take a class in the science department and I''m glad I took it with him. He does his best to make psych appealing to non-majors and does a great job. Lectures are fascinating & interactive, and his Acorn page is incredible. All exams are open book, but it don''t let that fool you as it''s still very challenging.', '["Amazing lectures ","Test heavy","Online Savvy"]', NULL, 1, 0, 1, NULL, 0, 0, 1668795371, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYzNzYz', 36863763, '0016655', '9270', 'HIST-2563', 'HIST2563', 2, 2, 2, 4, NULL, '["Get ready to read","Hilarious","Graded by few things"]', NULL, 1, 1, NULL, 3, 0, 1, 1669129952, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYzODUx', 36863851, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 4, 4, 4, 3, 'I had to take one science class, and I''m glad I took it with Blustein. His lectures are fascinating & interactive, and he does his best to make them appealing for everyone. Acorn page is great and he records all his lectures in case students miss class. His exams are also open book, but don''t be fooled, this won''t help you if you don''t study.', '["Amazing lectures ","Lecture heavy","Online Savvy"]', NULL, 1, 0, 1, NULL, 0, 0, 1668796448, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODYzOTA2', 36863906, '0139613', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 2, 'Crandall is an excellent prof. Her lectures are interesting, and she gives fun and exciting projects. She does a great job of explaining everything clearly, and her slides & Acorn are great. She grades well, is accessible outside of class, and she won''t hesitate to help you if you need it. Check in quizzes are helpful and simple too.', '["Group projects","Amazing lectures ","Clear grading criteria"]', 'A-', 1, 0, 1, NULL, 0, 0, 1670465065, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODc1OTcx', 36875971, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 3, 'top G', '["Gives good feedback","Lots of homework","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1669063668, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODg3MjI2', 36887226, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 2, 2, 2, 4, 'he doesn''t teach, just posts instructions of pointless assignments that for the most part make no sense.', '["Tough grader","Group projects","Lots of homework"]', 'Incomplete', 1, 0, NULL, NULL, 0, 0, 1669248150, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODk2ODAw', 36896800, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 3, 3, 3, 5, 'This class is passable but it''s definitely not enjoyable. The group projects are super vague and midterms are hard if you don''t remember every little detail he says. Professor''s not a terrible guy but he can be pretty mean and intimidating, just make sure you pay attention in case you get called on if you don''t want to be shamed.', '["Tough grader","Group projects","Graded by few things"]', 'Not sure yet', 1, 1, NULL, 3, 0, 1, 1669601813, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODk5OTcz', 36899973, '0021447', '9945', 'MATH-1023', 'MATH1023', 5, 5, 5, 2, 'He is no less than GOD. Take his class', '["EXTRA CREDIT","Amazing lectures ","Hilarious"]', 'A+', 1, 0, 1, NULL, 1, 0, 1669655662, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODkyMTA=', 3689210, '0000957', NULL, 'SOC-1113', 'SOC1113', 5, 5, 5, 1, 'She is super enthusiastic about everything in this course. Her passion for anthropology is obvious. Definitely take a course from her, you won''t regret it!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1114188576, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2ODkzNzE5', 36893719, '0021211', NULL, 'PHIL-1213', 'PHIL1213', 3, 3, 3, 3, 'Nice enough guy, ask him questions and he will clarify. My issues with his courses are structural, he said he would post lecture notes and didn''t, so if you''re out sick for a day or two you miss information you''ve paid for. He also doesn''t allow laptops for notetaking, which I didn''t like because this is not 2004. Besides this, his course was fine.', '[]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1669507619, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTAyNTIz', 36902523, '0021421', '9764', 'KINE-2413', 'KINE2413', 5, 5, 5, 4, 'I loved taking Dr. Fowle''s class this semester! He was engaging through all lectures and made sure that you understand the material. He wants you to succeed in his class and does this by being accessible outside of class and explaining things multiple times. He knows that the material is tough so he gives lots of opportunities to succeed in class.', '["Caring","Respected","Accessible outside class"]', 'Not sure yet', 1, NULL, 1, 3, 0, 0, 1669666432, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTAyNjYx', 36902661, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 2, 2, 2, 4, 'took this class because I was told it was easy especially with him, wrong. his lectures are boring and he often talks to fast making it hard to keep up. weekly quizzes are a nice grade booster but open book midterms are difficult as there are questions about things that you haven''t learned so you can''t find the answer in class notes. don''t take.', '["Participation matters","EXTRA CREDIT","Lecture heavy"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1669666987, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTAyNzI0', 36902724, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 3, 'Ryan''s literally an angel on this earth! Classes are offered online. Topic is a little boring but as long as you study you''ll be fine. MyLab assignments are super helpful for studying and a really awesome grade booster (worth 25% of final grade) as they''re easy to get 100% on. He also will drop your lowest test mark and replace with the final.', '["Amazing lectures ","Clear grading criteria","Accessible outside class"]', 'Not sure yet', 1, 0, 1, 3, 1, 0, 1669667277, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTExNzg0', 36911784, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 2, 2, 2, 3, 'The way this course is taught is odd. There are no assignments, the entirety of your grade is based on 3 quizzes, 1 midterm and 1 final test. Only the best 2 quiz scores are counted, but having 4 tests to make up 100% of a grade is ridiculous. A few assignments to build up your average and to get feedback on would improve the class tenfold.', '["Get ready to read","Test heavy","Graded by few things"]', 'C', 1, 0, NULL, NULL, 0, 0, 1669746495, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTExODQz', 36911843, '0034433', '7134', 'BUSI-2223', 'BUSI2223', 4, 4, 4, 3, 'Tough but fair. Finance 1 is a hard course, but Yang does his best to make things as simple to grasp as possible. He wants you to try things out yourself, so don''t expect to be given the answer right away. He''s engaging and can be funny, and while his accent can be a little thick, he delivers lectures in a way that anyone can excel in if they try', '["Participation matters","Clear grading criteria","Lots of homework"]', 'B', 1, 0, 1, 3, 0, 0, 1669746758, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTI0MzU1', 36924355, '0015959', '7597', 'CODE-1013', 'CODE1013', 5, 5, 5, 2, 'She is literally the Goat prof. If you get any chance take a class with her.', '["Inspirational","Caring","Respected"]', NULL, 1, 1, 1, NULL, 0, 0, 1669836375, 1788283362);
