INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTM0NTY=', 3693456, '0021212', NULL, NULL, 'SEVERALVARI', 4.5, 4, 5, 5, 'Very intellegent man, but maybe a little too hopeful on the midterms. They are hard, watch out! His hair is HOT! And as for the spastic movements, it keeps you listening and watching.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1114266799, 1788283353);
