INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTM5MTgx', 36939181, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'Truly a great prof who cares about his students. Very nice, and will go out of his way to help you out. If you have the opportunity to take a class with him do it.', '["Amazing lectures ","Caring","Respected"]', 'A+', 1, 0, 1, 3, 0, 0, 1669929213, 1788283364);
