INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTU5MTA4', 36959108, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'Don''t take this class if you don''t have to. Participation is worth 20%, such a hard marker it''s ridiculous. Comm isn''t hard, the over-the-top marking screws you. She is a very kind person, but impossible to reach outside of class. Lectures are boring, skipping class annoys her, she very rudely calls out people who look bored, as if it''s our fault.', '["Tough grader","Participation matters","Group projects"]', 'B+', 1, 1, NULL, 3, 1, 0, 1670120549, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTU5MTU4', 36959158, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'He only wants you to succeed. It was so nice to have a prof that cares about our learning, not memorization. MyLab assignments and practice questions help you prepare for tests so well. He makes dumb jokes and is genuinely so kind. This was a mandatory class for me, but if you''re looking for an elective I would take his classes if I were you.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A', 1, 0, 1, NULL, 0, 0, 1670121281, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTU5MjI5', 36959229, '0141387', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 3, 'Made me love poli sci so much more. He does a government simulation for two weeks, it was literally so fun. No midterms, only a quiz, and an exam. He''s young, energetic, and super knowledgeable. My favourite elective, hope I can have him as a prof again.', '["Participation matters","Amazing lectures ","Accessible outside class"]', 'A', 1, 0, 1, NULL, 0, 0, 1670122137, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTY4ODE2', 36968816, '0044772', '7305', 'CHEM-2303', 'CHEM2303', 5, 5, 5, 4, 'Dr. Ellis is a very funny prof, his material is difficult and he goes through material very quickly but he gives loads of bonus points to make everything easier. Also does fun-fact Fridays so I would definitely would take again.', '["EXTRA CREDIT","Lots of homework","Hilarious"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1670251922, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM2OTc0ODQy', 36974842, '0028039', NULL, NULL, '3583', 5, 5, 5, 2, 'Had him for both animal bio and eukaryotic. He really cares about his students and wants them to do well. Keeps his PowerPoints short and only does a max of 10 slides per lecture. He posted all his lectures online as well so if you miss a class or didn''t catch something in the lecture you are able to review. Great prof all around.', '["Amazing lectures ","Gives good feedback","Accessible outside class"]', 'Not sure yet', 0, 0, 1, NULL, 0, 0, 1670272199, 1788283355);
