INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NDIwODg0', 37420884, '0048856', NULL, NULL, 'ORGANICLAB', 5, 5, 5, 3, 'I had Teri for CHEM2513 (Organic chem 1) and CHEM2530L (Organic chem 2 lab). Teri was an amazing prof. She made me understand o chem and that says a lot. She hosts office hours and AMAZING tutorials on her own time and genuinely cares so much about her students. She goes above and beyond to give every opportunity for success even as the lab prof.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1675973324, 1788283362);
