INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NDIxMzMx', 37421331, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 2, 'Teri is an amazing lab instructor and a great prof! I found that she is really good at making sure students understand the material by being very concise with her words. Her mantras and analogies also help to remember the material.', '["Gives good feedback","Hilarious","Caring"]', NULL, 1, 1, 1, NULL, 0, 0, 1675981337, 1788283362);
