INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTQ3OTM5', 37547939, '0176310', '11390', 'PSYC-3623', 'PSYC3623', 5, 5, 5, 2, 'Scott is a great guy! He really cares for his students and classes were always fun and engaging. There is a lot of stuff graded for the class, but it''s nothing that is super hard so it''s easy to keep your grade up. Very approachable and easy to contact outside of class. Wish he taught more classes here, he''s awesome!', '["Amazing lectures ","Clear grading criteria","Caring"]', NULL, 1, 1, 1, NULL, 0, 0, 1679972855, 1788283364);
