INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTU3NDI2', 37557426, '0039699', '11057', 'POLS-1403', 'POLS1403', 1, 1, 1, 5, 'Do not take this class if you have any interest in learning about politics, or if you plan on having questions about anything. No real knowledge gained, and never looked forward to going to class. Very mean to me several times when I was asking for help. Not understanding at all.', '[]', 'Not sure yet', 1, 1, NULL, 3, 3, 0, 1680133656, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTU4MDUy', 37558052, '0012762', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 5, 'Just stay away. Communications is useless yet students are marked so harshly, ridiculous. Kendra takes "tough grader" to the next level. If you don''t have to take this course DON''T TAKE IT! Steer clear of her no matter what class she''s teaching, she loved me, I got one of the highest marks, too many ppl fail, Biz students good luck, you''ll need it.', '["Tough grader","Participation matters","Lots of homework"]', 'B', 1, 1, NULL, 3, 1, 0, 1680142401, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTU4MTYy', 37558162, '0003993', '9969', 'MATH-1613', 'MATH1613', 5, 5, 5, 3, 'I hate math, but I love Jim. Amazing prof, so helpful, he doesn''t have dedicated office hours bc he wants to be available whenever he can be. He so clearly cares about your success, holds review sessions before tests, wants to help you understand, he''s an oddball and loves to laugh, the extra help he offers is a lifesaver.', '["Hilarious","Caring","Accessible outside class"]', 'B-', 1, 0, 1, 3, 0, 0, 1680143809, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTU4MTgx', 37558181, '0039699', '11057', 'POLS-1403', 'POLS1403', 2, 2, 2, 5, 'All that matters is his opinion if he disagrees with yours he shames you in front of the entire class. No textbook but you have to buy a book every week for the papers. For POLS1403 going to class is useless only go on the day you have to submit your papers, if it''s online submission don''t go at all. I''m a Politics major I didn''t learn anything.', '["Get ready to read","Participation matters","So many papers"]', 'B+', 1, 0, NULL, NULL, 4, 0, 1680144078, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTU5MjU0', 37559254, '0304310', '11153', 'POLS-3773', 'POLS-3773', 1, 1, 1, 2, 'I genuinely cannot even describe to you how brutal this class was to take. Attendance is mandatory or else you will lose 10% off of your WHOLE grade. Lectures are actually useless and are oftentimes very uncomfortable because topics are very controversial and he likes to play "devil''s advocate". Overall I couldn''t tell you what I learned this year.', '[]', 'Not sure yet', 1, 1, NULL, NULL, 3, 1, 1680182692, 1788283339);
