INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTUwMjI1', 37550225, '0037539', '9943', 'MATH-1013', 'MATH1013', 2, 2, 2, 4, 'She''s really nice as a person and wants all her students to succeed. On the downside she tends to over explain topics so much that by the end of the class, you''re even more confused.', '["Tough grader","Lots of homework"]', 'A-', 1, 1, NULL, NULL, 0, 0, 1680025434, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTUwMjU0', 37550254, '0015486', NULL, 'BIO-1813', 'BIO1813', 5, 5, 5, 3, 'Super nice guy and open for anyone to ask questions. If there''s a tough topic that a lot of students don''t understand, he''ll go over it again more slowly and provides lots of helpful diagrams and videos.', '["Amazing lectures "]', 'A', 1, 0, 1, NULL, 0, 0, 1680025627, 1788283360);
