INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY2NjQ1', 37566645, '0001916', NULL, 'BIO-2563', 'BIO2563', 5, 5, 5, 3, 'An amazing prof, such an interesting class and he keeps you engaged, lots of videos to help you understand the things being learned. Also gives really good feedback and is helpful when needed. The tests can be a little hard, but not too bad.', '["Amazing lectures ","Clear grading criteria","Test heavy"]', 'B-', 1, 0, 1, NULL, 0, 0, 1680304189, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY2NjY5', 37566669, '0019405', '8735', 'FRAN-1113', 'FRAN1113', 5, 5, 5, 1, 'One of the best professors in my opinion! accommodating and caring toward students. He does not force anyone to speak out loud if they don''t want to. The only thing is you should go to class because lectures are done strictly on the chalkboard.', '["Clear grading criteria","Gives good feedback","Caring"]', 'B+', 1, 0, 1, 3, 0, 0, 1680304740, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY2NjYw', 37566660, '0021658', NULL, NULL, '1213', 2, 2, 2, 4, 'As much as I liked him as a person, I did not like him as a prof as much, very harsh marker and doesn''t explain how to fix the mistakes you make. Other than that, his lectures were always very entertaining and he was very accommodating and flexible with deadlines.', '["Tough grader","Hilarious","Graded by few things"]', 'D', 1, 1, NULL, NULL, 0, 0, 1680304475, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY2Njgz', 37566683, '0003424', '11060', 'POLS-2003', 'POLS2003', 4, 4, 4, 1, 'Such a sweet prof and so caring about her students and cares so much about what she is teaching. The only downside is sometimes her teaching style can be a little confusing but that can be helped by just sending her an email as she tends to respond very quickly!', '["Get ready to read","Group projects","Caring"]', 'A-', 1, 0, 1, 3, 2, 10, 1680304945, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY2Njk1', 37566695, '0180912', '11337', 'PSYC-2123', 'PSYC2123', 5, 5, 5, 1, 'What an amazing prof! I always understood everything going on in the class, and he was always available for any questions I had. The grading and tests were very fair and the content of the tests came straight from the lectures. He is also very accommodating as well.', '["Amazing lectures ","Clear grading criteria","Caring"]', 'B', 1, 0, 1, 3, 0, 0, 1680305146, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY3Njk2', 37567696, '0027840', NULL, NULL, 'THEATRE', 1, 1, 1, 5, 'Michael Devine will assign texts with the preface that you are to ''make it your own'', and to not watch professional performances of it. His marking and feedback then directly go back on this, only giving high grades if you replicate it exactly how he wants.
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY3NzA0', 37567704, '0000916', '7998', 'ECON-1023', 'ECON1023', 1, 1, 1, 4, 'I hold a great deal of respect for Dr. Moussa, but he is very hard to hear during his lectures. Wording of questions on assignments / tests can be confusing and irritating at times. Notes are cluttered and confusing.', '["Lecture heavy"]', 'Drop/Withdrawal', 1, 0, NULL, 3, 0, 0, 1680332020, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTY4MjI0', 37568224, '0027840', NULL, NULL, 'THEA', 1, 1, 1, 4, 'Gym teacher moreso than theater teacher', '["Participation matters"]', 'Drop/Withdrawal', 1, 1, NULL, 3, 1, 0, 1680373854, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTYyNzQ3', 37562747, '0133590', '6837', 'BIOL-1123', 'BIOL1123', 5, 5, 5, 2, 'Such a nice teacher! midterms were easy as long as you go over material, marks very easily. She is a little quiet sometimes during lecture, but really not too bad just sit closer up front. There was no final for this class which was nice, but we did have to do a group presentation, but again its was really easy and only worth 10% of your grade', '["Group projects","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1680221176, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTYzOQ==', 375639, '0008859', NULL, 'PHIL-3383', 'PHIL3383', 5, 5, 5, 3, 'Most intelligent man alive, bar none...SWINGERS CLUB!!!!!!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1038342652, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTc4MDA5', 37578009, '0176310', '11390', 'PSYC-3623', 'PSYC3623', 5, 5, 5, 2, 'One of those profs that actually teach what they are passionate about. Attendance is optional but would be part of your final grade. Quizzes are fair, mostly to make sure you read the textbook. The case analysis is super interesting. Scott would have guest speakers and provide you with tons of volunteer opportunities.', '["Get ready to read","Participation matters","Inspirational"]', 'A+', 1, 1, 1, 3, 0, 0, 1680613754, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTg0MDk2', 37584096, '0140662', '7142', 'BUSI-2433', 'BUSI2433', 5, 5, 5, 2, 'Wenxia weights the course requirements fairly; attendance is required but really only for daily participation and nothing really gets marked "wrong". 2 group projects but short and sweet, presentation isn''t horrible to do.
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTg0MTQy', 37584142, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 4, 'Tests were overcomplicated and when the majority of students did bad, he never accepted responsibility. Tested on things we were never taught and if slide notes and textbook are not memorized you''re in trouble.
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTk0NzA5', 37594709, '0018259', '10143', 'MUSI-1273', 'MUSI1273', 5, 5, 5, 3, 'Dr Boyd is a caring, enthusiastic professor who managed to make medieval plainchant fun! Her door is always open and her dog is usually there too. Assignments are easy enough if you go to office hours and get feedback.', '["Clear grading criteria","Gives good feedback","Caring"]', 'A+', 1, 0, 1, 3, 0, 0, 1680864164, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTk3OTI2', 37597926, '0047062', '6996', 'BIOL-3753', 'BIOL3753', 5, 5, 5, 3, 'Mark is a phenomenal prof! He is hilarious and passionate about the material and very knowledgeable. The questions on the midterm and exam aren''t too bad if you pay attention and attend class. Testing heavily focuses on your writing skills. He is also very accessible outside of class and is eager to answer any questions you might have.', '["Get ready to read","Hilarious","Graded by few things"]', 'A', 1, 0, 1, NULL, 0, 0, 1680969983, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTk4NDc0', 37598474, '0042843', NULL, NULL, 'ALLCLASSES', 5, 5, 5, 2, 'Donna Sears is one of my favorite teachers at Acadia University. She started a new course (Wine and Beverage Marketing); it was so much fun. We got to go on field trips and learn and taste wine, ciders, and spirits. This is my third class with Donna, and I recommend you take all her courses. I promise you will always do good in her classes.', '["Get ready to read","Participation matters","Group projects"]', 'A-', 1, 1, 1, NULL, 0, 0, 1680987578, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTk4NDg1', 37598485, '0034094', NULL, NULL, '4423BUSI', 1, 1, 1, 5, 'Avoid Harish Kapoor and ANY of his classes. He marks hard, he''s unreasonable, very opinionated, and is not afraid to fail you. As a marketing major, I had his classes three times, and have never gotten anything higher than a C. I study hard and read the textbook. You will fail if you don''t read the textbook. He is by FAR, the worst teacher ever.', '["Tough grader","Get ready to read","Test heavy"]', 'C', 1, 1, NULL, 3, 2, 0, 1680987915, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NTkwNzUy', 37590752, '0152134', '6640', 'APSC-2220L', 'APSC2220L', 5, 5, 5, 1, 'Very knowledgeable, helpful, and cheery. Loved every lab I had with him.', '["Participation matters","Group projects","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1680800315, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjA2MjQy', 37606242, '0024914', '9981', 'MATH-2023', 'MATH2023', 5, 5, 5, 3, 'Holger is one the sweetest math professors you''ll ever meet. He has high expectations but wants to do everything he can to help you meet them. He is very available outside of class time and happy to help you whether it''s directly connected to the course or not. Beware, he does sometimes wait until the due date to teach material on the assignments.', '["Participation matters","Lots of homework","Respected"]', 'A-', 1, 0, 1, NULL, 0, 0, 1681176750, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjA2Mjc0', 37606274, '0031453', '9986', 'MATH-2223', 'MATH2223', 3, 3, 3, 3, 'She wants you to do well and is very nice but her teaching style was just not for me. I remained confused during (not an language issue in my opinion) lectures and having online office hours is not my cup of tea. Very fair for the material on midterms and marking.', '[]', 'A-', 1, 0, NULL, 3, 0, 0, 1681177303, 1788283356);
