INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjMxOTEw', 37631910, '0001179', '11698', 'SOCI-1033', 'SOCI1033', 3, 3, 3, 3, 'If you enjoy doing group work/projects then this course will be great for you. She is not understanding whatsoever when it comes to students missing a quiz or group work due to any conflicting issues (medical, personal, etc). The course was very interesting itself, and the material taught was very well explained through lecture powerpoints.', '["Group projects","Clear grading criteria","Lecture heavy"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1681445898, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjQ0MDQ0', 37644044, '0132876', NULL, 'COMP-1023', 'COMP1023', 5, 5, 5, 2, 'Greg is an amazing person! He''s funny and makes every effort to make the content interesting. His assignments are often very vague when he posts them on ACORN but if you ask him in class, he will clear everything up. There are a lot of mistakes in his teaching material but he does his best to correct himself. Overall great guy and would take again.', '["Caring","Respected","Online Savvy"]', 'A+', 1, 0, 1, 3, 1, 0, 1681739815, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjQ0MDY4', 37644068, '0200916', '9958', 'MATH-1413', 'MATH1413', 5, 5, 5, 5, 'Dr. Beaton is a good professor and does his best to support his students. Assignments and participation questions are often very challenging but he does his best to answer questions when you come to office hours. It''s important to put in the work or you WILL NOT do well. Dr. Beaton is there for you and you need to be there for him.', '["Tough grader","Participation matters","EXTRA CREDIT"]', NULL, 1, 1, 1, 3, 0, 0, 1681740029, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NjY2NDM5', 37666439, '0019103', NULL, NULL, '1323', 5, 5, 5, 3, 'This man is an absolute LAD! He would always make the lectures interesting and fun to attend. He would not miss an opportunity to make things entertaining. I found certain topics in this course difficult, however, I just went for his office hours and he cleared all my doubts. I highly recommend this course with Dr Franklin to anyone.', '["Amazing lectures ","Hilarious","Caring"]', 'A+', 1, 0, 1, NULL, 2, 0, 1681932736, 1788283344);
