INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3Njc4MjUy', 37678252, '0041994', NULL, 'NUTR-2013', 'NUTR2013', 5, 5, 5, 2, 'Laurel is my favourite professor, she really cares about her students and wants them to succeed. Her quizzes and final exam were very fair.', '["Inspirational","Lots of homework","Caring"]', 'A+', 1, 1, 1, NULL, 0, 0, 1682028175, 1788283359);
