INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3Njg1MDE1', 37685015, '0019405', '8746', 'FRAN-2123', 'FRAN2123', 5, 5, 5, 2, 'Dr. Delpeche is very caring and quite funny. You''ll enjoy his lectures, and appreciate his clear grading material. Tests, exams, and assignments are of fair toughness. Highly recommend!', '["Amazing lectures ","Hilarious","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1682106348, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3Njg1MDUw', 37685050, '0016655', '9330', 'HIST-3303', 'HIST3303', 3, 3, 3, 2, 'Although his lectures were very good, and he was a kind prof....we did not receive any feedback/grades back ALL YEAR. Basically, everyone found out how well they were doing when they got their FINAL grade. Not very fair at all.', '["Get ready to read","Lots of homework","Hilarious"]', 'B', 1, 1, NULL, 3, 0, 0, 1682106615, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3Njg2Mjk0', 37686294, '0180912', '11317', 'PSYC-1023', 'PSYC1023', 5, 5, 5, 2, 'Dr. Leslie is the best professor ever! His lectures are engaging and fun. He opens every class by playing the ukulele and likes to play lots of fascinating videos. Tests are easy and mostly come down to memorization.', '["Get ready to read","Inspirational","Graded by few things"]', NULL, 1, 0, 1, 3, 0, 0, 1696265778, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3Njg2NTM2', 37686536, '0200916', '9958', 'MATH-1413', 'MATH1413', 5, 5, 5, 4, 'I honestly think Iain''s built for teaching this tedious course. He''s so accessible, cares a lot for his students'' success, and thorough. Attendance isn''t mandatory, but going to lectures is recommended for understanding the notes he posts after class. Word of Advice: revise your notes daily before day ends & don''t cram the night before, EVER!', '["Gives good feedback","Accessible outside class"]', 'C+', 1, 0, 1, 3, 1, 0, 1682121105, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzAzNDI5', 37703429, '0013980', '8394', 'ENGL-1423', 'ENGL1423', 5, 5, 5, 3, 'English isn''t my favorite, but the course was good. There''s lots of reading! but Laroque makes it interesting. The final is straight forward, but you need to read most of the authors to do well. Participation is worth a lot, so you''re forced to go to class and speak or do postings. I enjoyed the course. The prof is approachable.', '["Get ready to read","Participation matters","Gives good feedback"]', 'B+', 1, 1, 1, NULL, 0, 0, 1682366387, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzEzNDcz', 37713473, '0037751', '11057', 'POLS-1403', 'POLS1403', 5, 5, 5, 3, 'Dr. Brickner is my favorite prof at Acadia so far. Her lectures are amazing and inspiring, and she initiates fruitful class discussions. Lots of books in this class, but great choices and topics. She gives great writing feedback with interactive projects that will leave you with a new appreciation for global politics.', '["Get ready to read","Amazing lectures ","Hilarious"]', 'A', 1, 0, 1, 3, 0, 0, 1682443896, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzM3OTI5', 37737929, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 2, 2, 2, 4, 'This was the hardest psychology class I took at Acadia University. Dr. Champod has online assignments based on the textbook but the tests and in-class quizzes are only based on the PowerPoints. You must attend the class because not all the content is uploaded on Acorn. Remember all the material on the PowerPoint otherwise you will not do well.', '["Lecture heavy","Test heavy"]', 'B+', 1, 0, NULL, 3, 0, 0, 1682607325, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzM4MDk1', 37738095, '0029615', NULL, 'SOCI-3542', 'SOCI3542', 4, 4, 4, 3, 'If you want an A+ in any class with Jim you must bring in external academic source for every class! If you are taking SOCI3503 you must have an understanding of the chapter before class because there are no lectures, just discussions. If you are prepared for class then you will have fun!', '["Participation matters","Clear grading criteria","Hilarious"]', 'A+', 1, 1, 1, 3, 0, 0, 1682608052, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzM4MTI5', 37738129, '0015486', NULL, 'BIO-1813', 'BIO1813', 5, 5, 5, 3, 'This class is perfect for students who are new to bio. The daily quizzes are a great study tool. Matt is hilarious and uses everyday examples to help you understand the material better. If you pay attention and write down what Matt says to complement the PowerPoint lecture for studying then you will do great! Test questions are straight forward.', '["Amazing lectures ","Hilarious","Lecture heavy"]', 'A+', 1, 1, 1, NULL, 0, 0, 1682608239, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzQ2Mzk1', 37746395, '0024548', '9992', 'MATH-2253', 'MATH2253', 2, 2, 2, 3, 'He wants students to succeed. Has an accent, & is difficult to understand. Uses his laptop and stylus to write equations, which makes the lectures dull & boring. Hard to pay attention. Willing to answer questions/give extra help it often isn''t useful as he will just tell you the answer without explanation. not an awful prof but wouldn''t take again.', '["Lecture heavy","Test heavy","Graded by few things"]', 'B+', 1, 0, NULL, 3, 0, 0, 1682640950, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzQ2NDQ2', 37746446, '0180912', '11317', 'PSYC-1023', 'PSYC1023', 5, 5, 5, 1, 'Prof was engaging and entertaining. He is very passionate and uses those passions to make his lectures, he does have a clear political bias in his lectures though. He is a very fair marker and his tests were all MCQ, straightforward and direct from lectures. He would stream class which was appreciated. Really laid back, would definitely take again!', '["EXTRA CREDIT","Amazing lectures ","Clear grading criteria"]', 'A+', 1, 0, 1, 3, 0, 0, 1682641245, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3NzkwNDQ0', 37790444, '0001453', NULL, NULL, 'SCENESTUD', 5, 5, 5, 4, 'Paula is the best! Acadia school of music is lucky to have her. If you work hard and show up she will be on your side.', '["Participation matters","Gives good feedback","Inspirational"]', 'A+', 0, 0, 1, NULL, 0, 0, 1683049331, 1788283362);
