INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3ODMyNzMz', 37832733, '0133592', NULL, NULL, '1120L', 5, 5, 5, 2, 'One of the nicest profs I have had. He is a very energetic speaker and person and does a great job of putting together fun labs.', '["Participation matters","Group projects","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1683299180, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3ODMyNzky', 37832792, '0133595', NULL, 'BIO-3553', 'BIO3553', 5, 5, 5, 5, 'Immunology is a really difficult subject but Melanie is very interested in her work and that comes through in lectures. While lectures and tests are more difficult the labs are less difficult than manny other bio classes.', '["Group projects","Respected","Lecture heavy"]', 'A+', 1, 0, 1, 3, 1, 0, 1683299507, 1788283351);
