INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3OTEzNTcx', 37913571, '0000916', '7998', 'ECON-1023', 'ECON1023', 3, 3, 3, 1, 'While I can''t say I enjoyed his class, I did learn a ton about economics! He''s clearly quite passionate about the subject and incorporates a lot of real life examples, but you have to weigh that against his boring, messy PowerPoints and tendency to ramble. If you read the online textbook excerpts and try to stay awake, you''ll be golden.', '["Lecture heavy","Graded by few things","Accessible outside class"]', 'A+', 1, 0, NULL, 3, 0, 0, 1683945953, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM3OTEzNjY3', 37913667, '0139186', '7315', 'CHEM-2713', 'CHEM2713', 5, 5, 5, 2, 'Not much to say about Dr. Faraone which others haven''t already said. Great professor, always willing to help, records her lectures, and is generally very inspiring. Midterms are pretty easy if you aren''t a moron (and even if you are one like me, they still aren''t too bad) - just review the powerpoints and quizzes.
