INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4MTYzNDE3', 38163417, '0015407', NULL, 'ENG-1406', 'ENG1406', 5, 5, 5, 3, 'Doing your average liberal arts degree with no direction. Took an intro English course and was like whatever, but happened to have Dr Campbell and darn it all if she wasn''t inspiring. If you are interested in poetry at all I suggest you take a peak at Dr Campbell''s work. I love the duality of her being a winner of an educator and a stellar writer.', '["Get ready to read","Participation matters","Caring"]', 'A-', 1, 1, 1, NULL, 0, 0, 1691964740, 1788283356);
