INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4MzkxNDI1', 38391425, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 3, 'Entire grade relies on a single group project which has no rubric, expectations, or clear guidelines. She just showed us group projects from past students and expected us to know what to do. Classes consist of incoherent slides, and she has the BIGGEST WHITE SAVIOUR COMPLEX EVER. Takes forever to grade, unhelpful in Office Hrs, loves to boast AVOID', '["Get ready to read","Group projects","So many papers"]', 'Incomplete', 1, 0, NULL, 3, 10, 0, 1699997601, 1788283343);
