INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDAyNTky', 38402592, '0003424', '11060', 'POLS-2003', 'POLS2003', 5, 5, 5, 5, 'Dr. Alexander cares about her students and wants them to learn. She uses alternative methods. She is not always clear on her expectations which can be frustrating. I believe she is using this tactic to encourage creativity. I have taken a class with her every semester since I first had her because I like her that much. She has made me better.', '["Group projects","Inspirational","Caring"]', 'Not sure yet', 1, 0, 1, 3, 2, 9, 1700107587, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDAyNjU1', 38402655, '0304310', '11153', 'POLS-3773', 'POLS-3773', 5, 5, 5, 1, 'Attendance is mandatory, so if you don''t go to class. Don''t take this professor. If you do go to class, you are in for a treat. His lectures include a very good discussion. His grading is super relaxed. There is very little homework. Truly a fine professor.', '["Group projects","Amazing lectures ","Respected"]', 'A+', 1, 1, 1, NULL, 1, 0, 1700108138, 1788283339);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDAyNjgz', 38402683, '0016655', '9273', 'HIST-2613', 'HIST2613', 5, 5, 5, 3, 'I had a few classes with Dr. Sedgewick last year. Super funny dude, he gives big brother vibes. There is always interesting history things to learn in his class. He is open to questions and will research something he doesn''t know the answer to and get back to you very quickly. He is a hard marker, but you will learn a lot from him if you listen.', '["Tough grader","Amazing lectures ","Hilarious"]', 'A-', 1, 1, 1, 3, 0, 0, 1700108394, 1788283345);
