INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDAyODY3', 38402867, '0012762', NULL, 'COMM-1703', 'COMM1703', 1, 1, 1, 5, 'Not sure how Kendra still has a job. She is so bad, I wish more students came to this website to know to avoid her. Don''t be like me. Don''t take her class just because it fits well into your schedule. I regret hearing her voice. I wish her and her family the best. I hope she has many successes in a job that does not involve her teaching.', '["Tough grader"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1700110336, 1788283363);
