INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDMzMTQ0', 38433144, '0149576', '11115', 'POLS-3173', 'POLS3173', 5, 5, 5, 4, 'Dr. Mutlu''s class is the highlight of my day. He makes the most boring subjects interesting. But because the subject is still boring the class is very hard to write about.', '["Amazing lectures ","Hilarious","Respected"]', 'B-', 1, 0, 1, 3, 4, 0, 1700779297, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDQ0Nzgw', 38444780, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 5, 'WARNING: She will make you cry. Any slight disagreement with her, even on a subjective matter, she will passive-aggressively tell you that you are wrong, instead of listening. She is not a good professor. There are 5 projects due at the end of this class. The smallest is a 1000-word reflection worth 5%. There are 4 textbooks and a $15 subscription.', '["Group projects","Lots of homework","So many papers"]', 'Audit/No Grade', 1, 1, NULL, 3, 10, 0, 1701118091, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDQ0ODM2', 38444836, '0149576', NULL, 'POLS-2873', 'POLS2873', 5, 5, 5, 4, 'Dr. Mutlu is such a nice guy and a fantastic instructor. He cares a lot about his students, and I think some people will try to take advantage of this. But Dr. Mutlu is no fool, he will always speak his mind. His classes are so much fun, he carries good conversation. If you take a class with Dr. Mutlu, please show up, it is a waste not to.', '[]', 'Not sure yet', 1, 0, 1, NULL, 4, 0, 1701118369, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDQ2NzAw', 38446700, '0012762', '7648', 'COMM-1223', 'COMM1223', 1, 1, 1, 5, 'Kendra Carmichael is living proof that there is no God. If you take her class, prepare to keep your nose brown. She plays favourites. If you dare to take her class, your GPA will go down, you will become frustrated, and you will talk about her in therapy. I was not going to day drink during this semester. Thanks, Kendra Carmichael.', '["Tough grader","Lots of homework","Test heavy"]', 'C', 1, 1, NULL, 3, 1, 0, 1701129734, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDQ3MzQ0', 38447344, '0012762', NULL, NULL, 'COMM', 1, 1, 1, 5, 'She''s a bad prof, but the hate is blown out of proportion. Yes, she treats most students poorly. Yes, she makes her lectures way longer than they need to be. Yes, I keep myself from falling asleep in her class. Yes, I have never felt more worthless. But she is probably still a person and doesn''t deserve the hate. At least she showed up.', '["Tough grader","Participation matters","Lecture heavy"]', 'C-', 0, 0, NULL, 3, 0, 0, 1701134349, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDQwNTk1', 38440595, '0018196', '7288', 'CHEM-1023', 'CHEM1023', 1, 1, 1, 2, 'He is a very caring professor, but that does not make up for his teaching! his slides are so hard to follow, he NEVER goes over examples. I do understand that he wants us to try to learn on our own but how do you know where to start without going over an example?? You can tell this is not his favourite class to teach and it shows....', '["Gives good feedback","Caring","Graded by few things"]', 'C+', 1, 0, NULL, 3, 0, 0, 1701095322, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDU0MDI2', 38454026, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 3, 3, 3, 1, 'let''s be honest, he''s a mediocre at best prof who gives a great class because his expectations are very low and his grading scheme very easy.', '["Clear grading criteria"]', NULL, 1, 0, 1, NULL, 0, 1, 1701201928, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDU3MjI5', 38457229, '0000916', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 5, 'Awful professor. He should stop teaching altogether.
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY1MTg1', 38465185, '0001916', NULL, 'BIO-2043', 'BIO2043', 5, 5, 5, 4, 'Honestly he''s hilarious. The class is a bit hard, but it is university level science. Just study the readings he gives and you''ll be fine.', '["Tough grader","Hilarious"]', 'A-', 1, 0, 1, NULL, 0, 0, 1701289149, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY5MTkx', 38469191, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 5, 'A fine person. But if you have a job. Don''t take a class with Dr. Alexander. To finish all the projects in her class, you seriously need to neglect other aspects of your life. Full-time student, forget it, you will not have time to do other homework. Pay your bills, forget it, she has four required textbooks and a subscription to "top - hat".', '["Get ready to read","Group projects","Lots of homework"]', 'Not sure yet', 1, 0, NULL, 3, 10, 0, 1701310057, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY5MjM1', 38469235, '0012762', NULL, NULL, 'COMM', 1, 1, 1, 5, 'How does this woman have a job at Acadia? She is so terrible. Her terrible reviews go back more than 20 years. Does Acadia just not care enough that their students have to suffer a terrible professor like this? I don''t blame Kendra for being terrible. I blame Acadia for letting students pay thousands of dollars to be taught by her.', '["Tough grader"]', 'Audit/No Grade', 0, 1, NULL, 3, 1, 0, 1701310333, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY5Mjkz', 38469293, '0149576', NULL, 'POL-2683', 'POL2683', 5, 5, 5, 3, 'Acadia is a fantastic school. Most of our professors are good. Dr. Mutlu is the best. Funny and caring. I bet he plays with lego. Seems cool enough to play with lego. The class is ending so I won''t be able to ask him. If I see him around I will. Star Wars Lego is where it''s at. But kinda pricy. The knock off star wars lego will do fine.', '["Hilarious","Caring","Accessible outside class"]', 'Not sure yet', 1, 0, 1, NULL, 4, 0, 1701310690, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY5Mzgz', 38469383, '0304018', '11070', 'POLS-2223', 'POLS2223', 5, 5, 5, 3, 'Dr. Marland was a fantastic prof. He would often bring his dog to class and it would cheer everyone up. He''s a little full of himself, which is fine because he wrote the textbook. If you have an opportunity to take a class with him. Do it. You''ll be sad when it''s over.', '["Participation matters","EXTRA CREDIT","Respected"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1701311148, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDY5NDc1', 38469475, '0037751', NULL, 'POLS-2096', 'POLS2096', 5, 5, 5, 3, 'Dr. Brickner has engaging lectures. She is clear with her expectations and grades fairly. She''s always cracking jokes and is very relatable. Certainly worth taking her as an elective or for a POLS minor.', '["Clear grading criteria","Gives good feedback","Hilarious"]', 'C+', 1, 1, 1, 3, 0, 0, 1701311726, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDc5MDQy', 38479042, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 2, 2, 2, 4, 'A ton of work with unclear instructions, he won''t tell you what he wants until you''re already done, and grades seem to come out of thin air. 90% of the classes are just presentations. Prof isn''t a bad guy but the class is rough and the assignments took up so much time that I wish I could have used to study for other classes.', '["Group projects","Lots of homework"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1701382653, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDcwNTEy', 38470512, '0304018', '11070', 'POLS-2223', 'POLS2223', 5, 5, 5, 4, 'Dr. Marland gives the most fantastic and engaging lectures I''ve seen. He''s very professional, encourages interesting discussions, and really knows his stuff! He''s a tough grader, but if you put in the work you''ll do fine! He''s also VERY flexible about deadlines. He had no ACORN page which made it hard to keep up, but he responds to emails quickly.', '["Tough grader","Amazing lectures ","Respected"]', 'B', 1, 0, 1, 3, 0, 0, 1702316429, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDg2ODE5', 38486819, '0044535', '7226', 'BUSI-4253', 'BUSI4253', 1, 1, 1, 5, 'Igor is stuck in the past. Project and Enterprise Valuation should be a course that focuses on computer skills. This class requires minimal Excel work (in fact, it''s optional). Quizzes cover 20-30 formulas, and you''re not allowed to use a formula sheet. He also said that he doesn''t remember what''s on the final, so good luck studying for that.', '["Tough grader","Get ready to read","Test heavy"]', 'Not sure yet', 1, 0, NULL, 3, 1, 0, 1701456597, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDk3NDcx', 38497471, '0037751', '11103', 'POLS-3013', 'POLS3013', 5, 5, 5, 3, 'Dr. Brickner is a very kind and funny professor. If you enjoy politics, then you will enjoy her classes. She gives good feedback, and is very flexible. She allows everyone to express their opinions as well.', '["Gives good feedback","Hilarious","Caring"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1701626889, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDk3NTc2', 38497576, '0149576', '11143', 'POLS-3583', 'POLS3583', 4, 4, 4, 4, 'Dr. Mutlu very smart and funny, but he also makes you want to learn. Seriously, one of the only classes and profs that I like to go to class for. You''ll actually learn something from him! However, he doesn''t give very clear feedback and is a very hard marker.', '["Tough grader","Get ready to read","Hilarious"]', 'Not sure yet', 1, 1, 1, NULL, 2, 2, 1701735225, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NDk3NjA1', 38497605, '0003424', '11150', 'POLS-3703', 'POLS3703', 1, 1, 1, 4, 'This class was completely swapped from what it was advertised as, to be about issues she cares about. Prof can be rude and uncompromising. Mandatory purchase of 5 textbooks, and a subscription to TopHat to do your homework. Prof is VERY biased, you must agree or you''re wrong. No grading criteria but you''ll be criticized for not doing it right.', '["Get ready to read","Participation matters","Lots of homework"]', 'Not sure yet', 1, 0, NULL, 3, 10, 0, 1701628734, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTA3ODI5', 38507829, '0152134', '7691', 'COMP-2203', 'COMP2203', 5, 5, 5, 4, 'Angelo Posteraro makes a confusing topic easy to understand. He shows many examples in class and is always open to questions. His assignments are challenging but he will often give away the answers in class. His labs are also interesting and show how the content of his lectures are important in the real world.', '["Caring","Test heavy","Accessible outside class"]', NULL, 1, 1, 1, NULL, 0, 0, 1701717919, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTAwMDk3', 38500097, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 3, 3, 3, 5, 'his test questions are messed up bro', '["Tough grader","Amazing lectures ","Lots of homework"]', 'B', 1, 0, NULL, NULL, 0, 0, 1701651543, 1788283357);
