INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTAwMjgx', 38500281, '0034094', '7142', 'BUSI-2433', 'BUSI2433', 1, 1, 1, 5, 'He will straight up embarrass you in front of the class just for fun. People have got up and left while crying, be called out in front of the whole class if he thinks you''re not listening for even one second, snap in your face... the list goes on. please avoid at all cost.', '["Tough grader"]', 'Rather not say', 1, 1, NULL, 3, 1, 0, 1701653024, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTE5NzMw', 38519730, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 5, 'By far the worst professor at acadia and  not sure how he has been teaching for this many years. He will make you hate you life and wonders why nobody wants to major in marketing. Turns a fun and easy class into a nightmare. Does not care about his students whatsoever and miss 7 classes you fail. Assignments are impossible to make him happy.', '["Tough grader","Get ready to read","Lecture heavy"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1701791213, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTEwMTY0', 38510164, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 4, 4, 4, 4, 'he is a good teacher his lectures are super interesting and made me want to change my major. would definitely take his class again. be prepared to do a lot of work in your own time though because he posts a lot of videos to watch after class that we do not learn. he is also a hard grader and pretty much all that is graded are the exams.', '["Tough grader","Amazing lectures ","Test heavy"]', 'B-', 1, 0, 1, 3, 0, 0, 1701724926, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTEwMjQ2', 38510246, '0041312', NULL, 'ENG-1413', 'ENG1413', 4, 4, 4, 4, 'she can be a tough grader but she is a really great prof would take a class taught by her again', '["Tough grader","Get ready to read","Caring"]', 'C+', 1, 1, 1, NULL, 0, 0, 1701725124, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTExMjYx', 38511261, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 5, 'Dr. Alexander''s approach to teaching is very self-centered. As in, she makes everything about herself. She assigns homework like she is your only professor. She requires four textbooks and a subscription. She made the class entirely about an issue she cares about. She does not explain how to do assignments. She is the worst Politics Prof at Acadia.', '["Get ready to read","Lots of homework","So many papers"]', 'A+', 1, 0, NULL, 3, 11, 0, 1701728656, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTEyMTc2', 38512176, '0015927', '9783', 'KINE-3013', 'KINE3013', 1, 1, 1, 4, 'He does not care about anybody but himself and only talks about the "amazing" things he''s done in his life. He makes the two different class section midterms different difficulty levels & doesn''t give a f***.He also does not have any sort of organization skills what so ever and his powerpoint slides are just pictures of him scuba diving in Mexico.', '["Tough grader","Test heavy"]', 'A-', 1, 0, NULL, NULL, 0, 0, 1701732299, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTEyMTkw', 38512190, '0015927', '9783', 'KINE-3013', 'KINE3013', 1, 1, 1, 4, 'Very disrespectful and rude to students when someone volunteers to answer questions in front of the class. Most lectures are focused on his career, life, etc and not exercise physiology material and are very disorganized. Material is not related to lab at all, because communication between him and the lab instructor is very poor. Avoid at all cost!', '["Tough grader"]', 'A-', 1, 1, NULL, 3, 0, 0, 1701732341, 1788283353);
