INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTQ0MjA=', 3854420, '0021658', NULL, NULL, 'MEDIEVALLIT', 1.5, 1, 2, 5, 'Extremely close-minded--not interested in hearing ideas that contradict his own. Patronizing and belittling, he shuts out potentially innovative ideas. Does not teach to the capacity that I would like. Kevin is a controlling and lacks his own creative and stimulating ideas. Completely unoriginal.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1115999779, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTQwOTMz', 38540933, '0015927', '9783', 'KINE-3013', 'KINE3013', 1, 1, 1, 5, 'Rocket science would be easier to learn than the concepts in this class taught by Rene. He doesn''t explain things well and shoots down anyone who answer questions in class. Classes are often very vague but on exams you''re asked about specifics. He sexualizes concepts and teaches things that don''t even relate to the class. Good luck!', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1701889923, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTQyNzI=', 3854272, '0021658', NULL, NULL, 'MEDIEVALLIT', 2, 2, 2, 5, 'privileges insignificant grammatical foibles over actual ideas. Though he claims to be open-minded, new approaches (cultural studies, poststructuralism) freak him out massively and your mark will suffer. Stick to boring ideas others have written about a trillion times and it’ll be smooth sailing', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1115998585, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTU5Mjgy', 38559282, '0152134', '7691', 'COMP-2203', 'COMP2203', 5, 5, 5, 4, 'Mr. Posteraro is an absolute legend. Made every topic presented in class understandable with clear instructions. I always referred to his office hours when I had a doubt, he would explain it over and over again till I understood it. His slides are sleek and simple, Straight to the point. I highly recommend him in any course that he is teaching.', '["Participation matters","Amazing lectures ","Clear grading criteria"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1701975662, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTUwMTc3', 38550177, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 5, 'There is so much work in this class. I believe that Dr. Alexander cares about the issues that she teaches, but she kind of forces her opinions down your throat. She is very unclear about how she wants assignments to be completed. She expects a lot from her students, Multiple textbooks, a subscription, and a crazy amount of assignments.', '["Group projects","Lots of homework","So many papers"]', 'A+', 0, 0, NULL, NULL, 9, 0, 1701918495, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTUzOTg5', 38553989, '0003424', '11056', 'POLS-1303', 'POLS-1303', 4, 4, 4, 3, 'Although the workload is heavy and I did not share the same opinions on many topics as she did, she is one of the most caring professors I have had. Just take the time to talk to her, she will make sure you do good!', '["Get ready to read","Participation matters","Accessible outside class"]', 'Not sure yet', 1, 1, 1, 3, 1, 8, 1701958109, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTYzNTQ1', 38563545, '0149576', '11090', 'POLS-2683', 'POLS2683', 5, 5, 5, 3, 'Dr. Mutlu is a classic professor. He expects a classic student. Try hard in his class and you''ll do well. His lectures are fun.', '["Hilarious","Respected","Lecture heavy"]', 'Not sure yet', 1, 1, 1, 3, 3, 0, 1701986140, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTYzNjQw', 38563640, '0003424', '11060', 'POLS-2003', 'POLS2003', 1, 1, 1, 5, 'Insane workload, no room to argue, no clear grading criteria, very confusing lectures, and way too many books, do not recommend.', '["Get ready to read","Group projects","So many papers"]', 'Not sure yet', 1, 0, NULL, 3, 8, 0, 1701986385, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTcxMDAy', 38571002, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 2, 2, 2, 4, 'He is not as bad as people make him sound. He is a nice guy if you actually talk to him outside of class, or during class. He does make an easier class fairly difficult though. If you go to every class, take good notes, and actually study for the tests you will be fine. I do understand why some people dislike him but overall i do not mind the guy', '["Tough grader","Participation matters","Test heavy"]', 'B+', 1, 1, NULL, 3, 1, 0, 1702013001, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTcxNDYy', 38571462, '0008859', NULL, NULL, 'PHIL', 5, 5, 5, 1, 'He. Cares. This prof is absolutely fantastic. He is consistently empathetic and tries very hard to inspire and build his students up. He is lenient but fair, instead of going easy on you, he will offer personal guidance and help work through concepts you may struggle with. It is clear this man has a solid personal philosophy on education. Good Man.', '["Participation matters","Inspirational","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1702015447, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NTcxNTM3', 38571537, '0263737', NULL, NULL, 'HIST', 5, 5, 5, 3, 'She is clearly dedicated to her subject of study and her lectures show a true passion for education. I am not somebody who typically learns well in a lecture style class, and she makes it engaging, and consistently interesting regardless of your pre-existing thoughts on the subject. She is thorough, and kind.', '["Participation matters","Amazing lectures ","Gives good feedback"]', 'C', 1, 1, 1, NULL, 0, 0, 1702015886, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjA3NjE1', 38607615, '0021658', '8403', 'ENGL-2163', 'ENGL2163', 5, 5, 5, 3, 'Cannot say enough good about Prof Whetter. A joy to be around, interesting course content, and very engaging. Option to do an in class presentation rather than an end of the term exam. You can tell he has a genuine interest in medieval literature and that he loves to share this with others. Made me interested in the topic. Good readings as well.', '["Hilarious","Accessible outside class"]', 'A-', 1, 0, 1, 3, 0, 0, 1702305292, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjA5MTI0', 38609124, '0039663', '7325', 'CHEM-3103', 'chem3103', 5, 5, 5, 5, 'I owe him for helping me realize I don''t belong in chemistry. Or perhaps in university at all. 
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjE3NTM4', 38617538, '0029615', '11734', 'SOCI-2533', 'SOCI2533', 5, 5, 5, 2, 'great prof. always has lots of energy even early in the morning!', '["Participation matters","Group projects","Clear grading criteria"]', NULL, 1, 1, 1, NULL, 0, 0, 1702337125, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjI5NzIx', 38629721, '0024859', '7309', 'CHEM-2513', 'CHEM2513', 1, 1, 1, 4, 'This class is hard on its own but with little support or guidance from Jha, it''s even worse. He''s so intelligent that he has difficulty dumbing things down to students when asked questions. Lots of quizzes yet almost no practice material. Easy marker but he kind of has to be so everyone doesn''t fail.. Unreasonable amount of content for 1 hr tests.', '["Beware of pop quizzes","Lecture heavy","Graded by few things"]', 'B-', 1, 1, NULL, NULL, 0, 2, 1702403301, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjIxOTIy', 38621922, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 1, 1, 1, 5, 'The resources for students is shameful compared to other professors I''ve had. She basically makes lectures mandatory because she uses 5 year old slides she never bothers to update online but has new important information you need. It''s your problem if you cannot come to class. Her testing is unnecessarily difficult, always has open-ended questions.', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1702350571, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjIxOTgw', 38621980, '0133594', NULL, 'PSYC-2213', 'PSYC2213', 1, 1, 1, 5, 'This prof does not make her classes accessible for those sick or unable to attend class. She never updates her PowerPoint which means you need to be able to pay attention and remember what she says. She never gives any sort of guideline and her tests and quizzes are detail-oriented while somehow being vague.', '["Tough grader","Lecture heavy","Test heavy"]', NULL, 1, 1, NULL, 3, 0, 0, 1702350739, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjM0NzQ4', 38634748, '0043258', '9701', 'KINE-1413', 'KINE1413', 4, 4, 4, 4, 'Anatomy is a very hard course to take coming out of highschool so you better know how to study. He is very easy to reach by email and he will alter your grade weights to make sure you are able to get the best grade possible. Go to class because he takes attendence and if you have good attendence he makes your exam worth less.', '["Caring","Lecture heavy","Accessible outside class"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1702416066, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjM3Mzc0', 38637374, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 2, 2, 2, 4, 'Daniel made me cry because his exams and midterms are purely memorization and not very helpful or informative, over 30 classes I have no idea what to study for on the exam and his classes are uninteresting', '["Tough grader","Lecture heavy","Graded by few things"]', 'Incomplete', 1, 0, NULL, NULL, 0, 0, 1702423025, 1788283357);
