INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjM4ODMw', 38638830, '0000768', '7127', 'BUSI-2013', 'BUSI2013', 5, 5, 5, 1, 'Prof Feltmate is an absolute legend. Teaches the material in a way that everyone can understand and takes things step by step. Participation is worth 20%, but he gives you points even if you get the answer wrong. Midterm and exam were exactly as he explained, and you were allowed cheat sheets. Super nice guy, one of the best profs at Acadia.', '["Hilarious","Caring"]', 'A+', 1, 0, 1, 3, 0, 0, 1702427158, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjMzMDY5', 38633069, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 1, 1, 1, 5, 'Dr. Champod chooses to make her class more difficult than it needs to be. She uses slides that are completely unreliable if you miss class, or even mishear what she is saying because the slides do not match the ones she provides on Acorn. She also includes material on tests that are not written on the slides. If you don''t need this class, stay away', '["Tough grader","Test heavy","Graded by few things"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1702411880, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjQyMjM3', 38642237, '0044535', '7175', 'BUSI-3243', 'BUSI3243', 1, 1, 1, 5, 'He lectures like we''ve all been in the Finance field for years, provides little context and explanation for what he''s discussing in lectures. When you ask questions he is demeaning when he answers, provides no feedback on homework''s, his quizes are extremely hard and you need to have so many formulas memorized, and grades extremely hard', '["Tough grader","Test heavy"]', 'C-', 1, 0, NULL, 3, 0, 0, 1702437074, 1788283345);
