INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjY5ODI3', 38669827, '0015754', NULL, NULL, 'SHAKESPEARE', 5, 5, 5, 3, 'Easily one of my favorite profs at Acadia. No matter what your writing level is, you''ll get helpful feedback! Lectures are very interesting and helpful for understanding/sparking thought about the texts we read. Intriguing class discussions and activities. I genuinely had so much fun doing every assignment. HIGHLY recommend class with Dr. Slights!', '["Amazing lectures ","Gives good feedback","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1702568940, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjYyNDEw', 38662410, '0176310', '11390', 'PSYC-3623', 'PSYC3623', 5, 5, 5, 3, 'I loved this class and prof. class was 3hrs long but flew by with him, it was the only class ive liked in my degree. Tests were fair but do have some questions from textbook and he was a great person overall', '["Gives good feedback","Inspirational","Lecture heavy"]', 'A', 1, 1, 1, 3, 0, 0, 1702521124, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc1MDA0', 38675004, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 2, 'Teri has been a game changer for my level of chemistry understanding. She goes out of her way to help each and every student. Teri was very considerate by observing where we were content wise in lecture, so she could align her lab material accordingly. The lab was useful and entertaining. She is an all around great professor!', '["EXTRA CREDIT","Amazing lectures ","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1702584045, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc2MDQ0', 38676044, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 1, 'Love', '["Amazing lectures ","Hilarious","Caring"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1702586538, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc2MTg5', 38676189, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 3, 'Amazing prof. one of the best I''ve ever had. She always makes sure you understand the concepts and will go over them many times with you. Unfortunately she was not teaching the class but the lab instead, however she always offered many tutorials to help us out with the material. Hopefully she will be teaching the class again soon.', '["Amazing lectures ","Respected","Online Savvy"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1702586894, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc2MjU2', 38676256, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 2, 'Attend his lectures. His testes are fairly easy, but a lot of the answers are found in what he says in lectures versus his notes. He is very accommodating and knowledgable. He is also very funny and I really enjoyed his class.', '["Amazing lectures ","Hilarious","Graded by few things"]', 'A+', 1, 1, 1, NULL, 0, 0, 1702587065, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc2Mzcx', 38676371, '0071592', '6856', 'BIOL-2043', 'BIOL2043', 5, 5, 5, 1, 'Jen is very nice. She cares about your understanding of the material and will take the time to go over it with you. she is very passionate about what she teaches and it shows. I had the lab with her as well and it was very fun and easy. This class was very interesting as its pretty applicable to your everyday life.', '["Participation matters","Amazing lectures ","Caring"]', 'A+', 1, 1, 1, NULL, 0, 0, 1702587333, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc2NTA2', 38676506, '0037539', '9943', 'MATH-1013', 'MATH1013', 1, 1, 1, 4, 'I did not even have Eva Curry as my prof as she''s on sebatical or something. However, a MANDATORY 3% of my final grade was a note taking activity we had to do in groups every two weeks, set up by HER. This was the most useless thing I have literally ever done. It was so poorly organized and the grading scheme was extremely unfair. Bad at emails.', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 1, 1, NULL, NULL, 0, 0, 1702587686, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc3Mzg5', 38677389, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'One of the worst, most annoying professors I have ever had. Marks as if this is your masters degree. Boring lectures.', '["Tough grader","Participation matters","Lecture heavy"]', 'D-', 1, 1, NULL, 3, 0, 0, 1702589845, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njc5MDE4', 38679018, '0169986', '11389', 'PSYC-3613', 'PSYC3613', 5, 5, 5, 1, 'Dr. Lametti is the heart of the psychology department, he truly cares about the success of his students. He provides very descriptive reviews before any midterms or exams, allows cheat sheets, and gives you any long answer questions in advance to allow you to prep your answers. He is super easy to reach and his lectures are super engaging and fun.', '["Amazing lectures ","Clear grading criteria","Accessible outside class"]', NULL, 1, 0, 1, NULL, 0, 0, 1702594122, 1788283343);
