INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjcxNDQ=', 3867144, '0018366', NULL, NULL, 'BRITLIT', 1.5, 2, 1, 5, 'Hypermedia based made it uncomfortable for a lot of students and the presentations were really hard to sit through. She is a very intelligent woman and there are very few students who could compete with her on an intellectual basis. Don''t take it if you are easily stressed because when you 40% project due date rolls around- hypertension will occur!', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1116239511, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njg0MDM4', 38684038, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'Great prof. Truly looks out for his students, even financially.  Goes out of his way to make material accessible and really well organized.  So easy to navigate through all the concepts.  Tests are fair and so is exam, no surprises.  WileyPlus assignments are super helpful, can be a little hard, but definitely worth completing.', '["Hilarious","Caring","Respected"]', 'Not sure yet', 1, 0, 1, 3, 1, 0, 1702609415, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjgxMjQ4', 38681248, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, NULL, '["Tough grader","Get ready to read","Participation matters"]', 'B', 1, 1, NULL, 3, 0, 0, 1702600883, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjgzMzY0', 38683364, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 5, 5, 5, 3, 'Best course on the brain at Acadia! You have to attend class to do well but the lectures are great. She gives a lot of info on the midterms/exams in class and she explains the material very clearly.', '[]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1702607314, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NjgzODkw', 38683890, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'The material seems easy until you get it back and are given a 70 max.  Almost everything is out of 5 marks making impossible to do good.  Second in class writing application is so much work in such little time.  No one I know did good.  Participate, participate, participate!  You want her to like you and its with 20% of your grade so do it.', '["Tough grader","Participation matters","Group projects"]', 'Not sure yet', 1, 1, NULL, 3, 1, 0, 1702608939, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4Njk1MjUy', 38695252, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 3, 'Teri is awesome!!! she is very caring and wants all of her students to do well in her course. If you have the option to have her as a professor , take the opportunity.', '["Amazing lectures ","Caring","Respected"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1702672723, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzA2NzU5', 38706759, '0000657', '8900', 'GEOL-1013', 'GEOL1013', 5, 5, 5, 2, 'Sandra is a great person, you can tell she really loves the subject matter she teaches. However, she did sort of expect you to remember and memorize a lot of what she lectured about. The midterms and exams had some niche questions which only had a slide or two, but they''re open book so they were fine.', '["Participation matters","Caring","Lecture heavy"]', 'A+', 1, 0, 1, 3, 0, 0, 1702745458, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzA2OTcx', 38706971, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 3, 'Amazing lab instructor, was not teaching the OCHEM course, but was generous enough to hold very helpful tutorials and office hours to help out with material! Very kind and organized. She is very good at explaining the material.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1702746952, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzA4NjUw', 38708650, '0000902', '8899', 'GEOL-1010L', 'GEOL1010L', 4, 4, 4, 3, 'Had Dr. McMullin for the lab portion of GEOL1013 and he was great. Average professor but you can tell he''s passionate about the subject. The last three labs are way more difficult than the first ones but the field trips are super fun!', '["Participation matters","Respected","Graded by few things"]', 'A', 0, 1, 1, NULL, 0, 0, 1702757226, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzAyMjcy', 38702272, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 5, 'I think deep down he can be a nice guy, most the time isn''t. I found his lectures pretty useless when midterms came around and he tells you to ask questions but will just respond with "we already covered it in class" or "read your textbook". No surprise but no class evaluation most likely knows how the students feel about him and just doesn''t care.', '["Tough grader","Get ready to read","Lecture heavy"]', 'C+', 1, 1, NULL, 3, 3, 0, 1702699203, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNDY5', 38712469, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 3, 'Teri was the lab instructor for Organic Chemistry, and went way above and beyond. She hosted tutorials throughout the semester on lecture content (lots before the final), and welcomed lecture questions at her lab office hours. The class is hard, but Teri is very passionate and is incredible at explaining difficult concepts. She''s also hilarious:)', '["Amazing lectures ","Hilarious","Accessible outside class"]', 'Not sure yet', 0, 1, 1, NULL, 0, 0, 1702780020, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNTEz', 38712513, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 3, 3, 3, 5, 'Dr. Champod is a very passionate and knowledgeable professor, however I found physiological psychology to be an incredibly challenging course. Despite studying lots for her tests, there were always questions that I had no idea how to answer. You absolutely have to go to class as she says things that aren''t on the slides that are on the tests.', '["Caring","Test heavy","Online Savvy"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1702780321, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNTM1', 38712535, '0180912', '11324', 'PSYC-2013', 'PSYC2013', 5, 5, 5, 2, 'Dr Leslie is an awesome professor. He records all of his lectures for students who are sick, and so that students can review lectures prior to tests. He''s very responsive to emails and always willing to help. His tests are all multiple choice and are relatively easy as long as you go to class and study a bit before.', '["Gives good feedback","Caring","Respected"]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1702780463, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNTkx', 38712591, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 5, 5, 5, 4, 'Dr Bleile''s lab is tough, and she is a very hard grader, but she is an amazing lab instructor. The lab material is helpful, and I learned so much about reading and writing scientific papers. She is incredibly accessible outside of class, answering emails at any hour with detailed responses and she truly wants all her students to succeed.', '["Tough grader","Graded by few things","Accessible outside class"]', 'Not sure yet', 0, 0, 1, NULL, 0, 0, 1702780721, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNjgz', 38712683, '0000673', '6900', 'BIOL-2813', 'BIOL2813', 3, 3, 3, 3, 'Dr Boates is a very kind and caring professor. His lectures are a little boring, but he does his best to keep students engaged. He takes attendance 10 times throughout the semester worth 10%, but if you email him in advance you aren''t penalized. His tests aren''t cumulative and are multiple choice, so are easy if you go to class and study.', '["Caring","Graded by few things"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1702781159, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNzE3', 38712717, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 5, 5, 5, 2, 'Dr Gauvin delivered some of the most engaging lectures I''ve ever been to. She cares so much about her students both in and outside of the classroom. Her tests are relatively easy if you go to class and study, she is not trying to trick you and the questions are clearly pulled from content in her PowerPoints.', '["Amazing lectures ","Caring","Accessible outside class"]', 'Not sure yet', 1, 0, 1, 3, 0, 0, 1702781290, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzEyNzcz', 38712773, '0024859', '7309', 'CHEM-2513', 'CHEM2513', 1, 1, 1, 5, 'I didn''t have a good experience with Dr Jha. He was very disorganized, and his lecture were impossible to learn from. He skipped through examples, just giving the answer instead of how to get there. His exams had trick questions, and lots of students had issues with him marking their tests wrong. Very nice and smart man, just wasn''t a good prof.', '["Tough grader","Test heavy"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 3, 1702781599, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzI5Mzc5', 38729379, '0192432', NULL, 'PYSCH-1013', 'PYSCH1013', 2, 2, 2, 5, 'The way his questions are worded is ridiculous, the whole class is purely memorization and WAY too many questions for 50 mins, so If you have the option to do it from home definitely do it because u can feel the TA''s breathing down your neck. To top it ALL off he has a background in neuroscience and its pretty much an intro to neuroscience class.', '["Tough grader","Participation matters","Lecture heavy"]', 'A-', 0, 0, NULL, NULL, 0, 0, 1702926934, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzI5NTA4', 38729508, '0139613', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 1, 'Dr Crandall takes her time with teaching and puts a lot of detail into one topic instead of rushing through. The simulation portion of the class was actually fun and interesting (this is also where you can get all of your participation points). Exam is super easy to study for - only on like 4 topics, only downside is exam was long and handwritten.', '["Group projects","Caring"]', 'A-', 1, 0, 1, NULL, 0, 0, 1702927440, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzM1ODA3', 38735807, '0000768', '7127', 'BUSI-2013', 'BUSI2013', 4, 4, 4, 1, 'If you want an easy A+ take this course, if you want to learn anything about accounting don''t take this course', '[]', 'A+', 1, 0, 1, 3, 0, 0, 1702950577, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzMxMjg3', 38731287, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'If you do not show up to class expect to fail, and if you do show up, expect to fail. The assignments are similar to junior high, but they are graded at a masters level. Attendance is required, but half of what you learn is outside of class or on your own. If you put 100% effort do not expect to get a grade higher than 70%. Do not take course!', '["Tough grader","Participation matters","Group projects"]', 'C', 1, 1, NULL, 3, 1, 0, 1702934025, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzQzMDQ5', 38743049, '0017498', '9969', 'MATH-1613', 'MATH1613', 5, 5, 5, 3, 'super nice and good teaching style. she did notes on her iPad/ computer and posted them after every class so you didn''t have to take notes. very good at explaining, had weekly assignments which made it easy to know how you are doing in the class. gives best grade to every student by using 4-5 different marking schemes to give you the best option.', '[]', 'A-', 1, 1, 1, 3, 0, 0, 1703008055, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzQzNTg5', 38743589, '0038515', '10989', 'PHYS-1053', 'PHYS1053', 5, 5, 5, 2, 'Anna kept me sane!', '["Amazing lectures ","Gives good feedback","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1703010464, 1788283339);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzU5NTQ5', 38759549, '0140662', '7142', 'BUSI-2433', 'BUSI2433', 4, 4, 4, 2, 'Wenxia is overall a good professor and an easy grader. Attendance is mandatory but you can still skip a few classes here and there and have no consequence. Graded on 3 easy group projects, 1 short individual assignment, 8 short multiple-choice quizzes, and a final test worth 25%. Quizzes can be confusing but you have access to the class slides.', '["Participation matters","Group projects"]', 'B+', 1, 1, 1, 3, 0, 0, 1703108620, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzU5NjU2', 38759656, '0034433', '7136', 'BUSI-2233', 'BUSI2233', 4, 4, 4, 4, 'Dr. Yang is not a bad prof as some people have said, he can be a little hard to understand at times though. Midterms and Exam were fairly difficult and several people did fail or withdraw, he did offer extra credit on both the midterms which was nice. Do the textbook questions he assigns, go to class (and participate), and do the assignments.', '["Tough grader","Participation matters"]', 'B+', 1, 1, 1, 3, 0, 0, 1703109135, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzU5ODM1', 38759835, '0017498', '9969', 'MATH-1613', 'MATH1613', 5, 5, 5, 1, 'Emma is a good professor and teaches the material well and in a way you can understand. She also posts class notes that are quite detailed, so no issues if you miss some classes. If you have prior knowledge of algebra you will do well with minimal effort. The Exam and Test reviews contain exactly what is on them.', '["Clear grading criteria","Lots of homework","Test heavy"]', 'A-', 1, 0, 1, 3, 0, 0, 1703109937, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzUwNzYw', 38750760, '0043258', '9701', 'KINE-1413', 'KINE1413', 5, 5, 5, 4, 'Anatomy is a very hard course so be ready to learn and study hard! Scott is an amazing prof and the best for 1st year. He is so caring and nice and will try his best to up your mark if you do all the work and attend class. Lectures are heavy. You should study them everyday. Take good notes and attend lab because it will help you understand better.', '["Participation matters","Caring","Lecture heavy"]', 'C', 1, 1, 1, NULL, 0, 0, 1703041098, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzY4Mjc3', 38768277, '0039699', '11109', 'POLS-3083', 'POLS3083', 3, 3, 3, 4, 'Dr. Whitehall had a great reading list and lectures that really helped understand the books, but he had trouble maintaining the attention of the class. Tends to go off on tangents, and assigns several essays through the year. A little bit of a bore. His office hours are VERY helpful, he gives great guidance. if you put in the work you''ll do fine.', '["Get ready to read","So many papers","Caring"]', 'B', 1, 0, NULL, 3, 1, 2, 1703184434, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzYwNzU3', 38760757, '0133595', '6978', 'BIOL-3553', 'BIOL3553', 1, 1, 1, 5, 'Melanie is a lovely lady to talk to but her grading scheme + class is truly the most inaccessible thing I''ve ever taken. Immunology is a tremendously difficult subject but she does nothing to make it easier. Slides are from textbooks, there is way too much content + memorization for the was she tests, said she''d alter the grading scheme but didn''t.', '["Lecture heavy","Test heavy"]', 'B+', 1, 1, NULL, 3, 0, 0, 1703114775, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzYwODAw', 38760800, '0133595', NULL, 'BIO-3553', 'BIO3553', 1, 1, 1, 5, 'In Melanie''s class she was unable to answer questions, had little to no background information on the topics, and would just read off the slides (which were simply copy pasted from the textbook).
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzYwODEy', 38760812, '0133595', '6978', 'BIOL-3553', 'BIOL3553', 1, 1, 1, 5, '"I knew nobody was going to get this right"- about a question, she asked us on a midterm... very inaccessible, you are not set up to succeed. Being told there is no understanding and only memorizing. It is a hard class, but there are always ways to help students- none of which Melanie attempts. I am truly dissapointed and defeated', '[]', NULL, 1, 1, NULL, 3, 0, 0, 1703115069, 1788283351);
