INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4NzYwODY5', 38760869, '0133595', '6978', 'BIOL-3553', 'BIOL3553', 1, 1, 1, 5, 'I have never put more work into a class to have nothing to show for it or to receive such little help from a professor. She was transparent about not being able to answer questions in class but then would test our application of the topics... which she herself has to re-study every year because "you can only memorize it, you won''t understand".', '[]', NULL, 1, NULL, NULL, 3, 0, 0, 1703115373, 1788283351);
