INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTQ3NjI5', 38947629, '0308310', '13254', 'POLS-1503', 'POLS-1503', 5, 5, 5, 2, 'Dr Professor Wilson made class something I wanted to attend and gave clear instructions for what he wanted done for assignments. He made topics that can be difficult to talk about comfortable to talk about and made everyone feel supported and welcome. If you want a Professor that cares about students take Dr Professor Wilsons class. 100% take again', '["Amazing lectures ","Clear grading criteria","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1706897644, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTQ3NjIw', 38947620, '0308310', '13254', 'POLS-1503', 'POLS-1503', 5, 5, 5, 3, 'Doctor Professor Wilson is awesome. His classes are engaging but also super chill. Lots of reading to do but really interesting content. His assignments are straight forward and tells you exactly what he wants. Every prof should aspire to be like Doc Prof Wilson.', '["Participation matters","Amazing lectures ","Inspirational"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1706897535, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTU3MjI0', 38957224, '0011148', '10922', 'PHIL-2233', 'PHIL2233', 5, 5, 5, 3, 'shocked by the negative reviews here. Im a 4th yr and phil. isnt my major but I would die for this prof... Super engaging, the classes fly by, is always asking the class for opinions, stays unbiased, inclusive, and guiding. Her Ethics of Life class has changed me for the better, not exaggerating, that course will make you a better person .', '["Amazing lectures ","Gives good feedback","Caring"]', 'Incomplete', 1, 0, 1, NULL, 1, 0, 1707265861, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTU3MjY5', 38957269, '0037751', '11149', 'POLS-3693', 'POLS3693', 5, 5, 5, 4, 'Dr Brickner is approachable in and out of the classroom. She made the class interesting and engaging. Beware that she is not an easy grader, but is super generous with extra time and or help.', '["Participation matters","Gives good feedback","Lecture heavy"]', 'A-', 1, 1, 1, NULL, 0, 0, 1707266848, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTU3MjYx', 38957261, '0308310', '11107', 'POLS-3063', 'POLS-3063', 5, 5, 5, 2, 'Dr Professor Wilson is very approachable and great to work with in class. He works hard to design his lectures so we can and do relate to them on a personal level. Be prepared to participate in class, but not in an stressful called on manner, more that the entire class has an open conversation.', '["Participation matters","Hilarious","Accessible outside class"]', 'Incomplete', 1, 1, 1, 3, 0, 0, 1707266682, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTU3Mjgx', 38957281, '0141387', '11096', 'POLS-2893', 'POLS-2893', 5, 5, 5, 3, 'Jeffrey Sachs is approachable in and out of the classroom. He makes every class interesting and engaging. It is easy to stay focused and on topic with him teaching a class.', '["Get ready to read","Participation matters","Graded by few things"]', 'Incomplete', 1, 1, 1, NULL, 0, 0, 1707267085, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTUwNDc0', 38950474, '0000671', '7598', 'CODE-1023', 'CODE-1023', 1, 1, 1, 5, 'Prof has been at Acadia since 1974 as he keeps telling, with all his other stories too. Lectures are boring and he goes off track a lot. Unavailable outside class and unwilling to listen to feedback. His marking is done by TAs who are tough, and the materials feel outdated. WAY too much for assignments in 1st yr class. Why is he still teaching?', '["Tough grader","Lots of homework","Beware of pop quizzes"]', 'B-', 1, 1, NULL, 3, 1, 0, 1707051698, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTUwNDc1', 38950475, '0000671', '7598', 'CODE-1023', 'CODE-1023', 1, 1, 1, 5, 'Nightmare course and waste of time. Any decent ratings are from 14yrs ago. Prof is boring and confused and set in his ways. Only took because it was mandatory.', '["Tough grader","Lots of homework","Beware of pop quizzes"]', 'C-', 1, 1, NULL, 3, 0, 0, 1707051993, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTUwNDc2', 38950476, '0018503', '8616', 'ESST-2003', 'ESST2003', 5, 5, 5, 3, 'John is a cool guy with lots of life and community partnership and research experience. Caring prof and interesting classes. Reasonable about workload as long as you show up and do the readings and participate.', '["Participation matters","Group projects","Accessible outside class"]', 'B+', 1, 1, 1, NULL, 0, 0, 1707052304, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTUwNDcx', 38950471, '0015959', '7597', 'CODE-1013', 'CODE1013', 5, 5, 5, 2, 'Great prof and interesting topics. Got me thinking about my future. Good final assignment options instead of just another essay.', '["Participation matters","Group projects","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1707050874, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTY3NjQ5', 38967649, '0012981', NULL, 'ENG-1413', 'ENG1413', 2, 2, 2, 3, 'She makes you read a lot', '["Get ready to read","So many papers"]', 'A', 1, 1, 1, NULL, 0, 1, 1707658064, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTY3NjUw', 38967650, '0141387', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 3, 'If you ever get the chance to take one of his classes DO IT', '["Amazing lectures ","Inspirational","Caring"]', 'A+', 1, 1, 1, NULL, 0, 0, 1707658161, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMjcw', 38963270, '0037406', '11355', 'PSYC-3053', 'PSYC3053', 5, 5, 5, 3, 'Randy is passionate and makes time for students. Lectures contain a lot of information, she explains them very well, as long as you are attentive in class you will get a good grade. Cogneuro consisted of a midterm, a lab, and the final. overall the course was really interesting and I highly recommend taking any courses with Randy!', '["Amazing lectures ","Caring","Lecture heavy"]', 'A', 1, 1, 1, NULL, 0, 0, 1707435484, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMzM4', 38963338, '0034413', '7292', 'CHEM-1053', 'CHEM1053', 5, 5, 5, 2, 'Matt was a good professor. He tried to keep things funny and entertaining, his assignments were not boring and meant to be fun! there was a lot of material for chem in our world but overall it was a pretty easy course if you attend lectures and listen you will be fine. the final was mainly multiple choice!', '["Clear grading criteria","Hilarious"]', 'A+', 1, 1, 1, NULL, 0, 0, 1707437208, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMzMw', 38963330, '0169986', '11389', 'PSYC-3613', 'PSYC3613', 5, 5, 5, 4, 'Dan is a good prof and is always available for questions in/out of class. His lectures are pretty heavy but if you are attentive and understand the info you will be fine. The questions on tests are very application based so make sure you ask questions if you do not understand.  would take his classes again!', '["Caring","Graded by few things","Accessible outside class"]', 'A', 1, 1, 1, NULL, 0, 0, 1707436966, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMzQz', 38963343, '0141387', '11096', 'POLS-2893', 'POLS-2893', 5, 5, 5, 3, 'Dr. Sachs is a fantastic lecturer. He keeps good conversation in class, he is so engaging that even the quieter students will participate in the discussion. His assignments can be a lot of work, but he is always willing to guide his students. Very professional in the classroom, and he has a good sense of humour.', '["Amazing lectures ","Gives good feedback","Respected"]', 'B', 1, 0, 1, NULL, 0, 0, 1707437331, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMzUw', 38963350, '0000673', '6900', 'BIOL-2813', 'BIOL2813', 3, 3, 3, 3, 'Sherman Boates is a decent prof! the material of the course is pretty interesting if you like anatomy and doesn''t go too in depth but enough for a solid understanding. Although lectures can be slow and boring at some points he does give marks for attendance. the tests are average and as long as you study and pay attention. also an assignment', '["Caring","Graded by few things"]', 'A+', 1, 1, 1, NULL, 0, 0, 1707437432, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTYzMzg5', 38963389, '0021211', '10923', 'PHIL-2303', 'PHIL2303', 5, 5, 5, 3, 'Dr. Abela is such a good prof. He studies current events and brings them up in class which is a must for a topic like the environment. Going to his class I learned things. He does not force his personal Philosophy onto the class which I found a few other Philosophy Profs doing. If you want to take philosophy, start with Dr. Abela.', '["Amazing lectures ","Respected","Accessible outside class"]', 'B+', 1, 0, 1, 3, 0, 0, 1707438507, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTc2OTgx', 38976981, '0133590', '6837', 'BIOL-1123', 'BIOL1123', 2, 2, 2, 3, 'so difficult to read her lecture slides when you want to review for a test. super quiet and does not elaborate on the pictures that are shown on the slides. if you miss a class, slides will be super confusing. textbook is better', '[]', 'Incomplete', 1, 0, NULL, 3, 0, 0, 1707972627, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTc3MDM0', 38977034, '0133712', '9943', 'MATH-1013', 'MATH1013', 2, 2, 2, 3, 'Caroline is very caring, the lectures themselves were easy to following and understand but the assignments and labs were much harder than the lectures. The lecture material was quite simple and vague, I found it difficult to use it for assignments and studying. She does drop the lowest midterm grade for this course!', '[]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1707974853, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTc3MDQx', 38977041, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 2, 2, 2, 3, 'Caroline often continues the class material throughout the lab, instead of giving you the time to work on the lab activity and ask the TAs and herself questions. You will have to pay to download maplesoft and it is usually no instructions on how to use it for your labs.', '[]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1707975080, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTcwMDU5', 38970059, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 4, 4, 4, 2, 'I had Dr. Gauvin for abnormal psychology and it was a great course. Super nice! The lectures were really good and informative! Must take notes. Midterms and exams are straight forward, tests on both slides and text book. Has mandatory group activities, that require the use of knowledge from your textbook so reading is a requirement!! Great prof!', '["Get ready to read","Participation matters","Group projects"]', 'A-', 1, 1, 1, 3, 0, 0, 1707769620, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTcwMDY2', 38970066, '0012071', '9384', 'HIST-3733', 'HIST3733', 5, 5, 5, 3, 'This course focused on museums: each class focused on a different topic. I learnt so much in the class - and connected to so many other aspects - I didn''t realize how museums are so connected - even today!  There is a lot of reading, and be prepared for class discussions. Group project.', '["Participation matters","Amazing lectures ","Respected"]', 'A-', 1, 1, 1, NULL, 0, 0, 1707769722, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTcyNTg2', 38972586, '0306472', NULL, NULL, '1013', 2, 2, 2, 4, 'Rambles a lot and it is hard on the head. She is very passionate about her subject matter, but almost too much so. She is also unclear about her expectations for assignments, and as someone else mentioned you lose all participation points if you don''t speak in class. Does not answer emails. Would not recommend to anyone besides masters students.', '["Tough grader","Get ready to read","Participation matters"]', 'A', 1, 1, NULL, NULL, 0, 0, 1707848120, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTgwMDgx', 38980081, '0012071', '9264', 'HIST-2493', 'HIST2493', 4, 4, 4, 3, 'This is a participation heavy class: come with readings completed and prepared to discuss films. I saw so many really interesting films in this class. Does not post slides: attendance and participation is important for grade. Take notes. Fun group project where we created our own short about history! I really enjoyed the lectures and this class.', '["Participation matters","Group projects","Lecture heavy"]', 'B+', 0, 1, 1, NULL, 0, 0, 1708081003, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTgwOTM0', 38980934, '0133595', NULL, 'BIO-3553', 'BIO3553', 5, 5, 5, 4, 'Dr. Coombs is my favourite professor at Acadia University. Her objective is for her students to learn the basics of Immunology. Following any difficult objective, frustration is often targeted toward the professor. The energy you put into this class will be returned to you. Additionally there are easy points for almost half of your grade!', '[]', 'Rather not say', 0, 0, 1, NULL, 0, 0, 1708117818, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM4OTk4MTkx', 38998191, '0015407', '8496', 'ENGL-3843', 'ENGL3843', 5, 5, 5, 3, 'My favourite English professor so far! She really cares about her students and provides insightful feedback but also validates your writing and ideas!', '["Gives good feedback","Inspirational","Caring"]', 'A+', 1, 0, 1, 3, 0, 0, 1708806768, 1788283356);
