INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5MTA3Mjky', 39107292, '0019103', NULL, NULL, '2753', 5, 5, 5, 2, 'Dr. Mendivil is the best mathematics prof I have ever had in my life. His lectures are abstract, but so clear. His teaching can be unorthodox at times, but he does such a good job turning some of the more complex calculus theories into easily understandable math problems. His testing is fair, and he marks tutorial quizzes so easily. 10/10 prof.', '["Amazing lectures ","Inspirational","Respected"]', 'A+', 1, 1, 1, NULL, 0, 0, 1711907586, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5MTE2NDI3', 39116427, '0011148', '10907', 'PHIL-1413', 'PHIL1413', 5, 5, 5, 2, 'Anna''s very caring, accommodating, open to questions, and is always willing to chat with you or help you with anything. She is super clear about her expectations and grading which is helpful. Those who rate her poorly probably just don''t like philosophy rather than don''t like her, but if you like philosophy, you will love this class and this prof!', '["Participation matters","Clear grading criteria","Caring"]', 'A+', 1, 1, 1, NULL, 1, 0, 1712080725, 1788283341);
