INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5NzcwMDkx', 39770091, '0140662', '7142', 'BUSI-2433', 'BUSI2433', 1, 1, 1, 1, 'This professor accused me of cheating without any evidence. I did not cheat and never would. Went to the head of marketing to appeal it, got denied, then went to the head of business to appeal it and it was also concluded that I cheated. Do not have any friends in this class or you may get accused as well.', '["Test heavy","Graded by few things"]', 'C+', 1, 1, NULL, 3, 0, 0, 1727440103, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5Nzg1OTIz', 39785923, '0302829', '11705', 'SOCI-2103', 'SOCI-2103', 5, 5, 5, 4, 'Rabindra is very passionate about what he teaches and wants the best for his students as well as to get them to understand the content thoroughly. He is a great person who is very willing to help and although his lectures/the material can be hard to grasp, do not be afraid to ask for help.', '["Participation matters","Caring"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1728006468, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5NzgyNTIy', 39782522, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 2, 2, 2, 5, 'Any teacher that uses Pearson/Revel online textbooks doesn''t care about their students, period. $100 to access an online textbook system for one year is a scam, and it wouldn''t be so bad if the system actually worked properly. Don''t take this class unless you absolutely cannot graduate without it, as you are being set up to fail by the prof.', '["Get ready to read","Lots of homework","Lecture heavy"]', 'C+', 1, 1, NULL, 3, 0, 0, 1727904499, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5Nzk1MzM1', 39795335, '0307318', NULL, 'CLAS-1113', 'CLAS1113', 5, 5, 5, 1, 'Dr. Swain is the best prof to have on campus. She is passionate about what she teaches and cares for her students well-being especially in regards to mental health and students with disabilities. She understands that assignments pile up quickly and is really keen on giving extensions to students so they don`t lose marks for late assignments.', '["Amazing lectures ","Caring","Accessible outside class"]', 'B+', 1, 0, 1, 3, 1, 0, 1728410752, 1788283358);
