INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5OTUzNDEy', 39953412, '0145558', NULL, 'PSYCH-1110L', 'PSYCH1110L', 5, 5, 5, 3, 'Steph was an awesome prof for the Intro Psyc 1 & 2 labs! Super informative, big on learning and understanding APA and writing style, and a very caring person! Super easy to contact outside of class, and it isn''t hard to catch her in the Huggins basement if you need to chat quickly. Super clear w/ grading & gives excellent feedback.', '["Respected","Lecture heavy","Accessible outside class"]', 'A', 0, 1, 1, 3, 0, 0, 1731628498, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5OTY5MTI5', 39969129, '0001050', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 5, 'All this guy does is mumble the whole lecture. He also assigns random pop quizzes, so you have to go to class. He does not assign any work so you don''t know what to practice for the tests either. I don''t thinks he''s a bad guy but when you ask for help he just tells you to go on acorn and do it yourself. If you can avoid taking his class do it.', '["Tough grader","Beware of pop quizzes"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1731941141, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTM5OTYyMjAy', 39962202, '0002460', NULL, NULL, 'VOICE', 1, 1, 1, 5, 'I have never had such a horrible experience with a professor. For years, there have been complaints against her in the school of music. She is consistently manipulative, condescending, and judgemental. As the head of music, any time I or my peers have come to her with a concern, she has found a way to blame the students for the issue.', '[]', NULL, 0, 1, NULL, NULL, 0, 0, 1731776242, 1788283357);
