INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDM0ODM4', 30434838, '0132938', '7998', 'ECON-1023', 'ECON1023', 5, 5, 5, 5, 'Going to class is not mandateory but, will help you pass the course he notices whos there and whos not. His tests are hard make sure you understand the material don''t memorize. If you fail the tests don''t panic you just have to pass the exam and that will be your final mark. (my mark before exam was A F) . Exam is hard, start studying early.', '["Tough Grader","Gives good feedback","Skip class? You won''t pass."]', 'B-', 1, 0, 1, 0, 1, 0, 1534336426, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDQwOTc4', 30440978, '0040072', '8012', 'ECON-2613', 'ECON2613', 4, 4, 4, 5, 'Burc is a great prof! He wants his students to pass ,and is willing to help you as much as he can. Burc doesn''t make it easy ,but he makes you learn the material. Make sure to attend all his labs and try the assigned questions. Burc is the type of prof that in the end, if he knows you tried hard, he mightbump your mark up to a pass if you need it', '["Gives good feedback","Respected","Skip class? You won''t pass."]', 'C', 1, 1, 1, 5, 0, 0, 1534508697, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDU3MDE0', 30457014, '0018366', NULL, 'ENG-101', 'ENG101', 1, 1, 1, 5, 'Horrible.', '["Tough Grader"]', NULL, 1, NULL, 0, 0, 1, 0, 1535034119, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDY2MTk3', 30466197, '0048856', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Teri was a great 1st year chem prof! She was very enthusiastic! She had lots of good acronyms and would make different jokes and references to help you remember the course material. She expects participation during class and doesn''t just lecture the whole time, she asks questions to ensure you''re following. Very caring about her student''s success!', '["Hilarious","Amazing lectures","Caring"]', 'A', 1, 0, 1, 0, 3, 0, 1535404198, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDY2MjM5', 30466239, '0024859', '7286', 'CHEM-1013', 'CHEM1013', 3, 3, 3, 3, 'Dr. Jha was an okay prof, not my favourite though. He is pretty clear in his lectures and seems to care about the success of his students, in chemistry and in general. He does however lack a bit of enthusiasm and can be a little hard to listen to. He is nice, you just have to get used to his personality. Also, don''t expect him to recognize you!', '["Caring","LECTURE HEAVY"]', 'A-', 1, 0, 0, 0, 0, 1, 1535404800, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNDY2MjU3', 30466257, '0038515', '10989', 'PHYS-1053', 'PHYS1053', 5, 5, 5, 2, 'Anna is AMAZING! She knows all her students by name, its impressive! Her lectures are easy to follow, shes very cheerful and always available to help and she truly cares about her students success. She is very clear on what she is grading on and does everything she can to give you the most points possible! Highly recommend taking a class with her!', '["ACCESSIBLE OUTSIDE CLASS","Clear grading criteria","Caring"]', 'A+', 1, 0, 1, 0, 0, 0, 1535405117, 1788283339);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTA1NjM1', 30505635, '0000664', '10982', 'PHYS-1013', 'PHYS1013', 5, 5, 5, 4, 'He looks like Bill Gates.', '["Inspirational"]', NULL, 1, 1, 1, 5, 6, 0, 1537206970, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTA2MzEy', 30506312, '0012981', '8429', 'ENGL-2683', 'ENGL2683', 5, 5, 5, 3, 'Excellent prof. Excellent course. My favorite to date. Can''t go wrong.', '["Gives good feedback","ACCESSIBLE OUTSIDE CLASS","EXTRA CREDIT"]', NULL, 1, 1, 1, 5, 1, 0, 1537224096, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTI0NjU4', 30524658, '0034094', '7187', 'BUSI-3433', 'BUSI3433', 1, 1, 1, 3, 'This dude must love the sound of his own voice. Spends most of the class going on pointless tangents instead of actually teaching. Gives at least 10 &quot;examples&quot; for every concept he presents, no matter how simple it is, most of which barely have anything to do with what he is teaching. Is also rude to students if they don''t hang on his every word.', '["Skip class? You won''t pass.","BEWARE OF POP QUIZZES","LECTURE HEAVY"]', NULL, 1, 1, 0, 5, 4, 1, 1537975586, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTQ0MzE1', 30544315, '0024548', NULL, 'MATH-1213', 'MATH1213', 5, 5, 5, 2, 'He cares about his students and their grades. I feel like he was very lenient while grading, unlike a lot of math professors. He is such a sweet heart. If you care about his class, he''ll care about you. He remembers who shows up every day, and those people get treated kindly in turn. :)', '["Skip class? You won''t pass.","Hilarious","Caring"]', 'A-', 1, 1, 1, 5, 0, 0, 1538682746, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTc2NTQz', 30576543, '0027644', '10948', 'PHIL-3203', 'PHIL3203', 5, 5, 5, 3, 'Fantastic professor, he is extremely knowledgable and does a great job of explaining the concepts. My favourite prof at Acadia- take his classes if you can.', '["Inspirational","Amazing lectures","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1539720126, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTc4OTk4', 30578998, '0149576', NULL, 'POLS-2013', 'POLS2013', 5, 5, 5, 3, 'I have had many lectures with Dr. Mutlu over the years and he is EASILY my favourite professor. I feel like I have improved more as a student thanks to him, because he pushes students to do the best they can, whether its on papers, presentations, or asking more questions in class. He is also very clear what he wants on assignments! Very helpful!', '["Gives good feedback","Respected","Clear grading criteria"]', NULL, 1, NULL, 1, 5, 8, 0, 1539781467, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNTc5MDU4', 30579058, '0016390', '9364', 'HIST-3553', 'HIST3553', 5, 5, 5, 3, 'Dr. Dennis is the most passionate professor I have ever met. He makes 8:30am lectures easy to go to and has a great way of teaching. No one has an urge to be distracted by phones or laptops when he teaches, because he engages the whole class &amp; makes everyone interested, I love it. He has awesome feedback and makes sure students do their best', '["Gives good feedback","Inspirational","Amazing lectures"]', NULL, 1, NULL, 1, 5, 0, 0, 1539782274, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjAxMjA2', 30601206, '0012118', '6633', 'APSC-2113', 'APSC2113', 1, 1, 1, 4, 'Dr. Arnold has needs to learn how to have better lectures. Whats covered in class has slight resemblance to the assignments and tests. He never does examples only definitions and theories that we are suppose to just apply to everyday problems. Arnold rants about attendance and paying attention but you would be better off reading the text at home.', '["Tough Grader","TEST HEAVY","LECTURE HEAVY"]', NULL, 1, 1, 0, 5, 6, 0, 1540306194, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjE4MzE1', 30618315, '0034433', '7134', 'BUSI-2223', 'BUSI2223', 2, 2, 2, 4, 'Overall a good prof. Unfortunately, had to drop the class because the subject was simply overwhelming and I wasn''t really shown any support by the prof when i went to see him at his office hours. None the less, he was good at teaching finance. I would take the class again.', '["Tough Grader"]', NULL, 1, 0, 1, 5, 1, 0, 1540653778, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjI2MTEw', 30626110, '0029615', NULL, 'SOC-2103', 'SOC2103', 5, 5, 5, 3, 'Best prof Ive had. Ever! None of the other Soc profs even come close to comparing to Jim Britain. I suggest students take as many of his courses as possible. His lectures are mind blowing. He keeps it funny and interesting and doesnt use that stupid Acorn site. Love him!', '["Hilarious","Amazing lectures","EXTRA CREDIT"]', NULL, 1, 1, 1, 5, 0, 0, 1540840480, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjUyNDA0', 30652404, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 4, 'Terri is the best prof I''ve had at Acadia, she makes lectures fun to go to while teaching concepts in a funny clear way. Highly recommend', '["Skip class? You won''t pass.","Hilarious","Amazing lectures"]', NULL, 1, 0, 1, 0, 4, 0, 1541247631, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjY4OTAy', 30668902, '0139532', '11701', 'SOCI-2003', 'SOCI2003', 2, 2, 2, 4, 'Even though her lectures are quite long, she makes sure people get them. she puts a lot of effort in explaining any topic or course assignment over and over if you don''t understand something once. she does not mind repeating any explanation. she also encourages people to email her or even meet her during office hours. she is also very accommodating', '["Tough Grader","Gives good feedback","LECTURE HEAVY"]', NULL, 0, 1, 1, 0, 0, 0, 1541513320, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjY4OTUy', 30668952, '0139532', '11701', 'SOCI-2003', 'SOCI2003', 5, 5, 5, 4, 'Professor Casey is new but very cautious of that and tries to be understanding of any problems that come up with any expectations. she is obviously very caring and knows her stuff. I look forward to my classes with her in the future.', '["Respected","Caring","GROUP PROJECTS"]', NULL, 1, 1, 1, 5, 0, 0, 1541513610, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjY4OTk0', 30668994, '0139532', '11701', 'SOCI-2003', 'SOCI2003', 4, 4, 4, 4, 'Lectures are quite long, however, she puts a lot of effort into making the class interesting. she is very accommodating and encourages students to email her or meet her during office hours regarding any issue.', '["Tough Grader","Gives good feedback","LECTURE HEAVY"]', NULL, 0, 1, 1, 5, 0, 0, 1541513840, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjYxNDk0', 30661494, '0001916', NULL, 'MATH-2233', 'MATH2233', 5, 5, 5, 2, 'Trevor makes the lectures as interesting and engaging as possible by making jokes, and asking for a lot of class participation! He also notices who participates and you can tell that participation is impressive to him. He tries his absolute hardest to explain the material in a way that everyone can understand and is very understanding of schedules!', '["Participation matters","Hilarious","Amazing lectures"]', 'Not sure yet', 1, 1, 1, 5, 1, 0, 1541432368, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjc0NzA2', 30674706, '0001042', NULL, 'COMP-1013', 'COMP1013', 2, 2, 2, 4, 'Trudel''s bland lectures do not even come close to preparing you for assignments given, completely irrelevant to lecture material. Lectures consist of reading over prewritten code. Textbook is never used in class but necessary as it is used as a resource during the midterm and final. Don''t waste your time unless the course is required. Final is 60%!', '[]', NULL, 0, 0, 0, 5, 3, 0, 1541580178, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjc0NzE3', 30674717, '0026142', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 3, 'Mike is my favorite prof. He''ll make accounting simple to understand and fun to practice. Try to get to know him and you''ll find class a lot more fun and interesting. Get ready for the sing-a-longs!', '["Gives good feedback","Participation matters","Hilarious"]', 'Not sure yet', 1, 1, 1, 5, 0, 0, 1541580401, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjcxMzI1', 30671325, '0011703', '6715', 'ART-3033', 'ART3033', 5, 5, 5, 4, 'Great course. I loved working on the self portrait project and gained confidence in painting as a result.', '["Inspirational","Clear grading criteria","Caring"]', 'A', 1, 1, 1, 5, 0, 0, 1541528974, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNjcxNDQ4', 30671448, '0000916', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 3, 'Hassouna Moussa has the worst notes that I have ever experienced. You are much better off looking up the subjects on YouTube or other websites since it is very difficult to read and understand his notes. They are not spellchecked and the graphs are wrong lots of the time. He is a very quiet professor so I would recommend sitting near the front.', '["Get ready to read","LECTURE HEAVY"]', NULL, 1, 0, 0, 5, 0, 0, 1541529783, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNzM0MjY=', 3073426, '0013468', NULL, NULL, 'ETHISTTHEORY', 5, 5, 5, 4, 'Gret prof. He knows his stuff and is more concerned with teaching at a reasonable level than with what students think of him. He''s respectful and helpful, but sets high standards. He is demanding, but very fair and his expectations are always clear.', '[]', 'A', 0, 1, NULL, NULL, 0, 0, 1103470824, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNzYwNzY4', 30760768, '0023439', NULL, 'SOC-2013', 'SOC2013', 3, 3, 3, 4, 'Lesley has to rush through a lot of the lectures because there is so much material to cover. I''m not good at math, never have been so I struggled in this class. If you''re a decent math student then you''ll do fine in this class but if you struggle with math like me you''re going to have to put in a lot of work.', '[]', 'B-', 1, 1, 0, 5, 0, 0, 1542705732, 1788283349);
