INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwNzg2NTIy', 30786522, '0000916', '7997', 'ECON-1013', 'ECON1013', 3, 3, 3, 3, 'Really good prof who want''s you to succeed. Notes are very miss and you should expect to you use YouTube. Assignments are a lot of work and undervalued for the work you are expected to do per assignment.', '["Get ready to read","LOTS OF HOMEWORK","Caring"]', NULL, 1, 0, 0, 0, 0, 0, 1543267083, 1788283358);
