INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMwODA0OTA0', 30804904, '0013980', '8394', 'ENGL-1423', 'ENGL1423', 5, 5, 5, 2, 'Lance is the sweetest guy you''ll ever meet, he cares so much about you succeeding in his class. Although it is a once a weeknight class he always keeps you engaged and interested in the topics. He truly made me fall in love with english again. The texts he chooses are odd choices but SUCH GOOD BOOKS! (If you read them) 10/10 will take a class again', '["Gives good feedback","Participation matters","Amazing lectures"]', 'B+', 1, 1, 1, 5, 0, 0, 1543421003, 1788283349);
