INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMTU5NDcw', 31159470, '0044772', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 4, 'Dr. Ellis is the best prof I had in Acadia so far. He is super helpful, and wants you to succeed. Although he goes by quick when explaining content, he''s very enthusiastic about what he teaches which makes it more interesting. Midterms and exams are hard but if you put in the time you''ll do well. I would definitely take another class with him again', '["Tough Grader","Inspirational","Amazing lectures"]', 'A+', 1, 1, 1, 0, 7, 0, 1545869997, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMTcxNjYy', 31171662, '0041312', '8393', 'ENGL-1413', 'ENGL1413', 2, 2, 2, 5, 'English was always my preffered subject in academics throughout my whole life, until this course came. It is a lot of reading required in a short period of time, she is also a very tough marker, make sure you don''t leave out a single piece of MLA formatting or she will doc you BIG TIME. Very nice lady though.', '["Tough Grader","Get ready to read","Participation matters"]', NULL, 1, 1, 0, 0, 2, 0, 1546055097, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMjA5MDk3', 31209097, '0041312', NULL, 'ENGL-1013', 'ENGL1013', 2, 2, 2, 3, 'Shes not an awful prof, but she goes on and on about the same thing for basically the entire class. This is more of a personal thing, but i couldnt stand it once i noticed but she says right so much. I counted once, in half an hour she said it 230 times. I couldnt pay attention because of this!!!! Nice enough though.', '["Get ready to read","Participation matters","GROUP PROJECTS"]', 'D', 1, 1, 0, 5, 1, 0, 1546797134, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMjIyNTUw', 31222550, '0027644', '10907', 'PHIL-1413', 'PHIL1413', 1, 1, 1, 3, 'do not take god ethics and justice with this prof, not an easy elective and he is the weirdest man you will ever meet. If you don''t go to class he will not help you. It''s a waste of an elective. The book is very important, anything you need clarification on is in the book, don''t waste your time asking him for help.', '[]', NULL, 0, 1, 0, 5, 0, 0, 1546964417, 1788283350);
