INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMjMwMDE3', 31230017, '0000967', NULL, 'GEO-5533', 'GEO5533', 1, 1, 1, 5, 'I took Rob Raeside''s metamorphic course in the late 1980s. He was young then; he is old now. He failed a whole class on one exam. He then asked me what I thought of his exam: I noted the exam was &quot;loaded.&quot; That angered him. He then proceeded to bell curve up to pass all the class but me on that exam, failing me.', '["Tough Grader","Get ready to read","BEWARE OF POP QUIZZES"]', 'C', 1, 1, 0, 5, 0, 0, 1547034704, 1788283353);
