INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxMjMyNTQ2', 31232546, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 4, 4, 4, 3, 'Professor Sarhadi was a great professor for this course. He moved at pace that was easy to follow along, taking his time when the material became more challenging. He provided lots of practice questions and answers to further our understanding. He was fair in the content he asked on exams and how he marked. I would recommend him for this course.', '["Gives good feedback","Clear grading criteria","EXTRA CREDIT"]', 'A+', 1, 1, 1, 0, 1, 0, 1547065925, 1788283345);
