INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNDU2NDM4', 31456438, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 1, 1, 1, 5, 'Absolutely terrible, test answers must be word for word or you will get terrible marks. He does not use powerpoint or any online tools, so if you miss a class for any reason you are behind. Hard to talk to or negotiate with, threatens to take off points if you want to go ask why he graded things the way he did. Class averages are well below a pass.', '["Get ready to read","Lecture heavy","Tough grader"]', NULL, 1, 1, 0, 5, 4, 0, 1553089553, 1788283355);
