INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNDY3NjYw', 31467660, '0016415', '8615', 'ESST-1023', 'ESST1023', 5, 5, 5, 4, 'I have never felt more supported by a professor. He is so helpful, funny, and kind. He helps create a community within the classroom in a way that makes everyone feel comfortable. I highly recommend anyone to take his classes. We were graded on about 5 assignments. HIGHLY RECOMMEND!', '[]', NULL, 1, 1, 1, 0, 0, 0, 1553283241, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNDg0MjM0', 31484234, '0046920', '7134', 'BUSI-2223', 'BUSI2223', 5, 5, 5, 3, 'An amazing professor who really cares about his students. Very clear teaching method. He always made time to help, truly wants u to ''get it''. Can tell he''s a genuine, caring guy. Always made me feel really comfortable going in to see him &amp; he was easily able to explain everything i didnt get. Top notch prof and guy overall, best prof I''ve ever had!', '["Gives good feedback","Accessible outside class","Caring"]', 'A', 1, 1, 1, 5, 2, 0, 1553645642, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNDg2MjYw', 31486260, '0018196', '7312', 'CHEM-2533', 'CHEM2533', 5, 5, 5, 3, 'Took this course to prepare for MCATs - glad I did! Banksy did a great job of teaching chemistry - but an awesome job of demonstrating the value of working at something. I had to work hard - but it paid off with an A! And he is not an easy marker - so it is something that makes me very proud. Work hard and you will do well.', '["Gives good feedback","Clear grading criteria","Amazing lectures"]', 'A', 1, 0, 1, 5, 0, 0, 1553687580, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTA0NDc3', 31504477, '0041312', NULL, 'ENG-1223', 'ENG1223', 4, 4, 4, 4, 'She is a very caring and understanding prof. I am not sure if it is the course itself but WOW was it a lot of work. You have to read an essay for every class and make sure you read them because the class discussion is based off of them or there is a pop quiz on it. She marks hard!', '["Participation matters","Caring","Tough grader"]', 'A-', 1, 1, 0, 5, 0, 0, 1554013303, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTA0NDky', 31504492, '0039663', '7288', 'CHEM-1023', 'CHEM1023', 3, 3, 3, 3, 'No connection with students. Accent is awfully difficult to understand! Did not really learn much from class, mainly the weekly assignments and going over the powerpoint myself. He is not awful but not good nor great. The course itself is really basic when you look back on it, but you have to grind at first because it is all new (at least for me).', '[]', 'A', 1, 0, 0, 0, 1, 0, 1554013913, 1788283341);
