INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTAyODU4', 31502858, '0132938', '8014', 'ECON-2713', 'ECON2713', 5, 5, 5, 3, 'This prof knows his stuff. He seems to have a grasp on any topic related to economics. Learned a lot from him and his examples are helpful and relative. Would definitely take a class from him again.', '["Gives good feedback","Respected","Tough grader"]', NULL, 1, 1, 1, 0, 0, 0, 1553969710, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTE4MzQz', 31518343, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 4, 'Some things on the mid terms you wouldn''t have seen ever.', '["Get ready to read","Skip class? You won''t pass.","Tough grader"]', 'A-', 1, 0, 0, 5, 0, 0, 1554238232, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTE5NDU1', 31519455, '0019405', '8735', 'FRAN-1113', 'FRAN1113', 5, 5, 5, 2, 'Bernard was one of my favorite profs. He is super sweet and caring and just wants you to understand. He tells you what Is going to be on the tests and is an easy marker. Make sure to go to the classes because he does not post anything online, and to do the workshops. His handwriting is not great and is hard to understand though.', '["Respected","Clear grading criteria","Caring"]', 'A', 0, 1, 1, 5, 0, 0, 1554247771, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTE5NDc5', 31519479, '0034413', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Lukeman was an awesome prof, he made the first year amazing. He cares about how you do and wants you to do well in the class. I enjoyed going to his 8:30 classes and would recommend taking a class with him.', '["Respected","Hilarious","Amazing lectures"]', 'B+', 0, 0, 1, 0, 0, 0, 1554247965, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTExNTY3', 31511567, '0016415', '9185', 'HIST-1413', 'HIST1413', 5, 5, 5, 3, 'Dr. David Freeland Duke is literally one of the best professors I have had. He is caring, and will make time for you if you show you care about school. He is funny but can be tough if you take his course lightly. If you want an amazing classroom experience with a prof who will keep you entertained take a course taught by Dr. Duke!', '["Skip class? You won''t pass.","Amazing lectures","Caring"]', 'A', 1, 1, 1, 5, 1, 0, 1554154358, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTEyODgw', 31512880, '0024327', '11106', 'POLS-3043', 'POLS3043', 5, 5, 5, 3, 'Dr. Biro was great! Although the course was reading intensive(a third year course tho) it was very important to go to class and listen to lectures to better understand texts. easy to talk to during office hours and answers questions clearly', '["Gives good feedback","Respected","Participation matters"]', NULL, 1, 1, 1, 5, 0, 0, 1554166791, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTEyOTM4', 31512938, '0003100', '9375', 'HIST-3663', 'HIST3663', 3, 3, 3, 4, 'Dr. Henderson didn''t teach anything other than summarize the readings from textbooks. If you don''t do the readings you won''t do well, he only tests on readings, marks attendance do the readings you''ll be fine.', '[]', 'B+', 1, 0, 0, 5, 0, 0, 1554167266, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTI3OTI1', 31527925, '0003100', '9186', 'HIST-1423', 'HIST1423', 3, 3, 3, 5, 'Good prof and knows his stuff and makes lectures interesting and open to questions! However, he made the course so difficult that I am never going to take a class if he is teaching it. Midterms were 4 paragraph answers and 2 essays. He marks VERY hard, where it is just unfair. I love learning about history but I had an awful experience this time.', '["Amazing lectures","Tough grader"]', 'A-', 1, 1, 0, 0, 0, 0, 1554342832, 1788283355);
