INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTQ4MjE3', 31548217, '0024045', '7288', 'CHEM-1023', 'CHEM1023', 5, 5, 5, 3, 'Vlad tries hard to keep students engaged with real-world applications and in-class experiments. He ties classes together by starting with a review of the previous class. He gives you every chance to get extra help, so but if you don''t pass it''s because you aren''t coming to class or taking advantage of office hours. Witty and helpful prof!', '["Accessible outside class","Skip class? You won''t pass.","Caring"]', NULL, 1, 0, 1, 0, 0, 0, 1554724813, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTQ4MjMy', 31548232, '0016390', NULL, NULL, 'H2313', 1, 1, 1, 4, 'Okay, RELAX when writing on the board, its not a race! It is nearly impossible to read this mans writing, he gives little to no hints on what the exam will be on and overall this class is wack. DO NOT TAKE IF YOU DONT LOVE HSTORY', '["Get ready to read"]', 'B', 1, 1, 0, 5, 0, 1, 1554725544, 1788283351);
