INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNTQwOTg5', 31540989, '0012118', '6633', 'APSC-2113', 'APSC2113', 2, 2, 2, 5, 'He is a nice guy BUT he is a poor teacher. He does not go over enough examples, wastes too much time on theory while half the class goes on their phones. His tests are WAY too hard and the average grade is always low. Some of the problems on midterms are not similar to any problems done in class. These problems should be for homework instead.', '["Lots of homework","Test heavy","Tough grader"]', 'A', 1, 0, 0, 5, 1, 0, 1554515562, 1788283352);
