INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjIwNzA5', 31620709, '0012071', '9196', 'HIST-1823', 'HIST1823', 3, 3, 3, 3, 'Dr Dalton is energetic and passionate, which helps engage the large class. However, at times this enthusiasm translated to the professor speeding through critical topics and leaving important subjects until two minutes before the class was supposed to end. Be prepared to learn a lot and take a lot of notes!', '["Participation matters","Graded by few things","Lecture heavy"]', NULL, 1, 0, 1, 0, 0, 0, 1555575550, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjIwNzE0', 31620714, '0000967', '8946', 'GEOL-2753', 'GEOL2753', 4, 4, 4, 3, 'Dr Raeside''s lectures were very informative, and his slides captured the information well, which helped my studying later. The textbook isn''t essential, but it helps to learn the material from another perspective. The tests were a bit specific, but followed the same format as the practice tests and were pretty straightforward.', '["Gives good feedback","Skip class? You won''t pass.","Beware of pop quizzes"]', 'A', 1, 0, 1, 5, 0, 0, 1555575895, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjMxMzI1', 31631325, '0002460', '10308', 'MUSI-2700', 'MUSI2700', 1, 1, 1, 5, 'Christianne is very rude and sarcastic. She thinks she is above others and it shows. Acts like you create problems that she actually did. Doesn''t care about her music students one bit. Tries to purposely make your life harder/worse, by abusing her authority and going against things specified by documents such as the academic calendar and others.', '[]', 'Not sure yet', 1, 1, 0, 0, 1, 0, 1555702641, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjQwMzI4', 31640328, '0026142', '7129', 'BUSI-2033', 'BUSI2033', 5, 5, 5, 2, 'There aren''t enough words to describe Mike Kennedy. Absolutely no complaints with him, you get out what you put into his classes. I''m a die hard business major but if Mike was teaching astrophysics or zoology, I wouldn''t hesitate to sign up for those classes.', '["Respected","Inspirational","Caring"]', 'B', 1, 0, 1, 5, 0, 0, 1555905292, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjQwNDAy', 31640402, '0000916', '7997', 'ECON-1013', 'ECON1013', 3, 3, 3, 2, 'Great guy, knows the material but he''s really hard to understand. Open to answering questions in class, marks on bell curve.', '["Caring"]', 'A-', 1, 0, 1, 0, 0, 1, 1555906169, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjQwNDE4', 31640418, '0000768', '7127', 'BUSI-2013', 'BUSI2013', 5, 5, 5, 2, 'Great guy, 25% of your grade comes from participation and answering questions, he makes that super easy on top of that. Knows his stuff and midterms and exams are easy. Funny, loves sports; no complaints about Feltmate.', '["Gives good feedback","Participation matters","Caring"]', 'A', 1, 1, 1, 5, 1, 0, 1555906418, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMxNjUwMjc4', 31650278, '0169988', NULL, 'FYP-1000', 'FYP1000', 5, 5, 5, 4, 'Kait Pinder basically taught me how to read and write. She is utterly brilliant and an amazing teacher. She gives the best feedback and truly cares about her students. I would advise anyone to take as many classes with her as possible.', '["Gives good feedback","Amazing lectures","Caring"]', 'A', 1, 1, 1, 0, 0, 0, 1556025020, 1788283348);
