INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMTg3ODUy', 32187852, '0033849', '11991', 'THEA-2823', 'THEA2823', 5, 5, 5, 3, 'Go to class, seriously. Read your emails. Dont skip class! You will miss things you need. Susann is always willing to make time for a student who needs extra help. I went three times about the same thing. LOL thought she would hate me, she didn''t. Wish I had more classes with her.', '["Skip class? You won''t pass.","Clear grading criteria","Caring"]', NULL, 1, 1, 1, 5, 1, 0, 1566399397, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMTgzNTM4', 32183538, '0145558', NULL, 'PSYCH-1013', 'PSYCH1013', 5, 5, 5, 3, 'Stephanie was an amazing professor! I had her for intro psych and she made the class interesting. Shes extremely willing to give extra help and is very easy to talk to. Shes fantastic when answering questions and always clear. Her slides are well organized and follow the book. I highly respect her.', '["Gives good feedback","Accessible outside class"]', NULL, 1, 1, 1, 5, 0, 0, 1566249067, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMTk5NTMw', 32199530, '0021212', '9943', 'MATH-1013', 'MATH1013', 4, 4, 4, 3, 'Karsten is one of my favorite Math profs to date. You''ll always learn something new in his lectures, whether it''s useful or not.', '["Inspirational","Clear grading criteria","Lecture heavy"]', 'A-', 0, 0, 1, 5, 0, 0, 1566910758, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjA4Mjk=', 3220829, '0015927', NULL, NULL, 'KINE', 5, 5, 5, 4, 'He is hard but we are in university, he doesnt spoonfeed you like some profs.  He makes research issues not so bad.. hard to make that course really interesting. Overall, great guy!', '[]', NULL, 0, NULL, NULL, NULL, 0, 1, 1105686067, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjEwNzE0', 32210714, '0003100', NULL, 'HIST-3366', 'HIST3366', 5, 5, 5, 3, 'Dr. Henderson is my favourite prof at Acadia. He is passionate about what he teaches, and it shows. His midterms and exams are writing heavy, but he lets you pick from the questions so you have the opportunity to write about what you understand best. The first class I took with him was an elective but I wound up changing my major because of him.', '["Gives good feedback","Skip class? You won''t pass.","Amazing lectures"]', 'A-', 1, 1, 1, 0, 0, 0, 1567516708, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjEwNzE3', 32210717, '0043166', '9303', 'HIST-3113', 'HIST3113', 5, 5, 5, 5, 'Go to class. Do the reading. Participate. Dr. MacDonald is so passionate about what she teaches and it''s contagious. Her classes are reading heavy and her papers are long, but her excitement makes you want to work hard for her. I really appreciated her openness to alternative project formats in lieu of giving an oral presentation.', '["Get ready to read","Participation matters","Skip class? You won''t pass."]', 'B+', 1, 1, 1, 5, 0, 0, 1567517122, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjEwNzIw', 32210720, '0012071', '9264', 'HIST-2493', 'HIST2493', 5, 5, 5, 4, 'Dr. Dalton is super passionate about what she teaches and she does a great job of teaching the material. The issues I had with her were that she would ignore emails asking questions, change the syllabus at the last second, and try to cram two semesters worth of material into a one semester course.', '["Skip class? You won''t pass.","Clear grading criteria","Lecture heavy"]', 'A-', 1, 1, 0, 0, 0, 1, 1567517362, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjEwNzIz', 32210723, '0015754', NULL, 'ENG-2283', 'ENG2283', 2, 2, 2, 4, 'She knows her stuff but she really seems to lack compassion, especially as a department head.', '["Get ready to read","Skip class? You won''t pass."]', 'B+', 1, 1, 0, 5, 1, 0, 1567517541, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjExOTc3', 32211977, '0169988', NULL, 'ENGL-1406', 'ENGL1406', 3, 3, 3, 4, 'She always prepare for class and is willing to help you out. However, I found that she marked very hard. Most of the novels that we read in class were very boring. She is the one who chooses the novels and other English professor did not choose the novels she picked. Overall I would take her class again because I learned a lot.', '[]', 'B+', 1, 1, 1, 5, 0, 0, 1567562025, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjEzNDgw', 32213480, '0016390', NULL, NULL, 'H2503', 5, 5, 5, 1, 'Dr. Dennis is the best professor in the history department at Acadia. He genuinely cares about you and your success. He is always willing to help you out if you ask for it. Very engaging lecturer. He is so passionate about his teaching, and you can really pick up on that. HIGHLY recommend.', '["Accessible outside class","Participation matters","Caring"]', 'B+', 1, 1, 1, 5, 0, 0, 1567635711, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjQ3ODQ4', 32247848, '0031453', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 3, 'Really hard to understand. The thick accent makes the class harder then it has to be.', '["Lots of homework"]', 'A', 1, 0, 0, 5, 0, 0, 1569498933, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjQwODEy', 32240812, '0016390', NULL, NULL, 'H2313', 5, 5, 5, 4, 'I transferred out of Acadia, but he alone would be a reason to transfer back. I recommend Acadia University to everyone as a great University but you MUST try at least one of his classes. He rewards those who put in the work, not just with grades but with knowledge and understanding. If you put in the effort you will be rewarded!', '["Get ready to read","Inspirational","Amazing lectures"]', 'A', 1, 1, 1, 5, 0, 0, 1569199450, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjQzNDc=', 3224347, '0000768', NULL, NULL, 'ACCOUNTING', 5, 5, 5, 3, 'Great Prof. He is dry, but he is effective and you can learn alot', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1105728863, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjUwNzYw', 32250760, '0002460', '10308', 'MUSI-2700', 'MUSI2700', 5, 5, 5, 4, 'Dr. Rushton is a talented teacher and always works to do the best by her students. She is constantly working as a prof and as director but manages well in both departments. She will literally do anything for students that are respectful and care about their education/career. If you''re not going to try, she won''t pull strings for you! do your best!', '["Gives good feedback","Inspirational","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1569617481, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjc0OTc4', 32274978, '0031453', NULL, 'MATH-1213', 'MATH1213', 1, 1, 1, 4, 'Incredibly hard to understand. The combination of a thick accent, her assuming the students know what she''s talking about, and jumping around between points make it next to impossible to follow. Don''t even bother to show up to class, teach yourself.', '["Lots of homework","Tough grader"]', NULL, 1, 0, 0, 5, 0, 0, 1570667571, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjc3NDgw', 32277480, '0037539', '9943', 'MATH-1013', 'MATH1013', 1, 1, 1, 4, 'Teaches way too fast with no explanations. Often gets way behind other calculus classes, which results in doing assignments without knowing any of the material on them. I was a very strong calculus student in high school but Eva makes it a struggle.', '[]', NULL, 1, 1, 0, 0, 0, 0, 1570743482, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMjc3ODcw', 32277870, '0016390', '9241', 'HIST-2313', 'HIST2313', 5, 5, 5, 4, 'Michael Dennis is the best professor in the entire university. He is so kind, engaging, and understanding. He definitely expects you to participate and put in the work, but he genuinely cares about your success and wants to help you in any way that he can. He also takes the time to get to know you as a person. An absolute must if you go to Acadia.', '["Accessible outside class","Participation matters","Caring"]', NULL, 1, 1, 1, 5, 0, 0, 1570752198, 1788283351);
