INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMzk0MzI0', 32394324, '0133595', '6978', 'BIOL-3553', 'BIOL3553', 5, 5, 5, 5, 'She is amazing. The class is really hard but about 30% of it is free points. The midterms are long but very fair and she is a very generous marker for presentations and papers. Dr Coombs really cares about her students and is so wonderful', '["Clear grading criteria","Caring"]', 'A', 1, NULL, 1, 5, 1, 0, 1573510600, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyMzk5OTQ5', 32399949, '0012118', '6614', 'APSC-1073', 'APSC1073', 2, 2, 2, 4, 'He''s a tough grader taking points off whenever possible. replys to emails late and often the information given is misleading giving different answers to the same question. Treats you like just another student.', '["Lots of homework","Get ready to read","Tough grader"]', NULL, 1, 1, 0, 5, 0, 0, 1573588186, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNDQyNzg2', 32442786, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 4, 'The course itself is quite hard and you definitely need to put in the work, however Teri is an amazing professor who puts in a lot of effort to try and help all of her students do well. She''s great at engaging students in lecture and tries her best to make the course as fun and enjoyable as possible! Definitely made the course more bearable!', '["Respected","Skip class? You won''t pass.","Hilarious"]', 'A-', 1, 1, 1, 0, 0, 0, 1574208097, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNDQyODQw', 32442840, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 4, 'Todd is one of the sweetest professors at Acadia. Although the course is extremely note heavy, the slides he gives in lecture have all the information you could ever need. Even though students tend to not do so well on his tests, he gives out lots of partial points for just trying your best! Tries hard to make his lectures enjoyable and fun!', '["Respected","Lecture heavy","Caring"]', 'B+', 1, 0, 1, 0, 0, 0, 1574208478, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNDUwOTAw', 32450900, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 4, 'It''s a class that''s so easy you feel like you''ve learned it all in grade 10 but yet she makes it so specific and grades so hard that no one gets higher than a B', '["Lots of homework","Get ready to read","Skip class? You won''t pass."]', 'B', 1, 1, 0, 5, 1, 0, 1574290889, 1788283363);
