INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTI4MjE0', 32528214, '0133592', NULL, NULL, '1110LAB', 1, 1, 1, 3, 'This guy never taught anything at all. It was all taught by TAs. Also, the guy, every time he looked at me. He looked at me with such visible disgust. Like the kind of disgust, you look at a dumpster full of maggots with. It was really hurtful and made me feel uncomfortable and disrespected. He also tried to switch me into liberal arts degree.', '["Graded by few things"]', NULL, 1, 1, 0, 0, 0, 0, 1575501512, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTI4NDgw', 32528480, '0000673', NULL, 'BIOL-2000', 'BIOL2000', 2, 2, 2, 2, 'He was okay. I felt like he didn''t respect or like me very much. Took us on a field trip even though the university took away the labs, so he didn''t have too but he did and that was cool.', '["Accessible outside class","Graded by few things","Group projects"]', NULL, 1, 1, 0, 0, 0, 0, 1575502553, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTI4NzEx', 32528711, '0000657', '8900', 'GEOL-1013', 'GEOL1013', 5, 5, 5, 4, 'Great prof. She actually cares about us students. It''s hard for me to get into things I don''t like but Sandra tried really hard to make it enjoyable. If I missed anything she would go out of her way to make sure I got it. She''s very passionate about rocks and her passion really shines through.', '["Respected","Accessible outside class","Caring"]', NULL, 1, 1, 1, 5, 0, 0, 1575503497, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTIwOTEy', 32520912, '0034933', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 3, 'I would not recommend this prof to anyone. If you have to take a course that he is lecturing be prepared for ignorant remarks and unfair testing/marking.', '[]', 'B', 1, 1, 0, 0, 0, 0, 1575473455, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTIyNDE5', 32522419, '0037539', '9943', 'MATH-1013', 'MATH1013', 2, 2, 2, 4, 'Eva is very nice but does not hold up as a professor. She always seems to he unprepared for her own lectures. lectures are often over explained and over complicated yet you still have trouble knowing how to do the work. stops for questions and pauses for very long moments when clear no one knows the answer. Doesnt respond to emails quite often.', '["Lots of homework","Tough grader"]', 'Incomplete', 1, 0, 0, 0, 0, 0, 1575479852, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTQ5ODUy', 32549852, '0145558', '11321', 'PSYC-1123', 'PSYC1123', 5, 5, 5, 4, 'Stephanie is a great professor. Midterms are hard but she provides other assignments and extra credit to help towards the final mark. She is very helpful at her office hours as well. Highly recommend purchasing the textbook, very helpful.', '["Test heavy","Lecture heavy"]', NULL, 1, NULL, 1, 5, 0, 0, 1575652219, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTU5NzU2', 32559756, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 4, 'Professor Carmicheal is one of the worst/bias markers I have ever encountered. She will give the vaguest description for a paper/project, then she will grade the work like she gave the most in-depth instructions. To put it into perspective, If you ask any of my employers, they will tell you that communication is my strength, but it''s my worst mark.', '["Participation matters","Skip class? You won''t pass.","Beware of pop quizzes"]', 'B', 1, 1, 0, 5, 2, 0, 1575744047, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTY3NDkw', 32567490, '0016390', '9334', 'HIST-3323', 'HIST3323', 5, 5, 5, 4, 'He is an amazing and caring professor. I would highly recommend taking classes with him whenever possible!', '["Gives good feedback","Inspirational","Amazing lectures"]', NULL, 1, 1, 1, 5, 0, 0, 1575838867, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTY5NzQw', 32569740, '0024327', '11056', 'POLS-1303', 'POLS1303', 2, 2, 2, 5, 'Biro is a great teacher, and a friendly guy. He marks ridiculously hard for a first year politics course. Class is fun and engaging but good luck getting better than a 70 on an essay. Consider taking this course with Sachs as he marks reasonably.', '[]', NULL, 1, 1, 0, 5, 0, 0, 1575854155, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNTc0NjQ4', 32574648, '0012118', '6633', 'APSC-2113', 'APSC2113', 1, 1, 1, 4, 'Is rarely available outside class time. Does not respond to emails or phone messages. Refuses to curve midterms even when the median is below 30%. Does not understand why students don''t do well in his class, while he doesnt teach fundamental concepts well. Avoid his classes at all costs.', '["Get ready to read","Lecture heavy","Tough grader"]', 'A-', 1, 0, 0, 5, 0, 0, 1575906494, 1788283352);
