INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNjA4NTU4', 32608558, '0008859', '10916', 'PHIL-2103', 'PHIL2103', 4, 4, 4, 3, 'As a philosophy prof there''s lots of readings, but I was able to find most of the assigned readings online or through the library system (maybe don''t buy the textbook right away). Lecture style can be dry, but you can easily make it better by contributing your thoughts. A big fan of essay questions, make sure you really understand the readings.', '["Get ready to read","Graded by few things","Caring"]', 'B', 1, 0, 1, 5, 0, 0, 1576077661, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyNjA4ODM1', 32608835, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 1, 1, 1, 5, 'The material covered in this course is about double what is covered in organic chemistry at other institutions. Do not recommend it. Not an accurate representation of what you should be learning.', '["Graded by few things","Test heavy","Tough grader"]', 'C+', 1, 1, 0, 0, 0, 0, 1576079121, 1788283362);
