INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyODUyNTgz', 32852583, '0048856', NULL, 'CHEM-2510', 'CHEM2510', 5, 5, 5, 5, 'Teri is hands down one of the best profs at Acadia. If you have to take organic chem you''re gonna want the best and she is it! Sure the course material is hard but Teri teaches in a way that makes you want to learn.', '["Inspirational","Hilarious","Caring"]', 'B', 1, 0, 1, 0, 0, 0, 1579562370, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyODY1NjE0', 32865614, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 3, 'I had to take Organic 1 twice because I did not understand it the first time, but her class was still really good. The first time I got a D- and then a A- the second time. Her labs are also great with the reports being given templates and all the pre-lab quizzes are online instead of right before lab like in intro chem.', '["Participation matters","Skip class? You won''t pass.","Amazing lectures"]', 'A-', 1, 1, 1, 5, 0, 0, 1579893294, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyODY1NjE1', 32865615, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 4, 'She makes everything so clear and easy to understand! Amazing in lecture and lab. Best prof ever!', '["Gives good feedback","Amazing lectures","Caring"]', 'A+', 1, 1, 1, 0, 0, 0, 1579893303, 1788283362);
