INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyODY3NzQ1', 32867745, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 3, 'Teri is an excellent prof. Her teaching style is effective and her lectures are very easy to follow. She is a good prof. and an even better lab instructor. The best chemistry lab instructor that I have had at Acadia.', '["Accessible outside class","Skip class? You won''t pass.","Hilarious"]', 'A', 1, 1, 1, 0, 0, 0, 1579994561, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyODg3Mzg0', 32887384, '0169986', '11315', 'PSYC-1013', 'PSYC1013', 5, 5, 5, 3, 'Dan is a great guy! You can really tell he is passionate about what he teaches. He makes all of his lectures interesting and is genuinely funny. The odd question on the midterms/exam that seems to come out of nowhere (i.e., don''t remember learning bout it in class), but otherwise tests are completely fair/reasonable. I would definitely recommend!', '["Hilarious","Beware of pop quizzes","Amazing lectures"]', 'A', 1, 0, 1, 5, 0, 0, 1580765155, 1788283343);
