INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTQ3MTY2', 32947166, '0034445', NULL, NULL, 'ENGLISH1413', 5, 5, 5, 3, 'One of the best Profs at Acadia. I don''t know why people say he is a hard marker, I think his marking is extremely fair. He is incredibly funny and his lectures are very interesting. He can make the most boring subjects fascinating', '["Accessible outside class","Amazing lectures","Caring"]', 'A-', 1, 1, 1, 5, 0, 0, 1583248725, 1788283347);
