INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTUwNTYy', 32950562, '0031453', NULL, 'MATH-1214', 'MATH1214', 2, 2, 2, 2, 'Ying Zhang was smart and knew what she was doing for the most part, but for most people the language barrier was too difficult and made the semester very hard for them. If you are not good at math, this prof will not help much.', '[]', 'A-', 1, 0, 0, 5, 0, 0, 1583341444, 1788283356);
