INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTc4ODE5', 32978819, '0012762', '7648', 'COMM-1223', 'COMM1223', 2, 2, 2, 4, 'I thought that this class was gonna be a grade-booster (if anything), but instead, I ended with a C. This prof is a ridiculously tough grader, and then doesn''t provide any feedback on papers/presentations so you don''t even get the luxury to know what you did wrong.', '["Get ready to read","Beware of pop quizzes","Tough grader"]', 'C', 1, 1, 0, 5, 0, 0, 1584557510, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTczNjk5', 32973699, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 3, 'She''s the best prof I have ever had. She made the lectures very fun and thats not always easy considering that she is teaching organic chemistry. She makes everything so enjoyable. Would definitely recommend taking her class if you have the chance. She was also great at teaching lab and was very helpful if needed.', '["Accessible outside class","Inspirational","Hilarious"]', 'A-', 1, 0, 1, 0, 0, 0, 1584292118, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTg1Njk5', 32985699, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 3, 3, 3, 4, 'Avoid taking this class with him if possible. He is a good lecturer but makes the course hard for no reason. You can do well if you take very very detailed notes and attend all of his lectures while doing the reading before every class. I have never taken a class that so many students have ended up dropping. Our first midterm 75% of ppl failed.', '["Skip class? You won''t pass.","Test heavy","Lecture heavy"]', 'B-', 1, 1, 0, 5, 0, 0, 1584913375, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTg1NzMy', 32985732, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 2, 2, 2, 4, 'I wanted to like him as a prof but his tests were so hard that I couldn''t. His tests are memorization based and it is hard to study for due to the number of chapters on each test. The final was super hard and I had to leave pretty much every long answer blank. He will test you on things he never taught in class.', '["Accessible outside class","Get ready to read","Test heavy"]', NULL, 1, 1, 0, 5, 0, 0, 1584914425, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTg1Nzc5', 32985779, '0048856', NULL, 'CHEM-2510', 'CHEM2510', 5, 5, 5, 3, 'Teri is the BEST prof at Acadia by far!! Her teaching style is amazing and she really makes you want to learn and want to succeed, even in one of the hardest courses. Both her lectures and her labs are awesome. I would recommend taking a class with Teri if given the opportunity, you won''t regret it!', '["Accessible outside class","Amazing lectures","Caring"]', NULL, 1, 1, 1, 0, 0, 0, 1584915965, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTg1Nzk2', 32985796, '0018196', '7312', 'CHEM-2533', 'CHEM2533', 5, 5, 5, 5, 'Dr. Banks is the nicest and most caring prof!! His lectures can be hard to follow but he really does care about each and everyone of his students and wants everyone to do well. It''s a tough course to teach but he does an overall great job. Need to work very hard to do well as it is a very hard course!', '["Accessible outside class","Caring","Tough grader"]', NULL, 1, 1, 1, 0, 0, 0, 1584916417, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTg2NzEz', 32986713, '0018259', '10144', 'MUSI-1283', 'MUSI1283', 5, 5, 5, 3, 'Amazing teacher. Will go above and beyond to help you. Also has the cutest dog and always talks about her which is a bonus!', '["Gives good feedback","Accessible outside class","Amazing lectures"]', 'A-', 1, 1, 1, 5, 0, 0, 1584967346, 1788283358);
