INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTk3MTc5', 32997179, '0013980', NULL, 'ENG-1406', 'ENG1406', 5, 5, 5, 3, 'Best english prof at Acadia hands down. Makes it interesting, engages the class, so kind, and always willing to help.', '[]', NULL, 1, 1, 1, 0, 0, 0, 1585321837, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTk3MTg1', 32997185, '0027644', '10934', 'PHIL-2713', 'PHIL2713', 5, 5, 5, 3, 'Such a great prof. Sort of hard to follow at first, but then once you get used to the way he teaches its fine. He is an incredibly fair marker, and his tests are never unreasonable. You will cover a lot of interesting topics in his courses. He stays incredibly up to date on the material he is teaching which is awesome.', '[]', 'A+', 1, 0, 1, 0, 0, 0, 1585322114, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMyOTk3MTkw', 32997190, '0152004', NULL, 'SOCI-3263', 'SOCI3263', 5, 5, 5, 2, 'Sarah is such a great prof. She really cares about her students, and understands the stress that students are under. As long as you go to class and stay engaged, you will do well. She covers interesting topics, and is open to others'' opinions.', '[]', NULL, 1, 1, 1, 5, 0, 0, 1585322280, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA0NTA1', 33004505, '0169986', NULL, NULL, 'PSYC1113COG2143', 5, 5, 5, 2, 'Lametti is a great prof!! Although attendance isn''t mandatory for his classes, I attended all of them because he explains examples really well in class and his classes are not at all boring. His midterms and exams are fair, and his questions are based off of understanding material rather than memorizing definitions which I appreciated.', '["Accessible outside class","Clear grading criteria","Hilarious"]', 'A', 1, 0, 1, 0, 0, 0, 1585598521, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA0NTQx', 33004541, '0132876', '7772', 'COMP-4583', 'COMP4583', 5, 5, 5, 3, 'Dr. Lee is a great professor and is always working to make the class accessible and trying to innovate how we learn in a Computer Science degree. I would unequivocally recommend taking at least one class with him!', '["Accessible outside class","Clear grading criteria","Hilarious"]', 'A', 1, 1, 1, 0, 0, 0, 1585599088, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA3NDM0', 33007434, '0169988', '8448', 'ENGL-3073', 'ENGL3073', 4, 4, 4, 3, 'The most dedicated prof in the department! Dr. Pinder has a firm grasp on everything she teaches and is clearly passionate about it. She makes class interesting and fun, and she is easy to meet with and talk to about any concern you have. Highly recommend taking a class with her and getting to know her, go to her office hours!!', '["Accessible outside class","Get ready to read","Participation matters"]', 'A', 1, 1, 1, 5, 0, 0, 1585678132, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA5Mjgx', 33009281, '0015754', NULL, 'ENGL-1406', 'ENGL1406', 5, 5, 5, 3, 'Prof Slights is such a great choice for a first year English prof. Very approachable and truly cares for all of her students. Lots of reading and analyzing but nothing to difficult. interesting and engaging class.', '["Get ready to read","Caring","Tough grader"]', 'B', 1, 1, 1, 5, 0, 0, 1585705897, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA5MzIz', 33009323, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 4, 4, 4, 3, 'Dr. Hayes has been one of the funniest profs I''ve had so far. He tries to make his students stay awake even how boring the lecture is with his humor. Make sure you go to class and copy lectures because he does do skeleton notes sometimes. His midterms are very fair and straight forward.', '["Skip class? You won''t pass.","Graded by few things","Hilarious"]', NULL, 1, NULL, 1, 0, 0, 0, 1585706715, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDA5MzMw', 33009330, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 3, 3, 3, 4, 'She is a sweetheart. Tough tester though.', '["Skip class? You won''t pass.","Lecture heavy","Tough grader"]', NULL, 1, NULL, 1, 5, 0, 0, 1585706885, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDI1NTg=', 3302558, '0001916', NULL, 'BIO-3143', 'BIO3143', 5, 5, 5, 2, 'funny guy...not hard to look at either ;)', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1107176952, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDIwMzcx', 33020371, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 2, 2, 2, 4, 'marking scheme was entirely based on tests and the final. Studied a lot for the tests but only got in the 70-80% range on each when I usually get higher grades with less effort. Multiple choice questions were extremely misleading at times and short answer question had to have the exact wording he was looking for or no points were given.', '["Graded by few things","Test heavy","Tough grader"]', NULL, 0, NULL, 0, 0, 0, 0, 1586041199, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDIwNDM0', 33020434, '0037418', '9990', 'MATH-2243', 'MATH2243', 1, 1, 1, 3, 'Went to most lectures but quickly realized I''d have to teach the content to myself. His voice is difficult to listen to and he often corrects himself in his lectures, making it hard to follow along. If you get stuck taking a course with him definitely use MASH, as they can help you do well on the assignments and prep for midterms.', '["Lots of homework","Clear grading criteria"]', NULL, 1, 1, 0, 5, 1, 0, 1586042349, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDIzNjg0', 33023684, '0132876', '7793', 'COMP-5213', 'COMP5213', 5, 5, 5, 4, 'Great teacher and great humor.', '["Gives good feedback","Inspirational","Group projects"]', 'A', 1, 0, 1, 0, 0, 0, 1586149027, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzMDM2ODY4', 33036868, '0181048', '8903', 'GEOL-1033', 'GEOL1033', 5, 5, 5, 3, 'Morgan is a super fun and witty prof who cares about her students success. Although there is a lot of material covered throughout this course, Morgan managed to make each lecture as interesting as possible. Participation''s worth 25% and is calculated through TopHat, so if you are someone who usually doesn''t attend class, I wouldn''t recommend.', '["Participation matters","Lecture heavy","Caring"]', 'A-', 1, 1, 1, 0, 0, 0, 1586392222, 1788283351);
