INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzE1Nzk1', 33715795, '0139532', '11701', 'SOCI-2003', 'SOCI2003', 3, 3, 3, 4, 'very nice woman, but god is she AWFUL at explaining things. her powerpoints give awful definitions that have you sitting there trying to decode what they mean. you''ll need to find every definition off the internet and teach it to yourself. the concepts aren''t even that hard, she just cannot explain them in a way that make sense.', '["Lots of homework","Skip class? You won''t pass.","Clear grading criteria"]', 'B', 1, 1, 1, 0, 0, 0, 1603169011, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzE3OTcx', 33717971, '0016415', '9165', 'HIST-1003', 'HIST1003', 5, 5, 5, 4, 'Dr. Duke is by far the kindest professor I have ever met. I was in his HIST1003 class last year and enjoyed every moment. Despite not being in any of his classes, when I reached out to him while struggling he wrote me a 2 page email giving me advice and told me he knew I could do it.', '["Gives good feedback","Accessible outside class","Caring"]', 'A-', 1, NULL, 1, 5, 0, 0, 1603225553, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzEyOTI0', 33712924, '0024670', '9994', 'MATH-2313', 'MATH2313', 2, 2, 2, 5, 'Very uninspiring teacher. Boring, rote teaching style kind of like a talking textbook. Fails to explain why any of the math you''re leaning is relevant outside a math class. If you''re not a perfectionist, you won''t get good marks in her class. Very picky.', '["Lots of homework","Lecture heavy","Tough grader"]', 'Not sure yet', 1, 1, 0, 5, 0, 0, 1603122357, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzEzNzcw', 33713770, '0016779', NULL, NULL, '18THCENTURY', 4, 4, 4, 4, 'Prof Ahern really knows the material and his passion for it gets everyone in class engaged. You have to keep up with the readings but its worth it. He was always willing to help in office hours when I was working on an assignment.', '["Gives good feedback","Accessible outside class","Get ready to read"]', 'B+', 1, 1, 1, 5, 0, 0, 1603134928, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzI3ODA=', 3372780, '0016779', NULL, NULL, 'ENGL', 1, 1, 1, 3, 'Narrow minded viewpoint. Hates all literature except mainstream canonized stuff. Has a hate for the university overall. Very bitter about the strike last year, and takes pains to point this out to his class whenever he can.', '[]', NULL, 0, NULL, NULL, NULL, 3, 0, 1108756671, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzI3OTg=', 3372798, '0021658', '8533', 'ENGL-5113', 'ENGL5113', 3, 3, 3, 3, 'Very hot. He makes each lecture steamy and dreamy. No experience with marking yet, but his lectures are a bit student-driven. I''d like to see more imput from him. But he makes up for any short-comings with his steamy hotness.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1108757125, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzM1MTky', 33735192, '0040072', '8012', 'ECON-2613', 'ECON2613', 1, 1, 1, 4, 'Burc literally screwed his whole class over and failed a lot of us. he didn''t give any slack when your class got cancelled for corona. he doesn''t seem to realize that maybe its not the students fault if everyone is failing. he knows stats so well he doesn''t know how to explain it to people who have no idea what''s going on.', '["Lots of homework","Skip class? You won''t pass.","Tough grader"]', NULL, 1, 1, 0, 0, 0, 0, 1603733780, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzM2NjU4', 33736658, '0012762', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 3, 'Just genuinely the worst', '["Get ready to read","Participation matters","Skip class? You won''t pass."]', 'A-', 1, 1, 0, 5, 1, 0, 1603751109, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzQ2Nzg5', 33746789, '0102067', '11705', 'SOCI-2103', 'SOCI2103', 1, 1, 1, 4, 'Insane amount of tiny assignments that he doesnt really have a rubric for- more just his opinion. Lectures are super dull and he is as well.', '["Lots of homework","Get ready to read","So many papers"]', NULL, 1, 0, 0, 0, 0, 0, 1603943594, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzQ4OTY5', 33748969, '0132938', '8012', 'ECON-2613', 'ECON2613', 5, 5, 5, 4, 'Overall a great prof. Super smart which is great if you can keep up, otherwise you have to put in quite a bit of work. Always accessible and gives good feedback. Tests are hard but since it''s open laptop, if you prepare well enough they''re not bad at all.', '["Gives good feedback","Respected","Skip class? You won''t pass."]', 'A+', 1, 0, 1, 0, 0, 0, 1603998937, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzQ5MDc1', 33749075, '0026142', '7129', 'BUSI-2033', 'BUSI2033', 5, 5, 5, 2, 'Easily the best prof I''ve had at Acadia. Really cares about his students and makes class enjoyable. Tests aren''t easy but they''re not hard and he makes sure you''re adequately prepared for all of them. Very fair marker. Overall, absolutely no complaints, just a really great prof and person.', '["Gives good feedback","Inspirational","Caring"]', 'A+', 1, 0, 1, 0, 0, 0, 1604000161, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzU2MjQ4', 33756248, '0013468', NULL, 'MUSI-2263', 'MUSI2263', 5, 5, 5, 2, 'One of my favourite profs ever. Approachable. Easy going. Passionate about music. Friendly. HELPFUL no matter what. All around, a great dude', '["Gives good feedback","Respected","Hilarious"]', 'A', 1, 1, 1, 0, 0, 0, 1604268640, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzU2MjQy', 33756242, '0036828', '7838', 'CREL-2413', 'CREL2413', 2, 2, 2, 4, 'I had to withdraw from one of Donnas classes because the projects were too hard for me. The lack of course material on testing is what got me Cs until I withdrew. I didnt know how to study. Its for an certain type of learner. Donna will help you get an A, but you have to have passion for W &amp; Gender studies (in my opinion) to grasp the concepts', '[]', 'Drop/Withdrawal', 1, 1, 0, 0, 0, 1, 1604268534, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzU2MjYy', 33756262, '0002460', NULL, NULL, 'VOICE1', 3, 3, 3, 4, 'Heres the thing: If you want to do well, you need to get on her personal good side. You need to know abt her life, and go out of your way to be her friend. She will go out of her way for you if you do the same. If not, she is harder to get along with. Just my observation. She cares a lot, so reciprocate it', '["Gives good feedback","Amazing lectures","Tough grader"]', 'Rather not say', 0, 1, 1, 0, 0, 0, 1604268833, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzY3Mzk5', 33767399, '0031124', NULL, NULL, 'BUSI2743A1', 1, 1, 1, 5, 'This semester everything was strictly online. He posted no notes or lectures to the school''s website page. I do believe that this class could''ve been very interesting, but he grades very hard for no reason. He seems to scream and shout not to write answers word for word, but this is the only way you will succeed in this class. Awful!', '["Get ready to read","So many papers","Tough grader"]', NULL, 1, NULL, 0, 5, 0, 0, 1604460212, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzgxOTI=', 3378192, '0031124', NULL, NULL, 'OT', 1, 1, 1, 4, 'Should have paid attention to his SMU ratings. Brutal. Brutal. Brutal. He is unclear on his expectations and is extremely subjective in his marking. I think the only positive reviews come from his wife and himself and I have not spoken to anybody who likes this guy as a prof. Avoid if possible.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1108981195, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzkwMDc0', 33790074, '0016655', '9185', 'HIST-1413', 'HIST1413', 1, 1, 1, 4, 'Terrible. what else can I say? It was a virtual course so it wasn''t bound to be as good as the real thing, but come on. He didn''t do any lectures on his uploaded slides. Plus in the little foot note section he has little notes to himself on how he should explain a certain point but it''ll leave the student clueless on what it means,Avoid this class!', '["Lots of homework","Get ready to read"]', 'Not sure yet', 1, 0, 0, 0, 0, 1, 1604964874, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzNzkwMjg1', 33790285, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'She actually isn''t my main professor she just helps out in the course but she makes the class much more easy to understand. She is very organized and uploads most of the work for this course. She puts a great deal of effort into lecture slides, tests, practice questions, etc. If you end up with one of her courses then you should be happy about it.', '["Gives good feedback","Accessible outside class","Clear grading criteria"]', 'Not sure yet', 1, 1, 1, 5, 0, 0, 1604967084, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzODA0Njc0', 33804674, '0003429', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 3, 'She might be one of the most caring professors at this school. She''s incredibly polite, organized, smart, and she actually cares about what you have to say. Her lectures are well presented and she makes understanding harder concepts extremely easy. despite the fact that everything was virtual this year; she made everyone feel welcome at the school.', '["Gives good feedback","Accessible outside class","Caring"]', 'Not sure yet', 1, 1, 1, 5, 0, 0, 1605154197, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzODQyNzcw', 33842770, '0034433', '7134', 'BUSI-2223', 'BUSI2223', 1, 1, 1, 5, 'Literally gave up teaching 3 weeks into the course. Made the course self directed, then the whole class failed the first mid-term. Sucks at teaching. Slides were not helpful. Quite a hard course in the first place. Hate to say it, but him and this course was one of the reasons why I transferred.', '["Lots of homework","Skip class? You won''t pass.","Test heavy"]', 'F', 1, 1, 0, 5, 1, 0, 1605730221, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzODY4NzU5', 33868759, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'Vague assignment descriptions, hard marking', '["Participation matters","Skip class? You won''t pass.","Tough grader"]', NULL, 1, 1, 0, 5, 1, 0, 1606067616, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzOTY0NzIw', 33964720, '0016655', '9270', 'HIST-2563', 'HIST2563', 1, 1, 1, 5, 'Worst class ever. completely virtual but absolutely zero teaching. he just uploads 100 readings a week and maybe 5 hours of videos/podcasts, literally impossible to keep up with. class is intended for non-majors but good marks are completely unattainable. w o r s t prof ive had during ''hybrid'' system.', '["Get ready to read","Tough grader"]', NULL, 1, 0, 0, 0, 0, 1, 1607276230, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzOTc5NDE1', 33979415, '0036828', '7843', 'CREL-3123', 'CREL3123', 5, 5, 5, 4, 'You will never find a more dedicated and caring prof. Gives detailed feedback and encourages you to rewrite for a better grade. The Writing Life course is the absolute best course you can take if you want to be a better writer. Don''t be scared away by the &quot;religion&quot; part, Donna is wonderfully open to interpretations of worldview and belief.', '["Gives good feedback","Accessible outside class","Participation matters"]', 'A', 1, 1, 1, 5, 0, 0, 1607395578, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzOTc5NTA4', 33979508, '0036828', '7843', 'CREL-3123', 'CREL3123', 5, 5, 5, 3, 'I know many amazing profs, and I can honestly say that Donna is the very best. EVERYBODY in our class loves her and she cares so deeply about her students. She encourages and empowers her students and will do anything for them. She is one of the most amazing people I have ever met. I love her. EVERYBODY loves her, and that is very clear.', '["Respected","Hilarious","Caring"]', 'A+', 1, 1, 1, 0, 1, 0, 1607395927, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzOTg1MjE4', 33985218, '0036828', '7841', 'CREL-2533', 'CREL2533', 4, 4, 4, 3, 'Donna is clear with her expectations and super approachable, she wants to see you do well. Met with her during office hours several times and all meetings were very helpful.', '["Gives good feedback","Accessible outside class","Get ready to read"]', NULL, 1, 1, 1, 5, 0, 0, 1607447229, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTMzOTg3MzQ1', 33987345, '0011703', '6690', 'ART-2053', 'ART2053', 5, 5, 5, 3, 'Judith is a amazing teacher, and very talented. She expects a lot of you, and you definitely have a step up if you have background knowledge in art. Put time and effort in and youll do great.', '["Lots of homework","Skip class? You won''t pass.","Inspirational"]', 'A+', 1, 1, 1, 5, 0, 0, 1607454621, 1788283361);
