INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDAyMDYw', 40002060, '0021211', NULL, NULL, 'PHILENVR', 5, 5, 5, 3, 'Dr. Abela is a great prof, but definitely not suited to everyone. He lectures fully off of the top of his head/his notes and does not use powerpoints or post any notes - if you miss a class, you better get notes from someone else. He is very kind and accessible outside of class. Smartest man I''ve ever met. Hard but fair marker, gives good feedback.', '["Tough grader","Get ready to read","Gives good feedback"]', 'B', 1, 0, 1, 3, 0, 0, 1732202824, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDAyMDgy', 40002082, '0016977', '13373', 'MUSI-1823', 'MUSI-1823', 5, 5, 5, 2, 'I don''t think I have ever met a nicer person. Dr. Keech very clearly loves what she does and will do absolutely everything in her power to help you succeed. Go to her office hours - not only is it going to be immensely helpful for the keyboard checks, but she''s also just very nice to chat with.', '["Participation matters","Gives good feedback","Caring"]', 'Not sure yet', 1, 1, 1, 3, 1, 0, 1732202910, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDEwODQ3', 40010847, '0308310', '11107', 'POLS-3063', 'POLS-3063', 5, 5, 5, 2, 'Impactful course material and the readings/discussions are available for you to participate in at the level you''re comfortable with. 
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDEyNzg0', 40012784, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 5, 5, 5, 1, 'I enjoy his lectures, never skip one, i feel related and connected to his perspectives and personality. He''s funny and the way he speaks about his ideas is really like sharing his thoughts.', '["Participation matters","Amazing lectures ","Inspirational"]', 'A', 1, 0, 1, NULL, 0, 0, 1732286247, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDI1ODA2', 40025806, '0025724', '9695', 'KINE-1243', 'KINE1243', 2, 2, 2, 4, 'Janna is a funny prof, but seriously so disorganized and unprofessional. If she shows anything in class, be prepared to see it on the test. Janna does not want you to fail, but she does not make it easy to pass. Talk to her, engage in the class, you will do fine.', '["Tough grader","Get ready to read","Hilarious"]', 'A+', 1, 0, NULL, NULL, 0, 0, 1732502785, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDI1ODY0', 40025864, '0021421', '9764', 'KINE-2413', 'KINE2413', 5, 5, 5, 2, 'Enjoy it while you can, dude is seriously great, textbook costs waaaaay too much. Have fun, talk to the guy, and just try to learn the material. It is only hard if you make it hard.... Don''t wait til last minute to do labs :)', '["Get ready to read","Amazing lectures ","Accessible outside class"]', 'A', 1, 0, 1, 3, 0, 0, 1732503316, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDI2NTk4', 40026598, '0003993', '9969', 'MATH-1613', 'MATH1613', 1, 1, 1, 5, 'All of his assignments are submitted in person, If you show up to class a minute late he will not take your assignment and you''ll receive a 0. He locks the door after 5 minutes which caused many students to miss out on lectures. I can recall a time where another student showed up for a midterm 2 minutes after the class began, and could not take it.', '["Tough grader","Get ready to read","Lots of homework"]', 'D', 1, 0, NULL, 3, 1, 1, 1732513299, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDI5MjQ3', 40029247, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 5, 5, 5, 3, 'I was nervous heading into my psych lab based off the reviews &#8212; I will definitely agree that Dr. Bleile is a tough grader, but honestly it was not as bad as I thought. She is SO kind and understanding, and willing to help you if you ask. Overall if you read the rubric for the labs, you are fine. Deductions on assignments are more due to format.', '["Tough grader","Caring","Accessible outside class"]', 'B+', 1, 0, 1, NULL, 0, 0, 1732557938, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDI5Mjg2', 40029286, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 2, 2, 2, 5, 'Lecture slides are super outdated with little information so you seriously have to listen to what she says. Felt like 80% of information in lectures were verbal. I dropped the course due to it being difficult for me. The quiz I did was practically all short answer so you really have to remember material which was very heavy. Wouldn''t take again.', '["Lecture heavy"]', NULL, 1, 0, NULL, 3, 0, 0, 1732558195, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDIzOTA2', 40023906, '0300636', '12104', 'WGST-1413', 'WGST1413', 3, 3, 3, 3, 'Nice prof, class was a little dull if you are already familiar with feminism', '["Tough grader","Participation matters","Group projects"]', NULL, 1, 1, 1, NULL, 0, 0, 1732478687, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDIzOTY0', 40023964, '0029615', '11698', 'SOCI-1033', 'SOCI1033', 5, 5, 5, 3, 'Super fun and engaging prof, discussion based lectures. You can either participate in class, or submit an alternative written assignment each week, but you do have to do something. Also you need to read the book, there''s no avoiding that - but it''s short and easy to understand. I highly recommend this course to anyone, you will learn a lot!', '["Get ready to read","Participation matters","Hilarious"]', NULL, 1, 0, 1, 3, 0, 0, 1732479461, 1788283347);
