INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDk1NTU1', 40095555, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 4, 'She is an amazing lecturer. She''s hilarious and she uses great analogies to help you remember and understand the material. Completely worth going to her lecture. 10/10 Prof.', '["Amazing lectures ","Hilarious","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1733322410, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMDk3MjMw', 40097230, '0102067', '11716', 'SOCI-2233', 'SOCI2233', 2, 2, 2, 3, 'Lots of assigned readings that are long, and the tests are based off of them. Talks so much about stuff that doesn''t matter spent the whole course talking about one topic which we never received an actual definition for. Make sure you''re good with ASA citation style as that''s all he accepts.', '["Get ready to read","Group projects"]', 'Not sure yet', 1, 1, NULL, NULL, 0, 0, 1733329262, 1788283346);
