INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjI2NTMz', 40226533, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 4, 'Excellent professor. Tough course but his lectures are very entertaining... He makes you want to learn! Great guy, hilarious, and witty.', '["Inspirational","Hilarious","Respected"]', 'Rather not say', 1, 0, 1, NULL, 0, 0, 1733944715, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjI4NzQ5', 40228749, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 1, 1, 1, 5, 'Horrible professor, draws stick figures on the board instead of giving notes or PowerPoints. While the tests are open book he words the questions difficult on purpose.', '["Tough grader","Get ready to read","Participation matters"]', 'C+', 1, 1, NULL, 3, 0, 0, 1733948775, 1788283355);
