INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjIyNDQx', 40222441, '0018503', NULL, NULL, '1533X1', 1, 1, 1, 4, 'Hates anyone who''s not in CODE or ESST. Awful. Would never take a course with him again, brought down my overall gpa by so much for a first year ESST course.', '["Tough grader","Participation matters","Lots of homework"]', 'B-', 0, 1, NULL, NULL, 0, 0, 1733936477, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjM2MTY0', 40236164, '0048856', NULL, 'CHEM-2510', 'CHEM2510', 5, 5, 5, 1, 'Teri is by far the best professor I have had at Acadia so far. Although I was unable to be in her lectures I would not have gotten such a good grade if it wasn''t for her videos posted on the CHEM 2513 page, her tutorials and her labs. She explains everything so well, she is always happy to help and is hilarious. Definitely take a class with her!', '["Amazing lectures ","Hilarious","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1733963100, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjU1Mjk5', 40255299, '0015927', '9783', 'KINE-3013', 'KINE3013', 1, 1, 1, 3, 'The final exam was horrible! His slides are pictures and the stats on his slides are not backed up whatsoever by peer reviewed research. Him and his lab instructor need to retire asap as they both don''t care about the material anymore and they recycle whatever papers or slides they gave out on previous years. Overall I genuinely learned nothing&#8230;', '["Tough grader"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1734033162, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjU3ODcw', 40257870, '0001612', NULL, NULL, '2050L', 5, 5, 5, 3, 'Helene is a great lab instructor. She knows a lot about microbiology and can answer any questions you have. Her microbiology lab is easy and interesting. Labs are every 2 weeks but a lab report is due each lab which is the only downside. Great lab professor!!!', '["Clear grading criteria","Gives good feedback","Accessible outside class"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1734037950, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjU4MjYy', 40258262, '0015407', NULL, NULL, 'CREATWRITING', 4, 4, 4, 3, 'Dr. Campbell is such an amazing creative writing prof. I will admit her lectures are slightly boring, however she is such a sweet lady and gives amazing feedback. I definitely feel like I''ve grown as a writer. Her creative writing class is also a great elective as it typically does not require external reading and there are no tests/exams.', '["Participation matters","Clear grading criteria","Gives good feedback"]', 'A-', 1, 1, 1, NULL, 0, 0, 1734038695, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjU4NDM0', 40258434, '0263737', '12112', 'WGST-3503', 'WGST3503', 3, 3, 3, 4, 'This course has more writing assignments than my upper year English classes and has a lot of external readings, that being said, Dr. Cooper gives amazing lectures, is so smart, and is more than willing to provide extensions. Attention to detail when writing is a must, however her class truly made me a better writer and there are no tests/exams!', '["Tough grader","Participation matters"]', 'B+', 0, 1, 1, NULL, 0, 0, 1734039037, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjU4NzMx', 40258731, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 5, 5, 5, 3, 'Stephanie is one of the best profs I''ve had at Acadia so far. Her lectures are very interesting and engaging. She is a very fair marker. She sometimes gives you some hints during class on what will be on exam, so I recommend being in class regularly. If you go to class you are way more likely to do great on the exams. I recommend taking her class', '["Participation matters","Amazing lectures ","Clear grading criteria"]', 'A', 1, 0, 1, NULL, 0, 0, 1738011355, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjYwMzIw', 40260320, '0028039', '6858', 'BIOL-2053', 'BIOL2053', 5, 5, 5, 3, 'Todd is a very good microbio prof. He allows you to use a cheat sheet during the tests, where the questions aren''t overly hard. Todd''s lectures are very engaging and interesting. He relates a lot of the content to real life situations which is very helpful. I recommend taking his microbiology class even if it''s not required!', '["Amazing lectures ","Clear grading criteria","Hilarious"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1734042997, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjYwNTUy', 40260552, '0034413', '7292', 'CHEM-1053', 'CHEM1053', 5, 5, 5, 2, 'Professor Lukeman was a great prof for Chem and our world. The lectures were very engaging and interesting. He gives you lots of opportunities to get participation marks and keep a good grade in the class. I recommend taking this class as a gpa booster!', '["EXTRA CREDIT","Group projects","Hilarious"]', 'A', 1, 0, 1, NULL, 0, 0, 1738011303, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjc2NDQ2', 40276446, '0300636', '12104', 'WGST-1413', 'WGST1413', 1, 1, 1, 3, 'Shes an extremely tough grader. Gives little to no explanation on why you got the grade. First assignment was a ''gender autobiography'' where you express your experiences with gender. This was probably one of the most humbling grades I''ve gotten back, and just the fact that it was based on my own experiences is a little sad. Try to avoid this one', '["Tough grader","Get ready to read","Participation matters"]', 'B+', 1, 1, NULL, NULL, 0, 0, 1734109869, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjczNTc3', 40273577, '0000673', '7032', 'BIOL-4423', 'BIOL4423', 5, 5, 5, 4, 'Very caring and personable professor. Students should be so lucky to have Dr Boates to teach them', '["Participation matters","Group projects","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1734094111, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjg0NTU0', 40284554, '0306410', '11784', 'SOCI-3403', 'SOCI3403', 5, 5, 5, 3, 'Emily Lockhart is an understanding and supportive prof who will give you a good grade if you simply put passion and effort into the work you''re creating. She is silly too', '["Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1734131113, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjg0NTc3', 40284577, '0306161', '6856', 'BIOL-2043', 'BIOL2043', 2, 2, 2, 1, 'The material is new to most students, and clearly to Zoe too. The lectures were so bad - 80% of the class stopped going. She struggles just reading the slides verbatim. The lab was easy (Thanks to Jen) and so were the tests. She''s a poor communicator, so don''t email her a question you want an actual answer to. You''re better off teaching yourself :(', '[]', 'A+', 1, 0, NULL, NULL, 0, 0, 1734131190, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjg0NTkx', 40284591, '0302829', '11705', 'SOCI-2103', 'SOCI-2103', 4, 4, 4, 3, 'Pretty basic lectures, a little hard to understand because of his speedy talk and accent, and he does not give feedback on assignments. Other than these things, Rabindra is an excellent guy and a good professor who cares about his students and just wants to see quality work and effort', '["Participation matters","Caring","Lecture heavy"]', 'B+', 1, 1, 1, 3, 0, 0, 1734131218, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjg0NzI3', 40284727, '0263737', '12104', 'WGST-1413', 'WGST1413', 4, 4, 4, 4, 'Dr. Cooper is a fantastic professor who will go a mile for you if you attend classes and engage with the material. Her lectures are well-done and easy to understand, she is always ready to answer questions, and she cares about students. She even provides all needed textbook chapters free of charge because the book is $300 so slay!', '["Get ready to read","Participation matters","Clear grading criteria"]', 'A', 1, 1, 1, NULL, 1, 0, 1734131560, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjg0ODMz', 40284833, '0043958', '9743', 'KINE-1993', 'KINE1993', 5, 5, 5, 3, 'Sarah was a great prof, her lectures were fairly engaging and she''s passionate about what she''s teaching. The group project could''ve been bad, I may have lucked out with my group. My only real complaint is the fitness Friday part- I didn''t feel like exercising in front of other students in a lecture room was necessary, just stressful.', '["Group projects","Gives good feedback","Accessible outside class"]', 'A', 1, 1, 1, NULL, 0, 0, 1734131835, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjgwOTUx', 40280951, '0139613', NULL, 'POLS-2006', 'POLS2006', 5, 5, 5, 2, 'Amazing prof! Explained everything clearly, was very open to questions, and genuinely learned a lot. Group projects were sometimes annoying and the exam was a lot of hand written questions but those are the only downsides to her class. Everything else about the class was great!', '["Group projects","Amazing lectures ","Clear grading criteria"]', 'A-', 1, 0, 1, 3, 0, 0, 1734121850, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjgzNzY1', 40283765, '0012981', NULL, 'ENG-1413', 'ENG1413', 5, 5, 5, 2, 'Lisa is a wonderful, helpful lady who will appreciate you more if you participate and always made everyone feel heard. Her English class was very enjoyable', '["Get ready to read","Participation matters","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1734129007, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMjk3NTEy', 40297512, '0307318', NULL, 'CLAS-1113', 'CLAS1113', 5, 5, 5, 1, 'Incredible professor! I''ve taken several courses with her. She explains complex topics clearly, bringing a spark of excitement & inspiration to any topic. She''s genuinely caring, & will work through any issue with you for a solution, no questions asked. There are so many more wonderful things to say, but alas, the character count. Highly recommend!', '["Inspirational","Caring","Accessible outside class"]', 'A+', 1, 1, 1, 3, 1, 0, 1734204690, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzE0ODM0', 40314834, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 1, 1, 1, 5, 'Horrible prof, great guy. Very last minute with everything, and isn''t supportive towards students whatsoever. Stay far away from this guy.', '["Tough grader","Test heavy","Graded by few things"]', 'Drop/Withdrawal', 1, 1, NULL, NULL, 0, 0, 1734312466, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzE1OQ==', 403159, '0015927', NULL, 'KINE-3043', 'KINE3043', 4.5, 5, 4, 4, 'Helped me through really rough times', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1039230069, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzE3NDc2', 40317476, '0040908', '13370', 'MATH-1253', 'MATH1253', 5, 5, 5, 1, 'Danielle is probably the sweetest human being you could ever meet. She cares so much for her students and really tries her best to accommodate for any issues in the class. She made stats incredibly easy to understand, and her lectures were always at a good pace. Definitely switch into her course if possible! You won''t regret it!', '["Gives good feedback","Caring","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1734321970, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzEzNjcy', 40313672, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 1, 1, 1, 5, 'Nice man but cannot teach. PowerPoint slides do not make any sense and its so much information you dont know whats important and whats not. Midterms are very hard and the questions are worded difficult on purpose.', '["Tough grader","Get ready to read","Lots of homework"]', 'C+', 1, 0, NULL, NULL, 0, 0, 1734307652, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzI0NjY3', 40324667, '0024670', '9994', 'MATH-2313', 'MATH2313', 1, 1, 1, 5, 'Dr. Clarke is a great person and is very open to questions. However, her tests are incredibly hard and proof based. It doesn''t feel like I was set up for success and I often felt extremely discouraged. Linear algebra should not be as complex as she makes it.', '[]', 'Rather not say', 0, 1, NULL, NULL, 0, 0, 1734371978, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzIyNTYw', 40322560, '0048856', NULL, NULL, '2513', 5, 5, 5, 2, 'Teri is the best prof I''ve ever had. She cares so much about her students, she''s always positive and makes a hard course, like organic chemistry, genuinely interesting. She engages her students super well. I would recommend any course with her.', '["Amazing lectures ","Hilarious"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1734364804, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzIyNjA2', 40322606, '0048856', NULL, NULL, '2513', 5, 5, 5, 3, 'Terri was the best prof ever, she cares so much about her students and helping them learn the content. Organic chem is a very hard class but she made it interesting and explained concepts very well. Her teaching style is great.', '["Amazing lectures ","Hilarious","Respected"]', 'Rather not say', 1, 1, 1, NULL, 0, 0, 1734365031, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzIyNjMw', 40322630, '0048856', NULL, NULL, '2513', 5, 5, 5, 3, 'Teri always pulls through with the best explanations, making the material less daunting and actually interesting. Her tutorials are literally so helpful, wouldn''t have passed without her extra help! She goes above and beyond, best chem teacher I''ve had!', '["EXTRA CREDIT","Amazing lectures ","Gives good feedback"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1734365121, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzMxOTI2', 40331926, '0040072', '8012', 'ECON-2613', 'ECON2613', 5, 5, 5, 4, 'This prof is the best thing to happen to Acadia University. He keeps you interested the whole lecture and is very understanding. GO TO CLASS. You understand so much better in class and if he knows youre there and trying hes more willing to help.Go to his "Labs" on friday afternoons they help so much. Burc was my fave prof by for.', '["Hilarious","Caring","Accessible outside class"]', 'B+', 1, 0, 1, NULL, 0, 0, 1734390448, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzMzNzY3', 40333767, '0181064', NULL, 'BIOL-3633', 'BIOL3633', 1, 1, 1, 5, 'Bad at responding to emails, you have to email twice to get her to answer. Wouldn''t give the bare minimum as to give practice questions when requested, claiming I can look to past quizzes. Wouldn''t tell me my grade in percentage when I asked 4 times. This class may have been educational with anyone else. She is very smart just not a good teacher.', '["Tough grader","Lecture heavy","Test heavy"]', 'D', 1, 0, NULL, NULL, 0, 0, 1734395405, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzMzODI0', 40333824, '0011703', '6685', 'ART-2013', 'ART2013', 5, 5, 5, 4, 'Judith is a tough grader, and be prepared to put in a lot of hours working on the final projects, I spent over 50 hours on the last project. All of the fine art courses at Acadia require you to spend approximately 150 to 200 dollars on supplies for the class, so be prepared for that. Judith is really sweet and appreciates when you put effort in.', '["Tough grader","Lots of homework","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1734395565, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ0MzIz', 40344323, '0039663', '7325', 'CHEM-3103', 'chem3103', 1, 1, 1, 5, 'Great guy, horrible prof. Spends time doing useless derivations. If you ask for help he will laugh at you. Available for office hours but I would never go because he would just laugh at you for not knowing how to do it. His tests are online and he doesn''t check any of your work. However, he was great for General Chemistry in first year.', '[]', 'A', 1, 0, NULL, NULL, 0, 0, 1734450795, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ0Mzkw', 40344390, '0034413', NULL, NULL, '4733', 5, 5, 5, 3, 'The world''s best prof. Cares about his students success, very clear expectations on midterms and exams, and very engaging lectures. If you get the chance to rake a Lukeman course, do it!', '["Amazing lectures ","Clear grading criteria","Respected"]', 'A+', 1, 1, 1, NULL, 0, 0, 1734451063, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ0Njc2', 40344676, '0041312', NULL, 'ENG-1413', 'ENG1413', 2, 2, 2, 5, 'Expects too much from a first year English course. Hard to please her when writing an essay especially when it''s a level 1 course.', '["Tough grader","Participation matters"]', 'B', 1, 1, NULL, 3, 0, 0, 1734452361, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ0Njk3', 40344697, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 4, 4, 4, 2, 'Professor Sarhadi was available to answer questions during office hours and after class time. He accorded reasonable time to go over each chapter and provided many examples.', '["Gives good feedback","Graded by few things","Accessible outside class"]', 'A-', 1, 0, 1, 3, 0, 0, 1734452412, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5MzQ4', 40349348, '0021658', NULL, 'ENG-1413', 'ENG1413', 1, 1, 1, 5, 'Picks favourites in his class. Attendance mandatory even though he only talks about books and his own opinion on them. Grades based off of his opinion and not open to anyone else. Expects thesis level papers.', '[]', 'Not sure yet', 1, 1, NULL, NULL, 0, 0, 1734468058, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5Mzk3', 40349397, '0181064', '6845', 'BIOL-1853', 'BIOL-1853', 2, 2, 2, 3, 'Lectures are hard to understand. The tests are all multiple choice. Although, she does make her questions pretty hard to actually get the correct answer. She makes her questions more complicated than what we actually learned. Be prepared to teach yourself a lot of the material and make sure you memorize everything that is in red on her slideshows.', '["Caring","Lecture heavy","Accessible outside class"]', 'B-', 1, 0, 1, 3, 0, 0, 1734468240, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5Mzkx', 40349391, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 1, 1, 1, 5, 'All this class is based off is 2 midterms and a final. He does not care about whether his students do good. Did not give any study outline. His lectures were sidetracked and only focused on theories which he made through his own opinion. Midterm and final were way too complicated. He did not teach half of what was on it and did not teach well.', '["Tough grader"]', 'Not sure yet', 1, NULL, NULL, NULL, 1, 0, 1734468202, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5NDc1', 40349475, '0043258', '9701', 'KINE-1413', 'KINE1413', 5, 5, 5, 3, 'Scott was amazing. He did everything in his power to make sure everyone got the best grade possible. He weighed everyone''s mark differently in a way that could help students individually. He is super considerate and very easy to get a hold of outside the classroom. Anatomy was a hard class but he makes going to class worth it.', '["Participation matters","Caring","Accessible outside class"]', 'C+', 1, 1, 1, 3, 0, 0, 1734468477, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5NDg2', 40349486, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 3, 3, 3, 4, 'She is very kind and open to her students. Provides lots of feedback however she grades super tough. 3 papers in this class and she didn''t mark any of them before the next paper was due. So there was no way of knowing what to fix for the next paper without feedback from the last.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1734468497, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQ5NTky', 40349592, '0034933', '7646', 'COMM-1013', 'COMM1013', 2, 2, 2, 5, 'I took this class with Holt so I would have Friday''s free. DONT DO IT. He''s a nice guy but awful at grading papers. No feedback that is helpful, and all the presentations seem like he''s just trying to embarrass you and make you nervous. The tests are just definitions in the glossary of his own book, just an fyi. Impossible to do well on his tests.', '["Tough grader","So many papers","Test heavy"]', 'C', 1, 0, NULL, 3, 1, 0, 1734468857, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzQwMjA3', 40340207, '0133595', NULL, 'BIO-3553', 'BIO3553', 5, 5, 5, 4, 'Melanie is an excellent professor, the difficulty of the courses is a topics is a given but she prepares online practice quizzes, in class quizzes, good lab complementary exercises and is very accessible.
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzU5NzE=', 4035971, '0018154', NULL, NULL, 'RESEARCHMETHOD', 4.5, 5, 4, 3, 'Very, very helpful - go to her with assignments! She''ll practically do your analysis for you. She lost some brownie points for being less understanding than expected when my grandmother died, but we finished the project in time anyway, so perhaps she knew best.. or perhaps it was the all-nighters. Who knows.', '[]', NULL, 0, NULL, NULL, NULL, 1, 0, 1119860717, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzU5OTY=', 4035996, '0018366', NULL, NULL, '2006', 4, 4, 4, 4, 'Hated this woman/class at first; by year end it was the one I was saddest to see end. Although intimidating early on, Quema really does know her stuff. I''ll think I understnad a text, she''ll cover what I get in 5 minutes then continue on in more depth than I thought possible for another hour. Exhausting, but I''ve never felt more like I earned my A.', '[]', NULL, 0, NULL, NULL, NULL, 1, 0, 1119861467, 1788283341);
