INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzY0MTc1', 40364175, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 2, 'Amazing prof! She does in class demonstrations that the other first year chem profs do not. Lots of chances are given to boost your grade for first year. 10/10 would recommend.', '["EXTRA CREDIT","Caring"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1734540952, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzY0Mzcx', 40364371, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 3, 3, 3, 2, 'Though true that he has blank slides, taking notes of what he says fills in the gaps well. Nice guy with some concerning examples used in class. Assessments weren''t too bad at all.', '["Beware of pop quizzes"]', 'A+', 1, 0, 1, 3, 0, 0, 1734541690, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzYwOTI=', 4036092, '0000957', NULL, NULL, 'IDST', 5, 5, 5, 4, 'Wow. Never have I attended a class in which the students were more interested. Every class is fun and you look forward to them.', '[]', NULL, 0, NULL, NULL, NULL, 1, 0, 1119864277, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzc4Nzk4', 40378798, '0037406', '11355', 'PSYC-3053', 'PSYC3053', 5, 5, 5, 2, 'Dr. Newman is an excellent prof, but it is important to know that her lectures include a lot of content. She speaks fast but always provides great examples to make sure her lecture content is understandable. She is also a generous marker and provides great feedback and outlines for assignments/exams.', '["Gives good feedback","Caring","Lecture heavy"]', 'A', 1, 1, 1, NULL, 0, 0, 1734590248, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgwODg5', 40380889, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 1, 1, 1, 3, 'okay at teaching the material but she induces a severely frantic testing environment that visibly stresses people out before you write your test. needs to find some calm.', '[]', NULL, 1, 0, NULL, 3, 0, 0, 1734619412, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgxMTEx', 40381111, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 5, 5, 5, 3, 'I found Professor Sarhadi''s lectures to be very clear and well organised. While the material was challenging, he was able to break it down into understandable steps, and was available to explain when a student got stuck on anything.', '["Gives good feedback","Accessible outside class"]', 'A-', 1, 0, 1, 3, 0, 0, 1734621210, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyNTUy', 40382552, '0041312', '8394', 'ENGL-1423', 'ENGL1423', 4, 4, 4, 4, 'Michelle was a nice prof. The amount of readings are reasonable for an English course. Her grading criteria can be very specific, so ensure you meet with her if you do not understand any concepts. Overall a good professor.', '["Tough grader","Get ready to read","Participation matters"]', 'A', 1, 0, 1, 3, 0, 0, 1734628795, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyNjA2', 40382606, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 3, 'It''s unfortunate the content is so boring because Joe is a funny and engaging lecturer. however, he did an awful job at preparing students for the content on the midterms/final. students repeatedly asked for practice questions and Joe would respond he was too busy. the only content you have to prep you for the stats you will do are PowerPoints.', '["Lecture heavy","Test heavy","Graded by few things"]', 'B-', 1, 0, NULL, NULL, 1, 0, 1734629047, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyNzE3', 40382717, '0169986', '11339', 'PSYC-2143', 'PSYC2143', 5, 5, 5, 3, 'Dan has a unique teaching/testing method. Read the MCQ carefully. the short answer questions he gives you in advance and will go over the answers in class. You are also allowed a 1 page cheat sheet. Dan has MCQ at the end of every lecture to help the learning process in his students. Overall, a very fair professor. Hope to take more of his classes.', '["Amazing lectures ","Online Savvy"]', 'A+', 1, 0, 1, 3, 0, 0, 1734629487, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyNzcy', 40382772, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 2, 2, 2, 4, 'I''m a deans list student; this class was by far my worst at Acadia. The lecture slides were old and lacking I''d say 60% of the info needed. Quizzes are in class and short answer. Questions are on the smallest details. Midterms are somewhat better but not much. If you want to be successful attend every class, exchange notes, and study daily.', '["Tough grader","Lecture heavy","Test heavy"]', 'C-', 1, 1, NULL, 3, 0, 0, 1734629703, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyODA3', 40382807, '0302829', '11705', 'SOCI-2103', 'SOCI-2103', 2, 2, 2, 1, 'I am bad with accents so understanding was difficult. Lectures are a carbon copy from the textbook. Tests are all MCQ and very fair. No final exam but a final paper. Overall a nice professor, I just feel that the class did not add any value to my understanding of the subject matter, the textbook did.', '["Get ready to read","Group projects","Lecture heavy"]', 'A', 1, 1, NULL, 3, 1, 0, 1734629872, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzgyODQ5', 40382849, '0263737', '12104', 'WGST-1413', 'WGST1413', 3, 3, 3, 4, 'Attend every class you can, a lot of the information needed was spoken. I was not a fan of the final exam. I think it would have been done better as a take home, open-book final. It is inefficient to memorize all of the course content, which is what you need to do to be prepared for the final. 50% of your grade is from weekly MCQ quizzes on ACORN.', '["Tough grader","Participation matters"]', 'B+', 1, 1, NULL, 3, 0, 0, 1734630055, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzk0NTA1', 40394505, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 1, 'Iain is a gem protect this man at all costs, hands down one of the best professors, if you can take a course with him do it!!!', '["Amazing lectures ","Gives good feedback","Accessible outside class"]', 'A', 1, 0, 1, NULL, 0, 0, 1734678503, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzkxMTIy', 40391122, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 4, 'Iian is the best professor I''ve had in my first semester. Such a good teacher and really accessible outside of class. If you can take him instead of Grieve you 100% should. Assignments are quite hard but tests are way easier, the final was tough though.', '["Participation matters","Inspirational","Caring"]', 'B-', 1, 0, 1, NULL, 0, 0, 1734662314, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzkxMTgy', 40391182, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 4, 4, 4, 3, 'I didn''t actually have Cathy as my prof I just watched her videos but I thought I''d rate her cause she was the one teaching me stuff. There''s lots of extra credit in the course, I got a bonus 5% on my mark from various things. Like I said she records her lectures for anyone to watch if they need too which is so awesome. Best first year chem prof.', '["EXTRA CREDIT","Accessible outside class"]', 'C+', 1, 0, 1, NULL, 0, 0, 1734662542, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzkyMTY4', 40392168, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 4, 4, 4, 3, 'Great prof, he is available during office hours which is great for insightful tips. Good guy and wants best for his students academically.', '["Gives good feedback","Test heavy","Accessible outside class"]', 'B-', 1, 0, 1, 3, 0, 0, 1734666732, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwMzkzNjQ0', 40393644, '0019103', '9943', 'MATH-1013', 'MATH1013', 5, 5, 5, 2, 'Dr Mendivil is an excellent prof. His lessons were clear and understandable. He has a genuine respect for his students, additionally he has inspired me to explore other areas of math. Would definitely recommend.', '["Amazing lectures ","Clear grading criteria","Lots of homework"]', 'A+', 1, 1, 1, NULL, 0, 0, 1734673328, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDA3MjA=', 4040720, '0000957', NULL, NULL, 'ANTH', 5, 5, 5, 4, 'Very good prof. Encourages you to be involved with class. I enjoyed her class very much.', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1119967280, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDA4NTgy', 40408582, '0004338', '9694', 'KINE-1213', 'KINE1213', 5, 5, 5, 3, 'Best prof i''ve had so far. Super easy to reach out to and super caring. If you''re stressed about work, she will break it down for you to understand better. No due dates until the end of semester. SUPER UNDERSTANDING. Genuinely one of the sweetest people at acadia and you''ll be thankful to get her if you''re lucky enough.', '["Get ready to read","Group projects","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1734801593, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDE2MzI0', 40416324, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 4, 4, 4, 3, 'Get ready to read and practice', '["Get ready to read"]', 'B', 1, 0, 1, 3, 0, 0, 1734890902, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDE3OTQx', 40417941, '0013980', '13459', 'ENGL-2083', 'ENGL2083', 3, 3, 3, 2, 'I had my literary theory class with Lance, and he made the difficult and boring content better. Lance has a tendency to speak in fragmented sentences, making it hard to take notes so showing up is a must. He is an extremely fair grader and a pretty funny guy. He definitely cares about the success of his students and will help you as much as he can.', '["Get ready to read","Participation matters","Hilarious"]', 'A-', 1, 1, 1, NULL, 0, 0, 1734905757, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDE3OTY3', 40417967, '0016390', '9265', 'HIST-2503', 'HIST2503', 5, 5, 5, 3, 'Dr. Dennis is the best history prof at Acadia. His lectures are interesting, he is an extremely fair grader, and he truly wants his students to do well. His lectures are packed with information, but honestly as long as you show up and pay attention you''re guaranteed to pass with flying colours. 10/10 prof.', '["Amazing lectures ","Lecture heavy","Graded by few things"]', 'A-', 0, 1, 1, NULL, 0, 0, 1734905956, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDE3OTk0', 40417994, '0015754', '8407', 'ENGL-2193', 'ENGL2193', 2, 2, 2, 4, 'Dr. Slights'' feedback on papers is extremely passive aggressive. Her lectures were fun and she is very insightful in the study of Shakespeare, but that did not outweigh her unwillingness to help in office hours. I understand that this is a second year class, however I felt like I had to write like a Shakespearean scholar to get a good grade. 5/10.', '["Tough grader","Accessible outside class"]', 'A-', 1, 1, NULL, 3, 0, 0, 1734906210, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDE5ODEz', 40419813, '0034933', '7646', 'COMM-1013', 'COMM1013', 2, 2, 2, 4, 'Very narcissistic. Makes to buy his own text books. Midterm and final are very hard. Presentation aren''t bad', '["Tough grader"]', 'A-', 1, 0, NULL, 3, 0, 0, 1734922334, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDExMTk4', 40411198, '0043258', '9701', 'KINE-1413', 'KINE1413', 5, 5, 5, 2, 'Awesome prof, super chill. Class can be quite repetitive as every time we will go through slideshows. Uses TopHat, an interactive app which makes class more engaging and fun. Cares about students, if you do better on one test than another, he will shift the grade weighting to benefit you.', '["Lecture heavy","Online Savvy"]', 'A+', 1, 1, 1, 3, 0, 0, 1734822980, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDExMjI5', 40411229, '0004338', '9694', 'KINE-1213', 'KINE1213', 5, 5, 5, 1, 'Kindest prof you''ll ever have. Grades very easily, and provides various opportunities to receive extra marks as well. Class can be a bit boring, tests are very fair and based on content learned in class.', '["EXTRA CREDIT","Caring","Accessible outside class"]', 'A+', 1, 1, 1, 3, 0, 0, 1734823208, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDExMjYz', 40411263, '0302829', '11705', 'SOCI-2103', 'SOCI-2103', 3, 3, 3, 2, 'Attendance is worth a lot, you have to go to classes. He is a very nice guy, however lectures are very boring and it is easy to zone out. Tests are multiple choice and true and false, however there always seems to be questions that were not in the slideshows. He listens to student opinions and is very reasonable.', '["Participation matters","Lecture heavy"]', 'A+', 1, 1, 1, 3, 0, 0, 1734823472, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDExMzA0', 40411304, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 1, 1, 1, 5, 'Avoid this professor at all cost, he does not care for his students and is only there for the cheque. He doesn''t care if you do bad or good. Going to class really is not going to help much and grading is all over the place.', '["Tough grader","Get ready to read"]', 'B', 1, 0, NULL, NULL, 0, 0, 1734823775, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDExMzEw', 40411310, '0148951', '7654', 'COMP-1113', 'COMP1113', 3, 3, 3, 3, 'Lots and lots of slideshows. Random information from the slides that seem irrelevant will sometimes be questions on the test. If you ask her for help, she will explain it to you until you understand. Not a bad teacher, but very fast paced and a bland teaching style.', '["Gives good feedback","Lecture heavy"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1734823827, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDMyMQ==', 404321, '0024548', NULL, 'MATH-1213', 'MATH1213', 4, 5, 3, 2, 'nice guy but can''t explain what he is talking about', '[]', NULL, 0, NULL, NULL, NULL, 0, 0, 1039285964, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDU4MjE4', 40458218, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 3, 'Chemistry is hard!! BUT do the practice from her slides + practice assignments + extra practice from each unit if especially tricky & you can THRIVE! Its all about practice and silly ways to remember solubility rules & names of elements. Acids & Bases most complicated unit. Cathy goes above and beyond 10x, watch her vids or attend class.', '["Lots of homework","Caring","Respected"]', 'A+', 1, 0, 1, NULL, 0, 0, 1735524719, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDU4MjMy', 40458232, '0015486', '6841', 'BIOL-1813', 'BIOL1813', 5, 5, 5, 3, 'Matt is super respected and goes above and beyond. Had him for lecture and lab and he gets to know you individually and is willing to help. The best professor I''ve had! Making flash cards (quizlets) will be your best friend and start studying them and the reviewing unit quizzes around 2 wks before midterms!', '["Amazing lectures ","Inspirational","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1735525005, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDU4MjQ4', 40458248, '0040908', '13370', 'MATH-1253', 'MATH1253', 5, 5, 5, 2, 'Danielle is a very kind person and a great professor. She understands the struggles students have with math and anxiety around testing so she points out ways students usually make little mistakes on midterms! EXTREMELY helpful! She also is approachable and makes the class material digestible. You can tell she cares about how to convey lectures.', '["Gives good feedback","Caring","Graded by few things"]', 'A+', 1, 1, 1, NULL, 0, 0, 1735525237, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDU4NDgx', 40458481, '0001050', '7997', 'ECON-1013', 'ECON1013', 2, 2, 2, 3, 'I got straight A''s all semester as a second year student taking this course but did awful only in this class. You will need to teach yourself everything in this class. When students ask questions in class he acts like you should know it and does not try to answer respectfully or helpfully.', '["Tough grader","Participation matters","Beware of pop quizzes"]', NULL, 1, 1, NULL, 3, 0, 0, 1735528334, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDU4NTc1', 40458575, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 3, 'Teri is an amazing professor and made me love organic chemistry. She is so funny and has such great ways to help us remember concepts. She does a lot to make sure you''ll do well in her class. If you''re on the fence about O chem, definitely take her class.', '["Amazing lectures "]', 'A', 1, 0, 1, NULL, 0, 0, 1735529759, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDUxNzQw', 40451740, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 5, 5, 5, 3, 'The professor was very clear while teaching. For his courses, I suggest students be attentive in class and practice the questions that he gives on Acorn/Moodle. Ask as many questions as you can, and he is very responsive. This would be enough to do well. This semester, I didn''t do as I expected because I didn''t practice the questions on Acorn.', '["Clear grading criteria","Gives good feedback"]', 'B+', 1, 0, 1, 3, 0, 0, 1735415118, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDUzNzUx', 40453751, '0024327', NULL, NULL, 'POLS00', 5, 5, 5, 4, 'best prof ever recommend', '[]', 'A+', 1, 1, 1, 3, 0, 0, 1735438582, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDY1Nzg3', 40465787, '0024670', '9954', 'MATH-1313', 'MATH1313', 4, 4, 4, 4, 'Dr. Clark was an amazing and welcoming professor for a difficult class. Her tests were difficult but fair. She had many office hours. She was very clear about her expectations from the start, but be aware you absolutely have to attend her classes and take notes to do well. Overall I thoroughly enjoyed her class and would love to have her again.', '["Test heavy","Graded by few things","Accessible outside class"]', 'A-', 1, 0, 1, NULL, 0, 0, 1735684457, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDY2NTM1', 40466535, '0024282', '7686', 'COMP-2113', 'COMP2113', 4, 4, 4, 2, 'Amazing prof, but some instructions on the assignments are going to trick you', '[]', 'A+', 1, 0, 1, NULL, 0, 0, 1735701894, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2Mjk1', 40476295, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 3, 3, 3, 4, 'Overall wasn''t a horrible teacher. He posts all lectures on YouTube towards the end of the day, which was great if you missed a class, or missed information while he was teaching. His lectures were engaging and entertaining. Only negative is that the midterms were very challenging, even with weeks of studying. Final wasn''t as bad, but wasn''t easy.', '["Tough grader","Beware of pop quizzes","Test heavy"]', 'A-', 1, 0, 1, 3, 0, 0, 1735918842, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2Mzcx', 40476371, '0203419', '8393', 'ENGL-1413', 'ENGL-1413', 3, 3, 3, 5, 'Jordan listens to his students opinions and made a 3h night class tolerable. He was quick to answer my emails, I would recommend making appointments with him for help, as it also allows him to know you and understand your writing abilities. ( Seriously do it). He is very understanding with deadlines and extensions.', '["Tough grader","Participation matters","Lecture heavy"]', 'B', 1, 1, 1, 3, 0, 0, 1735919971, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2Mzk5', 40476399, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'I took the COMM 1213 course as it was mandatory in my first year of business. Kendra is by far the worst prof I have ever seen and was the only course I could not score in. I had straight A''s in all other courses I took even in economics and accounts. this course tanked my GPA to 3.7 . Don''t take this course and if you have to then take other prof.', '["Tough grader","Participation matters","Group projects"]', 'C+', 1, 1, NULL, 3, 0, 0, 1735920277, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NDEw', 40476410, '0040908', '13370', 'MATH-1253', 'MATH1253', 5, 5, 5, 1, 'She is so kind and you can tell how much she cares for her students. She explains the content wonderfully and she is easy to follow. If you pay attention, do her practices exams, and keep up with the short weekly homework assignment you are guaranteed to get a good grade in this class. She also offers zoom calls if you are sick and cannot attend.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1735920392, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NDQx', 40476441, '0019405', '8737', 'FRAN-1213', 'FRAN1213', 4, 4, 4, 1, 'He is so kind and caring. If you are taking intermediate French, you should be able to speak and understand it, so beyond easy to follow along. Only two tests (took 15 min each) and one final oral presentation. I only attended half the classes, but as long as you''re able to give in your homework in time he doesn''t care. Highly recommend.', '["Caring","Respected"]', 'A+', 1, 0, 1, 3, 0, 0, 1735920872, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NDUz', 40476453, '0003993', '9938', 'MATH-0110', 'MATH0110', 5, 5, 5, 2, 'i took the MATH 0110 course with him and generally I always hated math but with Mr. Jim started to like math and because of this I took my next year MATH course with him again. Overall he is a very chill and funny guy which genuinely loves to teach and cares for his students.', '["Clear grading criteria","Hilarious","Caring"]', 'A-', 0, 0, 1, 3, 0, 0, 1735920963, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NDcx', 40476471, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 3, 'He is a very good prof and taught well. he has wiley plus for the assignments and had around 10 assignments which were very long but had to be submitted just a few days before before the final exam. overall I recommend this prof for the financial accounting 1 course as even if you messed up the midterm you could score good through the final exam.', '["Lots of homework","Lecture heavy"]', 'A+', 1, 0, 1, 3, 0, 0, 1735921252, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NDg1', 40476485, '0145558', NULL, 'PSYCH-1110L', 'PSYCH1110L', 3, 3, 3, 3, 'She reads off her powerpoint slides, making the lab feel so much longer than it needs to. Only attended the class a handful of times, because the homework was doable on your own by reading the slides yourself. If you did attend class you were free to leave after her explanation. Do with that what you will.', '["Tough grader","Get ready to read","Lots of homework"]', 'B+', 1, 1, NULL, NULL, 0, 0, 1735921392, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc2NzU0', 40476754, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 2, 2, 2, 5, 'joe is a great lecturer, he is very funny, however, the class is graded on 2 tests, 1 midterm, and a final. did not provide study guides, info about the content of tests (except for # of questions, which helps no one), his questions were very subjective, often asking which of the following would match his own opinions. dont take it(save yourselves)', '["Tough grader","Hilarious","Graded by few things"]', 'B-', 1, 0, NULL, NULL, 0, 0, 1735925305, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc3MDQ5', 40477049, '0011148', '10907', 'PHIL-1413', 'PHIL1413', 1, 1, 1, 3, 'Three exams made up 85% of the grade, with one assignment for the other 15%. I never got feedback on any exams, even after emailing before the final. It''s now the new year, and I still have no grades or responses. I went into the final blind, unsure of my standing in the class. Do. Not. Take.', '["Test heavy","Graded by few things"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1735929094, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc3MDY5', 40477069, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 3, 'An absolute sweetheart', '["Amazing lectures ","Hilarious","Caring"]', 'C', 1, 1, 1, NULL, 0, 0, 1735929338, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc4MTk5', 40478199, '0005121', '7646', 'COMM-1013', 'COMM1013', 5, 5, 5, 3, 'Laura is very encouraging and wants her students to succeed. I enjoyed her class, but she only posts skeleton notes so going to class is almost necessary. Very interactive professor and makes lectures fun. Highly recommend taking her class!', '["Gives good feedback"]', 'A', 1, 1, 1, NULL, 0, 0, 1735940967, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc5OTE0', 40479914, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 2, 2, 2, 3, 'Not open for questions what so ever. Takes months to grade midterms', '["Participation matters"]', 'B', 1, 0, NULL, 3, 0, 0, 1735961721, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc5OTU5', 40479959, '0024914', '9955', 'MATH-1323', 'MATH1323', 4, 4, 4, 4, 'You would definitely need the textbook as there are not many examples covered in class. However the tests are not hard. Lots of homework questions of which show up on tests.', '[]', 'A', 1, 0, 1, 3, 0, 0, 1735962273, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDc5OTYy', 40479962, '0180912', '11324', 'PSYC-2013', 'PSYC2013', 5, 5, 5, 2, 'Very good prof', '["Clear grading criteria","Gives good feedback","Caring"]', 'B', 1, 0, 1, 3, 0, 0, 1735962327, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDcwMDA0', 40470004, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 5, 5, 5, 1, 'Ryan Stack is one of Acadia''s top professors, known for his engaging, funny, and well-structured lectures. Ideal for first-year students or anyone seeking a GPA boost. His course offers personalized support to each and every student to ensure their success. If you''re familiar with elementary math, this course is an excellent starting point.', '["Amazing lectures ","Clear grading criteria","Hilarious"]', 'A+', 1, 0, 1, 3, 0, 0, 1735797545, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDcwNzY4', 40470768, '0041312', NULL, 'ENG-1413', 'ENG1413', 5, 5, 5, 4, 'Michelle has seen me tear up in her office because I had trouble understanding critical essays (English is my second language), she was kind to me and pushed me to not drop her class. I sat in the front and participated a lot, which she appreciated. (Participate!!) Also, she is entertaining and I love her lectures, she makes the material not boring', '["Tough grader","Get ready to read","Participation matters"]', 'A-', 1, 0, 1, 3, 0, 0, 1735827618, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDgwODA1', 40480805, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 2, 'Iain Beaton is one of the most respected and approachable professors at Acadia. His engaging teaching style,combined with his willingness to address questions,makes him highly a must-take professor.Always open and friendly,he fosters a welcoming environment.He genuinely cares about the success of every student. Pay attention in class to excel', '["Amazing lectures ","Respected","Accessible outside class"]', NULL, 1, 0, 1, NULL, 0, 0, 1735974781, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDgwODQ4', 40480848, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 4, 4, 4, 3, 'Caroline Cochran is an approachable and supportive professor. Her review sessions are more beneficial than regular labs, which require a solid grasp of Maple. Labs mainly provide extra practice. To succeed, complete workbook exercises ahead of class and lab assignments on time. Finally, focus on test prep assignments to ensure you do well for tests', '["Participation matters","Gives good feedback","Caring"]', NULL, 1, 1, 1, NULL, 0, 0, 1735975493, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDgyNjEx', 40482611, '0027644', '13564', 'LAWS-2003', 'LAWS2003', 3, 3, 3, 4, 'He is very knowledgeable about cases and he is very open to any questions being asked about them, the only thing that is confusing is his choice of wording and speed at which he speaks. His lecture notes are also vague so you have to do the readings before hand not after. But he is very kind and he try''s to keep you engaged in the lectures.', '["Get ready to read","Lecture heavy","Accessible outside class"]', 'B+', 1, 0, NULL, 3, 0, 0, 1736025292, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk2NzI0', 40496724, '0152004', '11707', 'SOCI-2113', 'SOCI2113', 3, 3, 3, 3, 'This prof cares about the material and students, but can be disorganized. Assignment instructions were vague at best, the syllabus was contradictory and unorganized, and she often did not answer emails. However there were no tests/exam. Participation is 15% but will give 0 if you don''t speak in class, even if you do the participation assignments.', '["Group projects"]', 'A', 1, 0, NULL, NULL, 0, 0, 1736216644, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk3MTYx', 40497161, '0012762', '7647', 'COMM-1213', 'COMM1213', 4, 4, 4, 5, 'Say what you want but Carmichael cares about COMM1213. I worked my butt off to get an A-, but I know many with Cs. Go to office hours, proofread your work, and read the content in her Moodle. It takes a lot of time, yes, but reading the textbook helps a lot. Her assignment descriptions are quite literally a roadmap on how to pass the class.', '["Tough grader","Get ready to read","Participation matters"]', 'A-', 1, 1, 1, 3, 1, 0, 1736219634, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk3MTgw', 40497180, '0000664', '10982', 'PHYS-1013', 'PHYS1013', 1, 1, 1, 4, 'Almost all mark is just tests, all lectures that barely go with lab activities, very monotone speaking', '["Lecture heavy","Test heavy","Graded by few things"]', 'D+', 1, 0, NULL, 3, 0, 0, 1736219760, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk3MjM5', 40497239, '0019103', '9969', 'MATH-1613', 'MATH1613', 5, 5, 5, 2, 'I loved Franklin''s class. His lectures were awesome and I found the content easy to comprehend. He posts blank and filled workbooks so you can do them in class or catch up if you were sick. Make sure to go on Fridays to do the quiz. If you attempt the quiz you will pass it. The homework is hard, but the quizzes and midterms make up for them.', '["Caring","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736220194, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk3MzQ5', 40497349, '0200913', '7114', 'BUSI-1013', 'BUSI1013', 3, 3, 3, 2, 'Wiley Plus WILL be the death of you. He gives you "deadlines" but they aren''t really due until the end of the term. They take FOREVER to finish. Ryan is a really nice guy and is very understanding. He made questions on the midterm that the class found hard worth less after they were marked to raise grades. Midterms/final are in person on Moodle.', '["Lots of homework"]', 'A+', 1, 0, NULL, 3, 0, 0, 1736220961, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDk5NTk1', 40499595, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 2, 2, 2, 4, 'He has no idea what is going on most days, and opens the class by saying he''s only ever taken on psychology courses and hated it', '["EXTRA CREDIT","Lecture heavy","Graded by few things"]', 'B-', 1, 0, NULL, NULL, 0, 0, 1736264478, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkxMTI3', 40491127, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 5, 5, 5, 3, 'You really need to pay attention in her classes, but she makes the material engaging! She provides everything you need to succeed, so attending class is essential. Her teaching made me want to take more courses with her and learn more about the brain!', '["Amazing lectures ","Respected","Lecture heavy"]', 'A+', 1, 0, 1, 3, 0, 0, 1736180255, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkxMTQx', 40491141, '0035856', '7718', 'COMP-2903', 'COMP-2903', 5, 5, 5, 3, 'prof gives one of the best lectures but u may loose grades if you do not follow his grading criteria for assignments', '["Tough grader","Participation matters","Amazing lectures "]', 'A+', 1, 1, 1, NULL, 0, 0, 1736180307, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkxODM5', 40491839, '0310940', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 1, 'I would highly suggest choosing Garett as a professor. He is very understanding and makes lectures interesting and easy to understand!', '["Amazing lectures ","Caring","Accessible outside class"]', 'A+', 1, 0, 1, 3, 0, 0, 1736185472, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkxOTA5', 40491909, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 1, 'Chemistry is difficult but Cathy was so helpful. You do need to put in the work but she does an amazing job at explaining all the concepts and what you need to know. Some perks of her classes are that she records her lectures (and she edits them so they''re not too lengthy), she writes out how to do all the examples and there''s lots of extra credit!', '["EXTRA CREDIT","Caring","Lecture heavy"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736185808, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkxOTMz', 40491933, '0040908', '13370', 'MATH-1253', 'MATH1253', 5, 5, 5, 1, 'I had Danielle for my math lab and she was exceptional. She was so sweet and helpful. I highly suggest choosing her for your math lecture/lab course.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1736185924, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkyMDI3', 40492027, '0176953', '13370', 'MATH-1253', 'MATH-1253', 2, 2, 2, 3, 'Ayman was very sweet but hard to understand due to his accent. He would teach very slowly and it was hard to hear him. He would also do random pop quizzes for participation marks and never tell you the day it was on. If you are taking Math 1253 pick Danielle Quinn.', '["Participation matters","Beware of pop quizzes","Accessible outside class"]', 'A+', 1, 1, NULL, NULL, 0, 0, 1736186408, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkyMDgw', 40492080, '0144618', '6834', 'BIOL-1110L', 'BIOL-1110L', 2, 2, 2, 4, 'If you are registering for the BIOL labs here is my opinion on Kendra. She does not really care to help. She almost seems annoyed at you. She barely provides any feedback and you will be deducted on things in your report that you were never taught. She is alright but you will have to search for answers elsewhere to get top marks.', '["Tough grader","Graded by few things"]', 'A+', 1, 1, NULL, NULL, 1, 0, 1736186776, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkyMTY2', 40492166, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 2, 2, 2, 4, 'Dan did make lectures interesting but his style of teaching was all over the place. You definitely need to put in time after class to get organized. This is also a very lengthy course so you need to review weekly and having a teacher with barely any words on his slideshows was not the best.', '["Tough grader","Lecture heavy"]', 'A+', 1, 0, NULL, 3, 0, 0, 1736187366, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkzMzU5', 40493359, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 5, 'I didn''t have this prof for this class, I won''t say which one I did as it was not in the past year. Genuinely the worst professor I have had and I have been in school for many years. Unkind, uncaring, and coasting through. I am an A+ student and got an A- in the most difficult way possible. He simply does not teach or prepare you.', '["Tough grader","Test heavy","Graded by few things"]', 'A-', 1, 1, NULL, NULL, 0, 0, 1736194155, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNDkzNTE4', 40493518, '0133590', '6993', 'BIOL-3663', 'BIOL3663', 5, 5, 5, 1, 'Allison is amazing, and one of the sweetest and most caring profs I''ve had. The course is quite relaxed, there is a partner presentation and final project but no exam. She is a kind marker and the midterms weren''t unreasonable as she gives a good test review before each one!', '["Clear grading criteria","Inspirational","Caring"]', 'A+', 1, 1, 1, NULL, 0, 0, 1736195342, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTA0Mzg5', 40504389, '0027644', '10948', 'PHIL-3203', 'PHIL3203', 5, 5, 5, 3, 'He gives you the exact test and exam questions in advance so no surprises and there is choice. He''s a generous grader and gives as many points as he can. If you don''t cover the points he wanted but give other relevant info then he will give you points for that. Go to class, take good notes bc there are holes in the lecture slides and you''ll be fine', '["Clear grading criteria","Lecture heavy","Graded by few things"]', 'A+', 1, 0, 1, 3, 0, 0, 1736296033, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTA3NTcy', 40507572, '0027840', NULL, 'THEA-1013', 'THEA1013', 4, 4, 4, 4, 'Be prepared to be an active participant in his class, overall, the material was great, but the group projects sucked. The criteria wasn''t quite clear and the shortcomings of group members can affect your grade highly.', '["Tough grader","Participation matters","Group projects"]', 'B+', 1, 1, 1, NULL, 0, 0, 1736345098, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTA3NjEy', 40507612, '0000916', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 5, 'The worst teacher I''ve ever had. His lecture notes and slides are clearly translated into English as they are choppy and hard to read. The assignments are such hard work but so little points. Moussa is almost impossible to understand and it amazes me how he''s still a teacher. Will never take another class with him again.', '[]', 'C+', 1, 1, NULL, NULL, 0, 0, 1736345985, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE2MTc4', 40516178, '0041312', NULL, 'ENG-1413', 'ENG1413', 1, 1, 1, 5, 'Evil woman', '["Tough grader","Get ready to read"]', 'C+', 1, 1, NULL, 3, 0, 0, 1736437575, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE5NDE4', 40519418, '0133715', NULL, 'BIO-3613', 'BIO3613', 3, 3, 3, 4, 'Russell emphasizes understanding over memorization, and that''s reflected in his exams. You definitely need to work hard, but you don''t need to know everything, just enough to support your answers. Go to class because he talks a lot for each slide. He wants students to do well: he gives a lot of bonus % and choice on exams, especially the final', '["Hilarious","Lecture heavy","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736460930, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE5NDY4', 40519468, '0003429', '6922', 'BIOL-3153', 'BIOL3153', 5, 5, 5, 3, 'Glenys tries to break down development as easily as she can, since it can sometimes be a little complex. Her lectures are always interesting, and we''ll work in groups to figure out questions to help our understanding. The lab is great & helps to reinforce lectures, with 3D embryos (not pictures). Long answer Qs on the exams are graded super fairly', '["Amazing lectures ","Gives good feedback","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736461338, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE5NTE2', 40519516, '0038515', '10989', 'PHYS-1053', 'PHYS1053', 5, 5, 5, 2, 'Physics is hard, but Anna is amazing. She does her best to explain & reinforce concepts. The exams can be tough, but she grades them fairly & gives as many partial marks as she can. She  encourages us to see her outside of class if we need help, and holds help sessions before each exam! Also lenient with deadlines & will move exams if we all wish', '["Caring","Accessible outside class","Online Savvy"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736461776, 1788283339);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE5NjA0', 40519604, '0302662', '11343', 'PSYC-2183', 'PSYC2183', 4, 4, 4, 3, 'Dr. Gauvin is a great lecturer and explains everything really well. She''ll often hint when something will be a big concept on the exam, and we have a lot of discussions & videos in class that end up being tested, so if you go to class the exams are super fair. The assignments are great & fair too. Interesting topics in class & I learned a lot!', '["Caring","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1736462606, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTE5NzM0', 40519734, '0043258', '9701', 'KINE-1413', 'KINE1413', 5, 5, 5, 2, 'Amazing!!!', '["Amazing lectures ","Hilarious"]', 'B+', 1, 1, 1, 3, 0, 0, 1736463789, 1788283354);
