INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTI2OTg5', 40526989, '0025724', '9695', 'KINE-1243', 'KINE1243', 1, 1, 1, 3, 'Literally hates dead people. She ripped into me for not showing up when my parents died in a car crash. No extension nothing.', '["Tough grader","Clear grading criteria","Graded by few things"]', 'A+', 1, 1, NULL, NULL, 0, 0, 1736568018, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTI3NDgw', 40527480, '0016390', '9334', 'HIST-3323', 'HIST3323', 5, 5, 5, 3, 'Prof. Dennis'' lectures are engaging and thought-provoking. Attend class, take notes, and use resources like Unstuck ai to ace this course. Reasonable grading, understanding of personal situations.', '[]', 'A', 1, 1, 1, 3, 0, 0, 1736574791, 1788283351);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTIzMjYx', 40523261, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 5, 5, 5, 3, 'Caroline was a great professor , she cared a lot about students grades a swell as their well being. I would recommend her to anyone.', '["Clear grading criteria","Gives good feedback","Caring"]', 'A', 0, 1, 1, NULL, 0, 0, 1736526127, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2NjUy', 40536652, '0011703', '6690', 'ART-2053', 'ART2053', 5, 5, 5, 3, 'Really great and caring prof, gave me an extension on an assignment during a rough week. If you put the time in and be creative you will do well in this course. Be prepared to spend upwards of 200$ as on the second class we went out and bought our materials as a class. Don''t forget about your sketchbook!!', '["Gives good feedback","Lots of homework","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1736775380, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2Njgy', 40536682, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 4, 4, 4, 4, 'Does lots of examples on the board so make sure to attend lectures and take notes to do well, although it was hard to focus. I found the midterms and exam really hard as tests are taken online so you don''t really get partial points. She''s very caring and posts her lectures online which were super helpful. Plus she gave us candy after midterms :)', '["Caring","Respected","Test heavy"]', 'C+', 1, 1, 1, NULL, 0, 0, 1736776468, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2NzA2', 40536706, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 3, 'One of the best profs I''ve had. Calc is hard but he is fantastic at explaining and takes time to fully answer students questions. Lectures are def mandatory as the slides do not have all of the info. He does tons of examples on the board and makes sure everyone understands before moving on. Gives detailed feedback on quizzes before midterms.', '["Amazing lectures ","Gives good feedback","Caring"]', 'B+', 1, 1, 1, NULL, 0, 0, 1736777016, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2NzI5', 40536729, '0040908', '13370', 'MATH-1253', 'MATH1253', 5, 5, 5, 2, 'Had her for my lab instructor and she was fantastic. Learned more statistics from her than my actual stats prof. If you did the assignments before the lab you could leave within the first 5 minutes, after an attendance check. This course was not hard, but she was always reiterating how open she was to questions so super caring.', '["EXTRA CREDIT","Amazing lectures ","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1736777519, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2ODEw', 40536810, '0133712', '9942', 'MATH-1010L', 'MATH1010L', 5, 5, 5, 3, 'Very knowledgeable, held extra help sessions outside of class that were super helpful for the assignments. MASH was the most valuable resource to help with the assignments, as there are TAs with the answer keys that can help with Maple script. Don''t leave the assignments until the last minute.', '["Tough grader","Respected","Accessible outside class"]', 'B+', 1, 1, 1, NULL, 0, 0, 1736778929, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2ODM1', 40536835, '0144618', '6834', 'BIOL-1110L', 'BIOL-1110L', 2, 2, 2, 2, 'Never really saw her. The TAs I had were fantastic and did all of the teaching and grading (as far as I know). Didn''t really answer questions and seemed annoyed when you asked, so TAs would answer you instead.', '[]', NULL, 1, 1, 1, NULL, 0, 0, 1736779292, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2ODY3', 40536867, '0176953', '13370', 'MATH-1253', 'MATH-1253', 2, 2, 2, 1, 'Easy to understand but talked really slowly and constantly repeated what he just said so he can''t really keep your attention well. He''s nice but got mad at our class a lot for skipping lol. Random quizzes and attendance checks with no warning. Just read off the slides and didn''t do examples. Couldn''t expand upon any content outside of the slides.', '["Clear grading criteria","Beware of pop quizzes","Lecture heavy"]', 'A', 1, 0, NULL, NULL, 0, 0, 1736779721, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM2ODk1', 40536895, '0310940', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 2, 'Best prof I had first sem. He was very engaging and you could tell he was extremely passionate about biology and his research. He would show stuff before class about his crab and marine research which honestly made him a better prof and easier to learn from. Constantly expanded upon what was on the slides and made 8:30 bio worth going to.', '["Amazing lectures ","Inspirational","Caring"]', 'B+', 1, 1, 1, NULL, 0, 0, 1736780147, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM4ODIy', 40538822, '0307325', '9797', 'KINE-3213', 'KINE3213', 5, 5, 5, 3, 'Love Chelsey, she really cares about her student''s success and she is overall a great prof. She is clear in her teaching and good at simplifying complex concepts. Overall I really enjoyed my course with her!', '["Clear grading criteria","Gives good feedback","Caring"]', 'A', 1, 0, 1, NULL, 0, 0, 1736793546, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTM5NzUy', 40539752, '0006710', '7256', 'BUSI-4953', 'BUSI4953', 1, 1, 1, 4, 'All he does is gives sites and says it helps for the assignments. Avoid if possible because he doesn''t know what he wants.', '["Lots of homework","So many papers"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1736798985, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTQ3Mjc2', 40547276, '0192432', '11315', 'PSYC-1013', 'PSYC-1013', 4, 4, 4, 2, 'Great prof, always made classes/lectures interesting and used hands on learning as much as possible when it comes to psychology. Also, answers emails quickly and is very reasonable.', '["Amazing lectures "]', 'B+', 1, 0, 1, NULL, 0, 0, 1736881510, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTQyMTg3', 40542187, '0015754', '8407', 'ENGL-2193', 'ENGL2193', 3, 3, 3, 4, 'Dr. Slights is very passionate about her primary area of teaching: Shakespeare. She is clear, and is a good lecturer. Her grading tends to be very harsh, and feedback boarders on nit-picky. On one hand, this does open many doors to improvement, and on the other hand it can be a bit discouraging. Participating, reading and showing up is a must.', '["Tough grader","Get ready to read","Participation matters"]', 'B+', 1, 1, 1, 3, 0, 0, 1736815119, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTQyMjQ5', 40542249, '0001453', NULL, NULL, '2013', 5, 5, 5, 2, 'Took a history of musical theatre course with Paula. The lectures were loaded with content, and it is one of the courses I felt I had to memorize instead of understand. This did not stop me from loving the course. Paula is engaging and extremely insightful, and her passion when teaching is remarkable. Recommend taking a ''classroom'' course with her.', '["Participation matters","Caring","Lecture heavy"]', 'A+', 1, 1, 1, NULL, 0, 0, 1736815551, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTU0MDgx', 40554081, '0024670', NULL, 'MATH-1423', 'MATH1423', 1, 1, 1, 5, 'Terrible. Worst professor I''ve ever had. Doesn''t know how to teach what''s so ever. Everyone in the class is lost. She doesn''t have online notes or anything. She just draws on the whiteboard. No one in the class has learned a damn thing.', '["Tough grader","Participation matters","Lecture heavy"]', 'B+', 1, 1, NULL, 3, 0, 0, 1736961725, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTU5Nzk0', 40559794, '0139613', '11056', 'POLS-1303', 'POLS1303', 5, 5, 5, 4, 'Erin is such a wonderful teacher, she is so caring and really makes an effort to make class engaging. Lots of group work in the class, and if you participate and are good at self-reflections you can get a really good grade. not too much work.', '["Participation matters","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1737035671, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTc5MDk4', 40579098, '0203419', '8387', 'ENGL-1213', 'ENGL-1213', 3, 3, 3, 3, 'Jordan is pretty good. Most classes are the same - you look at a piece (art/writing), he talks about it, then you break off into groups to talk about it. Definitely prioritize your pre class readings as you will probably be asked questions about them. Tough marker - doesn''t give much feedback. Better to ask in person for feedback.', '["Tough grader","Get ready to read","Group projects"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1737432626, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTcwNjUx', 40570651, '0152134', '7691', 'COMP-2203', 'COMP2203', 5, 5, 5, 3, 'Love this guy. He really wants you to succeed and his lectures are super clear & organized. He even does review problems for the class right before tests.', '[]', 'A+', 1, NULL, 1, NULL, 0, 0, 1737219087, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTg3NzUx', 40587751, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 4, 'Worst class ever. I swear he has personal vendettas against students and takes it out on your marks. Behaves VERY inappropriately for a professor (was straight up flirting with one of the girls in my class). Tests are nearly if not all multiple choice (80-100 questions). Not a good prof. Avoid him at all costs!', '["Tough grader","Participation matters","Graded by few things"]', 'C', 1, 1, NULL, 3, 1, 0, 1737573529, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTgxMzMx', 40581331, '0006710', NULL, 'BUSI-4053', 'BUSI4053', 5, 5, 5, 4, 'Coming back to write this review after taking his class in 2019. At the time I didn''t care for his class but the presentation skills I learned in the course really helped me in my professional career. Conor teaches important skills. References are important. He does not spoon feed the students. Ask question when instructions aren''t clear.', '["Participation matters","Respected"]', 'A', 1, 1, 1, 3, 0, 0, 1737484047, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTgyNDQ1', 40582445, '0012762', '7647', 'COMM-1213', 'COMM1213', 4, 4, 4, 5, 'Hate is blown out of proportion. Show up. Work Hard and you will be rewarded', '["Participation matters"]', 'B+', 1, 1, 1, 3, 0, 0, 1737492990, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTgzMDY5', 40583069, '0306489', '13690', 'ECON-3543', 'ECON-3543', 5, 5, 5, 2, 'If you want to have a great experience and actually learn something, take on of Barry''s classes. His lectures are engaging and he is able to make meaningful connections between what we learn in class and how it affects our world. Great guy, awesome stories, 10/10 would recommend.', '["Inspirational","Hilarious","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1737498757, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNTgzMjkx', 40583291, '0024914', '9955', 'MATH-1323', 'MATH1323', 4, 4, 4, 3, 'Holger is a great choice for first-year students, providing support and accessibility outside class. The course involves significant written and online work, so staying on top of notes daily is essential to avoid struggles later. With a good sense of humor, he is well-liked and one of the best profs for matrix available at Acadia.', '["Amazing lectures ","Lots of homework","Caring"]', NULL, 1, 1, 1, 3, 0, 0, 1737500635, 1788283345);
