INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzAzOTE2', 40703916, '0300770', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'She goes back on her word all the time telling you something is right then you''ll do it in a assignments or test and it''s completely wrong and she is very annoying.', '["Tough grader","Participation matters","Group projects"]', 'C+', 1, 1, NULL, 3, 0, 0, 1740438568, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzI3Mzcx', 40727371, '0012762', '7647', 'COMM-1213', 'COMM1213', 1, 1, 1, 5, 'Carmichael is one of those teachers that wants to f all the male athletes. I''m a good writer, and I got nothing over a C the entire semester. She gives zero direction on what her expectations are on each project. Expect to work on projects for weeks and get a 60. I thought people were dramatic and I''d be able to suck up to her, but boy was I wrong.', '["Tough grader","Participation matters","Group projects"]', 'B-', 1, 1, NULL, 3, 0, 0, 1741014822, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzI3Mzg1', 40727385, '0306489', '13690', 'ECON-3543', 'ECON-3543', 5, 5, 5, 1, 'Barry Watson is a great prof. He really cares about the topics he teaches and the students he''s teaching it to. Take one of his classes if you can. He has great stories that align with his lectures which make them interesting and funny. He is also available to talk/meet 99% of the time. He''s a very interesting man and his classes are great!', '["Amazing lectures ","Hilarious","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1741015190, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzIwMjc2', 40720276, '0035856', '7718', 'COMP-2903', 'COMP-2903', 5, 5, 5, 1, 'If you read the rubric, you can score 100%. he''s super serious about work ethic, lateness and such. not a problem for me, but other students who were disorganised suffered by missing deadlines. he''s fair, almost to a fault bc if you miss a deadline w/o a 48 hour notice you''ll get a zero. he''s super respectful and the course gets easier as it goes.', '["Amazing lectures ","Inspirational","Respected"]', 'A+', 1, 1, 1, NULL, 0, 0, 1740761032, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzM0ODcx', 40734871, '0176895', NULL, NULL, '1413', 1, 1, 1, 4, 'I have the feeling she is unaware of what she is doing. Very bias and unhelpful. Does not even have a rubric. Do not take unless you like bad grades, boring lectures and learning 0', '["Tough grader","Participation matters","Graded by few things"]', NULL, 1, 1, NULL, NULL, 0, 0, 1741134509, 1788283339);
