INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzQ1NTk5', 40745599, '0205001', '7129', 'BUSI-2033', 'BUSI2033', 5, 5, 5, 1, 'I had a nice experience taking this course. My concepts got cleared with self practice questions, quizzes and real life examples.', '["Participation matters","Group projects","Clear grading criteria"]', 'A', 1, 0, 1, 3, 0, 0, 1741320821, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzQyODk0', 40742894, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 2, 2, 2, 4, 'He''s alright. Loves throwing in wrinkles on the tests that weren''t on the practice material. Pretty sure he checks these and most of the positive reviews look like he wrote himself.', '["Graded by few things"]', 'B+', 1, 0, NULL, 3, 0, 0, 1741286715, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzQzMTMy', 40743132, '0037539', '9994', 'MATH-2313', 'MATH2313', 1, 1, 1, 5, 'NEVER TAKE A CLASS WITH EVA CURRY. SHE IS A TERRIBLE TEACHER, WAY TO MUCH HOMEWORK, YOU HAVE TO SUBMIT 8 PAGES OF NOTES BEFORE EACH WEEK WHILE ALSO HAVING TO COMPLETE A WRITTEN AND ONLINE ASSIGNMENT. HER NOTES WERE CONFUSING AND HER TEST WERE IMPOSSIBLY HARD. AN 8 PAGE TEST FOR A 45 MINUTE MIDTERM IS NUTS.', '["Tough grader","Participation matters","Lots of homework"]', 'C+', 1, 1, NULL, 3, 0, 0, 1741289222, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzU2NTU4', 40756558, '0306489', '7997', 'ECON-1013', 'ECON-1013', 5, 5, 5, 1, 'I recommend taking a Barry Watson course, great prof and guy. He connects his lectures to stuff actually happening in the world and has really interesting stories to share. I attended every one of his classes because it was my favourite lecture. He turned a hard, boring class into an interesting, engaging class. He''s the best!', '["Amazing lectures ","Hilarious","Accessible outside class"]', 'B+', 1, 0, 1, NULL, 0, 0, 1741666216, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY3Mjgx', 40767281, '0011148', '10925', 'PHIL-2313', 'PHIL2313', 5, 5, 5, 2, 'This class was really enjoyable. Theory-based ethics and lively discussion in class. Anna Wilks is a great professor and I have taken lots of her courses.', '["Clear grading criteria","Inspirational","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1741884084, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY3MzAx', 40767301, '0011148', '10918', 'PHIL-2113', 'PHIL-2113', 5, 5, 5, 2, 'This was the first half of the early modern philosophy courses and it was excellent. Her treatment of the Rationalist thinkers was super engaging, particularly her lectures on Leibniz. Highly recommend taking any of her courses.', '["Clear grading criteria","Inspirational","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1741884279, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY3MzEz', 40767313, '0011148', '10927', 'PHIL-2403', 'PHIL-2403', 5, 5, 5, 2, 'Anna Wilks provided this excellent class on Philosophy of Religion. She gave lots of student direction in topics covered, even introducing new material from African Philosophy. Moreover, she always includes diverse viewpoints giving the student a holistic perspective. Super Great Prof!', '["Clear grading criteria","Inspirational","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1741884442, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY3MzM3', 40767337, '0011148', '10943', 'PHIL-2553', 'PHIL-2553', 5, 5, 5, 2, 'Dr. Wilks gave a wide-reaching treatment of 19th century social and political philosophy. Covering thinkers like Marx, Nietzsche, Darwin and more. Super engaging and great class discussion. Particularly enjoyed the material on Darwin.', '["Clear grading criteria","Inspirational","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1741884611, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY3NDA5', 40767409, '0011148', '10919', 'PHIL-2123', 'PHIL-2123', 5, 5, 5, 2, 'This was the second half of early modern philosophy, the empiricists. I really enjoyed this course, particularly Berkely and Hume. I didn''t do as well in this course as I would have liked to but I was just coming back from academic dismissal and Anna''s class gave me the fuel I needed to become a better student.', '["Clear grading criteria","Inspirational","Caring"]', 'B+', 1, 1, 1, 3, 0, 0, 1741885263, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzY5NTA2', 40769506, '0180912', '11321', 'PSYC-1123', 'PSYC1123', 1, 1, 1, 1, 'He pushed intermittent fasting too much, bringing up every lecture. He was way too political, and we only really learned about things from a political standpoint; he also pushed many religious narratives, saying that things were "God''s will", he didn''t actually test on the review questions like he said he would, overall would not recommend', '["Test heavy","Graded by few things","Online Savvy"]', 'A-', 1, 0, NULL, 3, 0, 0, 1741910378, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzYxNTc0', 40761574, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 5, 'I had Dr. Hayes for RDA, while he is one of the most funniest profs I have had, he gives NO test review, like none, maybe 1 or two practice questions in each lecture. His slides sometimes are confusing and complicated, and it is genuinely like he wants it to be as hard as possible. Felt like my studying did nothing cause it was so hard.', '["Hilarious"]', 'B', 1, 0, NULL, NULL, 0, 0, 1741776969, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzYxNzQy', 40761742, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 5, 'I''m going to say this in the nicest way possible, he is awful. His lectures are terrible. He cant teach, all he does is yap. He does not care about his students. For a statistics class where there are at least 20 formulas, no formula sheet is given. I would rather be taught by a bear who I am constantly at risk of being killed by.', '["Tough grader","Graded by few things"]', 'B-', 1, 0, NULL, NULL, 0, 0, 1741787060, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzg1NDIw', 40785420, '0038351', '8736', 'FRAN-1123', 'FRAN1123', 2, 2, 2, 4, 'Marina is a nice person although she comes off as rude. She made me do all my assignments again 3 times, and for what, I got a C in the course. She has unrealistic standards for students and is hard to understand.  Although she is a very sweet woman, avoid taking her if you want a good gpa.', '["Tough grader"]', 'C', 1, 1, NULL, 3, 0, 0, 1742327537, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzg4NjM2', 40788636, '0024327', NULL, NULL, '1303', 5, 5, 5, 3, 'Very patient, kind, and understanding guy. Assigns lots of readings but always has reasonable expectations for his students. Gives good feedback on essays and doesn''t bog down the course with too many tests. 
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzg4NjMz', 40788633, '0026327', '9060', 'GERM-1013', 'GERM1013', 5, 5, 5, 2, 'Very accessible/available. He routinely ensures everyone understands. Attendance/participation are huge but he''s very understanding. He gives extensions and will help you if you show that you care and are trying. 
