INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzkxMDA2', 40791006, '0003424', '11056', 'POLS-1303', 'POLS-1303', 2, 2, 2, 5, 'Professor was nice and understanding enough but assigned way too much work.', '["Get ready to read","So many papers","Lecture heavy"]', 'Drop/Withdrawal', 1, 1, NULL, 3, 0, 0, 1742417771, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzkzODQz', 40793843, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 1, 1, 1, 4, 'Dr. Hayes is&#8230; certainly a character. He is hilarious and makes a lot of jokes through his lectures, but doesn''t care about his students at any level. He does not prepare his students for the few but high-worth midterms that are ridiculously confusing and he gives the &#8220;disappointed in you guys&#8221; lecture when the class does sub-par on it. Avoid.', '["Tough grader","Test heavy","Graded by few things"]', 'B+', 1, 0, NULL, NULL, 0, 0, 1742471650, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzkzODUw', 40793850, '0018154', '11323', 'PSYC-2010L', 'PSYC2010L', 5, 5, 5, 4, 'Dr. Bleile is a tough grader, but she''s just specific about formatting! She takes her students seriously and sees them as more than just numbers. She does take a while to grade papers, but it''s a mixed matter between her and TAs. Meeting up with her (office hours or appt) gives you a real insight to how much she cares about her students. Recommend!', '["Tough grader","Clear grading criteria","Gives good feedback"]', 'A-', 1, 1, 1, NULL, 0, 0, 1742472147, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwNzkzOTMy', 40793932, '0200916', '9958', 'MATH-1413', 'MATH1413', 5, 5, 5, 4, 'As good as they get.', '["Participation matters","EXTRA CREDIT","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1742476078, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODA4NDkx', 40808491, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 5, 'Does not care about his students AT ALL. No review for a STATS course, and maybe 1 or 2 practice questions in every few lectures (which are so vague). Tests are PURPOSELY confusing and hard, then tells us "the average is very low"...I think it was around 64% last test. If students are struggling, maybe you should offer more help and support?!', '["Tough grader"]', 'B-', 1, 0, NULL, NULL, 0, 0, 1742833593, 1788283347);
