INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODEzNTk2', 40813596, '0044535', '7134', 'BUSI-2223', 'BUSI2223', 2, 2, 2, 4, 'Igor was a very nice person but he was hard to understand in class as he was kinda all over the place. It felt he could get irritated with students very easily and is impossible to get ahold of outside of class time.', '["Participation matters","Beware of pop quizzes"]', 'B+', 1, 0, NULL, 3, 0, 0, 1742909340, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODI2Mjcy', 40826272, '0133715', NULL, 'BIO-3013', 'BIO3013', 2, 2, 2, 4, 'This class only makes sense if you already know what he''s talking about. His lecture slides make no sense and he expects you to somehow fully understand every aspect of every concept he mentions, even if he only talks about it for a couple minutes. No matter how much time I spend studying for this class, its never enough.', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1743079362, 1788283354);
