INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODIwMjQ4', 40820248, '0041312', '8394', 'ENGL-1423', 'ENGL1423', 3, 3, 3, 3, 'Not really a tough grader, but very specific so make sure to read everything she posts on Moodle. Keep up with readings or else won''t pass the multiple quizzes given. Lectures are boring but it is English so don''t have high expectations. Decent prof overall.', '[]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1742999767, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODIwMzg1', 40820385, '0011703', '6685', 'ART-2013', 'ART2013', 4, 4, 4, 3, 'Judith is kind and she''s very knowledgeable, but there is also a lot expected of you for an intro class. I really enjoy art, but the amount of time that was expected for us to spend on the final project (between exams/mandatory classes) was a lot. I recommend the class, but take it alongside classes that wont be too demanding during exam season.', '["Tough grader","Participation matters","Accessible outside class"]', 'A', 1, 1, 1, 3, 0, 0, 1743001240, 1788283361);
