INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwODU3Njcw', 40857670, '0132938', '7997', 'ECON-1013', 'ECON1013', 5, 5, 5, 3, 'Very caring prof and tries to get to know students. Answers emails fast and is very accessible. Lectures are very useful, and I wouldn''t miss because of how worth it they are. Extra credit is available and there are weekly quizzes that are very do-able and good additions for your grade. Also very funny guy, dry humor for early morning!', '["EXTRA CREDIT","Hilarious","Accessible outside class"]', 'B', 1, 0, 1, NULL, 0, 0, 1743606854, 1788283341);
