INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTM4MjI0', 40938224, '0180912', '11317', 'PSYC-1023', 'PSYC1023', 3, 3, 3, 4, 'The psych majors are definitely favored. If you''re not a psych major, there''s very few things that are graded so you need to make sure you do well on everything else to pass', '["Tough grader","Lecture heavy","Graded by few things"]', 'Rather not say', 1, 0, NULL, NULL, 0, 0, 1744665510, 1788283348);
