INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTQ4NzY1', 40948765, '0011148', '10922', 'PHIL-2233', 'PHIL2233', 2, 2, 2, 5, 'This course was solely lectures that were boring and hard to follow. She often went too fast to take notes, or spent majority of the class on one slide. It was hard to stay engaged with the slides, and listen to what was being said about the slides. Some slides were outdated. She was also a hard marker with a few assignments and a large exam.', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 1, 0, NULL, 3, 0, 0, 1744749696, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTQwMDEw', 40940010, '0022921', '10984', 'PHYS-1023', 'PHYS1023', 5, 5, 5, 3, 'Great professor, really engaging and you could tell he loves physics. Simple, easy to understand grading scheme set up to help you succeed. He was very helpful in office hours and extra review sessions as well.', '["Amazing lectures ","Clear grading criteria","Gives good feedback"]', 'A', 1, 0, 1, 3, 0, 0, 1744677239, 1788283351);
