INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTY3MjY3', 40967267, '0018259', '10143', 'MUSI-1273', 'MUSI1273', 5, 5, 5, 4, 'Excellent prof who cares about her students and her role. Shows up to every class with enthusiasm and is well prepared. Expectations are clear and as long as you show up to class, pay attention, and review daily, you''ll do great.', '["Amazing lectures ","Gives good feedback","Respected"]', 'A', 1, 1, 1, 3, 0, 0, 1744908036, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTY3MzI5', 40967329, '0203419', '8393', 'ENGL-1413', 'ENGL-1413', 4, 4, 4, 5, 'Jordan is very intelligent and knows his stuff. He won''t let you make a statement without backing it up, which is good. Classes could feel a little dry at times, but maybe that''s just me. I would have loved if there were more moments of class discussion/reading, and less slides. Great english prof who cares.', '["Tough grader","Get ready to read","Participation matters"]', NULL, 1, 0, 1, NULL, 0, 0, 1744908320, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTY3Mzcw', 40967370, '0012981', NULL, 'ENG-1413', 'ENG1413', 5, 5, 5, 3, 'Lisa is an excellent teacher who really values class attendance and participation. Her class was very engaging. Would recommend.', '["Participation matters","Clear grading criteria","Gives good feedback"]', 'A', 1, 0, 1, 3, 0, 0, 1744908529, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTc3MTU3', 40977157, '0034412', '9767', 'KINE-2433', 'KINE2433', 2, 2, 2, 5, 'His tests are insanely hard and he does not prepare you for them at all. An extremely tough grader. He''s very nice but an awful prof. Would not take a course with him again.', '["Tough grader","Test heavy"]', 'D', 1, 0, NULL, NULL, 0, 0, 1744996829, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTg5MDQ5', 40989049, '0308310', '13254', 'POLS-1503', 'POLS-1503', 5, 5, 5, 3, 'I have learned more from this man than all of my university classes combined; truly. I would recommend him to anyone. Take his courses, the material is important and he really cares to teach/inform students. The late nights are totally worth it.', '["Amazing lectures ","Inspirational","Hilarious"]', 'A+', 1, 1, 1, 3, 0, 0, 1745211599, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQwOTkwMTE0', 40990114, '0013980', '13460', 'ENGL-2093', 'ENGL2093', 5, 5, 5, 2, 'Lance is honestly great. He is one of the most accommodating profs I have ever had the pleasure of having, Sure, there is a lot of reading, but it is all generally interesting and even if it isn''t Lance makes it engaging. I will definitely be taking another class with him!', '["Participation matters","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1745245042, 1788283349);
