INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxMDA3MzMz', 41007333, '0047076', '7287', 'CHEM-1020L', 'CHEM1020L', 3, 3, 3, 4, 'Her labs are not difficult, but it''s tough to always feel like she''s expecting everyone to mess up. She''s kind if you respect her. Don''t take offence if she''s short with you.', '[]', 'A+', 1, 1, 1, NULL, 0, 0, 1745353332, 1788283361);
