INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNDczOTgw', 41473980, '0000768', NULL, NULL, 'ACCOUNTING', 5, 5, 5, 3, 'Excellent prof invested in students being engaged & doing well. Covers material in a way that builds on previous lessons so while it seems easy you''re learning more complex things every day. Should have Prof Ashley Doyle who removed herself from this site sit in on his classes so she can learn to actually teach and stop being sarcastic and judgy.', '[]', 'A', 1, 1, 1, NULL, 0, 0, 1751348801, 1788283363);
