INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNjQ0ODc0', 41644874, '0008859', '10907', 'PHIL-1413', 'PHIL1413', 3, 3, 3, 4, 'I personally did not have the experience most do with professor Wilks. I found his lectures and discussions really insightful. However, his marking was not very clear to me. I could not get the marks I desired in his course and I couldn''t really understand why. In summary awesome lectures confusing criteria. Also only grades three things.', '[]', 'B', 1, 1, 1, NULL, 0, 0, 1757990451, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNjQ0ODg4', 41644888, '0012762', '7646', 'COMM-1013', 'COMM1013', 1, 1, 1, 5, 'What you hear is true, It feels like less of a space for learning and more of a task to see who can play her game the best. You will never crack 70 on an assignment and I think she enjoys keeping you guessing whether you will pass or not. I suggest for your well-being throughout the semester to wait to get into the other comm class.', '["Tough grader","Participation matters","Group projects"]', 'B-', 1, 1, NULL, 3, 0, 0, 1757990892, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNjQ0OTE4', 41644918, '0000916', '7997', 'ECON-1013', 'ECON1013', 2, 2, 2, 3, 'Professor Moussa is the nicest guy. He is very lenient with grades and extra credit and he tries to help you succeed. However, you are basically teaching yourself Econ if you go into his classes. Some of his graphs were not in English and there was no need to go to the lectures.', '[]', 'B+', 1, 0, NULL, 3, 0, 0, 1757991724, 1788283358);
