INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNjUxMDQz', 41651043, '0306489', '7997', 'ECON-1013', 'ECON-1013', 5, 5, 5, 3, 'Nothing but good to say about Barry, always has interesting stories and tends to tie everything into lecture. Keep class engaged with his lectures but keeps his tests to the basic to make sure students are really understanding the fundamentals of the course. I highly suggest taking a course with him, in my opinion he''s the best prof at Acadia.', '["Amazing lectures ","Respected","Lecture heavy"]', 'A+', 1, 1, 1, NULL, 0, 0, 1758218460, 1788283341);
