INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzY3NTc4', 41767578, '0024327', NULL, NULL, 'POLSCI', 5, 5, 5, 3, 'Could not recommend Dr Biro enough. He is very approachable. Encourages a lot of group work and class discussions but will not force those who don''t want to talk. Very reasonable course load. This is my second class with him at this point and I will continue to look for his courses for the rest of my degree.', '[]', 'A', 1, 1, 1, NULL, 0, 0, 1761676141, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzY5ODM3', 41769837, '0306999', '11057', 'POLS-1403', 'POLS-1403', 5, 5, 5, 2, 'Young prof and passionate about what she was teaching and was always open to have a discussion. She makes it very clear what she expects from you and will mark you well if so. I found her lectures very engaging and we did fun activities one class a week to put what we learnt to practice. I will be looking out for more of her classes in the future.', '["Participation matters","Amazing lectures ","Lecture heavy"]', 'A', 1, 1, 1, NULL, 0, 0, 1761696576, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzg1MjA5', 41785209, '0024548', NULL, 'MAT-1213', 'MAT1213', 5, 5, 5, 2, 'The accent was difficult to understand in the beginning, but you get used to it. Work is very simple, and he''ll help you if you need it. 10/10 loved this class, and he''s funny too!', '["Hilarious","Caring","Accessible outside class"]', 'A', 1, 0, 1, NULL, 0, 0, 1761934659, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzg5OTQ2', 41789946, '0205001', '7114', 'BUSI-1013', 'BUSI-1013', 1, 1, 1, 5, 'took this as an elective.assignments that take hrs posted the day they are due. cannot meet for office hours.taught myself most of the material because the lectures were very unhelpful and unrelated to the homework. dropped because it was taking too much time from my other courses. NOT WORTH IT. Im an A student and this drove me insane.', '[]', 'Drop/Withdrawal', 1, 1, NULL, 3, 1, 0, 1762132383, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzk4MzY4', 41798368, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 1, 1, 1, 5, 'The slides are vague, so listening closely is necessary to catch details. Tests rely 90% on verbal info, with short answer questions that are very specific&#8212;you mostly have to memorize everything, more rote learning than actual understanding. The class felt harder than it should, and I wouldn''t take it again.', '["Tough grader","Get ready to read","Test heavy"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1762264805, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxNzkzMDMw', 41793030, '0018154', '11325', 'PSYC-2020L', 'PSYC2020L', 5, 5, 5, 5, 'Be ready to write hard. RDA is just a new world. Karmen does a great job at teaching those who want to be taught. Grading criteria are very clear. A lot of feedback that you need to take seriously. You can schedule an appointment with her if you don''t understand your feedback - she will kindly walk you through it. Reach out for help and be helped.', '["Tough grader","Group projects","Gives good feedback"]', 'A', 1, 0, 1, NULL, 0, 0, 1762192599, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODAwMjAx', 41800201, '0034433', '7134', 'BUSI-2223', 'BUSI2223', 5, 5, 5, 2, 'He''s the best finance prof at Acadia. He helps you understand why you solve things the way you do, and teaches you how to use a financial calculator unlike most other professors. He does do quizzes, but they are not a surprise quiz, he sends out the weekly plan and always says exactly what we are doing in class. I couldn''t recommend him more!', '["Get ready to read","Amazing lectures ","Accessible outside class"]', 'A-', 1, 1, 1, NULL, 0, 0, 1762279873, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODI0MTU3', 41824157, '0012762', NULL, NULL, 'COMM12131223', 5, 5, 5, 2, 'I took this course as an elective and was unsure if I would stay, based on what others have said about the course. I have to say, do not listen to these comments, until you go to the lecture and see for yourself. It is a break from a 300 person lecture. She always has office hours, she cares, and she makes class fun. Best grade I ever got.', '["Participation matters","Amazing lectures ","Accessible outside class"]', 'A', 1, 1, 1, 3, 0, 0, 1762540797, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODI1Nzk3', 41825797, '0000916', '7997', 'ECON-1013', 'ECON1013', 1, 1, 1, 4, 'You cant understand him and the lecture slides are confusing to even grasp anything from.', '[]', 'C+', 1, 0, NULL, NULL, 0, 0, 1762558497, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODUxMzYy', 41851362, '0315057', '7149', 'BUSI-2733', 'BUSI-2733', 2, 2, 2, 4, 'He doesn''t seem to understand students, and it shows. The lectures are incredibly not-enagaging, and his criteria for grading is very unclear.', '["Group projects","Lots of homework","Lecture heavy"]', 'B+', 1, 1, NULL, 3, 0, 0, 1762973655, 1788283348);
