INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYwOTgy', 41860982, '0180912', '11324', 'PSYC-2013', 'PSYC2013', 4, 4, 4, 2, 'Dr. Leslie is extremely friendly, very willing to help, and especially neurotic. For RDA make sure to pay attention and practice. For Intro-psych just study brah', '["Caring","Respected","Test heavy"]', 'A-', 1, 0, 1, NULL, 0, 0, 1763061023, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMDM2', 41861036, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 1, 1, 1, 2, 'Dr. Hayes clearly does not care about teaching RDA in the slightest, not that I blame him but like cmon do your job well. He gives extremely little material to practice and isn''t particularly open to helping. Clearly became a prof to do research and nothing else.', '["Tough grader","Test heavy","Graded by few things"]', 'B-', 1, 0, NULL, NULL, 0, 0, 1763061281, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMDU1', 41861055, '0169986', NULL, 'PYSC-2143', 'PYSC2143', 5, 5, 5, 1, 'Dr. Lametti was great for cognition, clearly interested in the material, and very willing to explain concepts if you don''t understand. Additionally allows cheat-sheets for the midterms which ensured everyone did at least pretty good.', '["Clear grading criteria","Gives good feedback"]', 'A+', 1, 0, 1, NULL, 0, 0, 1763061424, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMDc5', 41861079, '0192432', '11386', 'PSYC-3383', 'PSYC3383', 4, 4, 4, 3, 'Dr. Blustein was good for Human Neuropsych, interesting material and the grading scheme isn''t too weighted towards tests. Make sure to ask questions if you don''t understand concepts', '["Get ready to read","Caring","Test heavy"]', 'A+', 1, 0, 1, NULL, 0, 0, 1763061573, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMTAx', 41861101, '0133594', '11338', 'PSYC-2133', 'PSYC2133', 4, 4, 4, 4, 'Please go to class, in order to get a good/decent grade in this class just write down everything she says and correlate it to the slides later on. Dr. Champod is a tough graded, but is also very open to questions.', '[]', 'A-', 1, 0, 1, NULL, 0, 0, 1763061682, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMTMz', 41861133, '0006798', '9228', 'HIST-2203', 'HIST2203', 5, 5, 5, 2, 'Dr. Doerr is quite funny, if you never show up to class you can still get a B - low A grade, but he does tend to add little details during class that will show up on the test. Not sure why people complain about that part, we''re adults and we''re expected to go class guys', '["Clear grading criteria","Hilarious"]', 'A+', 1, 0, 1, NULL, 0, 0, 1763061827, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMTU2', 41861156, '0037406', '11355', 'PSYC-3053', 'PSYC3053', 5, 5, 5, 2, 'Dr. Newman is a fantastic professor, makes the material interesting and will hold in class conversations with you regarding any possible questions you have. She seems to make effort to learn all her students names. Although be prepared to study. Additionally for those of us in 2025, she loves 6-7', '["Hilarious","Respected","Lecture heavy"]', 'A+', 1, 0, 1, NULL, 0, 0, 1763061980, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODYxMjk0', 41861294, '0039699', '11057', 'POLS-1403', 'POLS1403', 1, 1, 1, 4, 'Your expected to buy an insane amount of books, incredibly unclear on what he wants, and a strangely high workload for a first year class. DONT TAKE POLS-1403', '[]', 'C', 1, 0, NULL, 3, 0, 0, 1763062520, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODc3MDg1', 41877085, '0012071', '9264', 'HIST-2493', 'HIST2493', 5, 5, 5, 3, 'Was a Canadian History on Film class: so the focus is watching films,which we do in class, rest of class is lecture/discussions. If you do not want to do readings, or speak up in class - this is not the class for you. Students who came not wanting to participate affect the class for everyone else. Dalton was knowledgeable and a great speaker.', '["Participation matters","Group projects","Respected"]', 'B+', 1, 1, 1, NULL, 0, 0, 1763325233, 1788283349);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODc3MzAz', 41877303, '0019405', NULL, NULL, 'FRENCH', 2, 2, 2, 1, 'Ive taken Bernard for 3 frenchs so far, Bernard is a very sweet teacher but honestly shouldn''t be teaching at university. He isnt the best at teaching lectures, he rarely answers his emails unless you email him 3 times, he never posts anything on Moodle, no info for projects or the syllabus. The only good thing is that he grades easy.', '[]', 'A+', 1, NULL, NULL, 3, 0, 0, 1763329139, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODk4MzY4', 41898368, '0016779', NULL, NULL, '18THCENTURY', 5, 5, 5, 3, 'Not sure why Stephen has so many bad reviews, he cares deeply for his students and was always there if help or guidance was needed and always wanted what is best for his students. Would definitely take this class again!', '["Get ready to read","Hilarious","Accessible outside class"]', 'A-', 1, 1, 1, 3, 0, 0, 1763516946, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxODkwNjg3', 41890687, '0016403', '6623', 'APSC-1223', 'APSC1223', 1, 1, 1, 4, 'He''s rude and talks down to the class. Honestly is a bad teacher and doesn''t help you out at all.', '[]', 'B-', 1, 1, NULL, NULL, 0, 0, 1763479484, 1788283363);
