INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTA5NDQ2', 41909446, '0147518', '11337', 'PSYC-2123', 'PSYC2123', 1, 1, 1, 5, 'I am so sorry. Praying for you all.', '[]', 'B-', 1, 0, NULL, NULL, 0, 0, 1763601969, 1788283347);
