INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTE3MDk0', 41917094, '0003479', NULL, 'MUSI-3666', 'MUSI3666', 1, 1, 1, 5, 'His tests are disgustingly in depth. he won''t let you take notes on your device. he wants you to have hand written notes no matter what. He is very arrogant over the email. If you can ignore the class, please do ignore and save yourself from absolute horror.', '["Tough grader","Beware of pop quizzes","Test heavy"]', 'B-', 1, 1, NULL, 3, 0, 0, 1763667050, 1788283360);
