INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI0ODY0', 41924864, '0176831', '7288', 'CHEM-1023', 'CHEM1023', 2, 2, 2, 5, 'Speaks clearly but doesnt fully cover all the topics in class and you will have alot of work to do at home.', '["Tough grader","Participation matters","Test heavy"]', 'C', 1, 0, NULL, NULL, 0, 0, 1763735856, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI0OTMy', 41924932, '0024548', NULL, NULL, 'MATH', 2, 2, 2, 4, 'While he seems like a good person who wants to make his students laugh it is very hard to understand him as is accent is very thick and his hand writting is terrible making it hard to both hear and see what he is writing. However the slides are avalible on Moodle which makes it easy for you to teach yourself and the course is not overly difficult.', '["Participation matters"]', 'Not sure yet', 1, 0, NULL, NULL, 0, 0, 1763736364, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI0OTQy', 41924942, '0024548', NULL, NULL, 'MATH', 3, 3, 3, 4, 'Overall a nice guy. Hard to understand with a very thick accent and poor hand writing making it hard to follow along. In general I''m sure he is a good prof and cares about his student but you end up teaching yourself the majority of the material outside of class using the slide shows he posts on moodle.', '["Participation matters"]', 'A', 1, 0, NULL, NULL, 0, 0, 1763736412, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI0OTg1', 41924985, '0310940', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 3, 'Amazing professor over all, very kind and willing to answer any questions. Very passionate about his field of study which makes it easy to follow along in lecture. All slides are posted on moodle but attending lectures is still important for fully understanding the material. Would 100% take any of his other classes.', '["Get ready to read","Amazing lectures ","Hilarious"]', 'A-', 1, 0, 1, 3, 0, 0, 1763736768, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI1MDI3', 41925027, '0306472', NULL, NULL, '1013', 2, 2, 2, 4, 'Be prepared to read the entire text book. She also does not share her slides so you will be taking notes the entire class. She has a thick accent and can be difficult to understand and you HAVE to particpate as it it 15% of your grade, so if you dont like to speak you will have to write out your answers and submit them for grading. Good luck!', '["Get ready to read","Participation matters","Lecture heavy"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1763737156, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI1MDM4', 41925038, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 2, 'She is the only reason I got through Chemistry 1023. I didnt have her as my prof but she posts all of her lectures online so I watched those to understand the concepts. She is amazing and very engaging.', '["Hilarious","Caring","Respected"]', NULL, 1, 0, 1, NULL, 0, 0, 1763737272, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQxOTI2NDAz', 41926403, '0263737', NULL, NULL, 'HIST', 1, 1, 1, 5, 'LATI1103 
