INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTM4NzM4', 42138738, '0040908', '13476', 'MATH-1250L', 'MATH1250L', 5, 5, 5, 2, 'Danielle is awesome to have as a lab instructor. Her prelab lectures taught me more than my actual statistics lectures did, the criteria of each lab assignment is very clear and pretty easy to do well on. The TAs and her are always available to answer questions and she is lovely, I would take her again. Lab assignments are due 24h after the prelab.', '["Clear grading criteria","Gives good feedback","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1765337781, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTM4OTE3', 42138917, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 4, 4, 4, 3, 'Ashley is strict in the prelab but it makes sense as she''s dealing with a hundred first-years at a time, many of whom haven''t done chem labs before. Very quick and helpful when you have questions, always present to help. All lab work has strict regulations, she is preparing us for future work in the sciences. All in all a good lab instructor.', '["Clear grading criteria"]', 'A', 1, 1, 1, NULL, 0, 0, 1765338202, 1788283361);
