INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTYxNDU3', 42161457, '0024914', '10007', 'MATH-2723', 'MATH2723', 2, 2, 2, 4, 'He is very nice, but he is not a good prof. Never does examples during lectures. Grades the test rather hard. The tests aren''t like the assignments at all. Also the written assignments are completely useless is terms of understanding the course content. Only thing I found helpful was the web work assignments.', '["Tough grader"]', 'A-', 1, 0, NULL, 3, 0, 0, 1765410985, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTYxNzIx', 42161721, '0001916', NULL, 'BIO-2563', 'BIO2563', 4, 4, 4, 3, 'He used power points that were straight forward but beware be uses a lot of pictures in his tests so know your organisms! I found that he bonuses were good, an additional 5% to the tests really helped boost my grade. I didn''t like that there were a lot of guest lectures.', '["EXTRA CREDIT","Clear grading criteria","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1765411607, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTYxODAy', 42161802, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 5, 5, 5, 3, 'Best professor I''ve ever had, she makes everything interesting and comes up with ways for students to remember content. I really appreciate all that she did for me to understand the course.', '["Amazing lectures ","Hilarious","Caring"]', 'A+', 1, 0, 1, NULL, 0, 0, 1765411775, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTc0ODUy', 42174852, '0306472', NULL, NULL, '1013', 5, 5, 5, 3, 'there is A LOT of reading to do, but she goes over it thoroughly in class. only thing is, is that she doesn''t upload her slides, so if you''re not in class or you didn''t read the textbook, you''ll have to ask someone else for notes (or just do the reading). she''s super nice, though, and very understanding!', '["Get ready to read","Participation matters","Lecture heavy"]', 'A-', 1, 1, 1, 3, 0, 0, 1765457935, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTc0ODY3', 42174867, '0034094', '7141', 'BUSI-2423', 'BUSI2423', 1, 1, 1, 4, 'If you like studying the textbook only to be tested on material from another dimension, take this class. Grading changes with his mood, he has obvious favourites, missing 5+ classes means an instant fail, and if you''re confused, he''ll make sure everyone knows it. If you have any other options for marketing professors then take them.', '["Tough grader","Group projects","Lecture heavy"]', NULL, 1, 1, NULL, 3, 1, 0, 1765458202, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMTc1NjAw', 42175600, '0176895', NULL, NULL, '1413', 3, 3, 3, 4, 'Make sure you go to class and do well on everything before any essay or test because she marks the essays really, really tough compared to everything else, and for the test,s she does not give any marks even if you got the idea but not exactly what she wants', '["Tough grader","Get ready to read","Participation matters"]', 'C+', 1, 1, NULL, 3, 0, 0, 1765463993, 1788283339);
