INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjY0Njkw', 42264690, '0205001', '7114', 'BUSI-1013', 'BUSI-1013', 4, 4, 4, 1, 'This course encouraged a high level of independence and academic rigor. The workload fostered strong time-management and self-learning skills. Very easy to talk to and genuinely cares about students'' understanding and success. Always ready to help and makes the course feel manageable and supportive.', '[]', 'A-', 1, 0, 1, 3, 0, 0, 1765829740, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjY0NzQ0', 42264744, '0205001', '7114', 'BUSI-1013', 'BUSI-1013', 5, 5, 5, 1, 'I took this course as an elective and wasn''t sure what to expect at first. The course was challenging and pushed me to stay organized and disciplined, which helped me grow as a student. What truly made the experience positive was the professor. They are very easy-going, approachable, and always ready to help.', '[]', 'A', 1, 0, 1, 3, 0, 0, 1765829854, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjY0Nzgx', 42264781, '0205001', '7114', 'BUSI-1013', 'BUSI-1013', 4, 4, 4, 2, 'When I enrolled in this course, I didn''t realize how much it would push me to grow academically. The course required effort and consistency, but it helped strengthen my learning habits. The professor made a huge difference &#8212; always calm, approachable, and ready to help.', '[]', 'A+', 1, 0, 1, 3, 0, 0, 1765829916, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjY0ODIz', 42264823, '0205001', '7114', 'BUSI-1013', 'BUSI-1013', 5, 5, 5, 1, 'At the beginning of the term, I was unsure about this course, but over time it helped me develop stronger discipline and focus. The professor was one of the most supportive instructors I''ve had', '["Participation matters","Caring","Accessible outside class"]', 'A', 1, 0, 1, 3, 0, 1, 1765829993, 1788283364);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjY2NzI3', 42266727, '0016779', NULL, NULL, '18THCENTURY', 1, 1, 1, 5, 'I would not recommend taking this course unless it is required, especially with this professor. He is extremely particular about writing style and class participation, which can be challenging if you do not follow his exact preferences. Also, he often deducts points for things he previously indicated were acceptable.', '["Tough grader","Participation matters"]', 'Rather not say', 1, 1, NULL, 3, 0, 0, 1765833990, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMjYyMDc0', 42262074, '0011148', '10907', 'PHIL-1413', 'PHIL1413', 2, 2, 2, 5, 'Such a nice woman, but her lectures are just very bland. She posts everything, and participation isn''t mandatory, but she is definitely a tough grader. She expects practically perfection on written tests. Will dock points off your grade if your response is not up to her standard. I think she is a great person, but I would not take her class again.', '["Tough grader","Lecture heavy","Graded by few things"]', 'Not sure yet', 0, 0, NULL, NULL, 0, 0, 1765823395, 1788283341);
