INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzIyOTEy', 42322912, '0315057', '7149', 'BUSI-2733', 'BUSI-2733', 3, 3, 3, 1, 'Not fully his fault but...Murphy''s Law. Continual tech issues, final canceled due to snow, linked the US textbook in the syllabus, missing the required case study. He cares a lot about his students but I can''t emphasize how much of a trainwreck this class was. He is fairly easy, and I would take his class again. He does get frustrated a lot though.', '["Group projects"]', 'A+', 1, 1, 1, 3, 0, 0, 1766027900, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzM3MTMz', 42337133, '0306472', NULL, NULL, '1013', 4, 4, 4, 3, 'Attendance and participation is a big part of the class so make sure to go! No slides are provided but it is very easy to take notes off her slideshows and all information is in the textbook. Overall, great intro sociology class. Midterms and exam was very fair.', '["Get ready to read","Participation matters","Graded by few things"]', 'A+', 1, 1, 1, 3, 0, 0, 1766099505, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzQ4NDU4', 42348458, '0133623', '8900', 'GEOL-1013', 'GEOL1013', 5, 5, 5, 3, 'You can tell she really enjoys teaching! She is very open to questions during class and is very knowledgeable. The tests are open book, however there are a lot of questions that come from in class examples not just theory based ones. She recorded her lectures on top of uploading the slides so if you miss a class you won''t fall behind.', '["Amazing lectures ","Caring","Accessible outside class"]', 'A', 1, 0, 1, 3, 0, 0, 1766168229, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzU4OTg0', 42358984, '0042843', NULL, NULL, 'ALLCLASSES', 1, 1, 1, 5, 'I really tried to give Dr Sears a shot but after reading these reviews, it''s clear that it''s her way or the highway. She is a very hard marker with minimal communication regarding rubrics, guidelines or marks. Makes it very challenging to do assignments when any feedback we get is given after the semester is over.', '["Tough grader"]', 'A', 0, 1, NULL, NULL, 0, 0, 1766236925, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzU5MDMz', 42359033, '0133712', '9943', 'MATH-1013', 'MATH1013', 5, 5, 5, 2, 'Professor Caroline is a highly logical individual, and we review our progress weekly. The workload is indeed substantial, requiring weekly completion of the Newton Alta exercises; otherwise, the final exam will prove daunting. Her lectures are considerable enthusiasm. She is exceptionally approachable, possesses legible handwriting,.', '["Amazing lectures ","Clear grading criteria","Lots of homework"]', 'A+', 1, 1, 1, NULL, 0, 0, 1766238188, 1788283342);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzUyMjA0', 42352204, '0050655', '8614', 'ESST-1003', 'ESST1003', 5, 5, 5, 1, 'a lot of reading, but it was all so interesting. the class felt like a big family. very sad that the class ended. tests were easy if you did the reading, as well as the final exam. went on 5 field trips and had a midterm on them after the last one. introduced oral tests this year where you just went to talk about what you learned. amazing class', '["Get ready to read","Amazing lectures ","Gives good feedback"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1766183325, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzUyMjc4', 42352278, '0000671', '7598', 'CODE-1023', 'CODE-1023', 2, 2, 2, 3, 'compared the things he graded to things TAs did, huge difference. fight for the mark you deserve. his lectures sucked. he always went off track. could never hear you, refused to put hearing aids in. he was a very funny guy, but not the best prof. would have loved to have taken this class 20 years ago when he wasn''t a literal fossil.', '["Tough grader","Participation matters","Hilarious"]', 'C+', 1, 1, NULL, NULL, 0, 0, 1766183674, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzUzMTQy', 42353142, '0037382', '8589', 'ENVS-1013', 'ENVS1013', 4, 4, 4, 3, 'Overall, I liked him as a prof. All of the information you need to know is on the lecture slides. However, on tests and quizzes sometimes there will be questions that weren''t on the review.', '["Lecture heavy","Accessible outside class"]', 'A+', 1, 0, 1, NULL, 0, 0, 1766187684, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzY3MzQ4', 42367348, '0004338', '9694', 'KINE-1213', 'KINE1213', 5, 5, 5, 2, 'I loved Prof Seaman, she gives out extra credit any chance she can get. She gives clear review for tests and exams. She is a lovely person and really cares about her students. I would take her class again, it was interesting and she''s a fair grader.', '["EXTRA CREDIT","Clear grading criteria","Caring"]', 'A+', 1, 0, 1, 3, 0, 0, 1766327262, 1788283353);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzY3MzU4', 42367358, '0181064', '6845', 'BIOL-1853', 'BIOL-1853', 4, 4, 4, 3, 'She was nice and willing to help if you reached out. Only two tests in the class, they are all multiple choice around 60 questions. Go through the learning outcomes and everything highlighted in red on her slides. She provided an opportunity of extra credit and her labs are interesting towards the end. She uses text books, but you don''t need them.', '["Graded by few things","Accessible outside class","Online Savvy"]', 'A-', 1, 0, 1, 3, 0, 0, 1766327563, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzYxNjMx', 42361631, '0133623', '8930', 'GEOL-2133', 'GEOL2133', 5, 5, 5, 4, 'Deanne is the most incredible professor I have ever taken a class with. She is both the head of the earth and environmental department, and an amazing professor. This class is very difficult and she knows that. She has no problem reviewing things, helping students, and making sure every student knows the material. The textbook is the golden ticket.', '["Amazing lectures ","Caring"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1766263199, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzc2MDE4', 42376018, '0024859', '7286', 'CHEM-1013', 'CHEM1013', 1, 1, 1, 3, 'Poor lectures often left more confused than went in. Just use Cathryn''s recordings instead of going to the lecture.', '["Tough grader","EXTRA CREDIT","Lecture heavy"]', 'Drop/Withdrawal', 1, 0, NULL, NULL, 0, 0, 1766426607, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzc4MTU2', 42378156, '0315057', '7149', 'BUSI-2733', 'BUSI-2733', 5, 5, 5, 3, 'Very new to Acadia and it shows. Genuinely cares about students. Not easy but not difficult. Gives detailed assignment feedback.', '["Gives good feedback","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1766439464, 1788283348);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzg4MTcy', 42388172, '0011703', '6685', 'ART-2013', 'ART2013', 2, 2, 2, 3, 'Science majors do NOT take as an elective', '["Tough grader","Participation matters","Lots of homework"]', 'B+', 1, 1, NULL, 3, 0, 0, 1766531537, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzg4NjUx', 42388651, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 1, 1, 1, 5, 'Lectures were just reading off slides, with no added explanation. I had to teach myself almost everything. Emails were replied to very late, and participation marks were deducted for not saying exact words in discussions. Very rigid and not understanding. I wouldn''t take another course with this professor.', '["Tough grader","Participation matters","Group projects"]', 'B', 1, 0, NULL, 3, 0, 0, 1766535232, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzk4MDM1', 42398035, '0037539', '9979', 'MATH-2013', 'MATH2013', 5, 5, 5, 4, 'Very caring and flexible', '[]', NULL, 1, NULL, 1, NULL, 0, 0, 1766703728, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzk5MTE0', 42399114, '0144618', '6834', 'BIOL-1110L', 'BIOL-1110L', 1, 1, 1, 3, 'Wasn''t expecting a mandatory intro lab to be all fantastic, but not looking forward to the second half with Kendra again next term. The TA''s were very helpful, but Kendra was often not around, and not very friendly when she was. It''s not a great learning environment when the professor is so head strong/high horse and seems annoyed to help you.', '["Get ready to read"]', NULL, 1, 1, NULL, NULL, 0, 0, 1766722354, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzkxNjE3', 42391617, '0176831', '7288', 'CHEM-1023', 'CHEM1023', 5, 5, 5, 1, 'Mr. Kafee is a great chemistry prof who explains concepts clearly and keeps the class stress-free. Finished with an A+, and the 6% attendance bonus was clutch and actually made showing up worth it. Super fair, supportive, and definitely a prof you want on your schedule.', '["Amazing lectures ","Lots of homework","Beware of pop quizzes"]', 'A+', 1, 1, 1, NULL, 0, 0, 1766577458, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyMzkyNDg2', 42392486, '0021211', '10901', 'PHIL-1113', 'PHIL1113', 3, 3, 3, 4, 'Dr. Paul is a great professor, and it''s clear he knows his material well. His class is challenging&#8212;he goes very in depth on some topics while expecting students to teach themselves others. I didn''t do very well personally, but passionate students will thrive. Even with my mark, I would consider taking him again.', '["Get ready to read","Participation matters","Lecture heavy"]', 'D+', 1, 1, NULL, 3, 0, 0, 1766597499, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDA2ODAz', 42406803, '0306161', '6856', 'BIOL-2043', 'BIOL2043', 4, 4, 4, 1, 'I was nervous based on reviews of Dr. Panchen last year. She was amazing! She clearly cares a lot about the subject. Being in class is important for lecture activities, and they do help you remember things! Occasionally she will stumble over her words or not be able to explain something more in-depth.', '["Participation matters"]', 'A+', 1, 1, 1, NULL, 0, 0, 1766880224, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDA2ODIw', 42406820, '0071592', '6855', 'BIOL-2040L', 'BIOL2040L', 5, 5, 5, 1, 'Jen makes Plant Biodiversity much easier! Her labs cover the basics so you have a good foundation of the course material. The slideshow at the beginning of each lab could be quite boring.', '[]', 'A+', 1, 1, 1, NULL, 0, 0, 1766880514, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDA2ODQ3', 42406847, '0048856', '7309', 'CHEM-2513', 'CHEM2513', 4, 4, 4, 3, 'Prof. Gullon is a very educated and dedicated instructor. There was a lot of content and she could go on tangents that introduced topics we didn''t need to know. As organic chemistry is such a jam-packed subject, I would''ve appreciated sticking to what we would eventually be evaluated on. She seemed to enjoy when students were overwhelmed. :(', '["EXTRA CREDIT"]', 'A+', 1, 0, 1, NULL, 0, 0, 1766880875, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDA2ODYw', 42406860, '0048856', '7308', 'CHEM-2510L', 'CHEM2510L', 5, 5, 5, 2, 'Amazing as a lab instructor! Pre-lab clearly explained everything we needed to know. Labs were much easier than I expected from such a feared course. Extra practice questions were always provided during the lab. READ YOUR LAB EXAM INSTRUCTIONS BEFORE YOU TOUCH ANYTHING!', '[]', 'A', 1, 1, 1, NULL, 1, 0, 1766881079, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDA2ODkw', 42406890, '0017498', '13476', 'MATH-1250L', 'MATH1250L', 4, 4, 4, 1, 'Quick explanations and then let you work on your own. Lab assignments were very straightforward.', '[]', 'A+', 1, 1, 1, NULL, 0, 0, 1766881508, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAwMzIx', 42400321, '0012118', '6633', 'APSC-2113', 'APSC2113', 3, 3, 3, 5, 'Dr. Arnold is a very nice guy, he wants people to succeed, and he is always happy to answer questions and give feedback. His lectures are okay but I found he doesn''t do enough examples in class. This made tests very difficult but the exam was fair. His grading scheme is one of the better ones in engineering. He''s not as bad as people say.', '["Beware of pop quizzes","Lecture heavy","Test heavy"]', 'C-', 1, 1, 1, 3, 0, 0, 1766764531, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAwMzMx', 42400331, '0024914', '10007', 'MATH-2723', 'MATH2723', 4, 4, 4, 3, 'Holger is very nice and his lectures are pretty enjoyable for being at 8:30am. If you''re going to ask questions do it during office hours. The assignments aren''t entirely useful but they are worth a lot. Tests were hard but open book and same goes for the exam. Good prof made DE easier than it should be.', '["Tough grader","Lots of homework"]', 'A-', 1, 0, 1, 3, 0, 0, 1766764849, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAwMzQ2', 42400346, '0152134', '6640', 'APSC-2220L', 'APSC2220L', 4, 4, 4, 3, 'Angelo is really nice and very knowledgeable. He''s circuits labs are far better than Thermo labs but he is an electrical engineer so that makes sense. I found he marks labs quite hard which is kind of annoying because you really need those good lab grades in circuits and Thermo. But he is very nice and treats you like you''re on the same level.', '["Tough grader","Participation matters","Gives good feedback"]', 'Audit/No Grade', 1, 1, 1, NULL, 0, 0, 1766765150, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAwMzcw', 42400370, '0024327', NULL, NULL, '1303', 4, 4, 4, 2, 'Dr. Biro was very good. He does grade essays hard but the rest of the course was easy so I can''t really complain.', '["Tough grader","Participation matters","EXTRA CREDIT"]', 'A', 1, 1, 1, 3, 0, 0, 1766765634, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAxMTk1', 42401195, '0200916', '9943', 'MATH-1013', 'Math-1013', 5, 5, 5, 3, 'Great prof', '["Respected"]', NULL, 0, NULL, 1, NULL, 0, 0, 1766778600, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDAzNTY1', 42403565, '0263737', NULL, NULL, 'HIST', 1, 1, 1, 5, 'Tanked my GPA. You can get away without the textbook in hist as we never really used it in class and there weren''t any readings on exams or midterms which protained to it.', '["Tough grader","Get ready to read","So many papers"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1766807537, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDEzOTIz', 42413923, '0302662', '11336', 'PSYC-2113', 'PSYC2113', 5, 5, 5, 3, 'One of the best profs I''ve had at Acadia. She genuinely cares about students success and was helpful for answering questions about honours and grad school. Exams were reasonale and she gives hints in class on what will be on them. I got stuck with a bad group for group work with 3 people who never showed up but the cases were interesting', '["Group projects","Caring","Accessible outside class"]', 'A-', 1, 1, 1, NULL, 0, 0, 1767038638, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDI0ODQ0', 42424844, '0200916', '9958', 'MATH-1413', 'MATH1413', 5, 5, 5, 3, 'Great proofs in class', '[]', NULL, 0, NULL, 1, NULL, 0, 0, 1767304299, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDM0ODk2', 42434896, '0306161', '6856', 'BIOL-2043', 'BIOL2043', 4, 4, 4, 2, 'Such an easy course (coming from a bio major). Zoe is a really great prof and you can tell she is passionate about her research. She can be a little quiet so its hard to focus in class. You can easily catch up if you skip class, it''s not hard to do well with minimal studying. The final exam is worth as much as the two midterms (15%) so no stress!', '["Clear grading criteria"]', 'A', 1, 0, 1, NULL, 0, 0, 1767555424, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDM0OTE5', 42434919, '0102323', '6948', 'BIOL-3293', 'BIOL3293', 5, 5, 5, 3, 'Alain is THE BEST prof I''ve ever had. He''s incredibly kind and cares a lot about his students. Class is moreso about the experience and converting you into a plant nerd than it is about just caring about grades. He is super knowledgeable and wants you to have fun in his classes. Incredibly hands on learning, the most fun you''ll have in a class.', '["Participation matters","Amazing lectures ","Gives good feedback"]', 'A', 0, 1, 1, NULL, 0, 0, 1767555870, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDM0OTEy', 42434912, '0011703', '6691', 'ART-2063', 'ART2063', 5, 5, 5, 4, 'Judith made everyone feel welcome. Her teaching style was flexible but with high standards. This was not an easy course but I learned a lot and am glad I took it. I learned a lot about drawing from nature.', '["Participation matters","Group projects","Inspirational"]', 'A+', 1, 1, 1, 3, 0, 0, 1767555780, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDM0OTMw', 42434930, '0071592', '6855', 'BIOL-2040L', 'BIOL2040L', 5, 5, 5, 1, 'Love Jen! Cares about her students, asks about your weekends and knows every student by name in her lab. Plant lab is easy and fun, very easy to leave early if you want.', '["Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1767556049, 1788283359);
