INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDQ3NTUz', 42447553, '0042843', NULL, NULL, 'ALLCLASSES', 1, 1, 1, 4, 'The worst professor I have had during my four years at Acadia. She does not give you any guidelines for any assignments and you won''t know how your doing in the class until the end of the semester (we didn''t get our first grade back until December 18th) she is a hard marker and will take off points for warm smile and posture. AVOID HER.', '["Tough grader"]', 'A', 1, 1, NULL, NULL, 0, 0, 1767725772, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDQzNzQz', 42443743, '0181064', '6845', 'BIOL-1853', 'BIOL-1853', 1, 1, 1, 1, 'ur cooooked', '["Get ready to read","Lecture heavy","Test heavy"]', NULL, 1, 0, NULL, NULL, 0, 0, 1767666093, 1788283358);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDQzOTgz', 42443983, '0132938', '8022', 'ECON-3123', 'ECON3123', 4, 4, 4, 5, 'Read every chapter of the textbook he covers in class and go to his office often. Do assignments early, bring them before they''re due, and he will help correct anything amiss. This shows effort to learn, and it helps more than you think. Note any &#8220;fun facts&#8221; he mentions in class (e.g., current Bank of Canada governor). Go to EVERY class.', '["Get ready to read","Participation matters","EXTRA CREDIT"]', 'A+', 1, 0, 1, 3, 0, 0, 1767668330, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDYyNzc4', 42462778, '0011703', '6685', 'ART-2013', 'ART2013', 5, 5, 5, 4, 'Great professor. Be prepared to work hard and you will learn a lot. Available outside of class time and a fair grader.', '["Participation matters","Amazing lectures ","Accessible outside class"]', 'A+', 1, 1, 1, 3, 0, 0, 1767900459, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDYzMTA1', 42463105, '0034695', NULL, NULL, 'BAND', 5, 5, 5, 2, 'the three hour rehearsal FLIES by with dr Hopkins as a prof, amazing guy who is very enthusiastic and has a lovely TA !!!', '["Gives good feedback","Inspirational","Caring"]', 'A+', 0, 1, 1, NULL, 0, 0, 1767903207, 1788283350);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDYzNjE1', 42463615, '0011703', '6691', 'ART-2063', 'ART2063', 5, 5, 5, 3, 'There was a sketchbook to be completed throughout the semester, don''t leave them for the last minute. Try your best to read her emails/announcements carefully for what is expected at the start of class, I missed some outline deadlines and it was fine, but don''t make it a habit .', '["Amazing lectures ","Accessible outside class"]', 'A+', 1, 1, 1, 3, 0, 0, 1767907073, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDc3NTA0', 42477504, '0102067', '11705', 'SOCI-2103', 'SOCI2103', 5, 5, 5, 3, 'took many courses with him over the years and always found the classes interesting and gave good feedback', '["Get ready to read","Participation matters","Gives good feedback"]', 'A', 1, 1, 1, 3, 0, 0, 1768182068, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDc4MjY3', 42478267, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'Participation is extremely important if you want a good grade. It makes up 20% of your final mark.', '["Tough grader","Participation matters","Group projects"]', 'B', 1, 1, NULL, 3, 0, 0, 1768189971, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDc4ODk4', 42478898, '0017498', '9969', 'MATH-1613', 'MATH1613', 5, 5, 5, 3, 'Not a big math gal but really enjoyed Dr. Connon''s class! She gives good assignments that aren''t overly complicated; much like the examples she does in class. Only received a poor grade due to be forced to give my energy to other classes and undiagnosed ADHD at the time.', '["Amazing lectures ","Beware of pop quizzes","Accessible outside class"]', 'C+', 1, 1, 1, NULL, 0, 0, 1768197328, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyMjAw', 42472200, '0150055', '7143', 'BUSI-2513', 'BUSI2513', 5, 5, 5, 3, 'Dr. Sarhadi is an excellent professor. We had daily lectures that were augmented by slides. It is in your best interest to attend all classes, especially classes where the math/calculation components are taught. These are quite difficult without guidance. Dr. Sarhadi gives very thorough feedback after each test; all you need to do is ask!', '["Group projects","Gives good feedback","Accessible outside class"]', 'B+', 1, 0, 1, NULL, 0, 0, 1768058650, 1788283345);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyMjAz', 42472203, '0031124', '7150', 'BUSI-2743', 'BUSI2743', 5, 5, 5, 4, 'Attend all classes. Dr. Weatherbee is a very fair tester; as long as you show up and pay attention, the tests are relatively straightforward. Complete the readings before class; class participation is an important part of your grade. Take notes as you read to better understand the concepts.', '["Get ready to read","Participation matters","Group projects"]', 'A-', 1, 1, 1, 3, 0, 0, 1768058833, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyMzY0', 42472364, '0310940', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 3, 'Garret is a great guy who makes his morning bio lectures decently interesting and clearly enjoys his job and biology. Go to class, take notes, study and you will pass the class with flying colors.', '["Caring","Lecture heavy","Graded by few things"]', 'A-', 1, 1, 1, 3, 0, 0, 1768064517, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyMzg2', 42472386, '0144618', '6834', 'BIOL-1110L', 'BIOL-1110L', 4, 4, 4, 3, 'Kendra can seem kind of cold and careless but is fairly nice and honest when asked questions. She is more straight to the point than some people are used to, but she gets her job done.', '["Participation matters","Clear grading criteria"]', 'A+', 1, 1, 1, NULL, 0, 0, 1768065256, 1788283359);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyMzk5', 42472399, '0306410', '13563', 'LAWS-1003', 'LAWS1003', 5, 5, 5, 2, 'Dr. Lockhart is an amazing professor who does a great job at teaching and clearly cares a lot about her students. Super nice and approachable for questions and makes it very clear what to expect on midterm/exam. Wants you to do well and makes it easy to do so if you show up to class and participate.', '["Caring","Respected","Lecture heavy"]', 'A+', 1, 1, 1, NULL, 0, 0, 1768065528, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyNDE0', 42472414, '0040908', '13476', 'MATH-1250L', 'MATH1250L', 5, 5, 5, 2, 'Great instructor for the stats lab, super nice, chill and understanding. very approachable for questions and wants students to do well.', '["Caring","Respected","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1768065775, 1788283340);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyNDI4', 42472428, '0029615', '11698', 'SOCI-1033', 'SOCI1033', 5, 5, 5, 2, 'Great guy, highly recommend taking his SOCI 1033 class, easy A as all you need to do is show up and do short participation things in class for full marks. Hilarious guy and bit unhinged but cares a lot about the students and wants everyone to do well. Easy to talk to but get stuff in on time that''s the only thing he is stiff about, deadlines.', '["Hilarious","Caring","Respected"]', 'A+', 1, 1, 1, 3, 0, 0, 1768066133, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDcyNDIw', 42472420, '0145558', NULL, 'PSYCH-1110L', 'PSYCH1110L', 4, 4, 4, 3, 'Dr. Jones is a good and knowledgeable professor that cares about her students and willing to meet in the middle if you communicate clearly about questions or concerns you might have. Go to the labs, get labs done on time and you will do fine. Cite your sources or she will ding you for points big time. Other than that good lab instructor.', '["Tough grader","Caring","Accessible outside class"]', 'A+', 1, 1, 1, NULL, 0, 0, 1768065994, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg0MDk1', 42484095, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'she''s nice but very tough grader, her way or the highway. if you participate in class she should like you, get in a good group for group project or your screwed. you don''t need to purchase the textbook lowkey.', '["Tough grader","Participation matters","Lecture heavy"]', 'C', 1, 1, NULL, 3, 0, 0, 1768257884, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg1MzEz', 42485313, '0000671', '7598', 'CODE-1023', 'CODE-1023', 2, 2, 2, 4, 'Super hard grader, especially difficult since he barely expresses what the assignment is or what he expects. Grading between TA and the prof are different, be careful. Get ready to yell and be asked to repeat yourself every time you speak. He is funny for sure, and super sweet. Not necessarily a prof i would take for an easy elective.', '["Tough grader","Participation matters","Lecture heavy"]', 'A', 1, 1, 1, NULL, 0, 0, 1768267975, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg1NTcx', 42485571, '0306489', '7997', 'ECON-1013', 'ECON-1013', 5, 5, 5, 2, 'Great professor! Prepares you well for tests/exams by giving out last years tests/exams which are very similar to what you would be tested on. Only thing is he doesn''t post many notes at all, so coming to class is very important.', '["Hilarious","Respected"]', 'A-', 1, 1, 1, NULL, 0, 0, 1768269984, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg1NTk4', 42485598, '0003993', '9943', 'MATH-1013', 'MATH1013', 4, 4, 4, 3, 'Jim is a kind professor. For extra help, he is very available outside class. Quizzes and homework every week as well as two midterms. the midterms are not as difficult as you think they would be. Only downside is he teaches as if you already know the information as most do already know it.', '["Beware of pop quizzes","So many papers","Respected"]', 'A+', 1, 1, 1, 3, 0, 0, 1768270224, 1788283360);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg1NjE2', 42485616, '0012762', '7647', 'COMM-1213', 'COMM1213', 2, 2, 2, 5, 'Kendra makes this class way harder than it needs to be. I recommend you speak every class. She will respect you for that. She marks based on her mood or marks most groups the same mark. She doesn''t give enough information for assignments but especially midterms as she doesn''t give an outline at all.', '["Tough grader","Participation matters","Group projects"]', 'A', 1, 1, NULL, 3, 0, 0, 1768270346, 1788283363);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDg4OTI3', 42488927, '0011148', '10907', 'PHIL-1413', 'PHIL1413', 1, 1, 1, 4, 'Had an actual personal grudge against me. Mean.I went to her office hours after receiving a C- on an assignment to see what I could improve on. She straight up asked me "Did you even study?" Hard to respect someone when they speak to you that way. Her feedback is "reread the instructions" Avoid her class, Im sure shes a nice woman outside of work!', '["Tough grader","Graded by few things"]', 'C', 1, 0, NULL, 3, 0, 0, 1768325059, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNDk1ODAw', 42495800, '0003100', NULL, NULL, 'HIST', 5, 5, 5, 2, 'Dr. Henderson is the best possible introduction to being a history major as a first year, HIST-1003 is overall a boring lecture heavy course but Henderson makes the most of it with guest professors coming in for some lectures or visits to the archives. Assignments are manageable and his feedback is easy to understand and work on.', '["Group projects","Gives good feedback","Lecture heavy"]', 'A', 1, 1, 1, NULL, 0, 0, 1768401496, 1788283355);
