INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNjM3Njgz', 42637683, '0306410', '13563', 'LAWS-1003', 'LAWS1003', 5, 5, 5, 2, 'Emily is one of, if not the best, professors Acadia has to offer. Her lectures are informative, well structured, and entertaining in a way that keeps you engaged. The coursework is never unreasonable and should be relatively easy as long as you keep up with the lectures and the readings. She is also genuinely kind and makes sure you succeed.', '["Participation matters","Clear grading criteria","Caring"]', 'A', 1, 1, 1, NULL, 0, 0, 1771895516, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNjM3NzA3', 42637707, '0310940', '6835', 'BIOL-1113', 'BIOL1113', 5, 5, 5, 2, 'Garrett is the exact kind of professor that makes you excited to go to lectures. I was in the 8:30 time (which is really early for me, not a morning person) and I would actually show up early due to his amazing pre-lecture talks about his own research. Garrett is truly passionate about his work and teaching and it shows.', '["Amazing lectures ","Hilarious","Graded by few things"]', 'A', 1, 0, 1, 3, 0, 0, 1771895876, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyNjM3NzI5', 42637729, '0032242', '7286', 'CHEM-1013', 'CHEM1013', 5, 5, 5, 4, 'This course is genuinely hard, however Cathy definitely makes it as easy as possible. Her lectures are always engaging and entertaining, she always goes over examples around basically any form of equation you will encounter on a midterm or assignment, and she gives easy bonus points in the form of in-class quizzes.', '["EXTRA CREDIT","Amazing lectures ","Caring"]', 'A', 1, 0, 1, NULL, 0, 0, 1771896148, 1788283361);
