INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODE0MjU5', 42814259, '0011703', '6714', 'ART-3023', 'ART3023', 5, 5, 5, 5, 'Great professor but know that there are a lot of challenging assignments. Be prepared to show up and get your work handed in on time.', '["Participation matters","Group projects","Accessible outside class"]', 'A', 1, 1, 1, 3, 0, 0, 1775855725, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODE2NTU0', 42816554, '0169986', NULL, 'PYSC-2143', 'PYSC2143', 5, 5, 5, 3, 'Dan is one of the best profs I''ve had at Acadia. Every prof says they want their students to succeed, but Dan REALLY means it. He posts practice questions before tests, is always accessible through email, and will even record a lecture for you if you tell him you have to miss it. Can''t recommend him enough, I learned so much from him.', '["Amazing lectures ","Graded by few things","Accessible outside class"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1775919860, 1788283343);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODE3ODY5', 42817869, '0037539', '9943', 'MATH-1013', 'MATH1013', 2, 2, 2, 5, 'She is a very difficult professor for a first year class. She is very in depth about her knowledge around theorems and uses it to her advantage when making tests for the class. Make sure to know how SHE wants you to solve the question, because if you do anything different it is considered as wrong.', '["Tough grader","Lots of homework","Test heavy"]', 'Not sure yet', 0, 1, NULL, NULL, 0, 0, 1775950959, 1788283344);
