INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODEzODA1', 42813805, '0043166', '9190', 'HIST-1533', 'HIST1533', 5, 5, 5, 3, 'I absolutely love Dr. MacDonald. She is interested in the material she teaches, and that rubs off on her students. While she is a slow marker, her criteria for grading is clear and she''s upfront about when to expect marks. She cares about her students and is always willing to answer questions/meet outside class. Will be taking more of her courses.', '["Participation matters","Caring","Accessible outside class"]', 'Not sure yet', 1, 1, 1, NULL, 0, 0, 1775850459, 1788283346);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODEzODA2', 42813806, '0043166', '9190', 'HIST-1533', 'HIST1533', 5, 5, 5, 2, 'If you have a chance, take a course with Dr. MacDonald! She is amazing and very interested in what she does. She is very fun and has a lot of fun with material culture and power/prestige. Very understanding of students and their lifes, and just cares that you try. Also finds ways to give marks for anything she can in a test or exam.', '["Participation matters","Hilarious","Accessible outside class"]', 'Not sure yet', 1, 1, 1, 3, 0, 0, 1775850460, 1788283346);
