INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODEzODM1', 42813835, '0003100', '9185', 'HIST-1413', 'HIST1413', 5, 5, 5, 2, 'Love Dr. Henderson. He''s so funny and it makes lectures engaging. He obviously cares about his students and is always willing to work with them. Exams are all take-home, and instructions are clear. Take a course with him if you can', '["Amazing lectures ","Inspirational","Accessible outside class"]', 'Not sure yet', 1, 0, 1, NULL, 0, 0, 1775850679, 1788283355);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODEzODU0', 42813854, '0302829', '11698', 'SOCI-1033', 'SOCI1033', 3, 3, 3, 1, 'Cares a lot about his students, always willing to work with them. Lectures are pretty much just the textbook regurgitated, if you read the lecture slides you can get away with not doing the readings. Attend class because he posts test review questions which appear word for word on the text. Easy grader, half my grade was attendance, kind of boring', '["Get ready to read","Caring"]', 'A+', 1, 1, 1, 3, 0, 0, 1775850858, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQyODI1MDE4', 42825018, '0181064', '6845', 'BIOL-1853', 'BIOL-1853', 2, 2, 2, 5, 'She reads directly of slide. 3 slide shows a week, with each slide show being around 22 slides. Highlights "important" in red, but makes very difficult and in depth questions. What is in red is rarely what she asks. Prepare to take heavy notes outside of class, because she is hard to follow compared to other teachers.', '["Get ready to read","Lots of homework","Lecture heavy"]', 'C+', 1, 0, NULL, 3, 0, 0, 1776103730, 1788283358);
