INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDU1OTEz', 43055913, '0031457', '7288', 'CHEM-1023', 'CHEM1023', 4, 4, 4, 3, 'he was pretty goated. course was well organized swell compared to others. bonus 6% from quizzes seems overly generous but I''m not complaining.', '["Participation matters","Amazing lectures ","Clear grading criteria"]', 'A+', 1, 0, 1, NULL, 0, 0, 1778126098, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDU1OTI3', 43055927, '0047076', '7287', 'CHEM-1020L', 'CHEM1020L', 2, 2, 2, 3, 'little too strict during labs sometimes. other than that she''s honestly overhated.', '["Participation matters","Lecture heavy"]', 'A+', 1, 1, NULL, NULL, 0, 0, 1778126211, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDU3Njc2', 43057676, '0031459', NULL, NULL, 'CLAS', 5, 5, 5, 2, 'Dr. Hewitt is so nice, always willing to give extra time or extensions, a very kind and understanding person. Her lectures are very interesting but move quickly, so make sure to take notes.', '["Amazing lectures ","Caring"]', 'A-', 1, 1, 1, 3, 0, 0, 1778154631, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDg4NTcy', 43088572, '0139613', NULL, 'POLS-2006', 'POLS2006', 4, 4, 4, 1, 'Dr. Crandall is a great professor! She really cares about her job, is consistent all around, and very fair.', '["Participation matters","Group projects","Caring"]', 'A', 1, 1, 1, 3, 0, 0, 1778463803, 1788283357);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDgwOTcx', 43080971, '0037539', '9962', 'MATH-1533', 'MATH1533', 1, 1, 1, 3, 'She takes so unbelievably long to grade everything, and her lectures are super scattered and disorganized. It also doesn''t help that she writes about as well as a 4 year old. Hated her class, not a fan of her teaching style.', '["Group projects","Lots of homework","So many papers"]', 'Not sure yet', 1, 1, NULL, 3, 0, 0, 1778356460, 1788283344);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMDkwMTg2', 43090186, '0175018', '7739', 'COMP-3503', 'COMP3503', 1, 1, 1, 2, 'If you are interested in machine learning I''d recommend taking MATH3293 statistical learning instead of spending money and time on his lecture.', '[]', 'A+', 0, NULL, NULL, NULL, 0, 0, 1778476041, 1788283341);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMTg4MTIz', 43188123, '0041312', NULL, 'ENG-1483', 'ENG1483', 5, 5, 5, 4, 'An incredible instructor! Professor Damour gives impassioned, well prepared lectures. Don''t skip class, do the readings, take notes, and form your own opinions. She wants personal analysis, not summaries. Participate in class and visit office hours; she''s approachable and happy to help. I could not recommend taking her class more!', '["Participation matters","Amazing lectures ","Gives good feedback"]', 'A+', 1, 1, 1, 3, 0, 0, 1779619966, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMTk5ODA2', 43199806, '0310937', '9060', 'GERM-1013', 'GERM1013', 5, 5, 5, 2, 'Coming into this class knowing 0 German i would definitely take this as an elective. Th textbook is super useful and definitely worth the buy as i used it to study for tests. She makes this class super fun and entertaining. Julia is extremely accommodating as well and cares for her students.', '["Participation matters","Amazing lectures ","Gives good feedback"]', 'A+', 1, 1, 1, 3, 0, 0, 1779909611, 1788283347);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMTkxNTkw', 43191590, '0041312', '13465', 'ENGL-1483', 'ENGL-1483', 5, 5, 5, 4, 'Michelle is a very supportive first year professor and I would take any of her classes. If you go to her classes and engage you will do great. She is an extremely flexible teacher and makes you feel human. If you are passionate about what you are doing you will thrive.', '["Participation matters","Gives good feedback","Accessible outside class"]', 'B+', 1, 1, 1, 3, 0, 0, 1779731739, 1788283362);
