INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjA2NTkw', 43206590, '0021211', '10901', 'PHIL-1113', 'PHIL1113', 5, 5, 5, 3, 'you have to come to class for this. i honestly loved his class, he wasnt boring to me. interesting topics and he teaches really well. the first week or two was confusing but then i got the hang of it. hes super nice but the only downside is that hes a tough grader. i never got better than a 75 on a test but he should add more ways to get credit', '["Tough grader","Get ready to read","Graded by few things"]', 'B+', 1, 1, 1, 3, 0, 0, 1780065631, 1788283352);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjA2ODgx', 43206881, '0041312', '8394', 'ENGL-1423', 'ENGL1423', 4, 4, 4, 3, 'She is very welcoming for participation in discussions, selected texts were interesting. There was a lot of reading overall but I feel an appropriate amount of time was given to complete it. She is very particular about grammar while grading but points lost on assignments felt fair to me personally. Generally friendly and helpful.', '["Get ready to read","Participation matters","Gives good feedback"]', 'A+', 1, 1, 1, 3, 0, 0, 1780072266, 1788283362);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjA2OTA3', 43206907, '0148951', '7654', 'COMP-1113', 'COMP1113', 3, 3, 3, 2, 'Very easy grader. If you did the assignments and labs then you would have to skip the exam entirely to fail, and maybe not even then. Very willing to explain anything you''re confused about but sometimes a little hard to follow.', '["Clear grading criteria","Lecture heavy"]', 'A-', 1, 0, 1, NULL, 0, 0, 1780072633, 1788283354);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjA3OTIx', 43207921, '0047076', '7285', 'CHEM-1010L', 'CHEM1010L', 4, 4, 4, 2, 'Ashley can come off as very strict, but she is actually very sweet if you respect her, listen carefully and follow expectations. She is very clear with what she wants done in the lab and in reports due at the end of each lab. It may seem like a lot, but if you pay attention and make notes of what she expects on each question, it''s very manageable.', '[]', 'A', 1, 1, 1, NULL, 0, 0, 1780089610, 1788283361);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjA5MjA1', 43209205, '0183679', '9186', 'HIST-1423', 'HIST1423', 2, 2, 2, 3, 'Nice person but lectures were vague and dismissive. Relied too heavily on textbook rather than his own lecturing ability. Would not give clear outline of what tests would cover so everything had to be studied. You essentially have to read the entire textbook', '["Get ready to read"]', 'A-', 1, 0, NULL, 3, 0, 0, 1780118226, 1788283356);
INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMjAzNDYy', 43203462, '0150055', '7166', 'BUSI-3063', 'BUSI3063', 5, 5, 5, 4, 'Professor Sarhadi explains business analytics concepts clearly and keeps expectations fair throughout the course. The class requires regular reading and effort, but grading is reasonable and feedback is helpful. If you stay organized and keep up with the work, you should do well.', '["Amazing lectures ","Gives good feedback","Graded by few things"]', 'A+', 1, 0, 1, 3, 0, 0, 1779993539, 1788283345);
