INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMzY0MjU2', 43364256, '0147518', '11326', 'PSYC-2023', 'PSYC2023', 4, 4, 4, 5, 'I promise it''s not as bad as everyone says! Honestly, just go to office hours, collaborate with other students in the class, and attend all the help sessions. The course material is hard, but Joseph Hayes is the kind of professor who will take time with you to make sure you fully understand. He does want you to succeed.', '[]', 'A', 1, 1, 1, NULL, 0, 0, 1786638926, 1788283347);
