INSERT INTO "professor_ratings" ("id", "rmpLegacyId", "professorId", "courseId", "courseCode", "courseCodeRaw", "quality", "helpful", "clarity", "difficulty", "comment", "tags", "gradeReceived", "isForCredit", "attendanceRequired", "wouldTakeAgain", "textbookUse", "thumbsUpTotal", "thumbsDownTotal", "postedAt", "importedAt") VALUES ('UmF0aW5nLTQzMzY0MjY4', 43364268, '0263737', '12104', 'WGST-1413', 'WGST1413', 5, 5, 5, 3, 'Mariah changed the way I view the world; it feels like you are listening to an awe-inspiring TED Talk every time she gives a lecture. If I could do all my courses with her, I would!!', '[]', 'A', 1, 1, 1, 3, 0, 0, 1786639127, 1788283358);
